    /**
     * Method which creates the Subscriber Profile and populates to the response
     * commdto (between wrapper and the Server) and sends the response back to
     * the client (SOAP client etc.) through messaging fw MQ.
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO createSubscriber(IXDMRequestDTO requestDTO) {
        String methodName = "createSubscriber(KnMessage)";
        knLogger.info(methodName, "ENTRY: create Subscriber with input - ", requestDTO);
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsProvInfoDTO subsProvInputDTO = null;
        KnXDMCreateRespDTO responseDTO = new KnXDMCreateRespDTO();

        try {
            // verify if the input DTO is KnXDMSubsProvInfoDTO
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            //KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DG_MDN_CREATED_REQ);
            if (requestDTO instanceof KnXDMSubsProvInfoDTO) {
                subsProvInputDTO = (KnXDMSubsProvInfoDTO) requestDTO;
                knLogger.debug(methodName, "received DTO for create Subscriber - ", subsProvInputDTO);
            } else {
                knLogger.error(methodName, "received and Invalid DTO for create subscriber op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_CREATION_FAILURE);
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }
            if(null != subsProvInputDTO.getSubsFS2() && KnGeneralUtil.getFeatureBitValue(subsProvInputDTO.getSubsFS2(),FEATURE_SET.MCPTT_VIA_GW.value())){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_MCS_CLIENTS_CREATED_REQ);
            }

            //Validating the  Corporate Hirarchy

            if(subsProvInputDTO.getExtCorpId() != null && !KnGeneralProfileUtil.validateExtCorpCCAndHierarchy(subsProvInputDTO.getExtCorpId(),
                    subsProvInputDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", subsProvInputDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid Corp hierarchy passed");
            }

            //Validating the  MDN Hirarchy
            if(!KnGeneralProfileUtil.validateMDNCCAndHierarchy(subsProvInputDTO.getMdn(), subsProvInputDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the mdn : ", subsProvInputDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }

            // Opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "Opening the Transaction");
            persisterTxn.open();
            // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
            if (subsProvInputDTO.getOperationType() != null && !subsProvInputDTO.getOperationType().isEmpty()) {
                commonMediator.validateSubAuthStatus(Collections.singletonList(subsProvInputDTO.getMdn()), persisterTxn);
            }
            // populate the Subscriber Prov library DTO
            subsProvInputDTO.setAutoPair(subsProvInputDTO.getPairingInd());
            // to deprecate existing autopair logic because of new logic
            subsProvInputDTO.setPairingInd(Boolean.FALSE);
            if (null == subsProvInputDTO.getNetworkName() || subsProvInputDTO.getNetworkName().isEmpty()) {
                subsProvInputDTO.setNetworkName(subsProvInputDTO.getMdn());
            }
            KnIPSubsProvInfoDTO subsProvInfoDTO = provMediator.populateSubsProvInfoDTO(subsProvInputDTO);

            Integer subsClientType = subsProvInfoDTO.getSubsClientType();
            // checking if any the client type = null then add the default client type
            if (subsClientType == null) {
                subsClientType = KnProvConstants.SUBS_CLIENT_TYPE.HANDSET.value();
                subsProvInfoDTO.setSubsClientType(subsClientType);
            }
            knLogger.debug(methodName, "Subscriber Client type- ", subsClientType);
            //retriving from db/cache client type config check is enable or disable
            //LMR client type changes
            if(subsClientType == SUBSCRIBERS_CLIENT_TYPE.DATAGROUPMDN.value()){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DG_MDN_CREATED_REQ);
            }
            if (subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.MOBILE_CLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.THIRDPARTYDISPATCHERCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.SGMDNPATCH.value()) {

                KnClientTypeConfigDTO clientTypeConfigDTO = genInfoUtil.getClientTypeConfig(subsClientType, persisterTxn);
                if (clientTypeConfigDTO.getIsEnable() != KnProvConstants.CLIENT_TYPE_CONFIGURATION.ENABLED.value()) {
                    knLogger.error(methodName, "Client type is disabled");
                    throw new KnProvBOException(KnErrorCodes.BOEntity.CLIENT_TYPE_DISABLED, "Subscriber Client Type is disabled");
                }
            }
            // calling the Prov Library
            KnOPCreateSubsInfoDTO respDTO = provClientIntf.createSubscriber(subsProvInfoDTO, persisterTxn);
            knLogger.debug(methodName, "Successfully Create Subscriber Profile with resp DTO - ", respDTO);

            // verify if the Corporate Subscription type is enabled
            // if enabled check the pairing ind is enabled to perform the
            // internal contact pairing
            int corporateSubscriptionType = -1;
            corporateSubscriptionType = subsProvInputDTO.getCorporateSubscriptionType();
            KnXDMCorpRespDTO corpResp = null;
            if (corporateSubscriptionType == KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {

                // calling corp library to perform Corp Auto pairing
                Boolean corpAutoParing = respDTO.getCorpAutoPairing();
                Boolean isOldCorp = respDTO.getIsOldCorp();

                if (corpAutoParing != null && isOldCorp != null) {
                    if (isOldCorp) {
                        knLogger.debug(methodName, "Corp exist. call enable/disble for corp Auto pairing");
                        if (corpAutoParing) {
                            KnXDMCorpSubscInfoRequestDTO contactRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
                            contactRequestDTO.setCorpId(String.valueOf(respDTO.getCorpId()));
                            contactRequestDTO.setSubscriberMdn(subsProvInputDTO.getMdn());
                            contactRequestDTO.setName(subsProvInfoDTO.getNetworkName());
                            contactRequestDTO.setHierarchyType(subsProvInputDTO.getHierarchyType());
                            corpResp = corpMediator.addToPairingList(contactRequestDTO, persisterTxn);
                        } else {
                            // disable auto pairing
                            KnXDMCorpInfoRequestDTO corpInfoRequestDTO = new KnXDMCorpInfoRequestDTO();
                            corpInfoRequestDTO.setEnableAutoPair(Boolean.FALSE);
                            corpInfoRequestDTO.setCorpId(String.valueOf(respDTO.getCorpId()));
                            corpInfoRequestDTO.setHierarchyType(subsProvInputDTO.getHierarchyType());
                            corpResp = corpMediator.updateCorpAutoPairing(corpInfoRequestDTO, persisterTxn);
                        }

                    } else { //corporate not exist
                        if (corpAutoParing) {
                            knLogger.debug(methodName, "Corp does exist hence created new. call enable auto pairing");
                            KnXDMCorpInfoRequestDTO corpInfoRequestDTO = new KnXDMCorpInfoRequestDTO();
                            corpInfoRequestDTO.setEnableAutoPair(Boolean.TRUE);
                            corpInfoRequestDTO.setCorpId(String.valueOf(respDTO.getCorpId()));
                            corpInfoRequestDTO.setHierarchyType(subsProvInputDTO.getHierarchyType());
                            corpResp = corpMediator.updateCorpAutoPairing(corpInfoRequestDTO, persisterTxn);
                        }
                    }

                    knLogger.debug(methodName, "Corp Autopairing response - ", corpResp);
                    if (corpResp.getResponseStatus() != KnMediatorConstants.SUCCESS) {
                        throw new KnXDMServerException(corpResp.getResponseCode(), corpResp.getResponseMessage());
                    }
                }

            }
            if (corporateSubscriptionType == KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
                int corpId = respDTO.getCorpId();

                boolean isRequiredCorpNotified = commonInfoUtil.isRequiredCorpNotified(respDTO.getSubsFS2(), corpId, persisterTxn);
                if (isRequiredCorpNotified) {

                    KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, true, persisterTxn);
                    knLogger.debug(methodName, "Corporate Profile - ", corpProfile);

                    //Update the UGWINTEROP
                    commonInfoUtil.updateLmrInterOpInDB(corpId, ENABLED, persisterTxn);
                    //Notify to MCS CORP
                    KnCorporateExdmsNotifyDto corporateExdmsNotifyDto = commonInfoUtil.formCorpNotifyPayload(CREATE_CORP.value(), corpProfile, ENABLED, MICROSERVICES_NOTIFY_EVENT_TYPE.CORPORATE_EVENT.value());
                    knLogger.info(methodName, "Publishing micro service notify for corp- ", corporateExdmsNotifyDto);
                    commonMediator.startNotifyMicroServicesJob(List.of(corporateExdmsNotifyDto));

                }
            }

            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            if(xcapMobileSync) {
                //  KnMqServiceConfig rmqInfoDto = commonMediator.retrieveServerConfDetails(persisterTxn);
                KnSubscrEXDMSNotifyDto knSubscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                knSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                knSubscrEXDMSNotifyDto.setCorpid(respDTO.getCorpId());
                knSubscrEXDMSNotifyDto.setMdn(subsProvInputDTO.getMdn());
                knSubscrEXDMSNotifyDto.setClientType(subsClientType);
                knSubscrEXDMSNotifyDto.setLastProfileUpdateTime(respDTO.getLastUpdateprofileTime());
                knSubscrEXDMSNotifyDto.setId(CREATE_SUBSCR.value() + KnConstants.LINE_SAPERATOR + subsProvInputDTO.getMdn());
                knSubscrEXDMSNotifyDto.setType(CREATE_SUBSCR.value());
                knSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knSubscrEXDMSNotifyDto.setSubsFS2(respDTO.getSubsFS2());
                knSubscrEXDMSNotifyDto.setMcId(respDTO.getMcId());
                knSubscrEXDMSNotifyDto.setMcdataId(respDTO.getMcDataId());
                knSubscrEXDMSNotifyDto.setMcpttId(respDTO.getMcPttId());
                knSubscrEXDMSNotifyDto.setMcvideoId(respDTO.getMcVideoId());
                knSubscrEXDMSNotifyDto.setNetworkName(respDTO.getNetworkName());
                knSubscrEXDMSNotifyDto.setDeviceId(subsProvInputDTO.getMdn());
                knSubscrEXDMSNotifyDto.setAuthStatus(respDTO.getServiceAuthStatus());
                List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
                notifyDtoList.add(knSubscrEXDMSNotifyDto);
                knLogger.info(methodName, "Publishing micro service notify for user- ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }

            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            LinkedHashSet<String> mdnSet = new LinkedHashSet<>();
            mdnSet.add(subsProvInfoDTO.getMdn());
            knLogger.info(methodName, "mdnSet", mdnSet);
            notifier.sendEtagMcsNotifications(mdnSet);

            // updating the pegs
            Collection<Integer> successPegs = new ArrayList<Integer>();
            successPegs.add(KnOMConstants.XDM_NUM_SUBSCR_CREATED);
            Collection<Integer> listOfPegs = respDTO.getSuccessPegs();
            if (listOfPegs != null && !listOfPegs.isEmpty()) {
                for (int pegId : listOfPegs) {
                    successPegs.add(pegId);
                }
            }
            KnStatisticsManagerImpl.getInstance().increment(successPegs);

            responseDTO = (KnXDMCreateRespDTO) commonMediator.getSuccessResponse(responseDTO);
            // Set the corp id, name and network name in response
//            if (responseDTO instanceof KnXDMCorpInfoRespDTO) {
            responseDTO.setCorpId(respDTO.getCorpId());
            responseDTO.setCorpName(respDTO.getCorpName());
            responseDTO.setNetworkName(respDTO.getNetworkName());
//            }
            if (corpResp != null && corpResp.getEnabledDispatchMemList() != null && !corpResp.getEnabledDispatchMemList().isEmpty()) {
                initiateDispatchGrpJob(corpResp.getEnabledDispatchMemList(), null, null,
                        null, respDTO.getCorpId());
            }
            if(subsClientType == SUBSCRIBERS_CLIENT_TYPE.DATAGROUPMDN.value() && responseDTO.getResponseStatus() == KnConstants.RESPONSE_STATUS.SUCCESS.value()){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DG_MDN_CREATED_REQ_SUCC);
            }
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_CREATION_FAILURE);
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to create Subscriber ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_CREATION_FAILURE);
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_CREATION_FAILURE);
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getFailureResponse(responseDTO, e);
        }
        knLogger.debug(methodName, "responseDTO type ", responseDTO.getClass().getName());
        knLogger.info(methodName, "EXIT: create Subscriber - ", responseDTO);
        return responseDTO;
    }

    /**
     * method for the Updating the Subscriber profile
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO updateSubscriber(KnMessage message) {
        String methodName = "updateSubscriber(KnMessage)";
        KnPersisterTxn persisterTxn = null;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        KnXDMSubsProvInfoDTO subsProvInputDTO = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // validating if the received input DTO is KnXDMSubsProvInfoDTO
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            knLogger.info(methodName, "Entry Received from the input DTO - ", requestDTO);
            if (requestDTO instanceof KnXDMSubsProvInfoDTO) {
                subsProvInputDTO = (KnXDMSubsProvInfoDTO) requestDTO;
                knLogger.debug(methodName, "received DTO for update Subscriber - ", subsProvInputDTO);
            } else {
                knLogger.error(methodName, "receive an Invalid DTO for update Subscriber op - ", requestDTO);
                responseDTO = new KnXDMRespDTO();
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
                return responseDTO;
            }
            //Validating the  CORP Hirarchy
            if(subsProvInputDTO.getExtCorpId() != null && !KnGeneralProfileUtil.validateExtCorpCCAndHierarchy(subsProvInputDTO.getExtCorpId(),
                    subsProvInputDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", subsProvInputDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid Corp hierarchy passed");
            }
            //Validating the  MDN Hirarchy
            if(!KnGeneralProfileUtil.validateMDNCCAndHierarchy(subsProvInputDTO.getMdn(), subsProvInputDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the mdn : ", subsProvInputDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
            if (subsProvInputDTO.getOperationType() != null && !subsProvInputDTO.getOperationType().isEmpty()) {
                commonMediator.validateSubAuthStatus(Collections.singletonList(subsProvInputDTO.getMdn()), persisterTxn);
            }

            KnOPUpdateSubsInfoDTO provRespDTO = null;
            // retrieving the subscriber profile to verify if there is a change
            // in the Subscription Type
            knLogger.debug(methodName, "retrieving the subscriber profile for mdn ");
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(subsProvInputDTO.getMdn());
            subscriberInfoDTO.setExtGatewayId(subsProvInputDTO.getExtGatewayId());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);

            Integer subsClientType = subsProfileInfoDTO.getSubsClientType();
            if (subsClientType == DISPATCH_CLIENT) {
                knLogger.debug(methodName, "dispatch onboarding email set ");
                subsProfileInfoDTO.setOnBoardingEmailReqd(1);
            }
            //retriving from db/cache client type config check is enable or disable
            //LMR client type changes
            if (subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.MOBILE_CLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.THIRDPARTYDISPATCHERCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.SGMDNPATCH.value()) {

                KnClientTypeConfigDTO clientTypeConfigDTO = genInfoUtil.getClientTypeConfig(subsClientType, persisterTxn);
                if (clientTypeConfigDTO.getIsEnable() != KnProvConstants.CLIENT_TYPE_CONFIGURATION.ENABLED.value()) {
                    knLogger.error(methodName, "Client type is disabled");
                    throw new KnProvBOException(KnErrorCodes.BOEntity.CLIENT_TYPE_DISABLED, "Subscriber Client Type is disabled");
                }
            }

            // populate the Subscriber Prov library DTO
            subsProvInputDTO.setAutoPair(subsProvInputDTO.getPairingInd());
            // to deprecate existing autopair logic because of new logic
            subsProvInputDTO.setPairingInd(Boolean.FALSE);
             if ((null == subsProvInputDTO.getNetworkName() || subsProvInputDTO.getNetworkName().isEmpty())
                    && (null == subsProfileInfoDTO.getNetworkName() || subsProfileInfoDTO.getNetworkName().isEmpty())) {
                subsProvInputDTO.setNetworkName(subsProvInputDTO.getMdn());
            }

            KnIPSubsProvInfoDTO subsProvInfoDTO = provMediator.populateSubsProvInfoDTO(subsProvInputDTO);
            // invoking the library for update subscriber
            provRespDTO = provClientIntf.updateSubscriber(subsProvInfoDTO, persisterTxn);
            knLogger.debug(methodName, "Response received from Server - ", provRespDTO);

            if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == provRespDTO.getResponseStatus()
                    && subsProfileInfoDTO.getOnBoardingEmailReqd() == ON_BOARDING_MAIL.REQUIRED.value()) {
                KnOPSubsProfileInfoDTO subsProfileInfo = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
                KnXDMSubsAliasDetailsRespDTO oidcResponseDTO = null;
                boolean isOIDCApplicable = generalCacheUtil.isOIDCApplicable(subsProfileInfo.getCorpId(), WEBDISPATCHER);
                String appId = subsProfileInfo.getDispatchType() == DISPATCH_TYPE_WEB ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                if(subsProfileInfoDTO.getMcpttCompliance() == MCPTT_COMPLIANCE_ENABLED){
                    oidcResponseDTO = commonMediator.createOidcDeviceSharingProfileWithMCSIds(subsProfileInfo, APP_ID.USERMCSCLIENTS.value(), persisterTxn);
                }else if (subsProfileInfo.getClientPVmajorVer() == PROTOCOL_VERSION_0 || subsProfileInfo.getClientPVmajorVer() > PROTOCOL_VERSION_13) {
                    oidcResponseDTO = commonMediator.createOidcDeviceSharingProfileWithMCSIds(subsProfileInfo, appId, persisterTxn);
                } else {
                    if ((isOIDCApplicable && appId.equals(APP_ID.DISPATCHER.value())) || (appId.equals(APP_ID.HANDSET_STANDARD.value()))) {
                        oidcResponseDTO = commonMediator.createOidcDeviceSharingProfileWithMCSIds(subsProfileInfo, appId, persisterTxn);
                    }
                }
                int failureStatus = oidcResponseDTO != null ? oidcResponseDTO.getStatus() : KnConstants.RESPONSE_STATUS.FAILURE.value();
                if (KnConstants.RESPONSE_STATUS.FAILURE.value() == failureStatus) {
                    knLogger.error(methodName, "Error for updating profile in IDM - ", failureStatus);
                    responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INTERNAL_ERROR);
                    responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                    throw new KnXDMServerException(responseDTO.getResponseCode(), "Unable to Create IDM Profile");
                }
            } else if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == provRespDTO.getResponseStatus() && subsProfileInfoDTO.getSubsClientType() == DISPATCH_CLIENT) {
                knLogger.debug(methodName, "inside new If ");
                KnOPSubsProfileInfoDTO subsProfileInfo = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
                //subsProfileInfo.setOnBoardingEmailReqd(ON_BOARDING_MAIL.NOT_REQUIRED.value());
                String appId =  APP_ID.DISPATCHER.value() ;
                KnXDMSubsAliasDetailsRespDTO oidcResponseDTO=null;
                String oldDbuserId=null;
                if(null!=subsProfileInfoDTO.getUserId()) {
                    oldDbuserId = subsProfileInfoDTO.getUserId();
                    subsProfileInfo.setOldUserId(oldDbuserId);
                }

                if (null!=subsProvInputDTO.getUserId()&& !subsProvInputDTO.getUserId().isEmpty() && null!= subsProfileInfo.getUserId()&&!subsProfileInfo.getUserId().isEmpty()&&!subsProfileInfo.getUserId().equals(oldDbuserId)) {  //null!=subsProfileInfoDTO.getUserId()&&
                    knLogger.debug(methodName, "inside to createOidcDeviceSharingProfileWithMCSIds ");
                    oidcResponseDTO = commonMediator.createOidcDeviceSharingProfileWithMCSIds(subsProfileInfo, appId, persisterTxn);
                    int failureStatus = oidcResponseDTO != null ? oidcResponseDTO.getStatus() : KnConstants.RESPONSE_STATUS.FAILURE.value();
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == failureStatus) {
                        knLogger.error(methodName, "Error for updating profile in IDM - ", failureStatus);
                        responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INTERNAL_ERROR);
                        responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                        throw new KnXDMServerException(responseDTO.getResponseCode(), "Unable to Create IDM Profile");
                    }
                }


            }

            // if client type changed set auth status to provisioned
            knLogger.debug(methodName, "Subs clientType :", subsProfileInfoDTO.getSubsClientType(), " subsProvInputDTO.getSubscriberClientType() :",
                    subsProvInputDTO.getSubscriberClientType());
            int oldSubsClientType = subsProfileInfoDTO.getSubsClientType();
            int newSubsClientType = 0;
            if (subsProvInputDTO.getSubscriberClientType() != null)
                newSubsClientType = subsProvInputDTO.getSubscriberClientType();

            // verify that if the client Type has been changed form HANDSET to PTTRADIOHANDSETCLIENT and vice versa
            boolean isPTTRadioClientTypeChange = false;
            if (oldSubsClientType != newSubsClientType) {
                String str = "" + SUBS_CLIENT_TYPE.HANDSET.value() + "|"
                        + SUBS_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value() + "," + SUBS_CLIENT_TYPE.CROSSCARRIER.value()
                        + "|" + SUBS_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value() + ","
                        + SUBS_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value() + "|" + SUBS_CLIENT_TYPE.POC_WIFIONLY.value()
                        + "";
                String[] regEx1 = str.split(",");
                for (int i = 0; i < regEx1.length; i++) {
                    if (String.valueOf(oldSubsClientType).matches(regEx1[i])
                            && String.valueOf(newSubsClientType).matches(regEx1[i])) {
                        isPTTRadioClientTypeChange = true;
                        knLogger.info(methodName, "Client type change skipped");
                    }
                }

            }

            if (newSubsClientType != 0 && oldSubsClientType != newSubsClientType && !isPTTRadioClientTypeChange) {
                knLogger.debug(methodName, "client Type changed. setting service auth status to Provisioning");
                KnXDMSubsStatusInfoDTO subsStatusInfoDTO = new KnXDMSubsStatusInfoDTO();
                subsStatusInfoDTO.setMdn(subsProvInputDTO.getMdn());
                subsStatusInfoDTO.setClientType(requestDTO.getClientType());
                subsStatusInfoDTO.setServiceAuthStatus(KnConstants.SERVICE_AUTH_STATUS.PROVISIONED.value());
                KnConstants.MESSAGE_TYPE action = KnConstants.MESSAGE_TYPE.CLIENT_TYPE_CHANGE;
                IXDMResponseDTO respDTO = changeServiceAuthStatus(subsStatusInfoDTO, persisterTxn, action);
                if (respDTO.getResponseStatus() != KnConstants.STATUS_SUCCESS) {
                    throw new KnProvBOException(respDTO.getResponseCode(), respDTO.getResponseMessage());

                }
                knLogger.debug(methodName, "response received from Server - ", provRespDTO);

            }

            // if (subsProfileInfoDTO.getCorporateSubscriptionType() ==
            // KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
            // populating the corporate Library DTO
            KnXDMCorpSubscInfoRequestDTO corpSubsRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
            corpSubsRequestDTO.setSubscriberMdn(subsProvInputDTO.getMdn());
            if (subsProvInputDTO.getPublicSubscriptionType() == -1) {
                corpSubsRequestDTO.setNewPublicSubscriptionType(subsProfileInfoDTO.getPublicSubscriptionType());
            } else {
                corpSubsRequestDTO.setNewPublicSubscriptionType(subsProvInputDTO.getPublicSubscriptionType());
            }

            if (subsProvInputDTO.getCorporateSubscriptionType() == -1) {
                corpSubsRequestDTO.setNewCorpSubscriptionType(subsProfileInfoDTO.getCorporateSubscriptionType());
            } else {
                corpSubsRequestDTO.setNewCorpSubscriptionType(subsProvInputDTO.getCorporateSubscriptionType());
            }
            corpSubsRequestDTO.setPublicSubscriptionType(subsProfileInfoDTO.getPublicSubscriptionType());
            corpSubsRequestDTO.setCorpSubscriptionType(subsProfileInfoDTO.getCorporateSubscriptionType());
            corpSubsRequestDTO.setClientType(subsProfileInfoDTO.getSubsClientType());
            corpSubsRequestDTO.setNewClientType(subsProfileInfoDTO.getSubsClientType());
            corpSubsRequestDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
            corpSubsRequestDTO.setNewCorpId(provRespDTO.getCorpId());
            corpSubsRequestDTO.setName(subsProvInputDTO.getNetworkName());
            corpSubsRequestDTO.setAutoPairingFlag(subsProvInputDTO.getPairingInd());
            corpSubsRequestDTO.setOldName(subsProfileInfoDTO.getNetworkName());
            corpSubsRequestDTO.setHierarchyType(subsProvInputDTO.getHierarchyType());
            corpSubsRequestDTO.setActiveFs2(subsProfileInfoDTO.getActiveFS2());
            LinkedList<KnLIEventDTO> eventDTOList = new LinkedList<KnLIEventDTO>();
            // invoking the corporate library
            KnCorpResponseDTO corpResp = corpMediator.updateSubscriber(corpSubsRequestDTO, persisterTxn);
            KnXDMCorpRespDTO corpRespD = populateXdmResponse(corpResp);
            int status = corpRespD.getResponseStatus();
            knLogger.debug(methodName, " corp Library response - ", corpResp);
            if (status != 0) {
                throw new KnXDMServerException(corpRespD.getResponseCode(), corpRespD.getResponseMessage());
            }
            knLogger.debug(methodName, "Update is successful from Corporate Library");

            // calling corp library to perform Corp AUTO pairing
            Boolean corpAutoParing = provRespDTO.getCorpAutoPairing();
            Boolean isOldCorp = provRespDTO.getIsOldCorp();
            KnXDMCorpRespDTO corporateRespDto = null;
            if (corpAutoParing != null && isOldCorp != null) {
                if (isOldCorp) {
                    knLogger.debug(methodName, "Corp exist. call enable/disble for corp Auto pairing");
                    if (corpAutoParing) {
                        KnXDMCorpSubscInfoRequestDTO contactRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
                        contactRequestDTO.setCorpId(String.valueOf(provRespDTO.getCorpId()));
                        contactRequestDTO.setSubscriberMdn(subsProvInputDTO.getMdn());
                        contactRequestDTO.setName(subsProvInfoDTO.getNetworkName());
                        contactRequestDTO.setHierarchyType(subsProvInputDTO.getHierarchyType());
                        corporateRespDto = corpMediator.addToPairingList(contactRequestDTO, persisterTxn);
                    } else {
                        // disable auto pairing
                        KnXDMCorpInfoRequestDTO corpInfoRequestDTO = new KnXDMCorpInfoRequestDTO();
                        corpInfoRequestDTO.setEnableAutoPair(Boolean.FALSE);
                        corpInfoRequestDTO.setCorpId(String.valueOf(provRespDTO.getCorpId()));
                        corpInfoRequestDTO.setHierarchyType(subsProvInputDTO.getHierarchyType());
                        corporateRespDto = corpMediator.updateCorpAutoPairing(corpInfoRequestDTO, persisterTxn);
                    }

                } else { //corporate not exist
                    if (corpAutoParing) {
                        knLogger.debug(methodName, "Corp does exist hence created new. call enable auto pairing");
                        KnXDMCorpInfoRequestDTO corpInfoRequestDTO = new KnXDMCorpInfoRequestDTO();
                        corpInfoRequestDTO.setEnableAutoPair(Boolean.TRUE);
                        corpInfoRequestDTO.setCorpId(String.valueOf(provRespDTO.getCorpId()));
                        corpInfoRequestDTO.setHierarchyType(subsProvInputDTO.getHierarchyType());
                        corporateRespDto = corpMediator.updateCorpAutoPairing(corpInfoRequestDTO, persisterTxn);
                    }
                }

                knLogger.debug(methodName, "Corp Autopairing response - ", corpResp);
                if (corporateRespDto.getResponseStatus() != KnMediatorConstants.SUCCESS) {
                    throw new KnXDMServerException(corporateRespDto.getResponseCode(), corporateRespDto.getResponseMessage());
                }
            }

            // }
            // int oldCorpSubscriptionType =
            // subsProfileInfoDTO.getCorporateSubscriptionType();
            int oldPublicSubscriptionType = subsProfileInfoDTO.getPublicSubscriptionType();
            // int newCorpSubscriptionType =
            // subsProvInputDTO.getCorporateSubscriptionType();
            int newPublicSubscriptionType = subsProvInputDTO.getPublicSubscriptionType();

            // check if public is updated to NONE

            if ((oldPublicSubscriptionType == KnConstants.PUBLIC_SUBSCRIPTION_TYPE.PUBLIC
                    .value() && newPublicSubscriptionType == KnConstants.PUBLIC_SUBSCRIPTION_TYPE.NONE.value())
                    || (newSubsClientType != 0 && oldSubsClientType != KnConstants.SUBSCRIBERS_CLIENT_TYPE.POCDONORRADIO.value()
                    && newSubsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.POCDONORRADIO.value())) {

                knLogger.debug(methodName, "invoke the public library for deletion of public data");
                String ownerMdn = subsProvInputDTO.getMdn();
                // Get all contacts and ListService URI s of group with LI Event
                // DTO
                eventDTOList = commonMediator.getEventDTOList(ownerMdn, KnProvOperationTypes.UPDATE_SUBSCRIBER, persisterTxn);
                pubDocMediator.deleteAllContactsAndGroups(subsProvInputDTO.getMdn(), persisterTxn);
                knLogger.debug(methodName, "successfully delete all public data");
            }

            // Invoke the cleanup of OLD Corporate profile.
            int oldCorpId = subsProfileInfoDTO.getCorpId();
            int newCorpId = provRespDTO.getCorpId();

            if (oldCorpId != newCorpId) {
                knLogger.debug(methodName, "Invoking cleanup of old corporate profile ");
                KnOPProvDTO corpProfileRespDTO = provMediator.deleteCorpProfile(oldCorpId, persisterTxn);
                knLogger.debug(methodName, "Delete old corp profile response - ", corpProfileRespDTO);
            }

            boolean OldGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(subsProfileInfoDTO.getActiveFS2(), FEATURE_SET.BROADCASTGROUPSERVICE.value());
            boolean newGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(), FEATURE_SET.BROADCASTGROUPSERVICE.value());
            KnCorpResponseDTO corpRespDto = null;

            if (!newGrpBroadcastBit && OldGrpBroadcastBit) {
                corpRespDto = corpMediator.updateGrpBroadcasters(subscriberInfoDTO.getMdn(), persisterTxn);
                knLogger.debug(methodName, "disabled group broadcast members corp Library response - ", corpRespDto);
                if (corpRespDto.getStatus() != 0) {
                    throw new KnXDMServerException(corpRespDto.getStatusCode(), corpRespDto.getMessage());
                }

            }
            knLogger.debug(methodName,subsProfileInfoDTO.getActiveFS2(),provRespDTO.getActiveFS2(),subscriberInfoDTO.getCorpId());
            knLogger.debug(methodName,subscriberInfoDTO.getMdn(), provRespDTO.getActiveFS2(), subsProfileInfoDTO.getActiveFS2());
            boolean oldReGroupBit = KnGeneralUtil.getFeatureBitValue(
                    subsProfileInfoDTO.getActiveFS2(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            boolean newReGroupBit = KnGeneralUtil.getFeatureBitValue(
                    provRespDTO.getActiveFS2(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            if(oldReGroupBit != newReGroupBit){
                knLogger.info(methodName,"notification for preconfigure group");
                KnCorpResponseDTO groupNotifyResp = corpMediator.groupNotifyOnActiveFsChange(corpResp.getMdnCorpId(),
                        subscriberInfoDTO.getMdn(), provRespDTO.getActiveFS2(), subsProfileInfoDTO.getActiveFS2(), persisterTxn);
                if(corpResp.getChangeLogMap()!=null){
                    corpResp.getChangeLogMap().putAll(groupNotifyResp.getChangeLogMap());
                }else{
                    corpResp.setChangeLogMap(groupNotifyResp.getChangeLogMap());
                }
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);

            // sending the notification
            String pv = String.valueOf(subsProfileInfoDTO.getClientPVmajorVer());
            knLogger.debug(methodName, "PV :", pv);

            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(subscriberInfoDTO.getMdn(),provRespDTO.getActiveFS2(),subsProfileInfoDTO.getActiveFS2(),persisterTxn);

            String mcsXcapRootUri = genInfoUtil.getMCSXCAPRootURI(subscriberInfoDTO.getMdn(), persisterTxn);

            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);

            KnCorporateExdmsNotifyDto corporateExdmsNotifyDto = null;
            if (subsProfileInfoDTO.getCorporateSubscriptionType() == KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
                int corpId = provRespDTO.getCorpId();
                boolean isRequiredCorpNotified = commonInfoUtil.isRequiredCorpNotified(provRespDTO.getSubsFS2(), corpId, persisterTxn);
                if (isRequiredCorpNotified) {
                    KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, true, persisterTxn);
                    knLogger.debug(methodName, "Corporate Profile - ", corpProfile);

                    //Update the UGWINTEROP
                    commonInfoUtil.updateLmrInterOpInDB(corpId, ENABLED, persisterTxn);

                    //Notify to MCS
                    corporateExdmsNotifyDto = commonInfoUtil.formCorpNotifyPayload(MODIFY_CORP.value(), corpProfile, ENABLED, MICROSERVICES_NOTIFY_EVENT_TYPE.CORPORATE_EVENT.value());
                    knLogger.info(methodName, "Publishing micro service notify for corp- ", corporateExdmsNotifyDto);

                }
            }

            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            if (corporateExdmsNotifyDto != null) {
                knLogger.debug(methodName, " Sending notification for corp");
                commonMediator.startNotifyMicroServicesJob(List.of(corporateExdmsNotifyDto));
            }

            //MC DEVICE NOTIFY
            if(provRespDTO.isDeleteDeviceNotify()){
                sendDeleteDeviceNotification(provRespDTO.getDeviceIMPI());
            }

            if (null != opProvDTO.getDirChgDTO()) {
                knLogger.debug(methodName, "opProvDTO", opProvDTO);
                KnOPDirChgDTO dirChgDTO = opProvDTO.getDirChgDTO();
                if (null != opProvDTO.getDirChgDTO().getDocChgDTO()) {
                    String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
                    dirChgDTO = commonMediator.fetchMdnsFromDirChgDto(opProvDTO.getDirChgDTO(), xdmPttServerId, persisterTxn);
                }
                opProvDTO.setDirChgDTO(dirChgDTO);

                knLogger.debug(methodName, "TGSS doc changed sending notification");
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), pv);
            }

            if (null != provRespDTO.getDirChgDTO()) {
                knLogger.debug(methodName, "provRespDTO", provRespDTO);
                KnOPDirChgDTO dirChgDTO = provRespDTO.getDirChgDTO();
                if (null != provRespDTO.getDirChgDTO().getDocChgDTO()) {
                    String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
                    dirChgDTO = commonMediator.fetchMdnsFromDirChgDto(provRespDTO.getDirChgDTO(), xdmPttServerId, persisterTxn);
                }
                provRespDTO.setDirChgDTO(dirChgDTO);
            }

            if (oldSubsClientType != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Alias_MDN.value()
                    && oldSubsClientType != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Group_MDN.value()
                    && oldSubsClientType != KnProvConstants.SUBS_CLIENT_TYPE.DATAGROUPMDN.value()) {
                if ((null != provRespDTO.getDirChgDTO()) && (pv.matches(com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_REGEX))
                        && (provRespDTO.isActiveFSChanged() || provRespDTO.isSubsNameChanged()
                        || provRespDTO.isSubsTypeChanged())) {
                    KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                    if (provRespDTO.isActiveFSChanged()) {
                        profileNotifyDTO.setActiveFeatureSetChange(subsProfileInfoDTO.getMdn());
                    }
                    if (provRespDTO.isSubsNameChanged()) {
                        profileNotifyDTO.setSubscriberNameChange(subsProfileInfoDTO.getMdn());
                    }
                    if (provRespDTO.isSubsTypeChanged()) {
                        profileNotifyDTO.setSubscriptionTypeChange(subsProfileInfoDTO.getMdn());
                    }
                    profileNotifyDTO.setMdn(subsProfileInfoDTO.getMdn());
                    profileNotifyDTO.setPocHome(provRespDTO.getDirChgDTO().getPocHome());
                    profileNotifyDTO.setPresenceHome(provRespDTO.getDirChgDTO().getPresenceHome());
                    profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());

                    commonMediator.sendProfileNotification(profileNotifyDTO, provRespDTO.getDirChgDTO(), pv);
                } else {
                    commonMediator.sendXcapNotification(provRespDTO.getDirChgDTO(), pv);

                    List<KnXcapDiffNotifyDTO> xcapDiffList = new ArrayList<>();
                    if (provRespDTO.getDirChgDTOs() != null && !provRespDTO.getDirChgDTOs().isEmpty()) {
                        for (KnOPDirChgDTO dirChgDTO : provRespDTO.getDirChgDTOs()) {
                            KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                            Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                            ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) dirChgDTO.getDocChgDTO();
                            for (KnOPDocChgDTO chgDTO : chgDocList) {
                                KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                                xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                                xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                                xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                                xcapDocList.add(xcapDiffDocDTO);
                            }

                            xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                            xcapDiffNotifyDTO.setDirNewEtag(dirChgDTO.getDirNewEtag());
                            xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTO.getDirPrevEtag());
                            xcapDiffNotifyDTO.setDirURI(dirChgDTO.getDirUri());
                            xcapDiffNotifyDTO.setXcapRootUri(dirChgDTO.getXcapRootURI());
                            xcapDiffNotifyDTO.setProtocolVersion(pv);
                            xcapDiffNotifyDTO.setPocHome(dirChgDTO.getPocHome());
                            xcapDiffNotifyDTO.setPresenceHome(dirChgDTO.getPresenceHome());
                            xcapDiffList.add(xcapDiffNotifyDTO);

                        }

                    }
                    knLogger.debug(methodName, "Notification DTO generated - ", xcapDiffList);
                    KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                    notificationParamDTO.setCid(message.getCorrelationId());
                    boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, notificationParamDTO);
                    knLogger.debug(methodName, "Notification status - ", isNotified);
                }
            }

            if (corpRespDto != null) {
                Map<String, KnOPDirChgDTO> updateSubcriberChangeLogMap = corpResp.getChangeLogMap();
                LinkedList<KnLIEventDTO> updateGrpBroadcasterLiEventList = corpRespDto.getLiEventList();
                knLogger.debug(methodName, "LI event list from the update grp broadcast call - ", updateGrpBroadcasterLiEventList);
                if (updateGrpBroadcasterLiEventList != null) {
                    eventDTOList.addAll(updateGrpBroadcasterLiEventList);
                }
                knLogger.debug(methodName, "eventDTOList after update Grpbrocast call - ", eventDTOList);
                Map<String, KnOPDirChgDTO> updateGrpBroadcastersChangeLogMap = corpRespDto.getChangeLogMap();
                Map<String, KnOPDirChgDTO> combinedChangeLogMap = new HashMap<>();
                if (updateSubcriberChangeLogMap != null) {
                    combinedChangeLogMap.putAll(updateSubcriberChangeLogMap);
                }
                if (updateGrpBroadcastersChangeLogMap != null) {
                    combinedChangeLogMap.putAll(updateGrpBroadcastersChangeLogMap);
                }
                corpResp.setChangeLogMap(combinedChangeLogMap);

            }

            LinkedList<KnLIEventDTO> liEventlist = corpResp.getLiEventList();
            knLogger.debug(methodName, "LI event list from the corporate module - ", liEventlist);
            if (liEventlist != null) {
                eventDTOList.addAll(liEventlist);
            }
            knLogger.debug(methodName, "eventDTOList final in end - ", eventDTOList);
            String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResp);
            notifier.sendEtagMcsNotifications(xcapDiffList);
            xcapDiffList = commonMediator.fetchXcapDiffList(xcapDiffList, xdmPttServerId, null);
            knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
            notifier.setMaxNotfnsPerJob(2);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);

            commonMediator.sendTGSModeChangeNotification(corpResp.getTgsModeChgMap());

            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(corpResp.getChangeLogMap(), subsProfileInfoDTO.getCorpId());
            }

            // after success sending LI notification ..
            // send the dto .as of LI Notification . ...
            KnLIEventHandler.logLI(eventDTOList);
            // updating the Pegs
            Collection<Integer> successPegs = new ArrayList<Integer>();
            successPegs.add(KnOMConstants.XDM_NUM_SUBSCR_UPDATED);
            Collection<Integer> listOfPegs = provRespDTO.getSuccessPegs();
            if (listOfPegs != null && !listOfPegs.isEmpty()) {
                for (int pegId : listOfPegs) {
                    successPegs.add(pegId);
                }
            }
            KnStatisticsManagerImpl.getInstance().increment(successPegs);
            /*
             * Spawning a new thread for update of the DISPATCH_GRP_MEMBER FLAG
             * of Members of the dispatch groups that has been deleted
             */
            Collection<String> deletedMemberList = corpResp.getDisabledDispatchMemList();
            knLogger.debug(methodName, "deletedMemberList - ", KnGDPRTemplate.mdnList(deletedMemberList));
            // If deleted members list id not null and not empty start job to
            // update DISPATCH_GROUP_MEMBER field
            if (deletedMemberList != null && !deletedMemberList.isEmpty()) {
                knLogger.debug(methodName, "Calling Dispatch group member job - ");
                List<KnDispGrpMemChecker> jobList = new ArrayList<KnDispGrpMemChecker>(1);
                KnDispGrpMemChecker dispGrpMemCheckerJob = new KnDispGrpMemChecker();
                dispGrpMemCheckerJob.setMaxNotificationSize(maxNotificationSize);
                dispGrpMemCheckerJob.setUpdatedMdn(subsProvInputDTO.getMdn());
                // dispGrpMemCheckerJob.setSyncNotfyThresold(500);
                dispGrpMemCheckerJob.setCorpId(subsProfileInfoDTO.getCorpId());
                dispGrpMemCheckerJob.setDeletedMembers(corpResp.getDisabledDispatchMemList());
                jobList.add(dispGrpMemCheckerJob);
                try {
                    knLogger.debug(methodName, "Scheduling the Jobs - ", jobList);
                    scheduler.addRamJob(jobList, KnJobConstants.JOB_GROUP_NAME);
                } catch (KnJobSchedulerException e) {
                    knLogger.error(methodName, "KnJobSchedulerException occurred while ", "submitting Notification Job to Scheduler - " + e);
                    knLogger.error(methodName, e);
                }
            }

            if (xcapMobileSync) {
                sendModifySubscriberMicroserviceEventNotify(subsProvInputDTO, provRespDTO, subsProfileInfoDTO);
            }

            if (provRespDTO.isActiveFSChanged()) {
                // Starting a thread for resourceList/GroupEtag/DirectoryEtag.
                Map<String, Boolean> mdnListMap = new HashMap<>();
                mdnListMap.put(subsProvInputDTO.getMdn(), provRespDTO.isActiveFSChanged());
                commonMediator.initiateEtagMgmtJob(mdnListMap,UPDATE_SUBSCRIBER);

                boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
                knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClientBit," PV:",subsProfileInfoDTO.getClientPVmajorVer());
                if (xcapMobileSync && (xcapCouchClientBit || subsProfileInfoDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_18 )) {
                    KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                    subscrEXDMSNotifyDto.setMdn(subsProvInputDTO.getMdn());
                    subscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                    subscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(provRespDTO.getActiveFS2()));
                    subscrEXDMSNotifyDto.setActiveFS2(provRespDTO.getActiveFS2());
                    subscrEXDMSNotifyDto.setOldActiveFS(provRespDTO.getOldActiveFS2());
                    subscrEXDMSNotifyDto.setPv(subsProfileInfoDTO.getClientPVmajorVer() + "." + subsProfileInfoDTO.getClientPVminorVer());
                    subscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + subsProvInputDTO.getMdn());
                    subscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                    subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                    subscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                    subscrEXDMSNotifyDto.setLastProfileUpdateTime(provRespDTO.getLastProfileUpdateTime());
                    List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
                    notifyDtoList.add(subscrEXDMSNotifyDto);


                    if(provRespDTO.getProfileMdnActivsFsMap() != null && !provRespDTO.getProfileMdnActivsFsMap().isEmpty())
                    {
                        List<String> mdnList = new ArrayList<>(Optional.ofNullable(provRespDTO.getProfileMdnActivsFsMap())
                                .map(Map::keySet)
                                .orElse(Collections.emptySet()));
                        Map<String, String> onlineSubscribersListByMdn = KnGeneralCacheUtil.getInstance()
                                .getOnlineSubcribersListByMdn(mdnList);
                        List<String> listActiveMdns = new ArrayList<>(onlineSubscribersListByMdn.keySet());
                        provRespDTO.getProfileMdnActivsFsMap().entrySet().removeIf(entry -> !listActiveMdns.contains(entry.getKey()));
                        for (Entry profileMdnFsMap : provRespDTO.getProfileMdnActivsFsMap().entrySet()) {
                            KnSubscrEXDMSNotifyDto profilrMdnSubscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                            profilrMdnSubscrEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                            profilrMdnSubscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                            profilrMdnSubscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(profileMdnFsMap.getValue().toString()));
                            profilrMdnSubscrEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                            if (null != provRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS()) {
                                profilrMdnSubscrEXDMSNotifyDto.setOldActiveFS(provRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS());
                            }
                            profilrMdnSubscrEXDMSNotifyDto.setPv(subsProfileInfoDTO.getClientPVmajorVer() + "." + subsProfileInfoDTO.getClientPVminorVer());
                            profilrMdnSubscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + profileMdnFsMap.getKey().toString());
                            profilrMdnSubscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                            profilrMdnSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                            profilrMdnSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                            profilrMdnSubscrEXDMSNotifyDto.setLastProfileUpdateTime(provRespDTO.getLastProfileUpdateTime());
                            notifyDtoList.add(profilrMdnSubscrEXDMSNotifyDto);
                        }
                    }
                    knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                    commonMediator.startNotifyMicroServicesJob(notifyDtoList);
                    knLogger.debug(methodName, "micro service notify for activeFs change event - Sent");
                }
            }

            if (subsProfileInfoDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_18) {
                knLogger.debug(methodName, "Sending MCS notification");
                commonMediator.sendMCSNotification(provRespDTO.getDirChgDTO(), subsProfileInfoDTO.getMcId(), mcsXcapRootUri);
            }
            if (null != corpResp) {
                boolean notifyStatus = commonMediator.sendMCSGRPNotification(corpResp, allMcsXcapUris, subsProfileInfoDTO.getCorpId());
                knLogger.debug(methodName, "sending Group notification Status: ", notifyStatus);
            }
            if (null != provRespDTO && null != provRespDTO.getProfileMdnEtagMap()) {
                provRespDTO = commonMediator.fetchActiveProfileMdns(provRespDTO, xdmPttServerId);
                boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(provRespDTO.getProfileMdnEtagMap(), provRespDTO.getMcsXcapRootUriMap());
                knLogger.debug(methodName, "sending Profile notification Status: ", profileNotifyStatus);
            }
            if (provRespDTO.getUserProfileMdns() != null && !provRespDTO.getUserProfileMdns().isEmpty()) {
                KnIPUserProfileDTO ipUserProfileDTO = new KnIPUserProfileDTO();
                ipUserProfileDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
                ipUserProfileDTO.setUserProfileMdns(provRespDTO.getUserProfileMdns());

                String deleteUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfileDTO);
                Long transactionId = System.currentTimeMillis();
                knLogger.debug(methodName, "transactionId - ", transactionId);
                KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(String.valueOf(subsProfileInfoDTO.getCorpId()), transactionId.toString()
                        , null, UPM_OPERATION_TYPE.DELETE_USER_PROFILE_MDN.Value(), subsProvInputDTO.getMdn(),
                        UPM_RESOURCE_TYPE.MDN.Value(), deleteUpmJsonString, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                upmJobScheduler.addJob(knAsyncJobDTO);
            }

            // sending the response to the Client
            responseDTO.setEtag(provRespDTO.getEtag());
            knLogger.info(methodName, "EXIT: update Subscriber - ", responseDTO);
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Update subscriber Info", e);
            rollback(persisterTxn);
            if (!e.getErrorCode().equals(NO_CHG_IN_PROFILE)) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            }
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }

    }

    /**
     * this method is specifically used only for updating dispatch grp memeber
     *
     * @param subscribers
     * @param
     * @return
     * @throws KnXDMServerException
     */
    public IXDMResponseDTO updateDispForSubscribers(Map<String, Integer> subscribers, Integer bitNo) throws KnXDMServerException {
        String methodName = "updateDispForSubscribers(Map<String,Integer>)";
        knLogger.info(methodName, "ENTRY: update dispatch for subscribers ");
        knLogger.debug(methodName, "ENTRY: update dispatch for subscribers ",
                subscribers, " bit no- ", bitNo);
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        boolean ownedTxn = false;
        KnOPBulkRespDTO provRespDTO = null;
        Map<String, KnOPDispatchDirChgDTO> mdnDispatchChgDTOMap = null;
        KnPersisterTxn persisterTxn = null;
        List<String> NotifiedMdnsList = new ArrayList<>();
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "Opening the Transaction");
            persisterTxn.open();

            provRespDTO = provClientIntf.updateDispForSubscribers(subscribers, bitNo, persisterTxn);
            knLogger.debug(methodName,"Successfully updated Dispatches for bulk Subscribers  with resp DTO - ",provRespDTO);
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            // send final notification from mediator only (get dir change DTO
            // from response of KnBulkSPC).
            KnXcapDiffNotifyDTO xcapDiffNotifyDTO = null;
            mdnDispatchChgDTOMap = provRespDTO.getMdnDispatcherChgDTOMap();
            // List<KnOPDirChgDTO> dirChgDTOs = provRespDTO.getDirChgDTOs();
            int i = 0;
            List<KnXcapDiffNotifyDTO> xcapDiffList = new ArrayList<KnXcapDiffNotifyDTO>();
            List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
            Map<String, Boolean> mdnListMap = new HashMap<>();
            for (String mdn : mdnDispatchChgDTOMap.keySet()) {
                xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                KnOPDispatchDirChgDTO opDispatchDirChgDTO = mdnDispatchChgDTOMap.get(mdn);
                if ((opDispatchDirChgDTO.getProtoVersion()
                        .matches(com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_REGEX))
                        && (opDispatchDirChgDTO.isActiveFSChanged())) {

                    KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                    profileNotifyDTO.setActiveFeatureSetChange(mdn);
                    xcapDiffNotifyDTO.setProfileNotify(true);
                    profileNotifyDTO.setMdn(mdn);
                    profileNotifyDTO.setPocHome(opDispatchDirChgDTO.getPocHome());
                    profileNotifyDTO.setPresenceHome(opDispatchDirChgDTO.getPresenceHome());
                    profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());
                    xcapDiffNotifyDTO.setProfileNotifyDTO(profileNotifyDTO);
                    mdnListMap.put(mdn, opDispatchDirChgDTO.isActiveFSChanged());
                }

                Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) opDispatchDirChgDTO
                        .getDocChgDTO();
                for (KnOPDocChgDTO chgDTO : chgDocList) {
                    KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                    xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                    xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                    xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                    xcapDocList.add(xcapDiffDocDTO);
                }

                xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                xcapDiffNotifyDTO.setDirNewEtag(opDispatchDirChgDTO.getDirNewEtag());
                xcapDiffNotifyDTO.setDirPrevEtag(opDispatchDirChgDTO.getDirPrevEtag());
                xcapDiffNotifyDTO.setDirURI(opDispatchDirChgDTO.getDirUri());
                xcapDiffNotifyDTO.setXcapRootUri(opDispatchDirChgDTO.getXcapRootURI());
                xcapDiffNotifyDTO.setProtocolVersion(opDispatchDirChgDTO.getProtoVersion());
                xcapDiffNotifyDTO.setPocHome(opDispatchDirChgDTO.getPocHome());
                xcapDiffNotifyDTO.setPresenceHome(opDispatchDirChgDTO.getPresenceHome());

                xcapDiffList.add(xcapDiffNotifyDTO);
                i++;

                boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(opDispatchDirChgDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
                int pv = 1;

                if(opDispatchDirChgDTO.getProtoVersion()!=null ) {
                    if(opDispatchDirChgDTO.getProtoVersion().contains(".")) {
                        pv = Integer.parseInt(opDispatchDirChgDTO.getProtoVersion().substring(0, opDispatchDirChgDTO.getProtoVersion().indexOf(".")));
                    }else{
                        pv= Integer.parseInt(opDispatchDirChgDTO.getProtoVersion());
                    }
                }

                knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClientBit," PV:",pv);
                if (xcapMobileSync && (xcapCouchClientBit || pv >= PROTOCOL_VERSION_18)
                        && opDispatchDirChgDTO.isActiveFSChanged()) {
                    KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                    subscrEXDMSNotifyDto.setMdn(mdn);
                    subscrEXDMSNotifyDto.setCorpid(opDispatchDirChgDTO.getCorpId());
                    subscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(opDispatchDirChgDTO.getActiveFS2()));
                    subscrEXDMSNotifyDto.setActiveFS2(opDispatchDirChgDTO.getActiveFS2());
                    subscrEXDMSNotifyDto.setOldActiveFS(opDispatchDirChgDTO.getOldActiveFS());
                    subscrEXDMSNotifyDto.setPv(opDispatchDirChgDTO.getProtoVersion());
                    subscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                    subscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                    subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                    subscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                    subscrEXDMSNotifyDto.setLastProfileUpdateTime(opDispatchDirChgDTO.getLastProfileUpdateTime());
                    notifyDtoList.add(subscrEXDMSNotifyDto);
                }
                NotifiedMdnsList.add(mdn);
            }
            responseDTO.setMdnListMap(mdnListMap);
            responseDTO.setNotifiedMdnList(NotifiedMdnsList);
            knLogger.debug(methodName, "notifyDtoList :", notifyDtoList);
            knLogger.info(methodName, "Publishing micro service notify  for User event - ");
            commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            knLogger.debug(methodName, "micro service notify for clientTypeChange event - Sent");
            notifier.setMaxNotfnsPerJob(KnMediatorConstants.DEFAULT_NOTIFY_SIZE);
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList);

            knLogger.debug(methodName, "Notification status - ", isNotified);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATED, mdnDispatchChgDTOMap.size());
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName,
                    "Failed to update dispatcher  of Subscriber ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * Method which retrieves the Subscriber Profile Information and populates
     * to the commdto (between wrapper and the Server) and sends the response
     * back to the client (SOAP client etc.) through messaging fw MQ.
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO getSubscriberDetails(IXDMRequestDTO requestDTO) {
        String methodName = "getSubscriberDetails(KnMessage)";
        knLogger.debug(methodName, "ENTRY: get Subscriber Details ");
        KnPersisterTxn persisterTxn = null;
        String mdn = null;
        KnXDMSubsProfileRespDTO responseDTO = new KnXDMSubsProfileRespDTO();
        KnXDMSubsInfoDTO subsInfoDTO = null;
        Map<Integer, Integer> provFSMap = new HashMap<Integer, Integer>();
        try {
            // verify if the received inputDTO is of type KnXDMSubsInfoDTO.
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            knLogger.debug(methodName, "Received input DTO - ", requestDTO);
            if (requestDTO instanceof KnXDMSubsInfoDTO) {
                subsInfoDTO = (KnXDMSubsInfoDTO) requestDTO;
                knLogger.debug(methodName, "received DTO for get Subscriber Details - ", subsInfoDTO);
            } else {
                knLogger.error(methodName, "received an Invalid DTO for get subscriber Details op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return responseDTO;
            }
            //Validating the  MDN Hirarchy
            if (!KnGeneralProfileUtil.validateMDNCCAndHierarchy(subsInfoDTO.getMdn(), subsInfoDTO.getHierarchyType())) {
                knLogger.error(methodName, "Hierarchy flag not valid for the mdn : ", subsInfoDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = null;
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();
            if (subsInfoDTO.getClientType() == PTX_XDMDATA_INTF) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GETBULK_SUBSCR_REQ);
                subscriberInfoDTO.setMdnList(subsInfoDTO.getMdnList());
                subscriberInfoDTO.setMcDataIds(subsInfoDTO.getMcDataIds());
                subscriberInfoDTO.setUserIds(subsInfoDTO.getUserIDs());
                subscriberInfoDTO.setSubsAliasInfoList(provMediator.populateSubsAliasInfoList(subsInfoDTO.getAliasInfoDTOList()));
                subscriberInfoDTO.setAliasMdnList(subsInfoDTO.getAliasMdnList());
                subsProfileInfoDTO = provClientIntf.getSubsDetails(subscriberInfoDTO, TRUE, persisterTxn);
                responseDTO = provMediator.populateRespSubsProfile(responseDTO, subsProfileInfoDTO);
            } else {
                // populating the prov library DTO
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_DETAILS);
                mdn = subsInfoDTO.getMdn();
                subscriberInfoDTO.setMdn(mdn);
                subscriberInfoDTO.setAliasMdn(subsInfoDTO.getAliasMdn());
                subscriberInfoDTO.setUserId(subsInfoDTO.getUserId());
                subscriberInfoDTO.setIfMatch(subsInfoDTO.getIfMatch());
                subscriberInfoDTO.setIfNoneMatch(subsInfoDTO.getIfNoneMatch());
                subscriberInfoDTO.setMcId(subsInfoDTO.getMcId());
                subscriberInfoDTO.setMcPttId(subsInfoDTO.getMcPttId());
                subscriberInfoDTO.setMcVideoId(subsInfoDTO.getMcVideoId());
                subscriberInfoDTO.setMcDataId(subsInfoDTO.getMcDataId());
                subscriberInfoDTO.setAliasInfoDTOList(subsInfoDTO.getAliasInfoDTOList());

                // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
                if (requestDTO.getOperationType() != null && !requestDTO.getOperationType().isEmpty()) {
                    if(mdn!=null && !mdn.isBlank()){
                        commonMediator.validateSubAuthStatus(Collections.singletonList(mdn), persisterTxn);
                    } else if (subsInfoDTO.getUserId()!=null && !subsInfoDTO.getUserId().isBlank()){
                        commonMediator.validateSubAuthStatusByUserId(subsInfoDTO.getUserId(), persisterTxn);
                    }
                }

                // invoking teh prov library api
                subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
                knLogger.debug(methodName, "Retrieved Subscriber Details - ", subsProfileInfoDTO);
                List<PROV_FS_BIT> availableProvFSList = Arrays.asList(PROV_FS_BIT.values());
                knLogger.debug(methodName, "availableProvFSList", availableProvFSList);
                for (PROV_FS_BIT availableProvFS : availableProvFSList) {
                    int provFSBitPos = availableProvFS.value();
                    boolean featureIsEnabled = KnGeneralUtil.getFeatureBitValue(subsProfileInfoDTO.getSubsFS2(), provFSBitPos);
                    if (featureIsEnabled) {
                        provFSMap.put(provFSBitPos, PROVFS_ENABLE.ENABLED.value());
                    } else {
                        provFSMap.put(provFSBitPos, PROVFS_ENABLE.DISABLED.value());
                    }
                    responseDTO.setProvFSMap(provFSMap);
                }
                knLogger.debug(methodName, "Final responseDTO", responseDTO, "provFSMap :", provFSMap);
                subsProfileInfoDTO.setBillingMDN(subsProfileInfoDTO.getMdn());
                if (subsProfileInfoDTO.getPamAccId() != null && subsProfileInfoDTO.getPamAccId() != 0) {
                    KnOPPAMAccInfoDTO pamAccInfo = provClientIntf.getPAMAccInfoFromId(subsProfileInfoDTO.getPamAccId(), true, persisterTxn);
                    knLogger.info(methodName, "Updating the custom map for getBillingMdn - ", KnGDPRTemplate.mdn(pamAccInfo.getBillingMdn()));
                    subsProfileInfoDTO.setBillingMDN(pamAccInfo.getBillingMdn());
                }
                responseDTO = provMediator.populateRespSubscriberProfile(responseDTO, subsProfileInfoDTO);
            }
            commonMediator.getSuccessResponse(responseDTO);
            // Invoking the Custom Invoker for Custom data:
            if (subsInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && subsInfoDTO.getClientType() != PTX_XDMDATA_INTF) {
                KnXDMSubsProvInfoDTO subsProvInfoDTO = new KnXDMSubsProvInfoDTO();
                subsProvInfoDTO.setMdn(subsProfileInfoDTO.getMdn());
                Map<String, Object> customReqMap = new HashMap<String, Object>();
                customReqMap.put(KnMediatorConstants.CUSTOM_PROV_ACTION, KnMediatorConstants.CUSTOM_PROV_VIEW_OP);
                subsProvInfoDTO.setCustomParamMap(customReqMap);
                Object customResp = KnProcessInvokerImpl.getInstance().invokeHook(KnMediatorConstants.CUSTOM_PROV_INVOKER, subsProvInfoDTO);
                knLogger.debug(methodName, "Response from the Custom Prov - ", customResp);
                if (customResp instanceof KnXDMRespDTO) {
                    KnXDMRespDTO customResponseDTO = (KnXDMRespDTO) customResp;
                    if (customResponseDTO.getResponseStatus() == KnConstants.RESPONSE_STATUS.SUCCESS.value()) {
                        responseDTO.setCustomParamMap(customResponseDTO.getCustomParamMap());
                    }
                }
            }
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();
            if (subsInfoDTO.getClientType() == PTX_XDMDATA_INTF) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GETBULK_SUBSCR_REQ_SUCC);
            }
            knLogger.info(methodName, "EXIT: retrieve Subscriber details - ", responseDTO);
            return responseDTO;
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_DETAILS_FAILURE);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to get Subscriber Profile Info", e);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_DETAILS_FAILURE);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_DETAILS_FAILURE);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * @param requestDTO IXDMRequestDTO
     * @return
     */
    public IXDMResponseDTO changeServiceAuthStatus(IXDMRequestDTO requestDTO, KnConstants.MESSAGE_TYPE action) {
        return changeServiceAuthStatus(requestDTO, null, action);
    }

    /**
     * @param message KnMessage
     * @return
     */
    public IXDMResponseDTO changeServiceAuthStatus(KnMessage message) {
        String methodName = "changeServiceAuthStatus(requestDTO)";
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            KnXDMSubsStatusInfoDTO subStatusInfoDTO = (KnXDMSubsStatusInfoDTO) requestDTO;

            //Validating the old MDN Hirarchy
            if(!KnGeneralProfileUtil.validateMDNCCAndHierarchy(subStatusInfoDTO.getMdn(), subStatusInfoDTO.getHierarchyType())){
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }

        } catch (KnXDMServerException e) {
            knLogger.error(methodName,"Failed to Change service auth status of Subscriber ", e);
            return commonMediator.getFailureResponse(responseDTO, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            return commonMediator.getFailureResponse(responseDTO, e);
        }

        return changeServiceAuthStatus(requestDTO, null, KnConstants.MESSAGE_TYPE.NO_ACTION);
    }

    /**
     * method to change Service Auth Status to re-activate or de-activate the
     * subscriber
     *
     * @param requestDTO   IXDMRequestDTO
     * @param persisterTxn
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO changeServiceAuthStatus(IXDMRequestDTO requestDTO, KnPersisterTxn persisterTxn, KnConstants.MESSAGE_TYPE action) {
        String methodName = "changeServiceAuthStatus(KnMessage)";
        knLogger.info(methodName, "ENTRY: change Service Auth Status - ", requestDTO);
        KnXDMSubsStatusInfoDTO subStatusInfoDTO = null;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        boolean ownedTxn = false;
        try {
            // verify if the inputDTO is of KnXDMSubsStatusInfoDTO
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            if (requestDTO instanceof KnXDMSubsStatusInfoDTO) {
                subStatusInfoDTO = (KnXDMSubsStatusInfoDTO) requestDTO;
                knLogger.debug(methodName, "Received DTO for change Service Auth Status - ", subStatusInfoDTO);
            } else {
                knLogger.error(methodName, "received and Invalid DTO for change service auth status op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }

            // opening the transaction
            if (persisterTxn == null) {
                persisterTxn = KnPersisterTxn.getPersisterTxn();
                knLogger.debug(methodName, "Opening the transaction");
                persisterTxn.open();
                ownedTxn = true;
            }
            // populating the prov libraryDTO
            KnIPSubsProvInfoDTO subscriberInfoDTO = new KnIPSubsProvInfoDTO();
            subscriberInfoDTO.setMdn(subStatusInfoDTO.getMdn());
            subscriberInfoDTO.setIfMatch(subStatusInfoDTO.getIfMatch());
            subscriberInfoDTO.setIfNoneMatch(subStatusInfoDTO.getIfNoneMatch());
            subscriberInfoDTO.setServiceAuthStatus(subStatusInfoDTO
                    .getServiceAuthStatus());
            subscriberInfoDTO.setClientType(requestDTO.getClientType());

            KnIPSubscriberInfoDTO subsInfoDTO = new KnIPSubscriberInfoDTO();
            subsInfoDTO.setMdn(subscriberInfoDTO.getMdn());

            // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
            if (requestDTO.getOperationType() != null && !requestDTO.getOperationType().isEmpty()) {
                commonMediator.validateSubAuthStatus(Collections.singletonList(subscriberInfoDTO.getMdn()), persisterTxn);
            }

            //corsscheck
            knLogger.debug(methodName, "retrieving the subscriber profile for mdn "+KnGDPRTemplate.mdn(subsInfoDTO.getMdn()));

            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subsInfoDTO, persisterTxn);

            String pv = String.valueOf(subsProfileInfoDTO.getClientPVmajorVer());
            subscriberInfoDTO.setMcpttCompliance(subsProfileInfoDTO.getMcpttCompliance());

            knLogger.debug(methodName,"pv :"+pv);

            // invoking the prov library
            KnOPChgAuthStatusRespDTO provRespDTO = provClientIntf
                    .changeServiceAuthStatus(subscriberInfoDTO, persisterTxn);
            Integer subsClientType = provRespDTO.getSubsClientType();
            //retriving from db client type config check is enable or disable
            knLogger.debug(methodName,"Subscriber client type :",subsClientType);
            //LMR client type changes
            if (subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.MOBILE_CLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.THIRDPARTYDISPATCHERCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.SGMDNPATCH.value()) {

                KnClientTypeConfigDTO clientTypeConfigDTO = genInfoUtil.getClientTypeConfig(subsClientType, persisterTxn);
                if (clientTypeConfigDTO.getIsEnable() != KnProvConstants.CLIENT_TYPE_CONFIGURATION.ENABLED.value()) {
                    knLogger.error(methodName, "Client type is disabled :", subsClientType);
                    throw new KnProvBOException(KnErrorCodes.BOEntity.CLIENT_TYPE_DISABLED, "Subscriber Client Type is disabled");
                }
            }

            knLogger.debug(methodName, "Response received from Server - ",
                    provRespDTO);

            //MC DEVICE NOTIFY
            if(provRespDTO.isDeleteDeviceNotify()){
                sendDeleteDeviceNotification(TEL_URI_TEMPLATE + subscriberInfoDTO.getMdn());
            }

            //profile mdn notify
            boolean profileMdnNotifystatus = commonMediator.prepareMcxNotifyForProfileMdns(provRespDTO);
            knLogger.debug(methodName,"profileMdnNotifystatus :",profileMdnNotifystatus);

            KnSubscriberInfoDTO knSubscriberInfoDTO = new KnSubscriberInfoDTO();

            //Fetching the boolean value for 45th bit,
            // If it is true then we will call the new REST API.
            boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFs2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
            knLogger.debug(methodName, "xcapCouchClientBit ",xcapCouchClientBit);

            //checking if 45th bit is 0/false or 1/true. If not 0/false then we make the rest call
            if(xcapCouchClientBit){
                //Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                knSubscriberInfoDTO.setMdn(provRespDTO.getMdn());
                knSubscriberInfoDTO.setDisabled(provRespDTO.isSyncDisabled());
                knLogger.debug(methodName, "knSubscriberInfoDTO : mdn",KnGDPRTemplate.mdn(knSubscriberInfoDTO.getMdn()));
                knLogger.debug(methodName, "knSubscriberInfoDTO : sync",knSubscriberInfoDTO.isDisabled());

                //Storing the list of bucket urls in a list
                Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                knLogger.debug(methodName, "bucketUrlList : ",bucketUrlList);
                KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                    List<String> bucketUrl = new ArrayList<>();
                    Integer curClusterId = entry.getKey();
                    knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                    bucketUrl.add(entry.getValue());
                    //REST call for profile creation starts here.
                    KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().updateSyncDocument(knSubscriberInfoDTO, bucketUrl);
                    knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                    if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                        failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                        failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                        failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                        failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_ENABLE.value());
                        if(knSubscriberInfoDTO.isDisabled()) {
                            failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DISABLE.value());
                        }
                        genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    }
                }
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync",xcapMobileSync);
            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(subsProfileInfoDTO.getMdn(),provRespDTO.getActiveFs2(),subsProfileInfoDTO.getActiveFS2(),persisterTxn);
            KnNotificationParamDTO knNotificationParamDTO = new KnNotificationParamDTO();
            knNotificationParamDTO.setPriority(NOTIFICATION_PRIORITY.HIGH.value());
            if(opProvDTO.getDirChgDTO()!=null){
                knLogger.debug(methodName, "TGSS doc changed sending notification");
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(),pv, knNotificationParamDTO );
            }

            String mcsXcapRootUri = genInfoUtil.getMCSXCAPRootURI(subsProfileInfoDTO.getMdn(),persisterTxn );

            // saving the transaction
            if (ownedTxn) {
                knLogger.debug(methodName, "Saving the transaction");
                persisterTxn.save();
            }


            if (subsProfileInfoDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_18) {
                knLogger.debug(methodName, "Sending MCS notification");
                commonMediator.sendMCSNotification(opProvDTO.getDirChgDTO(),subsProfileInfoDTO.getMcId(),mcsXcapRootUri, knNotificationParamDTO);
            }
            knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync);
            if (xcapMobileSync) {
                KnSubscrEXDMSNotifyBulkDTO knSubscrEXDMSNotifyBulkDTO = new KnSubscrEXDMSNotifyBulkDTO();
                //  List contain description of the data: variable name is mdnList as json o/p req
                List<KnSubscrEXDMSNotifyBulkDTO> KnSubscrEXDMSNotifyBulkDToList = new ArrayList<KnSubscrEXDMSNotifyBulkDTO>();

                knSubscrEXDMSNotifyBulkDTO.setId(CHANGE_SERVICE_AUTH_STATUS.value());
                knSubscrEXDMSNotifyBulkDTO.setType(CHANGE_SERVICE_AUTH_STATUS.value());
                knSubscrEXDMSNotifyBulkDTO.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knSubscrEXDMSNotifyBulkDTO.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());

                List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<>();
                KnSubscrEXDMSNotifyDto knSubscrEXDMSNotifyDTO = new KnSubscrEXDMSNotifyDto();
                knSubscrEXDMSNotifyDTO.setMdn(provRespDTO.getMdn());
                setKnSubscriberExdmsNotifyDto(provRespDTO, subsClientType, knSubscrEXDMSNotifyDTO);
                notifyDtoList.add(knSubscrEXDMSNotifyDTO);
                knLogger.debug(methodName, "knSubscrEXDMSNotifyDTO :", knSubscrEXDMSNotifyDTO.toString());

                if (provRespDTO.getProfileMdnList() != null && !provRespDTO.getProfileMdnList().isEmpty()) {
                    provRespDTO.getProfileMdnList().stream().forEach(profileMdn -> {
                        KnSubscrEXDMSNotifyDto profileMdnSubscrEXDMSNotifyDTO = new KnSubscrEXDMSNotifyDto();
                        profileMdnSubscrEXDMSNotifyDTO.setMdn(profileMdn);
                        setKnSubscriberExdmsNotifyDto(provRespDTO, subsClientType, profileMdnSubscrEXDMSNotifyDTO);
                        notifyDtoList.add(profileMdnSubscrEXDMSNotifyDTO);
                    });
                }
                knSubscrEXDMSNotifyBulkDTO.setMdnList(notifyDtoList);
                KnSubscrEXDMSNotifyBulkDToList.add(knSubscrEXDMSNotifyBulkDTO);
                knLogger.debug(methodName, "KnSubscrEXDMSNotifyBulkDToList :", KnSubscrEXDMSNotifyBulkDToList);

                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(KnSubscrEXDMSNotifyBulkDToList);
            }

            // populate the KnXcapDiffNotifyDTO
            // Notification requires the following params
            // 1. Dir Uri, 2. Dir prev etag, 3. Dir new etag,
            // 4. Doc Uri, 5. Doc new etag
            List<KnXcapDiffNotifyDTO> xcapDiffList = new ArrayList<>();
            List<KnOPDirChgDTO> dirChgDTOs = provRespDTO.getDirChgDTOs();
            int serviceAuthStatus = subStatusInfoDTO.getServiceAuthStatus();
            if (dirChgDTOs != null&&!dirChgDTOs.isEmpty()) {
                for(KnOPDirChgDTO dirChgDTO:dirChgDTOs) {
                    KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                    if (serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.DEACTIVATED.value()
                            || serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.PROVISIONED.value()) {
                        if ((dirChgDTO.getProtoVersion().matches(com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_REGEX))
                                && (action.equals(KnConstants.MESSAGE_TYPE.CLIENT_TYPE_CHANGE) || action.equals(KnConstants.MESSAGE_TYPE.USER_CREDENTIAL_CHANGE))) {
                            KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                            if (action.equals(KnConstants.MESSAGE_TYPE.CLIENT_TYPE_CHANGE)) {
                                profileNotifyDTO.setClientTypeChange(String.valueOf(provRespDTO.getSubsClientType()));
                                xcapDiffNotifyDTO.setReason(KnConstants.REASON.CLIENT_TYPE_CHANGE.value());
                            } else if (action.equals(KnConstants.MESSAGE_TYPE.USER_CREDENTIAL_CHANGE)) {
                                profileNotifyDTO.setCredentialChange(dirChgDTO.getMdn());
                                xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_CREDENTIAL_CHANGE.value());
                            }
                            if (provRespDTO.getProfileMdnList() != null && !provRespDTO.getProfileMdnList().isEmpty()) {
                                provRespDTO.getProfileMdnList().stream().forEach(profileMdn -> {
                                    if (profileMdn.equalsIgnoreCase(dirChgDTO.getMdn())) {
                                        profileNotifyDTO.setLastProfileUpdateTimestamp(String.valueOf(provRespDTO.getEtag()));
                                    }
                                });
                            }
                            if (provRespDTO.getMdn().equalsIgnoreCase(dirChgDTO.getMdn())) {
                                profileNotifyDTO.setLastProfileUpdateTimestamp(String.valueOf(provRespDTO.getEtag()));
                            }
                            xcapDiffNotifyDTO.setProfileNotify(true);
                            profileNotifyDTO.setMdn(dirChgDTO.getMdn());
                            profileNotifyDTO.setPocHome(dirChgDTO.getPocHome());
                            profileNotifyDTO.setPresenceHome(dirChgDTO.getPresenceHome());
                            profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());
                            xcapDiffNotifyDTO.setProfileNotifyDTO(profileNotifyDTO);
                        } else if (serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.DEACTIVATED.value()) {
                            xcapDiffNotifyDTO.setDeRegisterNotify(true);
                            KnDeRegisterNotifyDTO deRegisterNotifyDTO = new KnDeRegisterNotifyDTO();
                            deRegisterNotifyDTO.setMdn(dirChgDTO.getMdn());
                            deRegisterNotifyDTO.setPocHome(dirChgDTO.getPocHome());
                            deRegisterNotifyDTO.setPresenceHome(dirChgDTO.getPresenceHome());
                            deRegisterNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.USER_DEACTIVATE.value());
                            xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_DEACTIVATE.value());
                            xcapDiffNotifyDTO.setDeRegisterNotifyDTO(deRegisterNotifyDTO);
                        }

                    }
                    Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                    ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) dirChgDTO.getDocChgDTO();
                    for (KnOPDocChgDTO chgDTO : chgDocList) {
                        KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                        xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                        xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                        xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                        xcapDocList.add(xcapDiffDocDTO);
                    }

                    xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                    xcapDiffNotifyDTO.setDirNewEtag(dirChgDTO.getDirNewEtag());
                    xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTO.getDirPrevEtag());
                    xcapDiffNotifyDTO.setDirURI(dirChgDTO.getDirUri());
                    xcapDiffNotifyDTO.setXcapRootUri(dirChgDTO.getXcapRootURI());
                    xcapDiffNotifyDTO.setProtocolVersion(dirChgDTO.getProtoVersion());
                    xcapDiffNotifyDTO.setPocHome(provRespDTO.getPocServerHome());
                    xcapDiffNotifyDTO.setPresenceHome(provRespDTO.getPresenceServerHome());
                    xcapDiffList.add(xcapDiffNotifyDTO);
                }
                knLogger.debug(methodName, "Notification DTO generated - ", xcapDiffList);
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, knNotificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
            }

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATED);
            if (serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.ACTIVATED.value()) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_ACTIVATED);
            } else if (serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.DEACTIVATED.value()) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_DEACTIVATED);
            }


            // sending the response to the Client
            responseDTO.setEtag(provRespDTO.getEtag());
            knLogger.info(methodName, "EXIT: change Service Auth Status - ");
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            if (ownedTxn) {
                rollback(persisterTxn);
            }
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName,"Failed to Change service auth status of Subscriber ", e);
            if (ownedTxn) {
                rollback(persisterTxn);
            }
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            if (ownedTxn) {
                rollback(persisterTxn);
            }
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /*
     * method to change Service Auth Status to re-activate or de-activate the
     * bulk subscribers
     *
     * @param requestDTO IXDMRequestDTO
     *
     * @param persisterTxn
     *
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO changeServiceAuthStatusBulkSubs(IXDMRequestDTO requestDTO, List<String> mdns, KnPersisterTxn persisterTxn,
                                                           KnConstants.MESSAGE_TYPE action) {
        String methodName = "changeServiceAuthStatusBulkSubs(KnMessage)";
        knLogger.info(methodName,
                "ENTRY: change Service Auth Status for bulk subs- ", requestDTO);
        KnXDMSubsStatusInfoDTO subStatusInfoDTO = null;
        int corpId;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        boolean ownedTxn = false;
        boolean syncdisabled=true;
        Map<String ,Boolean> xcapCapabilityMap= new HashMap<String ,Boolean>();
        try {
            // verify if the inputDTO is of KnXDMSubsStatusInfoDTO
            if (requestDTO instanceof KnXDMSubsStatusInfoDTO) {
                subStatusInfoDTO = (KnXDMSubsStatusInfoDTO) requestDTO;
                knLogger.debug(methodName,
                        "Received DTO for change Service Auth Status - ",
                        subStatusInfoDTO);
            } else {
                knLogger.error(
                        methodName,
                        "received and Invalid DTO for change service auth status op - ",
                        requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO
                        .setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO
                        .setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE
                                .value());
                return responseDTO;
            }

            // opening the transaction
            if (persisterTxn == null) {
                persisterTxn = KnPersisterTxn.getPersisterTxn();
                knLogger.debug(methodName, "Opening the transaction");
                persisterTxn.open();
                ownedTxn = true;
            }

            // populate the Subscriber Prov library DTO
            KnIPBulkSubsProvInfoDTO bulkSubsProvInfoDTO = new KnIPBulkSubsProvInfoDTO();
            corpId=  bulkSubsProvInfoDTO.getCorpID();
            bulkSubsProvInfoDTO.setMdns(mdns);
            bulkSubsProvInfoDTO.setServiceAuthStatus(subStatusInfoDTO
                    .getServiceAuthStatus());
            // calling the Prov Library
            KnOPBulkChgAuthStatusRespDTO respDTO = provClientIntf
                    .changeServiceAuthStatuses(bulkSubsProvInfoDTO,
                            persisterTxn);
            knLogger.debug(
                    methodName,
                    "Successfully changeServiceAuthStatus for bulk Subscribers  with resp DTO - ",
                    respDTO);

            if (ownedTxn) {
                knLogger.debug(methodName, "Saving the transaction");
                persisterTxn.save();
            }

            KnXcapDiffNotifyDTO xcapDiffNotifyDTO = null;
            List<KnOPDirChgDTO> dirChgDTOs = respDTO.getDirChgDTOs();

            int serviceAuthStatus = bulkSubsProvInfoDTO.getServiceAuthStatus();
            int i = 0;
            knLogger.debug(methodName, "mdn size :", bulkSubsProvInfoDTO
                    .getMdns().size());
            knLogger.debug(methodName, "dirChgDTOs :", dirChgDTOs.size());
            List<KnXcapDiffNotifyDTO> xcapDiffList = new ArrayList<KnXcapDiffNotifyDTO>();
            for (String mdn : bulkSubsProvInfoDTO.getMdns()) {
                xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();

                if (serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.DEACTIVATED
                        .value()
                        || serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.PROVISIONED
                        .value()) {
                    if ((dirChgDTOs.get(i).getProtoVersion()
                            .matches(com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_REGEX))
                            && (action
                            .equals(KnConstants.MESSAGE_TYPE.CLIENT_TYPE_CHANGE) || action
                            .equals(KnConstants.MESSAGE_TYPE.USER_CREDENTIAL_CHANGE))) {

                        KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                        if (action
                                .equals(KnConstants.MESSAGE_TYPE.CLIENT_TYPE_CHANGE)) {
                            profileNotifyDTO.setClientTypeChange("1");
                            xcapDiffNotifyDTO
                                    .setReason(KnConstants.REASON.CLIENT_TYPE_CHANGE
                                            .value());
                        } else if (action
                                .equals(KnConstants.MESSAGE_TYPE.USER_CREDENTIAL_CHANGE)) {
                            profileNotifyDTO.setCredentialChange(mdn);
                            xcapDiffNotifyDTO
                                    .setReason(KnConstants.REASON.USER_CREDENTIAL_CHANGE
                                            .value());
                        }
                        xcapDiffNotifyDTO.setProfileNotify(true);
                        profileNotifyDTO.setMdn(mdn);
                        profileNotifyDTO.setPocHome(dirChgDTOs.get(i)
                                .getPocHome());
                        profileNotifyDTO.setPresenceHome(dirChgDTOs.get(i)
                                .getPresenceHome());
                        profileNotifyDTO
                                .setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE
                                        .value());

                        xcapDiffNotifyDTO.setProfileNotifyDTO(profileNotifyDTO);
                    } else {
                        xcapDiffNotifyDTO.setDeRegisterNotify(true);
                        KnDeRegisterNotifyDTO deRegisterNotifyDTO = new KnDeRegisterNotifyDTO();
                        deRegisterNotifyDTO.setMdn(mdn);
                        deRegisterNotifyDTO.setPocHome(dirChgDTOs.get(i)
                                .getPocHome());
                        deRegisterNotifyDTO.setPresenceHome(dirChgDTOs.get(i)
                                .getPresenceHome());
                        deRegisterNotifyDTO
                                .setAction(KnConstants.MESSAGE_TYPE.USER_DEACTIVATE
                                        .value());
                        xcapDiffNotifyDTO
                                .setReason(KnConstants.REASON.USER_DEACTIVATE
                                        .value());
                        xcapDiffNotifyDTO
                                .setDeRegisterNotifyDTO(deRegisterNotifyDTO);
                    }

                }
                Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) dirChgDTOs
                        .get(i).getDocChgDTO();
                for (KnOPDocChgDTO chgDTO : chgDocList) {
                    KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                    xcapDiffDocDTO
                            .setDocChangeType(chgDTO.getDocumentChgType());
                    xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                    xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                    xcapDocList.add(xcapDiffDocDTO);
                }

                xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                xcapDiffNotifyDTO.setDirNewEtag(dirChgDTOs.get(i)
                        .getDirNewEtag());
                xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTOs.get(i)
                        .getDirPrevEtag());
                xcapDiffNotifyDTO.setDirURI(dirChgDTOs.get(i).getDirUri());
                xcapDiffNotifyDTO.setXcapRootUri(dirChgDTOs.get(i)
                        .getXcapRootURI());
                xcapDiffNotifyDTO.setProtocolVersion(dirChgDTOs.get(i)
                        .getProtoVersion());
                xcapDiffNotifyDTO.setPocHome(respDTO.getPocServerHome());
                xcapDiffNotifyDTO.setPresenceHome(respDTO
                        .getPresenceServerHome());

                xcapDiffList.add(xcapDiffNotifyDTO);
                i++;
            }
            syncdisabled=true;
            if(serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.ACTIVATED.value())
                syncdisabled=false;

            KnSubscriberInfoDTO knSubscriberInfoDTO = new KnSubscriberInfoDTO();
            Map<String,String> actFSMap = respDTO.getActiveFSMap2();
            Map<String, Integer> subsClientTypeMap = respDTO.getClientTypeMap();
            knLogger.debug(methodName, "actFSMap and subsClientTypeMap :  ", KnGDPRTemplate.mapKeyMdn(actFSMap), subsClientTypeMap);
            //Storing the list of bucket urls in a list
            Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
            knLogger.debug(methodName, "bucketUrlList : ",bucketUrlList);

            xcapCapabilityMap=KnGeneralUtil.getFeatureBitForBulk(actFSMap, FEATURE_SET.XCAPCOUCHCLIENT.value());
            knLogger.debug(methodName, "xcapCapabilityMap :  ", xcapCapabilityMap);
            //boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(respDTO.getActiveFS(), FEATURE_SET.XCAPCOUCHCLIENT.value());

            for (Map.Entry<String, Boolean> xcapCapabilityMapEntry : xcapCapabilityMap.entrySet())
            {
                if(xcapCapabilityMapEntry.getValue()){
                    knLogger.info(methodName, "Entry - for making sync call !");

                    knSubscriberInfoDTO.setMdn(xcapCapabilityMapEntry.getKey());
                    knSubscriberInfoDTO.setDisabled(syncdisabled);
                    knLogger.debug(methodName, "[ syncDisabled ]",knSubscriberInfoDTO.isDisabled(),
                            "[ mdn ]",KnGDPRTemplate.mdn(knSubscriberInfoDTO.getMdn()));

                    KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                    failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                    genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);

                    for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                        List<String> bucketUrl = new ArrayList<>();
                        Integer curClusterId = entry.getKey();
                        knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                        bucketUrl.add(entry.getValue());
                        //REST call for profile creation starts here.
                        KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().updateSyncDocument(knSubscriberInfoDTO, bucketUrl);
                        knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                        if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                            failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                            failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                            failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                            failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_ENABLE.value());
                            if(knSubscriberInfoDTO.isDisabled()) {
                                failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DISABLE.value());
                            }
                            genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                        }
                    }

                }
            }
            KnNotificationParamDTO knNotificationParamDTO = new KnNotificationParamDTO();
            knNotificationParamDTO.setPriority(NOTIFICATION_PRIORITY.HIGH.value());
            notifier.setMaxNotfnsPerJob(KnMediatorConstants.DEFAULT_NOTIFY_SIZE);
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, knNotificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            if (ownedTxn) {
                knLogger.debug(methodName, "Saving the transaction");
                persisterTxn.save();
            }
            //notification services starts
            if(xcapMobileSync ){
                KnSubscrEXDMSNotifyBulkDTO knSubscrEXDMSNotifyBulkDTO=new KnSubscrEXDMSNotifyBulkDTO();
                List<KnSubscrEXDMSNotifyBulkDTO> knSubscrEXDMSNotifyBulkDTOList=new ArrayList<KnSubscrEXDMSNotifyBulkDTO>();

                knSubscrEXDMSNotifyBulkDTO.setId(CHANGE_SERVICE_AUTH_STATUS.value());
                knSubscrEXDMSNotifyBulkDTO.setType(CHANGE_SERVICE_AUTH_STATUS.value());
                knSubscrEXDMSNotifyBulkDTO.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knSubscrEXDMSNotifyBulkDTO.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());

                List<KnSubscrEXDMSNotifyDto> notifyDtoList= new ArrayList<KnSubscrEXDMSNotifyDto>();


                for (Map.Entry<String, Boolean> xcapCapabilityMapEntry : xcapCapabilityMap.entrySet())
                {
                    if(xcapCapabilityMapEntry.getValue()){
                        KnSubscrEXDMSNotifyDto knSubscrEXDMSNotifyDTO=new KnSubscrEXDMSNotifyDto();
                        knSubscrEXDMSNotifyDTO.setMdn(xcapCapabilityMapEntry.getKey());
                        knSubscrEXDMSNotifyDTO.setCorpid(corpId);
                        knSubscrEXDMSNotifyDTO.setAuthStatus(bulkSubsProvInfoDTO.getServiceAuthStatus());
                        knSubscrEXDMSNotifyDTO.setClientType(subsClientTypeMap.get(xcapCapabilityMapEntry.getKey()));
                        knSubscrEXDMSNotifyDTO.setLastProfileUpdateTime(respDTO.getEtag());
                        notifyDtoList.add(knSubscrEXDMSNotifyDTO);
                    }
                }
                knSubscrEXDMSNotifyBulkDTO.setMdnList(notifyDtoList);
                knSubscrEXDMSNotifyBulkDTOList.add(knSubscrEXDMSNotifyBulkDTO);
                knLogger.debug(methodName,"knSubscrEXDMSNotifyBulkDTOList :",knSubscrEXDMSNotifyBulkDTOList);

                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(knSubscrEXDMSNotifyBulkDTOList);
            }

            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATED);
            if (serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.ACTIVATED
                    .value()) {
                KnStatisticsManagerImpl.getInstance().increment(
                        KnOMConstants.XDM_NUM_SUBSCR_ACTIVATED);
            } else if (serviceAuthStatus == KnConstants.SERVICE_AUTH_STATUS.DEACTIVATED
                    .value()) {
                KnStatisticsManagerImpl.getInstance().increment(
                        KnOMConstants.XDM_NUM_SUBSCR_DEACTIVATED);
            }
            // sending the response to the Client
            knLogger.info(methodName, "EXIT: change Service Auth Status - ",
                    requestDTO);
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName,
                    "Failed to Change service auth status of Subscriber ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * Method which activates the Subscriber and populates to the response
     * commdto (between wrapper and the Server) and sends the response back to
     * the client (HTTP client etc.) through messaging fw MQ.
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO activateSubscriber(KnMessage message) {
        String methodName = "activateSubscriber(IXDMRequestDTO)";
        knLogger.info(methodName, "ENTRY: activate Subscriber  - ");
        KnPersisterTxn persisterTxn = null;
        KnXDMActivateInfoDTO activateInfoDTO = null;
        KnXDMSubsInfoDTO subsInfoDTO = null;
        KnXDMActivateRespDTO responseDTO = new KnXDMActivateRespDTO();
        int serviceAuthStatusFlag = 0;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // verify if the received DTO is of type KnXDMActivateInfoDTO
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMActivateInfoDTO) {
                activateInfoDTO = (KnXDMActivateInfoDTO) requestDTO;
                knLogger.debug(methodName, "Received input DTO to activate subscriber - ", activateInfoDTO);
            } else {
                knLogger.error(methodName, "received and Invalid DTO for activate subscriber op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return responseDTO;
            }
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            //Search temp vaskey table and validate key and find MDN
            /*clientIntf = new KnActivationClientIntf();
            KnIPClientRegistryDTO ipClientRegistryDTO = new KnIPClientRegistryDTO();
            ipClientRegistryDTO.setActivationKey(activateInfoDTO.getActivationKey());
            ipClientRegistryDTO.setServiceName(activateInfoDTO.getServiceName());
            ipClientRegistryDTO.setUserAgentDTO(activateInfoDTO.getUserAgentDTO());
            String mdn = clientIntf.getActClientManager().retrieveMDN(ipClientRegistryDTO);*/

            String mdn;
            KnIPClientRegistryDTO ipClientRegistryDTO = new KnIPClientRegistryDTO();
            int clientType = 1;
            if (activateInfoDTO.getVersion() != null && activateInfoDTO.getVersion().equals("1.0")) {
                //Search temp vaskey table and validate key and find MDN
                clientIntf = new KnActivationClientIntf();
                ipClientRegistryDTO.setActivationKey(activateInfoDTO.getActivationKey());
                ipClientRegistryDTO.setServiceName(activateInfoDTO.getServiceName());
                ipClientRegistryDTO.setUserAgentDTO(activateInfoDTO.getUserAgentDTO());
                mdn = clientIntf.getActClientManager().retrieveMDN(ipClientRegistryDTO);
                clientType = ipClientRegistryDTO.getSubsClientType();
            } else {
                mdn = activateInfoDTO.getMdn();
                clientType = activateInfoDTO.getSubsClientType();
            }
            // populating the library DTO
            KnIPActivateMDNInfoDTO activateMdnInputInfo = new KnIPActivateMDNInfoDTO();
            activateMdnInputInfo.setMdn(mdn);
            activateMdnInputInfo.setIMEI(activateInfoDTO.getIMEI());
            activateMdnInputInfo.setRealm(activateInfoDTO.getRealm());
            activateMdnInputInfo.setUserAgent(activateInfoDTO.getUserAgent());
            activateMdnInputInfo.setUserAgentDTO(activateInfoDTO
                    .getUserAgentDTO());
            activateMdnInputInfo.setSubsClientType(clientType);
            activateMdnInputInfo.setVocoderIdMap(activateInfoDTO.getVocoderIdMap());
            String clientFS2=activateInfoDTO.getClientFeatureSet2()!=null?activateInfoDTO.getClientFeatureSet2():KnGeneralUtil.convertLongToHexString(activateInfoDTO.getClientFeatureSet());
            activateMdnInputInfo.setClientFS2(clientFS2);
            activateMdnInputInfo.setApnName(activateInfoDTO.getApnName());
            if (activateInfoDTO.getSwType() != null) {
                activateMdnInputInfo.setSwType(activateInfoDTO.getSwType());
            }
            if (activateInfoDTO.getPlatformType() != null) {
                activateMdnInputInfo.setPlatformType(activateInfoDTO.getPlatformType());
            }

            KnAuthDTO authDTO = new KnAuthDTO();
            authDTO.setPassword(activateInfoDTO.getAuthDTO().getPassword());
            activateMdnInputInfo.setAuthDTO(authDTO);
            // invoking the prov library API
            knLogger.debug(methodName, "Invoking prov lib with dto - ",
                    activateMdnInputInfo);
            subsInfoDTO = (KnXDMSubsInfoDTO) requestDTO;

            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(mdn);
            subscriberInfoDTO.setIfMatch(subsInfoDTO.getIfMatch());
            subscriberInfoDTO.setIfNoneMatch(subsInfoDTO.getIfNoneMatch());

            // invoking the prov library api
            KnOPSubsProfileInfoDTO subsProfileInfo = provClientIntf
                    .getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            serviceAuthStatusFlag = subsProfileInfo.getServiceAuthStatus();

            if (serviceAuthStatusFlag == 2) {
                KnStatisticsManagerImpl.getInstance().increment(
                        KnOMConstants.XDM_NUM_POC_CLIENT_RE_ACTIVATE_REQ);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(
                        KnOMConstants.XDM_NUM_POC_CLIENT_ACTIVATE_REQ);
            }

            KnOPActivationInfoDTO activateResponse = provClientIntf
                    .activateSubscriber(activateMdnInputInfo, persisterTxn);
            knLogger.info(methodName, "response from the server - ",
                    activateResponse);

            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            if (activateResponse.isCleanUpTGSData()) {
                KnCorpTalkGroupRespDTO respDTO = corpMediator
                        .cleanUpSubsCampedGrps(activateMdnInputInfo.getMdn(),
                                persisterTxn);
                knLogger.info(methodName, " Delete of Scan List ",
                        subsProfileInfo);

                // KnOPSubsProfileInfoDTO subsProfileInfoDTO =
                // provInfoUtil.retrieveSubscriberInfo(mdn, persisterTxn);
                if (respDTO.isModeChange()) {
                    KnTGSModeChgDTO tgsModeChgDTO = new KnTGSModeChgDTO();
                    tgsModeChgDTO.setPocHome(activateResponse.getPocHome());
                    tgsModeChgDTO.setPresenceHome(activateResponse
                            .getPresHome());
                    tgsModeChgDTO.setTgsMode(KnMediatorConstants.OFF_MODE);
                    Map<String, KnTGSModeChgDTO> sehMap = new HashMap<String, KnTGSModeChgDTO>();
                    sehMap.put(subsInfoDTO.getMdn(), tgsModeChgDTO);
                    commonMediator.sendTGSModeChangeNotification(sehMap);
                    knLogger.info(methodName, "sending SEH notification ",
                            sehMap);
                } else {
                    knLogger.info(methodName,
                            " No records are deleted not sending SEH notification ");
                }
            }
            boolean OldGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    activateResponse.getOldActiveFS2(),
                    FEATURE_SET.BROADCASTGROUPSERVICE.value());
            boolean newGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    activateResponse.getActiveFS2(),
                    FEATURE_SET.BROADCASTGROUPSERVICE.value());
            KnCorpResponseDTO corpRespDto = null;

            if (!newGrpBroadcastBit && OldGrpBroadcastBit) {
                corpRespDto = corpMediator.updateGrpBroadcasters(
                        activateMdnInputInfo.getMdn(), persisterTxn);
                knLogger.debug(
                        methodName,
                        "disabled group broadcast members corp Library response - ",
                        corpRespDto);
                if (corpRespDto.getStatus() != 0) {
                    throw new KnXDMServerException(corpRespDto.getStatusCode(),
                            corpRespDto.getMessage());
                }
            }

            // sending the response to the client
            if (activateResponse != null) {
                responseDTO.setMdn(activateResponse.getMdn());
                responseDTO.setXCAPRootURI(activateResponse.getXcapRootUri());
                responseDTO.setXcapRootUri_Wifi(activateResponse
                        .getXcapRootUri_Wifi());
                responseDTO.setXUI(activateResponse.getXui());
                responseDTO.setActiveFeatureSet1(KnGeneralUtil.convertHexStringToLong(activateResponse.getActiveFS2()));
                responseDTO.setActiveFeatureSet2(activateResponse.getActiveFS2());
                responseDTO.setApnName(activateResponse.getApnName());
                responseDTO.setExpiryTime(activateResponse.getExpiryTime());
                responseDTO.setSgwRootUriCellular(activateResponse.getSgwRootUriCellular());
                responseDTO.setSgwRootUriWifi(activateResponse.getSgwRootUriWifi());
                responseDTO.setAuthUriCellular(activateResponse.getAuthUriCellular());
                responseDTO.setAuthUriWifi(activateResponse.getAuthUriWifi());
                responseDTO.setCbBukInfo(activateResponse.getCbBukInfo());
                responseDTO.setSgwAuthMec(activateResponse.getSgwAuthMec());
                responseDTO.setIpvc(activateResponse.getIpvc());
                responseDTO.setIpvcPrefC(activateResponse.getIpvcPrefC());
                responseDTO.setIpvcPrefW(activateResponse.getIpvcPrefW());
                responseDTO.setIpvcMulti(activateResponse.getIpvcMulti());
                responseDTO.setIpvcPrefMulti(activateResponse.getIpvcPrefMulti());
                responseDTO.setSgwLocUriCellular(activateResponse.getSgwLocUriCellular());
                responseDTO.setSgwLocUriWifi(activateResponse.getSgwLocUriWifi());
                responseDTO.setToken(activateResponse.getToken());
                responseDTO.setSubsClientType(String.valueOf(subsProfileInfoDTO.getSubsClientType()));
            }

            /* @autor Shashank -Code for Client PV Upgrade Check */
            int newMajorPV =0;
            if (activateInfoDTO.getUserAgentDTO() != null) {
                String protocolVersion = activateInfoDTO.getUserAgentDTO().getProtocolVersion();
                if (protocolVersion != null) {
                    String[] pv = protocolVersion.split("\\.");
                    if (pv != null && pv[0] != null) {
                        newMajorPV = Integer.parseInt(pv[0]);
                    }
                }
            }
            knLogger.debug(methodName, "New PV is  - ", newMajorPV);
            if(subsProfileInfo.getClientPVmajorVer() != newMajorPV ){
                /*if(subsProfileInfoDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13 && newMajorPV >= PROTOCOL_VERSION_13){
                    knLogger.debug(methodName, "Update public group context from kodiak-poc to oidcxcap - ");
                    pubDocMediator.modifyGroupUriContext(subsProvInputDTO.getMdn(), KnDBUtil.getPttServerId(), persisterTxn);
                }*/
                knLogger.debug(methodName, "If protocol version mismatch then notifying microservice via RMQ -");
                sendNotificationForPVUpgrade(subsProfileInfo,persisterTxn,newMajorPV);
            }

            KnSubscriptionKeyInfoPersistDTO subsInfo = new KnSubscriptionKeyInfoPersistDTO();
            subsInfo.setMdn(ipClientRegistryDTO.getMdn());
            subsInfo.setServiceName(ipClientRegistryDTO.getServiceName());
            subsInfo.setExpiryTime(activateResponse.getExpiryTime());
            subsInfo.setActivationKey(activateInfoDTO.getActivationKey());
            // if MDN is TP client type and if it associated with TP account we are not updating expiry time.
            if (activateResponse.getExpiryTime() != com.kodiak.library.activation.resources.KnConstants.THIRD_PARTY_EXPIRY_TIME) {
                IActClientXDMServerDAO locationServerDAO = KnActivationFactorySelector.getDAOFactory(KnFactorySelector.DB).createXDMServerDAO();
                locationServerDAO.updateExpiryTime(subsInfo, persisterTxn);
            }

            // Initalizing the KnSubscriberInfoDTO
            KnSubscriberInfoDTO knSubscriberInfoDTO = new KnSubscriberInfoDTO();
            // Fetching the boolean value for 45th bit,
            // If it is true then we will call the new REST API.
            boolean xcapCouchClient = KnGeneralUtil.getFeatureBitValue(activateResponse.getActiveFS2(),FEATURE_SET.XCAPCOUCHCLIENT.value());
            // boolean hybridClientSuportBit = false;
            knLogger.debug(methodName, "xcapCouchClient - ",xcapCouchClient);
            // checking if 45th bit is 0/false or 1/true. If not 0/false then we make the rest call
            boolean isPasswordUpdated=!activateResponse.getPassword().equalsIgnoreCase(subsProfileInfo.getClientPassword());
            if (xcapCouchClient && isPasswordUpdated){
                // Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                knSubscriberInfoDTO.setMdn(activateResponse.getMdn());
                knSubscriberInfoDTO.setEmail(activateResponse.getEmail());
                knSubscriberInfoDTO.setDisabled(false);
                knSubscriberInfoDTO.setPassword(activateResponse.getPassword());
                knLogger.debug(methodName, "knSubscriberInfoDTO  ",knSubscriberInfoDTO );

                // Storing the list of bucket urls in a list
                Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                //bucketUrlList.add("http://10.2.1.35:4985/pttdata/_user/");
                knLogger.debug(methodName, "bucketUrlList : ",bucketUrlList);
                KnFailedCBTxnLogDTO failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                    List<String> bucketUrl = new ArrayList<>();
                    Integer curClusterId = entry.getKey();
                    knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                    bucketUrl.add(entry.getValue());
                    //REST call for profile creation starts here.
                    KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().updateSyncDocument(knSubscriberInfoDTO, bucketUrl);
                    knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                    if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                        failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                        failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                        failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                        failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_UPDATE.value());
                        genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    }
                }

            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);

            //Get the RMQ configurations
            // KnMqServiceConfig rmqInfoDto = commonMediator.retrieveServerConfDetails(persisterTxn);

            if((subsProfileInfoDTO.getSubsClientType() == SUBSCRIBERS_CLIENT_TYPE.WIFIONLY.value()) ||
                    (subsProfileInfoDTO.getSubsClientType() == SUBSCRIBERS_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value()) ||
                    (subsProfileInfoDTO.getSubsClientType() == SUBSCRIBERS_CLIENT_TYPE.CROSS_CARRIER_PTT_CLIENT.value()) ||
                    (subsProfileInfoDTO.getSubsClientType() == SUBSCRIBERS_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value())){
                String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
                String appId = subsProfileInfoDTO.getDispatchType() == DISPATCH_TYPE_WEB ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                KnManageSyncUserProfileUtil syncUserProfileUtil = KnManageSyncUserProfileUtil.getInstance();
                KnXDMSubsAliasDetailsReqDTO userAliasDetailsRespDTO = new KnXDMSubsAliasDetailsReqDTO();
                userAliasDetailsRespDTO.setUserid(activateResponse.getMdn());
                String pwd = commonMediator.genTempPassword(activateResponse.getPassword(), subsProfileInfoDTO.getClientPVmajorVer(), appId);
                userAliasDetailsRespDTO.setPwd(pwd);
                userAliasDetailsRespDTO.setGeneratepwd(pwd == null);
                userAliasDetailsRespDTO.setTemppwd(false);
                Map<String, Object> attributes = new HashMap<>();
                attributes.put(MCPTT_ID_OIDC, subsProfileInfoDTO.getMdn());
                attributes.put(MCVIDEO_ID_OIDC, subsProfileInfoDTO.getMcVideoId());
                attributes.put(MCDATA_ID_OIDC, subsProfileInfoDTO.getMcDataId());
                userAliasDetailsRespDTO.setAttributes(attributes);
                KnXDMSubsAliasDetailsRespDTO syncResponseDTO = syncUserProfileUtil.createIDMUserForOIDCMgmt(userAliasDetailsRespDTO, appId, idmFqdn, false, null);
                if (syncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()) {
                    knLogger.error(methodName, "Error for Creating profile in IDM - ", syncResponseDTO.getStatus());
                    responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INTERNAL_ERROR);
                    responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                    throw new KnXDMServerException(responseDTO.getResponseCode(), "Unable to Create IDM Profile");
                }
            }

            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(mdn,activateResponse.getActiveFS2(),activateResponse.getOldActiveFS2(),persisterTxn);

            if(opProvDTO.getDirChgDTO()!=null){
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), String.valueOf(subsProfileInfoDTO.getClientPVmajorVer()));
            }

            String mcsXcapRootUri = genInfoUtil.getMCSXCAPRootURI(mdn,persisterTxn );

            // saving the transaction
            knLogger.info(methodName, "Saving the Transaction ");
            persisterTxn.save();

            if(subsProfileInfoDTO.getClientPVmajorVer()>= PROTOCOL_VERSION_18){
                knLogger.debug(methodName, "Sending MCS notification");
                commonMediator.sendMCSNotification(opProvDTO.getDirChgDTO(),subsProfileInfoDTO.getMcId(),mcsXcapRootUri);
            }

            knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClient," PV:",subsProfileInfoDTO.getClientPVmajorVer());

            //call fro the micro services notification
            if(xcapMobileSync && (xcapCouchClient || subsProfileInfoDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_18 )){

                KnActiEXDMSNotifyDto knActiEXDMSNotifyDto = new KnActiEXDMSNotifyDto();
                knActiEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(activateResponse.getActiveFS2()));
                knActiEXDMSNotifyDto.setActiveFS2(activateResponse.getActiveFS2());
                knActiEXDMSNotifyDto.setOldActiveFS(activateResponse.getOldActiveFS2());
                knActiEXDMSNotifyDto.setMdn(activateResponse.getMdn());
                knActiEXDMSNotifyDto.setCorpid(activateResponse.getCorpId());
                knActiEXDMSNotifyDto.setId(CLIENT_ACTIVATION.value() + KnConstants.LINE_SAPERATOR+ activateResponse.getMdn());
                knActiEXDMSNotifyDto.setType(CLIENT_ACTIVATION.value());
                knActiEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knActiEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                knActiEXDMSNotifyDto.setPv(activateResponse.getPvVersion());
                knActiEXDMSNotifyDto.setClientType(subsProfileInfoDTO.getSubsClientType());
                knActiEXDMSNotifyDto.setDispatchType(subsProfileInfoDTO.getDispatchType());
                knActiEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                knActiEXDMSNotifyDto.setSubsFS2(subsProfileInfoDTO.getSubsFS2());
                knActiEXDMSNotifyDto.setMcId(subsProfileInfoDTO.getMcId());
                knActiEXDMSNotifyDto.setMcdataId(subsProfileInfoDTO.getMcDataId());
                knActiEXDMSNotifyDto.setMcpttId(subsProfileInfoDTO.getMcpttId());
                knActiEXDMSNotifyDto.setMcvideoId(subsProfileInfoDTO.getMcVideoId());
                knActiEXDMSNotifyDto.setNetworkName(subsProfileInfoDTO.getNetworkName());
                //TO-DO: Need to check what should be deviceId.
                knActiEXDMSNotifyDto.setDeviceId(activateResponse.getMdn());
                knActiEXDMSNotifyDto.setSyncGwProfileCreated(isPasswordUpdated ?
                        KnConstants.SYNCGWPROFILECREATED.ENABLED.value() : KnConstants.SYNCGWPROFILECREATED.DISABLED.value());
                /*
                 * if (isPasswordUpdated) {
                 * knActiEXDMSNotifyDto.setSyncGwProfileCreated(KnConstants.SYNCGWPROFILECREATED
                 * .ENABLED.value()); } else {
                 * knActiEXDMSNotifyDto.setSyncGwProfileCreated(KnConstants.SYNCGWPROFILECREATED
                 * .DISABLED.value()); }
                 */
                List<KnActiEXDMSNotifyDto> notifyDtoList = new ArrayList<KnActiEXDMSNotifyDto>();
                notifyDtoList.add(knActiEXDMSNotifyDto);
                // FeatureBit Change:
                KnActiEXDMSNotifyDto featureBitChangeNotify = new KnActiEXDMSNotifyDto();
                featureBitChangeNotify.setActiveFS(KnGeneralUtil.convertHexStringToLong(activateResponse.getActiveFS2()));
                featureBitChangeNotify.setActiveFS2(activateResponse.getActiveFS2());
                featureBitChangeNotify.setOldActiveFS(activateResponse.getOldActiveFS2());
                featureBitChangeNotify.setMdn(activateResponse.getMdn());
                featureBitChangeNotify.setCorpid(activateResponse.getCorpId());
                featureBitChangeNotify.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                featureBitChangeNotify.setType(FEATURE_BIT_CHANGE.value());
                featureBitChangeNotify.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                featureBitChangeNotify.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                featureBitChangeNotify.setPv(activateResponse.getPvVersion());
                featureBitChangeNotify.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());

                notifyDtoList.add(featureBitChangeNotify);

                if(activateResponse.getProfileMdnActivsFsMap()!=null&&!activateResponse.getProfileMdnActivsFsMap().isEmpty())
                {
                    List<String> mdnList = new ArrayList<>(Optional.ofNullable(activateResponse.getProfileMdnActivsFsMap())
                            .map(Map::keySet)
                            .orElse(Collections.emptySet()));
                    Map<String, String> onlineSubscribersListByMdn = KnGeneralCacheUtil.getInstance()
                            .getOnlineSubcribersListByMdn(mdnList);
                    List<String> listActiveMdns = new ArrayList<>(onlineSubscribersListByMdn.keySet());
                    activateResponse.getProfileMdnActivsFsMap().entrySet().removeIf(entry -> !listActiveMdns.contains(entry.getKey()));
                    for (Entry profileMdnFsMap : activateResponse.getProfileMdnActivsFsMap().entrySet()) {
                        KnActiEXDMSNotifyDto profileMdnActiEXDMSNotifyDto = new KnActiEXDMSNotifyDto();
                        profileMdnActiEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(profileMdnFsMap.getValue().toString()));
                        profileMdnActiEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                        // profileMdnActiEXDMSNotifyDto.setOldActiveFS(activateResponse.getOldActiveFS2());
                        profileMdnActiEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                        if(null!=activateResponse.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS()) {
                            profileMdnActiEXDMSNotifyDto.setOldActiveFS(activateResponse.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS());
                        }
                        profileMdnActiEXDMSNotifyDto.setCorpid(activateResponse.getCorpId());
                        profileMdnActiEXDMSNotifyDto.setId(CLIENT_ACTIVATION.value() + KnConstants.LINE_SAPERATOR+ profileMdnFsMap.getKey().toString());
                        profileMdnActiEXDMSNotifyDto.setType(CLIENT_ACTIVATION.value());
                        profileMdnActiEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                        profileMdnActiEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                        profileMdnActiEXDMSNotifyDto.setPv(activateResponse.getPvVersion());
                        profileMdnActiEXDMSNotifyDto.setClientType(subsProfileInfoDTO.getSubsClientType());
                        profileMdnActiEXDMSNotifyDto.setDispatchType(subsProfileInfoDTO.getDispatchType());
                        profileMdnActiEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                        profileMdnActiEXDMSNotifyDto.setSubsFS2(subsProfileInfoDTO.getSubsFS2());
                        profileMdnActiEXDMSNotifyDto.setMcId(subsProfileInfoDTO.getMcId());
                        profileMdnActiEXDMSNotifyDto.setMcdataId(subsProfileInfoDTO.getMcDataId());
                        profileMdnActiEXDMSNotifyDto.setMcpttId(subsProfileInfoDTO.getMcpttId());
                        profileMdnActiEXDMSNotifyDto.setMcvideoId(subsProfileInfoDTO.getMcVideoId());
                        profileMdnActiEXDMSNotifyDto.setNetworkName(subsProfileInfoDTO.getNetworkName());
                        //TO-DO: Need to check what should be deviceId.
                        profileMdnActiEXDMSNotifyDto.setDeviceId(profileMdnFsMap.getKey().toString());
                        profileMdnActiEXDMSNotifyDto.setSyncGwProfileCreated(isPasswordUpdated ?
                                KnConstants.SYNCGWPROFILECREATED.ENABLED.value() : KnConstants.SYNCGWPROFILECREATED.DISABLED.value());
                        notifyDtoList.add(profileMdnActiEXDMSNotifyDto);

                        KnActiEXDMSNotifyDto profilrMdnSubscrEXDMSNotifyDto = new KnActiEXDMSNotifyDto();
                        profilrMdnSubscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(profileMdnFsMap.getValue().toString()));
                        profilrMdnSubscrEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                        profilrMdnSubscrEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                        profilrMdnSubscrEXDMSNotifyDto.setCorpid(activateResponse.getCorpId());
                        if(null!=activateResponse.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS()) {
                            profilrMdnSubscrEXDMSNotifyDto.setOldActiveFS(activateResponse.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS());
                        }
                        profilrMdnSubscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + profileMdnFsMap.getKey().toString());
                        profilrMdnSubscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                        profilrMdnSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                        profilrMdnSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                        profilrMdnSubscrEXDMSNotifyDto.setPv(activateResponse.getPvVersion());
                        profilrMdnSubscrEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                        notifyDtoList.add(profilrMdnSubscrEXDMSNotifyDto);
                    }
                }

                knLogger.debug(methodName,"notifyDtoList :",notifyDtoList);
                knLogger.info(methodName, "Publishing micro service notify for user - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }
            if (corpRespDto != null) {
                // prepare notification and send to notification mgr
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator
                        .prepareNotification(corpRespDto);
                knLogger.debug(methodName, "Sending notifications - ",
                        xcapDiffList);
                notifier.setMaxNotfnsPerJob(2);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
            }
            // Starting a thread for resourceList/GroupEtag/DirectoryEtag.
            Map<String, Boolean> mdnListMap = new HashMap<>();
            mdnListMap.put(mdn, activateResponse.getOldActiveFS1() != activateResponse.getActiveFS1());
            commonMediator.initiateEtagMgmtJob(mdnListMap);

            if(activateResponse != null){
                boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(activateResponse.getProfileMdnEtagMap(),activateResponse.getMcsXcapRootUriMap());
                knLogger.debug(methodName, "sending Profile notification Status: ", profileNotifyStatus);
            }
            knLogger.info(methodName, "EXIT: activate Subscriber - ", responseDTO);
            return commonMediator.getSuccessResponse(responseDTO);
        } catch (KnAuthenticationException e){
            knLogger.error(methodName, "Autherization failed", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_ACTIVATE_FAILURE);
            //responseDTO =  commonMediator.getFailureResponse(responseDTO, e);
            return commonMediator.getFailureResponse(responseDTO, e);
        }catch(KnAASException e){
            knLogger.error(methodName, "Autherization failed", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_ACTIVATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            if (serviceAuthStatusFlag == 2) {
                KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_RE_ACTIVATE_FAILURE);
            } else {
                KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_ACTIVATE_FAILURE);
            }
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to activate Subscriber ", e);
            rollback(persisterTxn);
            if (serviceAuthStatusFlag == 2) {
                KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_RE_ACTIVATE_FAILURE);
            } else {
                KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_ACTIVATE_FAILURE);
            }
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            if (serviceAuthStatusFlag == 2) {
                KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_RE_ACTIVATE_FAILURE);
            } else {
                KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_ACTIVATE_FAILURE);
            }
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * method to retrieve the Subscriber configuration Document
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO getSubscriberConfigDocument(KnMessage message) {
        String methodName = "getSubscriberConfigDocument(KnMessage)";
        knLogger.info(methodName, "get Subscriber Config Document ");
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsInfoDTO subsInfoDTO = null;
        KnXDMSubsConfigDocRespDTO responseDTO = new KnXDMSubsConfigDocRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // verify the input DTO is o type KnXDMSubsInfoDTO
           // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMSubsInfoDTO) {
                subsInfoDTO = (KnXDMSubsInfoDTO) requestDTO;
                knLogger.debug(methodName,
                        "received DTO for get Subscriber config DTO - ",
                        subsInfoDTO);
            } else {
                knLogger.error(methodName,
                        "received and Invalid DTO for get subscriber config doc op - "
                                + requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO
                        .setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO
                        .setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE
                                .value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction ");
            persisterTxn.open();

            // invoking the library to retrieve subscriber config document
            // populating the Library DTO before calling the API
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(subsInfoDTO.getMdn());
            subscriberInfoDTO.setIfMatch(subsInfoDTO.getIfMatch());
            subscriberInfoDTO.setIfNoneMatch(subsInfoDTO.getIfNoneMatch());
            subscriberInfoDTO.setApnName(subsInfoDTO.getApnName());
            subscriberInfoDTO.setMcPttIdFromToken(subsInfoDTO.getMcPttId());
            KnOPSubsConfigDocInfoDTO serverRespDTO = provClientIntf
                    .getSubscriberConfigDocument(subscriberInfoDTO,
                            persisterTxn);
            //pv version validation
            knLogger.info(methodName, "provClientIntf::",
                    provClientIntf,"subscriberInfoDTO::",subscriberInfoDTO);

            KnOPSubsProfileInfoDTO subsProfileInfoDTOForPrivacy = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            //int pvVersion=subsProfileInfoDTO.getSubsClientType();
            knLogger.info(methodName, "subsProfileInfoDTOForPrivacy::",
                    subsProfileInfoDTOForPrivacy);

            int pversion = subsProfileInfoDTOForPrivacy.getClientPVmajorVer();
            Integer privacyExecute =subsProfileInfoDTOForPrivacy.getPrivacyValueToExecute();
            knLogger.info(methodName, "--->privacyExecute getSubscriberConfig API::",
                    privacyExecute);

            knLogger.info(methodName, "pversion::",
                    pversion);

            knLogger.info(methodName, "before - serverRespDTO::",
                    serverRespDTO);

            if(privacyExecute != null && privacyExecute == 1 && pversion>= PROTOCOL_VERSION_16_X) {
                knLogger.info(methodName, "--->if pversion>=PROTOCOL_VERSION_16 equals true:",
                        pversion);
                knLogger.info(methodName, "subsInfoDTO:",
                        subsInfoDTO,"subsInfoDTO.getMdn():",KnGDPRTemplate.mdn(subsInfoDTO.getMdn()));
                Integer listener = findPrivacyOptStatus(subsInfoDTO.getMdn(), true, persisterTxn);
                knLogger.info(methodName, "listener:",
                        listener);
                serverRespDTO.setIsOptInNeeded(listener);

                knLogger.info(methodName, "after - serverRespDTO:",
                        serverRespDTO);
            }
            knLogger.debug(methodName,
                    "retrieve Subscriber config document - ", serverRespDTO);
            responseDTO = provMediator.populateSubsConfigDocument(responseDTO,
                    serverRespDTO);

            knLogger.debug(methodName, "Response DTO from XDM Mediator - ",
                    responseDTO);

            if (serverRespDTO.isCleanUpTGSData()) {
                // get the response , based on it send SEH mode
                KnCorpTalkGroupRespDTO respDTO = corpMediator
                        .cleanUpSubsCampedGrps(subsInfoDTO.getMdn(),
                                persisterTxn);
                knLogger.info(methodName, " Delete of Scan List ");
                if (respDTO.isModeChange()) {
                    KnTGSModeChgDTO tgsModeChgDTO = new KnTGSModeChgDTO();
                    tgsModeChgDTO.setPocHome(serverRespDTO.getPocPttId());
                    tgsModeChgDTO.setPresenceHome(serverRespDTO.getPresPttId());
                    tgsModeChgDTO.setTgsMode(KnMediatorConstants.OFF_MODE);
                    Map<String, KnTGSModeChgDTO> sehMap = new HashMap<String, KnTGSModeChgDTO>();
                    sehMap.put(subsInfoDTO.getMdn(), tgsModeChgDTO);
                    commonMediator.sendTGSModeChangeNotification(sehMap);
                    knLogger.info(methodName, "sending SEH notification ",
                            sehMap);
                } else {
                    knLogger.info(methodName,
                            " No records are deleted not sending SEH notification ");
                }
            }
            boolean OldGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    serverRespDTO.getOldActiveFS2(),
                    FEATURE_SET.BROADCASTGROUPSERVICE.value());
            boolean newGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    serverRespDTO.getActiveFS2(),
                    FEATURE_SET.BROADCASTGROUPSERVICE.value());
            KnCorpResponseDTO corpRespDto = null;

            if (!newGrpBroadcastBit && OldGrpBroadcastBit) {
                corpRespDto = corpMediator.updateGrpBroadcasters(
                        subscriberInfoDTO.getMdn(), persisterTxn);
                knLogger.debug(
                        methodName,
                        "disabled group broadcast members corp Library response - ",
                        corpRespDto);
                if (corpRespDto.getStatus() != 0) {
                    throw new KnXDMServerException(corpRespDto.getStatusCode(),
                            corpRespDto.getMessage());
                }
            }

            KnIPSubscriberInfoDTO subInfoDTO = new KnIPSubscriberInfoDTO();
            subInfoDTO.setMdn(subscriberInfoDTO.getMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subInfoDTO, persisterTxn);
            boolean oldReGroupBit = KnGeneralUtil.getFeatureBitValue(
                    serverRespDTO.getOldActiveFS2(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            boolean newReGroupBit = KnGeneralUtil.getFeatureBitValue(
                    serverRespDTO.getActiveFS2(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());

            if(oldReGroupBit != newReGroupBit){
                knLogger.info(methodName,"notification for preconfigure group");
                KnCorpResponseDTO groupNotifyResp = corpMediator.groupNotifyOnActiveFsChange(subsProfileInfoDTO.getCorpId(),
                        subsProfileInfoDTO.getMdn(), serverRespDTO.getActiveFS2(), serverRespDTO.getOldActiveFS2(), persisterTxn);
                if(corpRespDto!=null && null != corpRespDto.getChangeLogMap()){
                    corpRespDto.getChangeLogMap().putAll(groupNotifyResp.getChangeLogMap());
                }else{
                    corpRespDto=new KnCorpResponseDTO();
                    corpRespDto.setChangeLogMap(groupNotifyResp.getChangeLogMap());
                }
            }

            String pv = String.valueOf(subsProfileInfoDTO.getClientPVmajorVer());

            knLogger.debug(methodName,"pv :"+pv);


            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(subscriberInfoDTO.getMdn(),serverRespDTO.getActiveFS2(),serverRespDTO.getOldActiveFS2(),persisterTxn);

            if(opProvDTO.getDirChgDTO()!=null){
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), pv);
            }

            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);

            //Get All profile MDNs for given Real MDN
            List<String> UserProfileMdns= new ArrayList<String>();
            UserProfileMdns = provMediator.getMdnForUPM(subsProfileInfoDTOForPrivacy.getMdn().toString(), persisterTxn);
            UserProfileMdns.remove(subsProfileInfoDTOForPrivacy.getMdn().toString());
            knLogger.debug(methodName, "UserProfileMdns" ,KnGDPRTemplate.mdnList(UserProfileMdns));

            // saving the transaction
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            //MC DEVICE NOTIFY
            if(serverRespDTO.isDeleteDeviceNotify()){
                sendDeleteDeviceNotification(TEL_URI_TEMPLATE + subsProfileInfoDTO.getMdn());
            }

            // updating the performnace peg
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_SUBSCR_CONFIG_DOC);
            knLogger.info(methodName,
                    "EXIT: get Subscriber config document");
            knLogger.debug(methodName,
                    "EXIT: get Subscriber config document - ", responseDTO);

            if (corpRespDto != null) {
                // prepare notification and send to notification mgr
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator
                        .prepareNotification(corpRespDto);
                knLogger.debug(methodName, "Sending notifications - ",
                        xcapDiffList);
                notifier.setMaxNotfnsPerJob(2);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
            }
            if(serverRespDTO.isActiveFSUpdated()){
                // Starting a thread for resourceList/GroupEtag/DirectoryEtag.
                Map<String, Boolean> mdnListMap = new HashMap<>();
                mdnListMap.put(serverRespDTO.getMdn(), serverRespDTO.isActiveFSUpdated());
                commonMediator.initiateEtagMgmtJob(mdnListMap,GET_SUBSCRIBER_CONFIG_DOC);

                boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(serverRespDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
                knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClientBit," PV:",subsProfileInfoDTO.getClientPVmajorVer());
                if (xcapMobileSync && (xcapCouchClientBit || subsProfileInfoDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_18 )) {
                    KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                    subscrEXDMSNotifyDto.setMdn(subsInfoDTO.getMdn());
                    subscrEXDMSNotifyDto.setCorpid(subsProfileInfoDTO.getCorpId());
                    subscrEXDMSNotifyDto.setActiveFS2(serverRespDTO.getActiveFS2());
                    subscrEXDMSNotifyDto.setOldActiveFS(serverRespDTO.getOldActiveFS2());
                    subscrEXDMSNotifyDto.setPv(subsProfileInfoDTO.getClientPVmajorVer() + "." + subsProfileInfoDTO.getClientPVminorVer());
                    subscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + subsInfoDTO.getMdn());
                    subscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                    subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                    subscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                    subscrEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                    List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
                    notifyDtoList.add(subscrEXDMSNotifyDto);

                    if(serverRespDTO.getProfileMdnActivsFsMap()!=null&&!serverRespDTO.getProfileMdnActivsFsMap().isEmpty())
                    {
                        List<String> mdnList = new ArrayList<>(Optional.ofNullable(serverRespDTO.getProfileMdnActivsFsMap())
                                .map(Map::keySet)
                                .orElse(Collections.emptySet()));
                        Map<String, String> onlineSubscribersListByMdn = KnGeneralCacheUtil.getInstance()
                                .getOnlineSubcribersListByMdn(mdnList);
                        List<String> listActiveMdns = new ArrayList<>(onlineSubscribersListByMdn.keySet());
                        serverRespDTO.getProfileMdnActivsFsMap().entrySet().removeIf(entry -> !listActiveMdns.contains(entry.getKey()));
                        for (Entry profileMdnFsMap : serverRespDTO.getProfileMdnActivsFsMap().entrySet()) {
                            KnSubscrEXDMSNotifyDto profilrMdnSubscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                            profilrMdnSubscrEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                            profilrMdnSubscrEXDMSNotifyDto.setCorpid(subsProfileInfoDTO.getCorpId());
                            profilrMdnSubscrEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                            if(null!=serverRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS()) {
                                profilrMdnSubscrEXDMSNotifyDto.setOldActiveFS(serverRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS());
                            }
                            profilrMdnSubscrEXDMSNotifyDto.setPv(subsProfileInfoDTO.getClientPVmajorVer() + "." + subsProfileInfoDTO.getClientPVminorVer());
                            profilrMdnSubscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + profileMdnFsMap.getKey().toString());
                            profilrMdnSubscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                            profilrMdnSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                            profilrMdnSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                            profilrMdnSubscrEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                            notifyDtoList.add(profilrMdnSubscrEXDMSNotifyDto);
                        }
                    }

                    knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                    commonMediator.startNotifyMicroServicesJob(notifyDtoList);
                    knLogger.debug(methodName, "micro service notify for activeFs change event - Sent");
                }
            }
            if(serverRespDTO != null){
                boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(serverRespDTO.getProfileMdnEtagMap(),serverRespDTO.getMcsXcapRootUriMap());
                knLogger.debug(methodName, "sending Profile notification Status: ", profileNotifyStatus);
            }
            boolean upmBit = KnGeneralUtil.getFeatureBitValue(serverRespDTO.getSubscriberFS2(), USER_PROFILE_MGMT_BIT);
            knLogger.debug(methodName, "upmBit is Enabled -",upmBit);

            if(!upmBit)
            {
                //check if it is a Real mdn
                if (subsProfileInfoDTOForPrivacy.getUserProfileIndex()==null||subsProfileInfoDTOForPrivacy.getUserProfileIndex().equals(USER_PROFILE_INDEX)) {
                    if (!UserProfileMdns.isEmpty()) {

                        KnIPUserProfileDTO ipUserProfileDTO=new KnIPUserProfileDTO();
                        ipUserProfileDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
                        ipUserProfileDTO.setUserProfileMdns(UserProfileMdns);

                        String deleteUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfileDTO);
                        Long transactionId = System.currentTimeMillis();
                        knLogger.debug(methodName, "transactionId - ", transactionId);
                        KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(String.valueOf(subsProfileInfoDTO.getCorpId()), transactionId.toString()
                                , null, UPM_OPERATION_TYPE.DELETE_USER_PROFILE_MDN.Value(), subsProfileInfoDTOForPrivacy.getMdn().toString(),
                                UPM_RESOURCE_TYPE.MDN.Value(), deleteUpmJsonString, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                        upmJobScheduler.addJob(knAsyncJobDTO);

                    }
                }
            }
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_SUBSCR_CONFIG_DOC_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to get Subscriber Config Doc ",
                    e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_SUBSCR_CONFIG_DOC_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_SUBSCR_CONFIG_DOC_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }

    }

    /**
     * method to perform the force sync operation
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO forceSync(IXDMRequestDTO requestDTO) {
        String methodName = "forceSync(KnMessage)";
        knLogger.info(methodName, "Force Sync Operation ");
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsInfoDTO subsInfoDTO = null;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        try {
            // verify if the input DTO is of type KnXDMSubsInfoDTO
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            if (requestDTO instanceof KnXDMSubsInfoDTO) {
                subsInfoDTO = (KnXDMSubsInfoDTO) requestDTO;
                knLogger.info(methodName, "received DTO for force sync - ", subsInfoDTO);
            } else {
                knLogger.error(methodName,"received and Invalid DTO for create subscriber op - ", requestDTO);
                responseDTO = new KnXDMSubsConfigDocRespDTO();
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }
            //Validating the  MDN Hirarchy
            if(!KnGeneralProfileUtil.validateMDNCCAndHierarchy(subsInfoDTO.getMdn(), subsInfoDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the mdn : ", subsInfoDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction ");
            persisterTxn.open();
            // populating the prov Library DTO
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            String mdn = subsInfoDTO.getMdn();
            subscriberInfoDTO.setMdn(mdn);

            // invoking the prov library
            KnOPSubsProfileInfoDTO provRespDTO = provClientIntf.forceSync(subscriberInfoDTO, persisterTxn);
            knLogger.debug(methodName,"Force sync operation response from prov library -", provRespDTO);
            pubDocMediator.forceSyncPublicData(mdn, persisterTxn);
            knLogger.debug(methodName,"Force Sync is successful from Public Library");

            if (provRespDTO.getCorporateSubscriptionType() == KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value() ) {
                if(subsInfoDTO.getClientType() != CLIENT_TYPE_CAT_UI){
                    requestDTO.setHierarchyType(HIERARCHY_TYPE.NON_HIERARCHY);
                    subsInfoDTO.setCorpId(String.valueOf(provRespDTO.getCorpId()));
                }
                knLogger.debug(methodName, " corp Library request - ", requestDTO);
                KnXDMCorpRespDTO corpResp = corpMediator.forceSync(requestDTO, persisterTxn);

                int status = corpResp.getResponseStatus();
                knLogger.debug(methodName, " corp Library response - ", corpResp);
                responseDTO.setFailureDetails(corpResp.getFailureDetails());
                if (status != 0) {
                    throw new KnXDMServerException(corpResp.getResponseCode(), corpResp.getResponseMessage());
                }
                knLogger.debug(methodName, "Force Sync validation is successful from Corporate Library");

            }
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();
            // updating the performance Pegs
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_FORCE_SYNC);
            // sending the notification
            commonMediator.sendXcapNotification(provRespDTO.getDirChgtDTO());
            knLogger.info(methodName, "EXIT: force sync operation - ", responseDTO);
            // sending the response to the Client
            return commonMediator.getSuccessResponse(responseDTO);
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_FORCE_SYNC_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to force sync Subscriber ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_FORCE_SYNC_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_FORCE_SYNC_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * method to delete the subscriber this method will invoke various service
     * libraries for deletion of the subscriber data
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO deleteSubscriber(KnMessage message) {
        String methodName = "deleteSubscriber(KnMessage)";
        knLogger.debug(methodName, "Delete Subscriber Request ");
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsInfoDTO subsInfoDTO = null;
        KnXDMCreateRespDTO responseDTO = new KnXDMCreateRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // verifying the received input DTO is of type KnXDMSubsInfoDTO
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            //KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DG_MDN_DELETED_REQ);
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMSubsInfoDTO) {
                subsInfoDTO = (KnXDMSubsInfoDTO) requestDTO;
                knLogger.info(methodName,"Received DTO for Delete Subscriber -  ", subsInfoDTO);
            } else {
                knLogger.error(methodName,"received and Invalid DTO for Delete subscriber op - ", requestDTO);
                responseDTO = new KnXDMCreateRespDTO();
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return responseDTO;
            }
            //Validating the  MDN Hirarchy
            if(!KnGeneralProfileUtil.validateMDNCCAndHierarchy(subsInfoDTO.getMdn(), subsInfoDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the mdn : ", subsInfoDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction ");
            persisterTxn.open();
            String mdn = subsInfoDTO.getMdn();

            LinkedHashSet<String> mdnSet = new LinkedHashSet<>();
            mdnSet.add(mdn);
            knLogger.info(methodName, "mdnSet", mdnSet);
            notifier.sendEtagMcsNotifications(mdnSet);

            // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
            if (subsInfoDTO.getOperationType() != null && !subsInfoDTO.getOperationType().isEmpty()) {
                commonMediator.validateSubAuthStatus(Collections.singletonList(mdn), persisterTxn);
            }

            // retrieve the subscriber profile
            // this profile info will be useful in getting the type of
            // subscriber
            // if subscriber is public then invoke public library for deleting
            // of all grps/contacts
            // if subscriber is corp then invoke corp library for deleting of
            // owned grps/contacts
            if(subsInfoDTO.getClientType() == SUBSCRIBERS_CLIENT_TYPE.DATAGROUPMDN.value()){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DG_MDN_DELETED_REQ);
            }
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(mdn);
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            //check if the mdn is a pseudo mdn then restrict the operation
            if (subsProfileInfoDTO.getPamAccId() != null && subsProfileInfoDTO.getPamAccId() != 0) {
                knLogger.error(methodName, "Mdn is present as a pseudo number,operation not allowed");
                throw new KnProvBOException(KnErrorCodes.BOEntity.MDN_PRESENT_AS_PSEUDOMDN_IN_POCSUBSCRINFO,
                        "Mdn is present as a pseudo mdn in POCSUBSCRINFO");
            }

            final String[] baseMdn = {mdn};
            if (subsProfileInfoDTO.getMcpttId() != null) {
                subscriberInfoDTO.setMcPttIds(Collections.singletonList(subsProfileInfoDTO.getMcpttId()));
                try{
                    KnXDMProfileIdMdnMapRespDTO baseMdnRespDto = provClientIntf.getMdnProfileIdsForMcPttIds(subscriberInfoDTO, false, persisterTxn);
                    Map<String, Map<Integer, String>> profileMdnMap = baseMdnRespDto.getProfileIdMdnMap();
                    Map<Integer, String> baseMdnMapWithProfileIndex = profileMdnMap.get(subsProfileInfoDTO.getMcpttId());
                    Optional<Map.Entry<Integer, String>> baseMdnValue = baseMdnMapWithProfileIndex.entrySet().stream()
                            .filter(map -> map.getKey() == 0).findFirst();
                    baseMdnValue.ifPresent(opMap -> baseMdn[0] = baseMdnValue.get().getValue());
                } catch (KnProvBOException pbe) {
                    knLogger.error(methodName, "Profile not available, so continue further");
                }
            }
            // invoking the corporate library
            // int corpSubscriptionType =
            // subsProfileInfoDTO.getCorporateSubscriptionType();
            // if (corpSubscriptionType ==
            // KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
            knLogger.debug(methodName, "invoking the corporate library ");
            // populating the corporate Library DTO
            KnXDMCorpSubscInfoRequestDTO contactRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
            contactRequestDTO.setSubscriberMdn(subsInfoDTO.getMdn());
            contactRequestDTO.setHierarchyType(subsInfoDTO.getHierarchyType());
            contactRequestDTO.setMcpttCompliance(subsProfileInfoDTO.getMcpttCompliance());
            knLogger.debug(methodName, "invoking the corporate delete subscriber "+contactRequestDTO);
            KnCorpResponseDTO corpResp = corpMediator.deleteSubscriber(contactRequestDTO, persisterTxn);
            int status = corpResp.getStatus();
            knLogger.debug(methodName, " corp Library response - ", corpResp);
            if (status != 0) {
                throw new KnXDMServerException(corpResp.getStatusCode(), corpResp.getMessage());
            }
            knLogger.debug(methodName, "deleted the corporate data for mdn ");
            // }
            //prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResp);
            notifier.sendEtagMcsNotifications(xcapDiffList);
            notifier.sendEtagMcsNotifications(xcapDiffList);
            String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
            xcapDiffList = commonMediator.fetchXcapDiffList(xcapDiffList, xdmPttServerId, null);
            knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, persisterTxn);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            Collection<String> deletedMemberList = corpResp.getDisabledDispatchMemList();
            knLogger.debug(methodName, "deletedMemberList - ", KnGDPRTemplate.mdnList(deletedMemberList));
            commonMediator.sendTGSModeChangeNotification(corpResp.getTgsModeChgMap());
            knLogger.debug(methodName, "Sending LI notifications - ");
            KnLIEventHandler.logLI(corpResp.getLiEventList());
            knLogger.debug(methodName, "Li Notification Send status - ");
            int publicSubscriptionType = subsProfileInfoDTO.getPublicSubscriptionType();
            if (publicSubscriptionType == KnConstants.PUBLIC_SUBSCRIPTION_TYPE.PUBLIC.value()) {
                knLogger.debug(methodName, "invoking the public library");
                pubDocMediator.deleteAllContactsAndGroups(mdn, persisterTxn);
                knLogger.debug(methodName, "deleted public data for mdn ");
            }
            int corpId = subsProfileInfoDTO.getCorpId();
            KnCorpProfileDTO corpProfile = new KnCorpProfileDTO();
            if (corpId != 0) {
                corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, true, persisterTxn);
            }
            int lmrInteropFlag = DISABLED;
            KnCorpConfigInfoDto corpConfigInfoDto = commonInfoUtil.selectLmrInterOpInDB(corpId, persisterTxn);
            KnCorporateExdmsNotifyDto corporateExdmsNotifyDto = null;
            // invoking the prov library for Deleting subscriber profile
            KnOPDeleteSubsRespDTO provRespDTO = provClientIntf.deleteSubscriber(subscriberInfoDTO, persisterTxn);
            knLogger.debug(methodName,"Delete Subscriber operation response - ", provRespDTO);
            // Initializing the KnSubscriberInfoDTO for base RestAPI
            KnSubscriberInfoDTO knSubscriberInfoDTO= new KnSubscriberInfoDTO();
            // Fetching the boolean value for 45th bit, If it is true then we will call the new REST API.
            boolean xcapCouchClient = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
            knLogger.debug(methodName, "xcapCouchClient ", xcapCouchClient);
            // checking if 45th bit is 0/false or 1/true. If not 0/false then we make the rest call
            if (corpId != 0) {
            int corpSubsCount = provInfoUtil.retrieveCorpSubsCount(corpId, persisterTxn);
            knLogger.debug(methodName,"corpSubsCount: ",corpSubsCount);
            if (corpSubsCount == 0) {
                if (corpConfigInfoDto != null && corpConfigInfoDto.getParamValue() != null) {
                    lmrInteropFlag = Integer.parseInt(corpConfigInfoDto.getParamValue());
                    commonInfoUtil.deleteLmrInterOpInDB(corpId, persisterTxn);
                }
                //Notify to MCS
                corpProfile.setNetworkName(null);
                corporateExdmsNotifyDto = commonInfoUtil.formCorpNotifyPayload(DELETE_CORP.value(), corpProfile, lmrInteropFlag, MICROSERVICES_NOTIFY_EVENT_TYPE.CORPORATE_EVENT.value());
            } else if (corpSubsCount == 1){
                responseDTO.setLastSubscriber(true);
            }
            }
            if(xcapCouchClient){
                // Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                knSubscriberInfoDTO.setMdn(provRespDTO.getMdn());
                knLogger.debug(methodName, "knSubscriberInfoDTO : mdn",knSubscriberInfoDTO);
                // Fetching the bucket URLS
                Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                knLogger.debug(methodName, "bucketUrlList : ", bucketUrlList);
                KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                    List<String> bucketUrl = new ArrayList<>();
                    Integer curClusterId = entry.getKey();
                    knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                    bucketUrl.add(entry.getValue());
                    //REST call for profile creation starts here.
                    KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().deleteSyncDocument(knSubscriberInfoDTO, bucketUrl);
                    knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                    if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                        failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                        failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                        failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                        failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DELETE.value());
                        genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    }
                }
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            //Remove mdn from mcpttPermissionsConfig from CBS upm doc
            KnIPUserProfileDTO delMcpttReqDto=new KnIPUserProfileDTO();
            delMcpttReqDto.setMdn(mdn);
            delMcpttReqDto.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId())) ;
            delMcpttReqDto.setPocPttServerId(subsProfileInfoDTO.getPocPttServerId());

            if (persisterTxn.getTransactionStatus() == KnCorpCommonInfoUtil.TXN_STATE.STARTED.ordinal()) {
                corpClientIntf.deleteMcpttPermConfig(delMcpttReqDto, persisterTxn);
            }
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();
            // sending the notification
            // populate the KnXcapDiffNotifyDTO
            // Notification requires the following params
            // 1. Dir Uri, 2. Dir prev etag,
            if (subsProfileInfoDTO.getSubsClientType() != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Alias_MDN.value()
                    && subsProfileInfoDTO.getSubsClientType() != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Group_MDN.value()
                    && subsProfileInfoDTO.getSubsClientType() != KnProvConstants.SUBS_CLIENT_TYPE.DATAGROUPMDN.value() ) {
                KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                KnOPDirChgDTO dirChgDTO = provRespDTO.getDirChgDTO();
                xcapDiffNotifyDTO.setDeRegisterNotify(true);
                KnDeRegisterNotifyDTO deRegisterNotifyDTO = new KnDeRegisterNotifyDTO();
                deRegisterNotifyDTO.setMdn(provRespDTO.getMdn());
                deRegisterNotifyDTO.setPocHome(provRespDTO.getPocServerHome());
                deRegisterNotifyDTO.setPresenceHome(provRespDTO.getPresenceServerHome());
                deRegisterNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.USER_DELETE.value());
                xcapDiffNotifyDTO.setDeRegisterNotifyDTO(deRegisterNotifyDTO);
                // Collection<KnXcapDiffDocDTO> xcapDocList = new
                // ArrayList<KnXcapDiffDocDTO>();
                // xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                // xcapDiffNotifyDTO.setDirNewEtag(dirChgDTO.getDirNewEtag());
                xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTO.getDirPrevEtag());
                xcapDiffNotifyDTO.setDirURI(dirChgDTO.getDirUri());
                xcapDiffNotifyDTO.setXcapRootUri(dirChgDTO.getXcapRootURI());
                xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_DELETE.value());
                xcapDiffNotifyDTO.setProtocolVersion(dirChgDTO.getProtoVersion());
                xcapDiffNotifyDTO.setPocHome(provRespDTO.getPocServerHome());
                xcapDiffNotifyDTO.setPresenceHome(provRespDTO.getPresenceServerHome());
                knLogger.debug(methodName, "Notification DTO generated - ", xcapDiffNotifyDTO);

                // Filtering Inactive mdns, commented the changes as mdn go deleted from system
                //xcapDiffNotifyDTO = commonMediator.fetchMdnsFromXcapDiffNotifyObj(xcapDiffNotifyDTO, xdmPttServerId, null);
                //knLogger.debug(methodName, "Notification DTO generated - ", xcapDiffNotifyDTO);

                KnXcapDiffNotifier xcapDiffNotifier = KnXcapDiffNotifier.getInstance();
                boolean notificationStatus = notifier.sendXcapDiffNotifications(xcapDiffNotifyDTO);
                if (notificationStatus) {
                    knLogger.debug(methodName, "Successfully sent the notification");
                }
            }
            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(corpResp.getChangeLogMap(), subsProfileInfoDTO.getCorpId());
            }
            knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync);
            if(xcapMobileSync){
                KnSubscrEXDMSNotifyDto knSubscrEXDMSNotifyDto= new KnSubscrEXDMSNotifyDto();
                knSubscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                knSubscrEXDMSNotifyDto.setMdn(provRespDTO.getMdn());
                knSubscrEXDMSNotifyDto.setId(DELETE_SUBSCR.value() + KnConstants.LINE_SAPERATOR + provRespDTO.getMdn());
                knSubscrEXDMSNotifyDto.setType(DELETE_SUBSCR.value());
                knSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                knSubscrEXDMSNotifyDto.setClientType(subsProfileInfoDTO.getSubsClientType());
                knSubscrEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                knSubscrEXDMSNotifyDto.setBaseMdn(baseMdn[0]);
                knSubscrEXDMSNotifyDto.setMcpttId(subsProfileInfoDTO.getMcpttId());

                knSubscrEXDMSNotifyDto.setPocPttId(subsProfileInfoDTO.getPoCHome());
                knSubscrEXDMSNotifyDto.setSubsFS2(subsProfileInfoDTO.getSubsFS2());
                knSubscrEXDMSNotifyDto.setMcId(subsProfileInfoDTO.getMcId());
                knSubscrEXDMSNotifyDto.setMcdataId(subsProfileInfoDTO.getMcDataId());
                knSubscrEXDMSNotifyDto.setMcvideoId(subsProfileInfoDTO.getMcVideoId());
                knSubscrEXDMSNotifyDto.setNetworkName(subsProfileInfoDTO.getNetworkName());
                knSubscrEXDMSNotifyDto.setDeviceId(provRespDTO.getMdn());
                List<KnSubscrEXDMSNotifyDto> notifyDtoList= new ArrayList<>();
                notifyDtoList.add(knSubscrEXDMSNotifyDto);
                knLogger.info(methodName, "Publishing micro service notify for user- ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }
            // updating the pegs
            Collection<Integer> successPegs = new ArrayList<Integer>();
            successPegs.add(KnOMConstants.XDM_NUM_SUBSCR_DELETED);
            Collection<Integer> listOfPegs = provRespDTO.getSuccessPegs();
            if (listOfPegs != null && !listOfPegs.isEmpty()) {
                for (int pegId : listOfPegs) {
                    successPegs.add(pegId);
                }
            }
            KnStatisticsManagerImpl.getInstance().increment(successPegs);
            // sending the response to the Client
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getSuccessResponse(responseDTO);
            /*
             * Spawning a new thread for update of the DISPATCH_GRP_MEMBER FLAG
             * of Members of the dispatch groups that has been deleted
             */
            responseDTO.setCorpId(provRespDTO.getCorpId());
            responseDTO.setCorpName(corpProfile.getNetworkName());
            knLogger.debug(methodName, "deletedMemberList - ", KnGDPRTemplate.mdnList(deletedMemberList));
            // If deleted members list id not null and not empty start job to
            // update DISPATCH_GROUP_MEMBER field
            if (deletedMemberList != null && !deletedMemberList.isEmpty()) {
                knLogger.debug(methodName,"Calling Dispatch group member job - ");
                List<KnDispGrpMemChecker> jobList = new ArrayList<KnDispGrpMemChecker>(1);
                KnDispGrpMemChecker dispGrpMemCheckerJob = new KnDispGrpMemChecker();
                dispGrpMemCheckerJob.setMaxNotificationSize(maxNotificationSize);
                // dispGrpMemCheckerJob.setSyncNotfyThresold(500);
                dispGrpMemCheckerJob.setCorpId(subsProfileInfoDTO.getCorpId());
                dispGrpMemCheckerJob.setDeletedMembers(corpResp.getDisabledDispatchMemList());
                jobList.add(dispGrpMemCheckerJob);
                try {
                    knLogger.debug(methodName, "Scheduling the Jobs - ", jobList);
                    scheduler.addRamJob(jobList, KnJobConstants.JOB_GROUP_NAME);
                } catch (KnJobSchedulerException e) {
                    knLogger.error(methodName,"KnJobSchedulerException occurred while ", "submitting Notification Job to Scheduler - " + e);
                    knLogger.error(methodName, e);
                }
            }
            if(!provRespDTO.getUserProfileMdns().isEmpty())
            {
                KnIPUserProfileDTO ipUserProfileDTO=new KnIPUserProfileDTO();
                ipUserProfileDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
                ipUserProfileDTO.setUserProfileMdns(provRespDTO.getUserProfileMdns());

                String deleteUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfileDTO);
                Long transactionId = System.currentTimeMillis();
                knLogger.debug(methodName, "transactionId - ", transactionId);
                KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(String.valueOf(subsProfileInfoDTO.getCorpId()), transactionId.toString()
                        , null, UPM_OPERATION_TYPE.DELETE_USER_PROFILE_MDN.Value(), null,
                        UPM_RESOURCE_TYPE.MDN.Value(), deleteUpmJsonString, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                upmJobScheduler.addJob(knAsyncJobDTO);
            }
            //MC DEVICE NOTIFY
            if(provRespDTO.isDeleteDeviceNotify()){
                sendDeleteDeviceNotification(TEL_URI_TEMPLATE + mdn);
            }
            if (corpResp != null) {
                boolean notifyStatus = commonMediator.sendMCSGRPNotification(corpResp,allMcsXcapUris,subsProfileInfoDTO.getCorpId() );
                knLogger.debug(methodName, "sending Group notification Status: ", notifyStatus);
            }
            if(corporateExdmsNotifyDto != null) {
                knLogger.info(methodName, "Publishing micro service notify for Delete corp- ", corporateExdmsNotifyDto);
                commonMediator.startNotifyMicroServicesJob(List.of(corporateExdmsNotifyDto));
            }
            //place async jobs for clean up of group from user profile if any.
            Collection<Integer> groupIdList = corpResp.getGroupIds();
            if(groupIdList!=null && !groupIdList.isEmpty()) {
                String sharedGroupDelted = KnCorpCommonInfoUtil.ObjToJson(groupIdList);
                Long transactionId = System.nanoTime();
                knLogger.debug(methodName, "transactionId - ", transactionId);
                KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(String.valueOf(subsProfileInfoDTO.getCorpId()), transactionId.toString()
                        , null, UPM_OPERATION_TYPE.DELETE_GROUP_SHARED_USER_PROFILE_NOTIFICATION.Value(), null,
                        UPM_RESOURCE_TYPE.GROUP.Value(), sharedGroupDelted, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                upmJobScheduler.addJob(knAsyncJobDTO);
            }
            if(subsInfoDTO.getClientType() == SUBSCRIBERS_CLIENT_TYPE.DATAGROUPMDN.value() && responseDTO.getResponseStatus() == KnConstants.RESPONSE_STATUS.SUCCESS.value()){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DG_MDN_DELETED_REQ_SUCC);
            }
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_DELETION_FAILURE);
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName,"Failed to delete Subscriber Operation ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_DELETION_FAILURE);
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_DELETION_FAILURE);
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getFailureResponse(responseDTO, e);
        } catch (Throwable e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_DELETION_FAILURE);
            responseDTO = (KnXDMCreateRespDTO) commonMediator.getFailureResponse(responseDTO, new Exception(e));
        }
        knLogger.info(methodName, "EXIT: delete Subscriber operation - ", responseDTO);
        return responseDTO;
    }

    /**
     * method to migrate from one MDN to another MDN
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO changeMdn(KnMessage message) {
        String methodName = "changeMdn(KnMessage)";
        knLogger.debug(methodName, "Change MDN request ");
        KnPersisterTxn persisterTxn = null;
        KnXDMChangeMDNInfoDTO changeMdnInputDTO = null;
        // UCSPROVCONFIG-9013 — return KnXDMCreateRespDTO (subclass of KnXDMRespDTO)
        // so downstream subsmgmt can recover corpId via instanceof check and trigger
        // CAT publish. Backward-compatible: existing instanceof KnXDMRespDTO checks
        // still match this subclass.
        KnXDMCreateRespDTO responseDTO = new KnXDMCreateRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // verify if the input DTO is of type KnXDMChangeMDNInfoDTO
            // IXDMRequestDTO inputDTO = (IXDMRequestDTO) message.getPayLoad();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMChangeMDNInfoDTO) {
                changeMdnInputDTO = (KnXDMChangeMDNInfoDTO) requestDTO;
                knLogger.info(methodName, "received DTO for change MDN - ", changeMdnInputDTO);
            } else {
                knLogger.error(methodName,"received an Invalid DTO for changed MDN op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }

            //Validating the old MDN Hirarchy
            if(changeMdnInputDTO.getOldMDN() != null && !KnGeneralProfileUtil.validateMDNCCAndHierarchy(changeMdnInputDTO.getOldMDN(), changeMdnInputDTO.getHierarchyType())){
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }

            //Validating the old MDN Hirarchy
            if(changeMdnInputDTO.getNewMdn() != null && !KnGeneralProfileUtil.validateMDNCCAndHierarchy(changeMdnInputDTO.getNewMdn(), changeMdnInputDTO.getHierarchyType())){
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction ");
            persisterTxn.open();

            // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
            if (changeMdnInputDTO.getOperationType() != null && !changeMdnInputDTO.getOperationType().isEmpty()) {
                commonMediator.validateSubAuthStatus(Collections.singletonList(changeMdnInputDTO.getOldMDN()), persisterTxn);
            }

            // call Prov/Public/Corp libraries for change MDN API.
            // calling prov library
            KnIPChangeMDNInfoDTO changeMDNInfoDTO = new KnIPChangeMDNInfoDTO();
            changeMDNInfoDTO.setOldMDN(changeMdnInputDTO.getOldMDN());
            changeMDNInfoDTO.setNewMDN(changeMdnInputDTO.getNewMdn());
            changeMDNInfoDTO.setHierarchyType(changeMdnInputDTO.getHierarchyType());
            KnOPSubsProfileInfoDTO provRespDTO = provClientIntf.changeMDN(changeMDNInfoDTO,false, persisterTxn);
            knLogger.debug(methodName, "change MDN response from prov lib - ",provRespDTO);
            // UCSPROVCONFIG-9013 — propagate corpId so subsmgmt can scope CAT publish
            responseDTO.setCorpId(provRespDTO.getCorpId());

            Integer subsClientType = provRespDTO.getSubsClientType();
            //retriving from db/cache client type config check is enable or disable
            //LMR client type changes
            knLogger.debug(methodName,"Subscriber client type for config check :",subsClientType);
            if (subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.MOBILE_CLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.THIRDPARTYDISPATCHERCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value() || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value()
                    || subsClientType == KnConstants.SUBSCRIBERS_CLIENT_TYPE.SGMDNPATCH.value()) {

                KnClientTypeConfigDTO clientTypeConfigDTO = genInfoUtil.getClientTypeConfig(subsClientType, persisterTxn);
                if (clientTypeConfigDTO.getIsEnable() != KnProvConstants.CLIENT_TYPE_CONFIGURATION.ENABLED.value()) {
                    knLogger.error(methodName, "Client type is disabled");
                    throw new KnProvBOException(KnErrorCodes.BOEntity.CLIENT_TYPE_DISABLED, "Subscriber Client Type is disabled");
                }
            }

            pubDocMediator.changeMdn(changeMDNInfoDTO, persisterTxn);
            knLogger.debug(methodName, "change MDN Success from Pub lib.");

            // int corpSubscriptionType =
            // provRespDTO.getCorporateSubscriptionType();
            // if (corpSubscriptionType ==
            // KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
            // populating the corporate Library DTO
            KnXDMCorpSubscInfoRequestDTO corpSubsRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
            corpSubsRequestDTO.setSubscriberMdn(changeMdnInputDTO.getOldMDN());
            corpSubsRequestDTO.setNewMdn(changeMdnInputDTO.getNewMdn());
            corpSubsRequestDTO.setHierarchyType(changeMdnInputDTO.getHierarchyType());
            corpSubsRequestDTO.setMcpttCompliance(provRespDTO.getMcpttCompliance());
            // invoking the corporate library
            KnCorpResponseDTO corpResp = corpMediator.changeMdn(corpSubsRequestDTO, persisterTxn);

            int status = corpResp.getStatus();
            knLogger.debug(methodName, " corp Library response - ", corpResp);
            if (status != 0) {
                throw new KnXDMServerException(corpResp.getStatusCode(), corpResp.getMessage());
            }
            knLogger.debug(methodName, "Change MDN is successful from Corporate Library");
            //prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResp);
            knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, persisterTxn, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);

            knLogger.debug(methodName, "Sending LI notifications - ");
            KnLIEventHandler.logLI(corpResp.getLiEventList());
            knLogger.debug(methodName, "Li Notification Send status - ");
            // }

            provClientIntf.removeSubsInfo(changeMDNInfoDTO, persisterTxn);
            knLogger.debug(methodName,
                    "remove old subs info success from prov lib");


            // creating the Object for calling the cauch base RestAPI
            KnSubscriberInfoDTO knSubscriberInfoDTO= new KnSubscriberInfoDTO();

            // Fetching the boolean value for 45th bit, If it is true then we will call the new REST API.
            boolean xcapCouchClient = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(),FEATURE_SET.XCAPCOUCHCLIENT.value());
            knLogger.debug(methodName, "xcapCouchClient - ",xcapCouchClient);
            // Checking if 45th bit is 0/false or 1/true. If not 0/false then we make the rest call
            if(xcapCouchClient){
                // Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                knSubscriberInfoDTO.setMdn(changeMDNInfoDTO.getOldMDN());
                knLogger.debug(methodName, "mdn", KnGDPRTemplate.mdn(knSubscriberInfoDTO.getMdn()));

                // Fetching the bucket URLS.
                Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                knLogger.debug(methodName, "bucketUrlList : ",bucketUrlList);

                KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                    List<String> bucketUrl = new ArrayList<>();
                    Integer curClusterId = entry.getKey();
                    knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                    bucketUrl.add(entry.getValue());
                    //REST call for profile creation starts here.
                    KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().deleteSyncDocument(knSubscriberInfoDTO, bucketUrl);
                    knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                    if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                        failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                        failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                        failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                        failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DELETE.value());
                        genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    }
                }
            }


            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            // saving the transaction
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();
            // sending the notification
            // commonMediator.sendXcapNotification(provRespDTO.getDirChgtDTO());

            KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
            KnOPDirChgDTO dirChgDTO = provRespDTO.getDirChgtDTO();

            KnDeRegisterNotifyDTO deRegisterNotifyDTO = new KnDeRegisterNotifyDTO();
            deRegisterNotifyDTO.setMdn(provRespDTO.getMdn());
            deRegisterNotifyDTO.setNewMdn(changeMDNInfoDTO.getNewMDN());
            deRegisterNotifyDTO.setPocHome(provRespDTO.getPoCHome());
            deRegisterNotifyDTO.setPresenceHome(provRespDTO.getPresenceHome());
            deRegisterNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.MDN_CHANGE.value());
            xcapDiffNotifyDTO.setDeRegisterNotifyDTO(deRegisterNotifyDTO);
            xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTO.getDirPrevEtag());
            xcapDiffNotifyDTO.setDirURI(dirChgDTO.getDirUri());
            xcapDiffNotifyDTO.setXcapRootUri(dirChgDTO.getXcapRootURI());
            xcapDiffNotifyDTO.setReason(KnConstants.REASON.MDN_CHANGE.value());
            xcapDiffNotifyDTO.setProtocolVersion(dirChgDTO.getProtoVersion());
            xcapDiffNotifyDTO.setPocHome(provRespDTO.getPoCHome());
            xcapDiffNotifyDTO.setPresenceHome(provRespDTO.getPresenceHome());
            xcapDiffNotifyDTO.setChangeMdnNotify(true);
            xcapDiffNotifyDTO.setNtfyOnAnyMDN(dirChgDTO.getNtfyOnAnyMDN());
            knLogger.debug(methodName, "Notification DTO generated - ", xcapDiffNotifyDTO);

            KnXcapDiffNotifier xcapDiffNotifier = KnXcapDiffNotifier.getInstance();
            boolean notificationStatus = notifier.sendXcapDiffNotifications(xcapDiffNotifyDTO);

            for (KnOPDirChgDTO profileMdnDirChgDTO : provRespDTO.getDirChgDTOs()) {
                KnXcapDiffNotifyDTO profilrMdnXcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                profilrMdnXcapDiffNotifyDTO.setDirPrevEtag(profileMdnDirChgDTO.getDirPrevEtag());
                profilrMdnXcapDiffNotifyDTO.setDirURI(profileMdnDirChgDTO.getDirUri());
                profilrMdnXcapDiffNotifyDTO.setXcapRootUri(profileMdnDirChgDTO.getXcapRootURI());
                profilrMdnXcapDiffNotifyDTO.setReason(KnConstants.REASON.MDN_CHANGE.value());
                profilrMdnXcapDiffNotifyDTO.setProtocolVersion(profileMdnDirChgDTO.getProtoVersion());
                profilrMdnXcapDiffNotifyDTO.setPocHome(provRespDTO.getPoCHome());
                profilrMdnXcapDiffNotifyDTO.setPresenceHome(provRespDTO.getPresenceHome());
                profilrMdnXcapDiffNotifyDTO.setNtfyOnAnyMDN(profileMdnDirChgDTO.getNtfyOnAnyMDN());
                knLogger.debug(methodName, "Notification DTO generated for Profile MDN- ", profilrMdnXcapDiffNotifyDTO);
                notificationStatus = notifier.sendXcapDiffNotifications(profilrMdnXcapDiffNotifyDTO);

            }

            if (notificationStatus) {
                knLogger.debug(methodName, "Successfully sent the notification");
            }

            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                commonMediator.startNotifyMicroServicesJob(corpResp.getChangeLogMap(), provRespDTO.getCorpId());
            }
            //Notification to microservices
            if(xcapMobileSync){

                KnSubscrEXDMSNotifyDto knSubscrEXDMSNotifyDto= new KnSubscrEXDMSNotifyDto();
                knSubscrEXDMSNotifyDto.setMdn(provRespDTO.getMdn());
                knSubscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                knSubscrEXDMSNotifyDto.setNewMdn(changeMdnInputDTO.getNewMdn());
                knSubscrEXDMSNotifyDto.setId(CHANGE_MDN.value() + KnConstants.LINE_SAPERATOR + provRespDTO.getMdn());
                knSubscrEXDMSNotifyDto.setType(CHANGE_MDN.value());
                knSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                knSubscrEXDMSNotifyDto.setLastProfileUpdateTime(provRespDTO.getLastActivationTime());
                knSubscrEXDMSNotifyDto.setClientType(subsClientType);
                knSubscrEXDMSNotifyDto.setSubsFS2(provRespDTO.getSubsFS2());
                knSubscrEXDMSNotifyDto.setMcId(provRespDTO.getMcId());
                knSubscrEXDMSNotifyDto.setMcdataId(provRespDTO.getMcDataId());
                knSubscrEXDMSNotifyDto.setMcpttId(provRespDTO.getMcpttId());
                knSubscrEXDMSNotifyDto.setMcvideoId(provRespDTO.getMcVideoId());
                knSubscrEXDMSNotifyDto.setNetworkName(provRespDTO.getNetworkName());
                knSubscrEXDMSNotifyDto.setDeviceId(provRespDTO.getMdn());

                List<KnSubscrEXDMSNotifyDto> notifyDtoList= new ArrayList<>();
                notifyDtoList.add(knSubscrEXDMSNotifyDto);

                knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }

            if(corpResp!=null){
                boolean notifyStatus = commonMediator.sendMCSGRPNotification(corpResp,allMcsXcapUris,provRespDTO.getCorpId());
                knLogger.debug(methodName, "sending Group notification Status: ", notifyStatus);
            }

            if(provRespDTO != null){
                boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(provRespDTO.getProfileMdnEtagMap(),provRespDTO.getMcsXcapRootUriMap());
                knLogger.debug(methodName, "sending Profile notification Status: ", profileNotifyStatus);
            }
            // updating the performance pegs
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_MDN_CHANGE);
            knLogger.info(methodName, "EXIT: Change MDN operation - ",
                    responseDTO);

            // sending the response to the Client
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_MDN_CHANGE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Migrate Subscriber ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_MDN_CHANGE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_MDN_CHANGE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * method to update the network name of the subscriber
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO updateSubscriberName(KnMessage message) {
        String methodName = "updateSubscriberName(KnMessage)";
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsProvInfoDTO subsProvInputDTO = null;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // validating if the received input DTO is KnXDMSubsProvInfoDTO
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            knLogger.info(methodName, "Udpate Subscriber Name request ", requestDTO);
            if (requestDTO instanceof KnXDMSubsProvInfoDTO) {
                subsProvInputDTO = (KnXDMSubsProvInfoDTO) requestDTO;
                knLogger.debug(methodName,"received DTO for update Subscriber Name - ",subsProvInputDTO);
            } else {
                knLogger.error(methodName,"receive an Invalid DTO for update Subscriber Name op - ",requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            KnOPUpdateSubsInfoDTO provRespDTO = null;

            // retrieving the subscriber profile
            knLogger.debug(methodName,"retrieving the subscriber profile for mdn ");
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(subsProvInputDTO.getMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);

            // populate the prov input dto for update subscriber api.
            KnIPSubsProvInfoDTO subsProvInfoDTO = new KnIPSubsProvInfoDTO();
            subsProvInfoDTO.setMdn(subsProvInputDTO.getMdn());
            subsProvInfoDTO.setPublicSubscriptionType(subsProfileInfoDTO.getPublicSubscriptionType());
            subsProvInfoDTO.setCorporateSubscriptionType(subsProfileInfoDTO.getCorporateSubscriptionType());
            subsProvInfoDTO.setNetworkName(subsProvInputDTO.getNetworkName());
            subsProvInfoDTO.setExtCorpId(subsProfileInfoDTO.getExtCorpId());
            subsProvInfoDTO.setPairingInd(subsProfileInfoDTO.getPairingInd());
            subsProvInfoDTO.setAffiliateId(subsProfileInfoDTO.getAffiliateId());
            subsProvInfoDTO.setPayType(subsProfileInfoDTO.getPayType());
            subsProvInfoDTO.setRoamingTypes(subsProfileInfoDTO.getRoamingTypes());
            subsProvInfoDTO.setIfMatch(subsProvInputDTO.getIfMatch());
            subsProvInfoDTO.setHierarchyType(subsProfileInfoDTO.getHierarchyType());
            subsProvInfoDTO.setMcpttIdFromToken(subsProvInputDTO.getMcpttId());

            // invoking the library for updating the subscriberName
            provRespDTO = provClientIntf.updateSubscriber(subsProvInfoDTO,persisterTxn);
            knLogger.debug(methodName, "Response received from Server - ",provRespDTO);
            KnCorpResponseDTO corpRespDTO = null;
            if (subsProfileInfoDTO.getCorporateSubscriptionType() == KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
                // populating the corporate Library DTO
                KnXDMCorpSubscInfoRequestDTO corpSubsRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
                corpSubsRequestDTO.setSubscriberMdn(subsProvInputDTO.getMdn());
                corpSubsRequestDTO.setPublicSubscriptionType(subsProfileInfoDTO.getPublicSubscriptionType());
                corpSubsRequestDTO.setNewPublicSubscriptionType(subsProfileInfoDTO.getPublicSubscriptionType());
                corpSubsRequestDTO.setCorpSubscriptionType(subsProfileInfoDTO.getCorporateSubscriptionType());
                corpSubsRequestDTO.setNewCorpSubscriptionType(subsProfileInfoDTO.getCorporateSubscriptionType());
                corpSubsRequestDTO.setClientType(subsProfileInfoDTO.getSubsClientType());
                if (subsProvInputDTO.getSubscriberClientType() == null) {
                    corpSubsRequestDTO.setNewClientType(subsProfileInfoDTO.getSubsClientType());
                } else {
                    corpSubsRequestDTO.setNewClientType(subsProvInputDTO.getSubscriberClientType());
                }
                corpSubsRequestDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
                corpSubsRequestDTO.setNewCorpId(provRespDTO.getCorpId());
                corpSubsRequestDTO.setName(subsProvInputDTO.getNetworkName());
                corpSubsRequestDTO.setOldName(subsProfileInfoDTO.getNetworkName());
                corpSubsRequestDTO.setHierarchyType(subsProfileInfoDTO.getHierarchyType());

                // invoking the corporate library
                corpRespDTO = corpMediator.updateSubscriber(corpSubsRequestDTO, persisterTxn);
                KnXDMCorpRespDTO corpResp = populateXdmResponse(corpRespDTO);
                int status = corpResp.getResponseStatus();
                knLogger.debug(methodName, " corp Library response - ", corpResp);
                if (status != 0) {
                    throw new KnXDMServerException(corpResp.getResponseCode(), corpResp.getResponseMessage());
                }
                knLogger.debug(methodName, "Update network name is successful from Corporate Library");
            }

            boolean OldGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    subsProfileInfoDTO.getActiveFS2(),FEATURE_SET.BROADCASTGROUPSERVICE.value());
            boolean newGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    provRespDTO.getActiveFS2(),FEATURE_SET.BROADCASTGROUPSERVICE.value());
            KnCorpResponseDTO corpRespDto = null;

            if (!newGrpBroadcastBit && OldGrpBroadcastBit) {
                corpRespDto = corpMediator.updateGrpBroadcasters(subscriberInfoDTO.getMdn(), persisterTxn);
                knLogger.debug(methodName,"disabled group broadcast members corp Library response - ",corpRespDto);
                if (corpRespDto.getStatus() != 0) {
                    throw new KnXDMServerException(corpRespDto.getStatusCode(),corpRespDto.getMessage());
                }

            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            String pv = String.valueOf(subsProfileInfoDTO.getClientPVmajorVer());
            knLogger.debug(methodName, "PV :", pv);

            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(subscriberInfoDTO.getMdn(),provRespDTO.getActiveFS2(),subsProfileInfoDTO.getActiveFS2(),persisterTxn);

            if(opProvDTO.getDirChgDTO()!=null){
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), pv);
            }

            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);

            knLogger.debug(methodName, "saving the transaction ");
            persisterTxn.save();

            // sending the notification
            // commonMediator.sendXcapNotification(provRespDTO.getDirChgDTO(),
            // pv);
            if ((pv.matches(com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_REGEX))
                    && (provRespDTO.isActiveFSChanged()
                    || provRespDTO.isSubsNameChanged() || provRespDTO.isSubsTypeChanged())) {
                KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                if (provRespDTO.isActiveFSChanged()) {
                    profileNotifyDTO.setActiveFeatureSetChange(subsProfileInfoDTO.getMdn());
                }
                if (provRespDTO.isSubsNameChanged()) {
                    profileNotifyDTO.setSubscriberNameChange(subsProfileInfoDTO.getMdn());
                }
                if (provRespDTO.isSubsTypeChanged()) {
                    profileNotifyDTO.setSubscriptionTypeChange(subsProfileInfoDTO.getMdn());
                }
                profileNotifyDTO.setMdn(subsProfileInfoDTO.getMdn());
                profileNotifyDTO.setPocHome(provRespDTO.getDirChgDTO().getPocHome());
                profileNotifyDTO.setPresenceHome(provRespDTO.getDirChgDTO().getPresenceHome());
                profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());

                commonMediator.sendProfileNotification(profileNotifyDTO,provRespDTO.getDirChgDTO(), pv);
            } else {
                commonMediator.sendXcapNotification(provRespDTO.getDirChgDTO(),pv);

            }

            if (corpRespDto != null && corpRespDTO != null) {
                Map<String, KnOPDirChgDTO> updateSubcriberChangeLogMap = corpRespDTO.getChangeLogMap();
                Map<String, KnOPDirChgDTO> updateGrpBroadcastersChangeLogMap = corpRespDto.getChangeLogMap();
                Map<String, KnOPDirChgDTO> combinedChangeLogMap = new HashMap<>();
                if (updateSubcriberChangeLogMap != null) {
                    combinedChangeLogMap.putAll(updateSubcriberChangeLogMap);
                }
                if (updateGrpBroadcastersChangeLogMap != null) {
                    combinedChangeLogMap.putAll(updateGrpBroadcastersChangeLogMap);
                }
                corpRespDTO.setChangeLogMap(combinedChangeLogMap);

            }

            if (corpRespDTO != null) {
                // prepare notification and send to notification mgr
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpRespDTO);
                knLogger.debug(methodName, "Sending notifications - ",xcapDiffList);
                notifier.setMaxNotfnsPerJob(2);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);

                if(xcapMobileSync){
                    knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                    commonMediator.startNotifyMicroServicesJob(corpRespDTO.getChangeLogMap(), subsProfileInfoDTO.getCorpId());
                    sendModifySubscriberMicroserviceEventNotify(subsProvInputDTO, provRespDTO, subsProfileInfoDTO);
                }

                boolean status = commonMediator.sendMCSGRPNotification(corpRespDTO,allMcsXcapUris,subsProfileInfoDTO.getCorpId());
                knLogger.debug(methodName, "sending Group notification Status: ", status);
            }

            // updating the performance Peg
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATED);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_NAME_CHANGE);

            // sending the response to the Client
            responseDTO.setEtag(provRespDTO.getEtag());
            knLogger.info(methodName, "EXIT: update Subscriber Name - ",responseDTO);

            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Update subscriber Name", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }

    }

    public IXDMResponseDTO updateCampedGroup(KnMessage message) {
        String methodName = "updateCampedGroup(KnMessage)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpGroupInfoRequestDTO subsProvInputDTO = null;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // validating if the received input DTO is KnXDMSubsProvInfoDTO
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            knLogger.info(methodName, "updateCampedGroup request ", requestDTO);
            if (requestDTO instanceof KnXDMCorpGroupInfoRequestDTO) {
                subsProvInputDTO = (KnXDMCorpGroupInfoRequestDTO) requestDTO;
                knLogger.debug(methodName,
                        "received DTO for update Subscriber Name - ",
                        subsProvInputDTO);
            } else {
                knLogger.error(
                        methodName,
                        "receive an Invalid DTO for update Subscriber Name op - ",
                        requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO
                        .setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO
                        .setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE
                                .value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            KnOPProvDTO provRespDTO = null;
            knLogger.debug(" MDN ", KnGDPRTemplate.mdn(subsProvInputDTO.getOwnerMdn()),
                    " GroupID ", subsProvInputDTO.getGroupId());
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(subsProvInputDTO.getOwnerMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf
                    .getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            KnXDMTalkGroupRequestDTO talkGroupRequestDTO = new KnXDMTalkGroupRequestDTO();
            KnCorpResponseDTO corpRespDTO = null;
            KnCorpTalkGroupRespDTO corpTalkGroupRespDTO = null;
            KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
            if (subsProvInputDTO.getGroupId() == null) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_TGS_UNCAMPED_GRP_REQ);
                corpTalkGroupRespDTO = corpMediator.cleanUpSubsCampedGrps(
                        subsProvInputDTO.getOwnerMdn(), persisterTxn);
                if (corpTalkGroupRespDTO.getStatus() != 0) {
                    knLogger.info("Request FAILURE ..........", corpRespDTO);
                    throw new KnXDMServerException(corpRespDTO.getStatusCode(),
                            corpRespDTO.getMessage());
                } else {
                    KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_TGS_UNCAMPED_GRP_SUCC_RESP);
                }
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_TGS_CAMPED_GRP_REQ);
                // knLogger.info(methodName, " subsProvInputDTO ",
                // subsProvInputDTO);
                List<KnXDMTalkGroupInfoDTO> addedScanGroups = new ArrayList<KnXDMTalkGroupInfoDTO>();
                List<KnXDMTalkGroupInfoDTO> removeScanGroups = new ArrayList<KnXDMTalkGroupInfoDTO>();
                List<KnXDMTalkGroupInfoDTO> modifiedCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();
                xdmTalkGroupInfoDTO.setGroupId(Integer
                        .parseInt(subsProvInputDTO.getGroupId()));
                xdmTalkGroupInfoDTO.setPriority(99);
                addedScanGroups.add(xdmTalkGroupInfoDTO);
                talkGroupRequestDTO.setCorpId(String.valueOf(subsProfileInfoDTO
                        .getCorpId()));
                talkGroupRequestDTO.setMdn(subsProvInputDTO.getOwnerMdn());
                talkGroupRequestDTO.setMcPttId(subsProvInputDTO.getMcPttId());
                talkGroupRequestDTO.setRemovedCampGrpList(removeScanGroups);
                talkGroupRequestDTO.setModifiedCampGrpList(modifiedCampGrpList);
                talkGroupRequestDTO.setAddedCampGrpList(addedScanGroups);
                talkGroupRequestDTO.setMode(1);
                talkGroupRequestDTO
                        .setClientType(com.kodiak.common.resources.KnConstants.CLIENT_TYPE_XCAP);
                talkGroupRequestDTO.setHierarchyType(subsProfileInfoDTO.getHierarchyType());
                knLogger.info(methodName, "talkGroupRequestDTO ",
                        talkGroupRequestDTO);
                corpRespDTO = corpMediator.modifySubscriberScanList(
                        talkGroupRequestDTO, persisterTxn);
                if (corpRespDTO.getStatus() != 0) {
                    knLogger.info("Request FAILURE ..........", corpRespDTO);
                    throw new KnXDMServerException(corpRespDTO.getStatusCode(),
                            corpRespDTO.getMessage());
                } else {
                    KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_TGS_CAMPED_GRP_SUCC_RESP);
                    //prepare notification and send to notification mgr
                    Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpRespDTO);
                    knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
                    KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                    notificationParamDTO.setCid(message.getCorrelationId());
                    boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, persisterTxn, notificationParamDTO);
                    knLogger.debug(methodName, "Notification status - ", isNotified);
                }
                knLogger.debug("Request corpRespDTO ..........", corpRespDTO);
            }
            knLogger.debug("Response of  corpRespDTO ..........", corpRespDTO);
            // sending the notification
            String pv = String
                    .valueOf(subsProfileInfoDTO.getClientPVmajorVer());
            knLogger.debug(methodName, "PV :", pv);
            provRespDTO = provClientIntf.sendConfigDocNotification(
                    subsProvInputDTO.getOwnerMdn(), persisterTxn);
            commonMediator.sendXcapNotification(provRespDTO.getDirChgDTO(), pv);
            persisterTxn.save();
            // sending the response to the Client
            responseDTO.setEtag(provRespDTO.getEtag());
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Update Camped Group", e);
            rollback(persisterTxn);
            // KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_POC_GRP_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            // KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_POC_GRP_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * method to retrieve Default Subscriber Profile
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO getDefaultSubscriberProfile(IXDMRequestDTO requestDTO) {
        String methodName = "getDefaultSubscriberProfile(IXDMRequestDTO)";
        knLogger.info(methodName, "ENTRY: get Default Subscriber profile -  ",
                requestDTO);
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsProfileRespDTO responseDTO = new KnXDMSubsProfileRespDTO();
        KnXDMSubsInfoDTO subsInfoDTO = null;
        try {
            // verify if the received inputDTO is of type KnXDMSubsInfoDTO.
            knLogger.debug(methodName, "Received input DTO - ", requestDTO);
            if (requestDTO instanceof KnXDMSubsInfoDTO) {
                subsInfoDTO = (KnXDMSubsInfoDTO) requestDTO;
                knLogger.debug(methodName,
                        "received DTO for get default Subscriber profile - ",
                        subsInfoDTO);
            } else {
                knLogger.error(
                        methodName,
                        "received an Invalid DTO for get default subscriber Details op - ",
                        requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO
                        .setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO
                        .setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE
                                .value());
                return responseDTO;
            }
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            // invoking the prov Helper
            responseDTO = provMediator.getDefaultSubscriberProfile(subsInfoDTO,
                    persisterTxn);
            knLogger.debug(methodName, "Retrieved Subscriber Details - ",
                    responseDTO);

            // saving the transaction
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            return responseDTO;

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName,
                    "Failed to get Default Subscriber Profile Info", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } finally {
            knLogger.info(methodName,
                    "EXIT: retrieved default Subscriber details - ",
                    responseDTO);
        }

    }

    /**
     * method to update the Client Feature Set
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO updateClientFS1(KnMessage message) {
        String methodName = "updateClientFS1(KnMessage)";
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsProvInfoDTO subsProvInputDTO = null;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            // validating if the received input DTO is KnXDMSubsProvInfoDTO
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            knLogger.info(methodName, "Udpate Client FS1 request ", requestDTO);
            String operationType = requestDTO.getOperationType();
            int operationId = Integer.parseInt(operationType);
            if (requestDTO instanceof KnXDMSubsProvInfoDTO) {
                subsProvInputDTO = (KnXDMSubsProvInfoDTO) requestDTO;
                knLogger.debug(methodName,
                        "received DTO for update Client FS1 - ",
                        subsProvInputDTO);
            } else {
                knLogger.error(methodName,
                        "receive an Invalid DTO for update Client FS1 op - ",
                        requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO
                        .setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO
                        .setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE
                                .value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            KnOPUpdateSubsInfoDTO provRespDTO = null;

            // retrieving the subscriber profile
            knLogger.debug(methodName,
                    "retrieving the subscriber profile for mdn ");
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(subsProvInputDTO.getMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf
                    .getSubscriberDetails(subscriberInfoDTO, persisterTxn);

            int newMajorPV =0;
            if (subsProvInputDTO.getUserAgentDTO() != null) {
                String protocolVersion = subsProvInputDTO.getUserAgentDTO().getProtocolVersion();
                if (protocolVersion != null) {
                    String[] pv = protocolVersion.split("\\.");
                    if (pv[0] != null) {
                        newMajorPV = Integer.parseInt(pv[0]);
                    }
                }
            }

            knLogger.debug(methodName, "New PV is  - ", newMajorPV);
            knLogger.debug(methodName, "Current PV  - ", subsProfileInfoDTO.getClientPVmajorVer(),
                    " Client Type - ", subsProfileInfoDTO.getSubsClientType());
            if(subsProfileInfoDTO.getClientPVmajorVer() != newMajorPV ){
                /*if(subsProfileInfoDTO.getLicenseType() != ENABLED && newMajorPV >= PROTOCOL_VERSION_14 &&
                        (String.valueOf(subsProfileInfoDTO.getSubsClientType()).matches(CLIENT_TYPE_WIFI_CROSS_NORMAL_RADIO))) {
                    knLogger.error(methodName, "License type is disabled, CC & WIFI can't be upgraded to PV14 and above");
                    throw new KnXDMServerException(KnErrorCodes.BOEntity.UNSUPPORTED_DEVICE, "UNSUPPORTED DEVICE");
                }*/

                if((subsProfileInfoDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13)
                        && (newMajorPV >= PROTOCOL_VERSION_13)
                        && (String.valueOf(subsProfileInfoDTO.getSubsClientType()).matches(CLIENT_TYPE_HS_WIFI_CROSS_NORMAL_RADIO))){
                    knLogger.info(methodName, "Client PV upgrading from pre 13 to 13. Creating OIDC profile");
                    String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
                    String appId = subsProfileInfoDTO.getDispatchType() == DISPATCH_TYPE_WEB ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                    KnManageSyncUserProfileUtil syncUserProfileUtil = KnManageSyncUserProfileUtil.getInstance();
                    KnXDMSubsAliasDetailsReqDTO userAliasDetailsRespDTO = new KnXDMSubsAliasDetailsReqDTO();
                    userAliasDetailsRespDTO.setUserid(subsProfileInfoDTO.getMdn());
                    String pwd = commonMediator.genTempPassword(subsProfileInfoDTO.getClientPassword(), subsProfileInfoDTO.getClientPVmajorVer(), appId);
                    userAliasDetailsRespDTO.setPwd(pwd);
                    userAliasDetailsRespDTO.setGeneratepwd(pwd == null);
                    userAliasDetailsRespDTO.setTemppwd(false);
                    Map<String, Object> attributes = new HashMap<>();
                    attributes.put(MCPTT_ID_OIDC, /*subsProfileInfoDTO.getMcpttId()!=null?subsProfileInfoDTO.getMcpttId():TELURI+*/subsProfileInfoDTO.getMdn());
                    attributes.put(MCVIDEO_ID_OIDC, subsProfileInfoDTO.getMcVideoId()!=null?subsProfileInfoDTO.getMcVideoId():TELURI+subsProfileInfoDTO.getMdn());
                    attributes.put(MCDATA_ID_OIDC, subsProfileInfoDTO.getMcDataId()!=null?subsProfileInfoDTO.getMcDataId():TELURI+subsProfileInfoDTO.getMdn());
                    userAliasDetailsRespDTO.setAttributes(attributes);
                    KnXDMSubsAliasDetailsRespDTO syncResponseDTO = syncUserProfileUtil.createIDMUserForOIDCMgmt(userAliasDetailsRespDTO, appId,
                            idmFqdn, false, null);
                    if (syncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()) {
                        knLogger.error(methodName, "Error for Creating profile in IDM - ", syncResponseDTO.getStatus());
                        responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INTERNAL_ERROR);
                        responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                        throw new KnXDMServerException(responseDTO.getResponseCode(), "Unable to Create IDM Profile");
                    }
                    if(subsProfileInfoDTO.getSubsClientType() == SUBSCRIBERS_CLIENT_TYPE.HANDSET.value() ||
                            subsProfileInfoDTO.getSubsClientType() == SUBSCRIBERS_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value()){
                        // Update device info

                        clientIntf = new KnActivationClientIntf();
                        clientIntf.getActClientManager().updateDeviceInfo(subsProfileInfoDTO.getMdn(),
                                subsProfileInfoDTO.getClientPassword(), persisterTxn);
                    }
                    knLogger.debug(methodName, "saving the transaction ");
                    persisterTxn.save();
                    knLogger.debug(methodName, "If protocol version mismatch then notifying microservice via RMQ -");
                    sendNotificationForPVUpgrade(subsProfileInfoDTO,persisterTxn,newMajorPV);
                    return commonMediator.getSuccessResponse(responseDTO);
                }

            }

            // populate the prov input dto for update subscriber api.
            KnIPSubsProvInfoDTO subsProvInfoDTO = new KnIPSubsProvInfoDTO();
            subsProvInfoDTO.setMdn(subsProvInputDTO.getMdn());
            subsProvInfoDTO.setPublicSubscriptionType(subsProfileInfoDTO
                    .getPublicSubscriptionType());
            subsProvInfoDTO.setCorporateSubscriptionType(subsProfileInfoDTO
                    .getCorporateSubscriptionType());
            subsProvInfoDTO.setNetworkName(subsProfileInfoDTO.getNetworkName());
            subsProvInfoDTO.setExtCorpId(subsProfileInfoDTO.getExtCorpId());
            subsProvInfoDTO.setPairingInd(subsProfileInfoDTO.getPairingInd());
            subsProvInfoDTO.setAffiliateId(subsProfileInfoDTO.getAffiliateId());
            subsProvInfoDTO.setPayType(subsProfileInfoDTO.getPayType());
            subsProvInfoDTO.setRoamingTypes(subsProfileInfoDTO
                    .getRoamingTypes());
            subsProvInfoDTO.setIfMatch(subsProvInputDTO.getIfMatch());
            String clientFS2=subsProvInputDTO.getClientFS2()!=null?subsProvInputDTO.getClientFS2():KnGeneralUtil.convertLongToHexString(subsProvInputDTO.getClientFS1());
            subsProvInfoDTO.setClientFS2(clientFS2);;
            subsProvInfoDTO.setUserAgentDTO(subsProvInputDTO.getUserAgentDTO());
            subsProvInfoDTO.setUserAgent(subsProvInputDTO.getUserAgent());
            subsProvInfoDTO.setVocoderIdMap(subsProvInputDTO.getVocoderIdMap());
            subsProvInfoDTO.setMethod(KnConstants.UPDATE_CLIENT_FS);
            subsProvInfoDTO.setHierarchyType(subsProfileInfoDTO.getHierarchyType());
            subsProvInfoDTO.setMcpttIdFromToken(subsProvInputDTO.getMcpttId());
            if(subsProfileInfoDTO.getMcId()==null)
            {
                //setting empty strings since updateSubscriber populates the default MCIDs if Empty
                subsProvInfoDTO.setMcId("");
                subsProvInfoDTO.setMcpttId("");
                subsProvInfoDTO.setMcDataId("");
                subsProvInfoDTO.setMcVideoId("");
            }
            // invoking the library for updating the subscriberName
            provRespDTO = provClientIntf.updateSubscriber(subsProvInfoDTO,
                    persisterTxn);

            knLogger.debug(methodName, "Response received from Server - ", provRespDTO);

            if (provRespDTO.isCleanUpTGSData()) {
                KnCorpTalkGroupRespDTO respDTO = corpMediator
                        .cleanUpSubsCampedGrps(subsProvInputDTO.getMdn(),
                                persisterTxn);
                knLogger.info(methodName, " Delete of Scan List ");
                if (respDTO.isModeChange()) {
                    KnTGSModeChgDTO tgsModeChgDTO = new KnTGSModeChgDTO();
                    tgsModeChgDTO.setPocHome(provRespDTO.getPocPttId());
                    tgsModeChgDTO.setPresenceHome(provRespDTO.getPresPttId());
                    tgsModeChgDTO.setTgsMode(KnMediatorConstants.OFF_MODE);
                    Map<String, KnTGSModeChgDTO> sehMap = new HashMap<String, KnTGSModeChgDTO>();
                    sehMap.put(subsProvInputDTO.getMdn(), tgsModeChgDTO);
                    knLogger.info(methodName, "sending SEH notification ",
                            sehMap);
                    commonMediator.sendTGSModeChangeNotification(sehMap);
                } else {
                    knLogger.info(methodName,
                            " No records are deleted not sending SEH notification ");
                }
            }
            boolean OldGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    subsProfileInfoDTO.getActiveFS2(),
                    FEATURE_SET.BROADCASTGROUPSERVICE.value());
            boolean newGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(
                    provRespDTO.getActiveFS2(),
                    FEATURE_SET.BROADCASTGROUPSERVICE.value());
            KnCorpResponseDTO corpRespDto = null;
            if (!newGrpBroadcastBit && OldGrpBroadcastBit) {
                corpRespDto = corpMediator.updateGrpBroadcasters(
                        subscriberInfoDTO.getMdn(), persisterTxn);
                knLogger.debug(
                        methodName,
                        "disabled group broadcast members corp Library response - ",
                        corpRespDto);
                if (corpRespDto.getStatus() != 0) {
                    throw new KnXDMServerException(corpRespDto.getStatusCode(),
                            corpRespDto.getMessage());
                }

            }


            //Initalizing the KnSubscriberInfoDTO
            KnSubscriberInfoDTO knSubscriberInfoDTO= new KnSubscriberInfoDTO();

            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            //Fetching the boolean value for 45th bit,
            // If it is true then we will call the new REST API.
            boolean xcapCouchClient = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(),FEATURE_SET.XCAPCOUCHCLIENT.value());
            //checking if 45th bit is 0/false or 1/true. If not 0/false then we make the rest call
            knLogger.debug(methodName, "xcapCouchClient- ",xcapCouchClient);
            if (xcapMobileSync) {
                if(xcapCouchClient){
                    //Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                    knSubscriberInfoDTO.setMdn(subsProfileInfoDTO.getMdn());
                    knSubscriberInfoDTO.setPassword(subsProfileInfoDTO.getClientPassword());
                    knSubscriberInfoDTO.setDisabled(true);
                    if(subsProfileInfoDTO.getServiceAuthStatus() == KnConstants.SERVICE_AUTH_STATUS.ACTIVATED.value()){
                        knSubscriberInfoDTO.setDisabled(false);
                    }
                    knLogger.debug(methodName, "authstatus", subsProfileInfoDTO.getServiceAuthStatus() ,"knSubscriberInfoDTO- ",knSubscriberInfoDTO);
                    //Storing the list of bucket urls in a list
                    Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                    KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                    failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                    genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                        List<String> bucketUrl = new ArrayList<>();
                        Integer curClusterId = entry.getKey();
                        knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                        bucketUrl.add(entry.getValue());
                        //REST call for profile creation starts here.
                        KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().updateSyncDocument(knSubscriberInfoDTO, bucketUrl);
                        knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                        if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                            failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                            failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                            failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                            failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_ENABLE.value());
                            if(knSubscriberInfoDTO.isDisabled()) {
                                failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DISABLE.value());
                            }
                            genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                        }
                    }

                } else {
                    Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                    KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                    failedCBTxnLogDTO.setMdn(subsProfileInfoDTO.getMdn());
                    genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    knSubscriberInfoDTO.setMdn(subsProfileInfoDTO.getMdn());
                    for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                        List<String> bucketUrl = new ArrayList<>();
                        Integer curClusterId = entry.getKey();
                        knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                        bucketUrl.add(entry.getValue());
                        //REST call for profile creation starts here.
                        KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().deleteSyncDocument(knSubscriberInfoDTO, bucketUrl);
                        knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                        if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                            failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                            failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                            failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                            failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DELETE.value());
                            genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                        }
                    }
                }
            }

            // Notify the Micro-Services that the Subscriber's CouchBase support has been disabled/enabled as a Subscriber Hybrid status event
            knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClient," PV:",subsProfileInfoDTO.getClientPVmajorVer());
            if (xcapMobileSync && (xcapCouchClient || subsProfileInfoDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_18 )) {
                String mdn = subsProfileInfoDTO.getMdn();
                Integer corpId = subsProfileInfoDTO.getCorpId();
                KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                subscrEXDMSNotifyDto.setMdn(mdn);
                subscrEXDMSNotifyDto.setCorpid(corpId);
                subscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(provRespDTO.getActiveFS2()));
                subscrEXDMSNotifyDto.setActiveFS2(provRespDTO.getActiveFS2());
                subscrEXDMSNotifyDto.setOldActiveFS(provRespDTO.getOldActiveFS2());
                subscrEXDMSNotifyDto.setPv(subsProfileInfoDTO.getClientPVmajorVer() + ".0");
                subscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                subscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                subscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                subscrEXDMSNotifyDto.setLastProfileUpdateTime(provRespDTO.getLastProfileUpdateTime());
                List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
                notifyDtoList.add(subscrEXDMSNotifyDto);
                if(provRespDTO.getProfileMdnActivsFsMap()!=null&&!provRespDTO.getProfileMdnActivsFsMap().isEmpty())
                {
                    List<String> mdnList = new ArrayList<>(Optional.ofNullable(provRespDTO.getProfileMdnActivsFsMap())
                            .map(Map::keySet)
                            .orElse(Collections.emptySet()));
                    Map<String, String> onlineSubscribersListByMdn = KnGeneralCacheUtil.getInstance()
                            .getOnlineSubcribersListByMdn(mdnList);
                    List<String> listActiveMdns = new ArrayList<>(onlineSubscribersListByMdn.keySet());
                    provRespDTO.getProfileMdnActivsFsMap().entrySet().removeIf(entry -> !listActiveMdns.contains(entry.getKey()));
                    for (Entry profileMdnFsMap : provRespDTO.getProfileMdnActivsFsMap().entrySet()) {
                        KnSubscrEXDMSNotifyDto profilrMdnSubscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                        profilrMdnSubscrEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                        profilrMdnSubscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                        profilrMdnSubscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(profileMdnFsMap.getValue().toString()));
                        profilrMdnSubscrEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                        // profilrMdnSubscrEXDMSNotifyDto.setOldActiveFS(activateResponse.getOldActiveFS2());
                        if(null!=provRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS()) {
                            profilrMdnSubscrEXDMSNotifyDto.setOldActiveFS(provRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS());
                        }
                        profilrMdnSubscrEXDMSNotifyDto.setPv(subsProfileInfoDTO.getClientPVmajorVer() + "." + subsProfileInfoDTO.getClientPVminorVer());
                        profilrMdnSubscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + profileMdnFsMap.getKey().toString());
                        profilrMdnSubscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                        profilrMdnSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                        profilrMdnSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                        profilrMdnSubscrEXDMSNotifyDto.setLastProfileUpdateTime(provRespDTO.getLastProfileUpdateTime());
                        notifyDtoList.add(profilrMdnSubscrEXDMSNotifyDto);
                    }
                }
                knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
                knLogger.debug(methodName, "micro service notify for clientTypeChange event - Sent");
                if(subsProfileInfoDTO.getClientPVmajorVer() != newMajorPV ){
                    knLogger.debug(methodName, "If protocol version mismatch then notifying microservice via RMQ -");
                    sendNotificationForPVUpgrade(subsProfileInfoDTO,persisterTxn,newMajorPV);
                }
            }

            String pv = String.valueOf(subsProfileInfoDTO.getClientPVmajorVer());
            knLogger.debug(methodName, "PV :", pv);


            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(subsProfileInfoDTO.getMdn(),provRespDTO.getActiveFS2(),subsProfileInfoDTO.getActiveFS2(),persisterTxn);

            if(opProvDTO.getDirChgDTO()!=null){
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), pv);
            }

            knLogger.debug(methodName, "saving the transaction ");
            persisterTxn.save();

            // sending the notification
            // commonMediator.sendXcapNotification(provRespDTO.getDirChgDTO(),
            // pv);
            if ((pv.matches(com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_REGEX))
                    && (provRespDTO.isActiveFSChanged()
                    || provRespDTO.isSubsNameChanged() || provRespDTO.isSubsTypeChanged())) {
                KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                if (provRespDTO.isActiveFSChanged()) {
                    profileNotifyDTO.setActiveFeatureSetChange(subsProfileInfoDTO.getMdn());
                }
                if (provRespDTO.isSubsNameChanged()) {
                    profileNotifyDTO.setSubscriberNameChange(subsProfileInfoDTO.getMdn());
                }
                if (provRespDTO.isSubsTypeChanged()) {
                    profileNotifyDTO.setSubscriptionTypeChange(subsProfileInfoDTO.getMdn());
                }
                profileNotifyDTO.setMdn(subsProfileInfoDTO.getMdn());
                profileNotifyDTO.setPocHome(provRespDTO.getDirChgDTO().getPocHome());
                profileNotifyDTO.setPresenceHome(provRespDTO.getDirChgDTO().getPresenceHome());
                profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());

                commonMediator.sendProfileNotification(profileNotifyDTO, provRespDTO.getDirChgDTO(), pv);
            } else {
                commonMediator.sendXcapNotification(provRespDTO.getDirChgDTO(), pv);

            }
            if (corpRespDto != null) {
                // prepare notification and send to notification mgr
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpRespDto);
                knLogger.debug(methodName, "Sending notifications - ",xcapDiffList);
                notifier.setMaxNotfnsPerJob(2);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
            }
            if(provRespDTO!=null)
            {
                boolean status = commonMediator.prepareMcxNotifyForProfileMdns(provRespDTO.getProfileMdnEtagMap(),provRespDTO.getMcsXcapRootUriMap());
                knLogger.debug(methodName, "sending Profile notification Status: ", status);
            }
            // updating the performance Peg
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATED);
            // KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_NAME_CHANGE);
            // sending the response to the Client
            //responseDTO.setEtag(provRespDTO.getEtag());
            //added : force to mismatch the etag at client
            // Starting a thread for resourceList/GroupEtag/DirectoryEtag.
            Map<String, Boolean> mdnListMap = new HashMap<>();
            mdnListMap.put(subsProvInputDTO.getMdn(), provRespDTO.isActiveFSChanged());
            commonMediator.initiateEtagMgmtJob(mdnListMap);
            responseDTO.setEtag(0l);
            knLogger.debug(methodName, "ETag changed to 0l ");

            knLogger.info(methodName, "EXIT: update Client FS1 - ", responseDTO);
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Update Client FS1", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } finally {
            knLogger.info(methodName, "EXIT: update Client FS1 - ", responseDTO);
        }
    }

    /**
     * method to update the Client Feature Set
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */

    public IXDMResponseDTO updateUserAgent(IXDMRequestDTO requestDTO) {
        String methodName = "updateUserAgent(IXDMRequestDTO)";
        knLogger.info(methodName, "Update UserAgent request ", requestDTO);
        KnPersisterTxn persisterTxn = null;
        KnXDMSubsProvInfoDTO subsProvInputDTO = null;
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();
        try {
            // validating if the received input DTO is KnXDMSubsProvInfoDTO
            knLogger.debug(methodName, "Received from the input DTO - ",
                    requestDTO);
            if (requestDTO instanceof KnXDMSubsProvInfoDTO) {
                subsProvInputDTO = (KnXDMSubsProvInfoDTO) requestDTO;
                knLogger.debug(methodName,
                        "received DTO for updateUserAgent- ", subsProvInputDTO);
            } else {
                knLogger.error(methodName,
                        "receive an Invalid DTO for updateUserAgent - ",
                        requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO
                        .setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO
                        .setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE
                                .value());
                // commonMediator.sendFailureResponse(responseDTO, message,
                // null);
                return responseDTO;
            }

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            KnOPUpdateSubsInfoDTO provRespDTO = null;

            // retrieving the subscriber profile
            knLogger.debug(methodName,
                    "retrieving the subscriber profile for mdn "
                            + subsProvInputDTO.getMdn());
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(subsProvInputDTO.getMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf
                    .getSubscriberDetails(subscriberInfoDTO, persisterTxn);

            // populate the prov input dto for update subscriber api.
            KnIPSubsProvInfoDTO subsProvInfoDTO = new KnIPSubsProvInfoDTO();
            subsProvInfoDTO.setMdn(subsProvInputDTO.getMdn());
            subsProvInfoDTO.setUserAgentDTO(subsProvInputDTO.getUserAgentDTO());
            subsProvInfoDTO.setUserAgent(subsProvInputDTO.getUserAgent());
            // invoking the library for updating the subscriberName
            provRespDTO = provClientIntf.updateSubscriberUserAgent(
                    subsProvInfoDTO, persisterTxn);

            knLogger.debug(methodName, "Response received from Server - ",
                    provRespDTO);


            if (provRespDTO.getResponseMessage().equals(
                    KnProvConstants.UNSUPPORTED_DEVICE)) {
                KnXDMSubsStatusInfoDTO subsStatusInfoDTO = new KnXDMSubsStatusInfoDTO();
                subsStatusInfoDTO.setMdn(subsProvInputDTO.getMdn());
                subsStatusInfoDTO.setClientType(requestDTO.getClientType());
                subsStatusInfoDTO
                        .setServiceAuthStatus(KnConstants.SERVICE_AUTH_STATUS.PROVISIONED
                                .value());
                KnConstants.MESSAGE_TYPE action = KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE;
                IXDMResponseDTO responseXDMDTO = changeServiceAuthStatus(
                        subsStatusInfoDTO, persisterTxn, action);
                knLogger.debug( methodName, "return response received from server for un supported device- ",
                        responseXDMDTO);
            }

            int newMajorPV =0;
            if (subsProvInputDTO.getUserAgentDTO() != null) {
                String protocolVersion = subsProvInputDTO.getUserAgentDTO().getProtocolVersion();
                if (protocolVersion != null) {
                    String[] pv = protocolVersion.split("\\.");
                    if (pv != null && pv[0] != null) {
                        newMajorPV = Integer.parseInt(pv[0]);
                    }
                }
            }
            knLogger.debug(methodName, "New PV is  - ", newMajorPV);
            if(subsProfileInfoDTO.getClientPVmajorVer() != newMajorPV ){
                if(subsProfileInfoDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13 && newMajorPV >= PROTOCOL_VERSION_13){
                    knLogger.debug(methodName, "Update public group context from kodiak-poc to oidcxcap - ");
                    pubDocMediator.modifyGroupUriContext(subsProvInputDTO.getMdn(), KnDBUtil.getPttServerId(), persisterTxn);
                }
                knLogger.debug(methodName, "If protocol version mismatch then notifying microservice via RMQ -");
                sendNotificationForPVUpgrade(subsProfileInfoDTO,persisterTxn,newMajorPV);
            }

            String pv = String .valueOf(subsProfileInfoDTO.getClientPVmajorVer());
            knLogger.debug(methodName, "PV :", pv);

            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(subsProfileInfoDTO.getMdn(),subsProfileInfoDTO.getActiveFS2(),subsProfileInfoDTO.getActiveFS2(),persisterTxn);

            if(opProvDTO.getDirChgDTO()!=null){
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), pv);
            }

            knLogger.debug(methodName, "saving the transaction ");
            persisterTxn.save();
            // sending the notification



            if (provRespDTO.getDirChgDTO() != null) {
                commonMediator.sendXcapNotification(provRespDTO.getDirChgDTO(),
                        pv);
            }
            // updating the performance Peg
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATED);
            // KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_NAME_CHANGE);
            // sending the response to the Client
            responseDTO.setEtag(provRespDTO.getEtag());

            knLogger.info(methodName, "EXIT: update User Agent - ", responseDTO);
            return commonMediator.getSuccessResponse(responseDTO);

        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Update Client FS1", e);
            rollback(persisterTxn);
            if (!e.getErrorCode().equals(NO_CHG_IN_PROFILE)) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            }
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_SUBSCR_UPDATE_FAILURE);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * ** Method Usage : This method will add a single contact to the owner mdn
     * . 1. audit request logging 2. Send the response to the web card via
     * message framework on success add of the contact. 3. audit response
     * logging 4. Pegging of the method based on response 5. Sending Handset
     * Notification 6. Li logging if owner mdn is a target mdn
     *
     * @param message KnMessage
     */
    public void addContacts(KnMessage message) {

        String methodName = "addContacts";
        KnXDMContactListInfoDTO contactDTO = null;
        KnPersisterTxn persisterTxn = null;
        KnXDMPubRespDTO responseDTO = new KnXDMPubRespDTO();
        KnOpPubResponse response = null;
        IXDMRequestDTO pubContactInfoDTO = null;
        LinkedList<KnLIEventDTO> eventDTOList = new LinkedList<KnLIEventDTO>();
        IXDMResponseDTO respDTO = null;
        try {
            pubContactInfoDTO = (IXDMRequestDTO) message.getPayLoad();
            contactDTO = (KnXDMContactListInfoDTO) pubContactInfoDTO;
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.REQUEST,
                    "Request received - " + contactDTO.getOwnerMdn());

            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            response = pubDocMediator.addContacts(contactDTO, persisterTxn);
            persisterTxn.save();
            knLogger.debug(methodName, "ResponseDTO:  ", response);
            KnXDMPubRespDTO pubResp = new KnXDMPubRespDTO();
            pubResp.setResponseCode(response.getResponseCode());
            pubResp.setResponseMessage(response.getResponseMessage());
            pubResp.setResponseStatus(response.getResponseStatus());
            pubResp.setDocEtag(response.getDocEtag());
            knLogger.debug(methodName, "Add Contacts Resp : ", pubResp);
            // populate success response.
            respDTO = commonMediator.getSuccessResponse(pubResp);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.SUCCESS,
                    "Operation Successful - " + contactDTO.getOwnerMdn());
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_PUBLIC_POC_CONTACT_ADDED);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_PUBLIC_CONTACT_LIST_DOC_UPDATED);
            // Sending LI NOTIFICATION ..
            eventDTOList = commonMediator.liContactLogging(respDTO, contactDTO);
        } catch (Exception ex) {
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_PUBLIC_POC_CONTACT_ADD_FAILURE);
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", ex);
            knLogger.error(methodName, ex);
            respDTO = commonMediator.getFailureResponse(responseDTO, ex);
            eventDTOList = commonMediator.liContactLogging(respDTO, contactDTO);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
        } finally {
            persisterTxn = null;
        }
        // send Response to WEB ..
        commonMediator.sendRespPayLoadToMsgFW(respDTO, message);
        // sending handset Notification ..
        if (response != null) {
            commonMediator.sendPublicNotification(response.getDirChgDTO());
        }
        // sending LI Notification ..
        knLogger.debug(methodName, "sending LI Logging  ...", eventDTOList);
        KnLIEventHandler.logLI(eventDTOList);
    }

    /**
     * ** Method Usage : This method will delete a single contact to the owner
     * mdn . 1. audit request logging 2. Send the response to the web card via
     * message framework on success delete of the contact. 3. audit response
     * logging 4. Pegging of the method based on response 5. Sending Handset
     * Notification 6. Li logging if owner mdn is a target mdn
     *
     * @param message KnMessage
     */
    public void deleteContacts(KnMessage message) {

        String methodName = "deleteContacts";
        KnXDMContactListInfoDTO contactDTO = null;
        KnPersisterTxn persisterTxn = null;
        IXDMRequestDTO pubContactInfoDTO = null;
        KnXDMPubRespDTO responseDTO = new KnXDMPubRespDTO();
        IXDMResponseDTO respDTO = null;
        LinkedList<KnLIEventDTO> eventDTOList = new LinkedList<KnLIEventDTO>();
        KnOpPubResponse response = null;
        try {
            pubContactInfoDTO = (IXDMRequestDTO) message.getPayLoad();
            contactDTO = (KnXDMContactListInfoDTO) pubContactInfoDTO;
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.REQUEST,
                    "Request received - " + contactDTO.getOwnerMdn());

            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            response = pubDocMediator.deleteContacts(contactDTO, persisterTxn);
            persisterTxn.save();
            knLogger.debug(methodName, "ResponseDTO:  ", response);
            KnXDMPubRespDTO pubResp = new KnXDMPubRespDTO();
            pubResp.setResponseCode(response.getResponseCode());
            pubResp.setResponseMessage(response.getResponseMessage());
            pubResp.setResponseStatus(response.getResponseStatus());
            pubResp.setDocEtag(response.getDocEtag());
            knLogger.debug(methodName, "Delete Contacts Resp : ", pubResp);
            respDTO = commonMediator.getSuccessResponse(pubResp);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_PUBLIC_POC_CONTACT_DELETED);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_PUBLIC_CONTACT_LIST_DOC_UPDATED);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.SUCCESS,
                    "Operation Successful - "+ contactDTO.getOwnerMdn());
            // Sending LI NOTIFICATION ..
            knLogger.debug(methodName, "sending LI NOTIFICATION ...");
            eventDTOList = commonMediator.liContactLogging(respDTO, contactDTO);
        } catch (Exception ex) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", ex);
            knLogger.error(methodName, ex);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_PUBLIC_POC_CONTACT_DELETE_FAILURE);
            respDTO = commonMediator.getFailureResponse(responseDTO, ex);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
            eventDTOList = commonMediator.liContactLogging(respDTO, contactDTO);
        } finally {
            persisterTxn = null;
        }
        // send Response to WEB ..
        boolean result = commonMediator
                .sendRespPayLoadToMsgFW(respDTO, message);
        if (result) {
            knLogger.info(methodName, "Successfully sent the response");
        } else {
            knLogger.error(methodName, "Failed to send the response");
        }
        // sending handset Notification ..
        if (response != null) {
            commonMediator.sendPublicNotification(response.getDirChgDTO());
        }
        // sending LI Notification ..
        KnLIEventHandler.logLI(eventDTOList);
    }

