    /**
     * ** Method Usage : This method will Create or Replace the group for the
     * owner mdn . 1. audit request logging 2. Send the response to the web card
     * via message framework on success create of the group. 3. audit response
     * logging 4. Pegging of the method based on response 5. Sending Handset
     * Notification 6. Li logging if owner mdn is a target mdn
     *
     * @param message KnMessage

     */
    public void createGroup(KnMessage message) {

        String methodName = "createGroup";
        KnXDMGroupInfoDTO groupDTO = null;
        KnPersisterTxn persisterTxn = null;
        KnXDMPubRespDTO responseDTO = new KnXDMPubRespDTO();
        IXDMResponseDTO respDTO = null;
        IXDMRequestDTO pubGroupInfoDTO = null;
        KnOpPubResponse response = null;
        LinkedList<KnLIEventDTO> eventDTOList = new LinkedList<KnLIEventDTO>();
        try {
            pubGroupInfoDTO = (IXDMRequestDTO) message.getPayLoad();
            groupDTO = (KnXDMGroupInfoDTO) pubGroupInfoDTO;
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),methodName, KnAuditHelper.STATUS.REQUEST,
                    "Request received - " + groupDTO.getOwnerMdn());

            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            response = pubDocMediator.createGroup(groupDTO, persisterTxn);
            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            persisterTxn.save();
            knLogger.debug(methodName, "Create Group Resp : ", response);
            KnXDMPubRespDTO pubResp = new KnXDMPubRespDTO();
            pubResp.setResponseCode(response.getResponseCode());
            pubResp.setResponseMessage(response.getResponseMessage());
            pubResp.setResponseStatus(response.getResponseStatus());
            pubResp.setDocEtag(response.getDocEtag());
            respDTO = commonMediator.getSuccessResponse(pubResp);
            // audit response logging
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(), methodName, KnAuditHelper.STATUS.SUCCESS,
                    "Operation Successful - "+ groupDTO.getOwnerMdn());
            // pegging ..
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_POC_GRP_CREATED);
            // sending li logging ....
            if (response.isReplaceGrp()) {
                groupDTO.setOperationType(Integer.toString(com.kodiak.common.resources.KnConstants.OPERATION_ID_MODIFY_GROUP));
                eventDTOList = commonMediator.liGroupLogging(respDTO, groupDTO);
            } else {
                eventDTOList = commonMediator.liGroupLogging(respDTO, groupDTO);
            }

            if(xcapMobileSync){
                List<KnPubEXDMSNotifyDTO> grpNotifyDtoList = commonMediator.getPubGrpMicroSrvNotifyDto(response);
                knLogger.debug(methodName, "Publishing micro service notify");
                commonMediator.startNotifyMicroServicesJob(grpNotifyDtoList);
            }

        } catch (Exception ex) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", ex);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_POC_GRP_CREATE_FAILURE);
            respDTO = commonMediator.getFailureResponse(responseDTO, ex);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
            eventDTOList = commonMediator.liGroupLogging(respDTO, groupDTO);
        } finally {
            persisterTxn = null;
        }
        // send Response to WEB ..
        commonMediator.sendRespPayLoadToMsgFW(respDTO, message);
        // sending handset Notification ..
        if (response != null) {
            commonMediator.sendPublicNotification(response.getDirChgDTO());
        }
        // sending LI Notification ..
        KnLIEventHandler.logLI(eventDTOList);
    }

