    /**
     * @param message
     */
    public void getDirectory(KnMessage message) {

        String methodName = "getDirectory(KnMessage)";
        knLogger.debug(methodName, "ENTRY: ", message);
        KnXDMDirectoryInfoDTO subsDTO;
        KnPersisterTxn persisterTxn = null;
        KnXDMDirectoryRespDTO responseDTO = new KnXDMDirectoryRespDTO();
        IXDMRequestDTO pubSubsDirInfoDTO = null;

        try {
            pubSubsDirInfoDTO = (IXDMRequestDTO) message.getPayLoad();
            knLogger.info(methodName, "Payload : ", pubSubsDirInfoDTO);
            if (!(pubSubsDirInfoDTO instanceof KnXDMDirectoryInfoDTO)) {
                knLogger.error(methodName, "Invalid DTO - ", pubSubsDirInfoDTO);
                responseDTO = new KnXDMDirectoryRespDTO();
                responseDTO.setResponseMessage("Invalid DTO passed");
                responseDTO
                        .setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO
                        .setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE
                                .value());
                commonMediator.sendFailureResponse(responseDTO, message, null);
                return;
            }
            subsDTO = (KnXDMDirectoryInfoDTO) pubSubsDirInfoDTO;
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.REQUEST,
                    "Request received - " + subsDTO.getMdn());

            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();

            // responseDTO = new KnXDMDirectoryRespDTO();

            responseDTO = pubDocMediator.getIndexDetails(subsDTO, persisterTxn);
            // corpMediator.getCorpDirectory()
            knLogger.info(methodName, "Get All public Contacts/Groups Resp : ");

            // KnAppInfoDTO groupAppInfo = pubDocMediator.getGroupList(subsDTO,
            // persisterTxn);
            // knLogger.debug( methodName, "Get Group List Resp : " ,
            // groupAppInfo);
            // if (groupAppInfo != null) {
            // Collection<KnAppInfoDTO> appInfos = responseDTO.getAppInfoList();
            // appInfos.add(groupAppInfo);
            // }

            // Get Other details
            // Get Corp details
            if (responseDTO.getCorpId() > 0) {
                knLogger.debug(methodName, "Get Corp Resource/Group Info... ");
                String protocolVersion = responseDTO.getProtocolVersion();
                int protocol = Integer.parseInt(protocolVersion.substring(0, protocolVersion.indexOf('.')));
                KnXDMCorpSubscInfoRequestDTO corpSubsInfo = new KnXDMCorpSubscInfoRequestDTO();
                corpSubsInfo.setSubscriberMdn(subsDTO.getMdn());
                corpSubsInfo.setCorpId(String.valueOf(responseDTO.getCorpId()));
                corpSubsInfo.setXdmshome(responseDTO.getXdmsHome());
                corpSubsInfo.setUserProfileId(responseDTO.getUserProfileId());
                corpSubsInfo.setPvMajorVersion(protocol);
                corpSubsInfo.setActiveFs2(responseDTO.getActiveFs2());
                corpSubsInfo.setSubscriberFS2(responseDTO.getSubsriberFS2());
                corpSubsInfo.setClientType(responseDTO.getClientType());
                KnXDMCorpDirRespDTO corpDirResp = corpMediator.getCorpDirectory(corpSubsInfo, persisterTxn,protocol);
                Collection<KnAppInfoDTO> corpAppInfos = corpDirResp.getAppInfoList();

                if (corpAppInfos != null) {
                    Collection<KnAppInfoDTO> appInfos = responseDTO.getAppInfoList();
                    Collection<KnAppInfoDTO> finalCorpAppInfos = new ArrayList<>(corpAppInfos);
                    //for older client tgsc tag should not set for gwtdirectory response.
                    if (protocol < PROTOCOL_VERSION_7) {
                        for (KnAppInfoDTO appInfo : corpAppInfos) {
                            if (APP_UID_PUB_TGSC.equals(appInfo.getAuid())) {
                                finalCorpAppInfos.remove(appInfo);
                            }
                        }
                    }

                    if (protocol < PROTOCOL_VERSION_14) {
                        for (KnAppInfoDTO appInfo : corpAppInfos) {
                            if (APP_UID_TGSS_LIST.equals(appInfo.getAuid())) {
                                finalCorpAppInfos.remove(appInfo);
                            }
                        }
                    }
                    appInfos.addAll(finalCorpAppInfos);
                }
            }
            responseDTO.setMdn(subsDTO.getMdn());

            knLogger.debug(methodName, "Dir Response dto - ", responseDTO);
            commonMediator.sendSuccessResponse(responseDTO, message);
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_DIRECTORY);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.SUCCESS,
                    "Operation Successful - " + subsDTO.getMdn());
        } catch (KnPersistenceException pex) {
            if (persisterTxn != null)
                rollback(persisterTxn);
            knLogger.error(methodName, "Failed to get the Transaction", pex);
            responseDTO = new KnXDMDirectoryRespDTO();
            commonMediator.sendFailureResponse(responseDTO, message, pex);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_DIRECTORY_FAILURE);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
        } catch (KnXDMServerException xex) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Failed to get Directory ", xex);
            responseDTO = new KnXDMDirectoryRespDTO();
            commonMediator.sendFailureResponse(responseDTO, message, xex);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_DIRECTORY_FAILURE);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
        } catch (Exception ex) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", ex);
            responseDTO = new KnXDMDirectoryRespDTO();
            commonMediator.genericFailureResponse(responseDTO, message, ex);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_GET_DIRECTORY_FAILURE);
            auditPublic.writeAuditMessage("CID:" + message.getCorrelationId(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
        } finally {
            persisterTxn = null;
        }

    }

