    /**
     * method to check the health of the XDM
     *
     * @param message
     */
    public void isAlive(KnMessage message) {

        String methodName = "isAlive";
        knLogger.info(methodName, "ENTRY: ", message);
        KnXDMRespDTO responseDTO = new KnXDMRespDTO();

        try {
            responseDTO = new KnXDMRespDTO();
            commonMediator.postSuccessResponse(responseDTO, message);
        } catch (Exception ex) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", ex);
            responseDTO = new KnXDMRespDTO();
            commonMediator.genericFailureResponse(responseDTO, message, ex);
        } finally {
            knLogger.debug(methodName, "EXIT : ", responseDTO);
        }
    }

