    public IXDMResponseDTO getCorpSubscContactList(IXDMRequestDTO contactRequestDTO) {
        String methodName = "getCorpSubscContactList(contactRequestDTO)";
        KnXDMCorpContactListRespDTO respDto = new KnXDMCorpContactListRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            KnXDMCorpSubscInfoRequestDTO xdmRequestDTO = (KnXDMCorpSubscInfoRequestDTO) contactRequestDTO;



            if (contactRequestDTO.getClientType() != PTX_XDMDATA_INTF) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_GET_REQ_RCVD);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBS_CONTACT_INFO_REQ);
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            int clientType = contactRequestDTO.getClientType();
            if (CLIENT_TYPE_WCSR == clientType || CLIENT_TYPE_XCAP == clientType
                    || CLIENT_TYPE_CAT_UI == clientType || PTX_XDMDATA_INTF == clientType) {
                respDto = corpMediator.getCorpResourceList(contactRequestDTO,
                        persisterTxn);
            } else {
                //validate corp Hierarchy
                if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
                respDto = corpMediator.getCorpSubscContactList(
                        contactRequestDTO, persisterTxn);
            }
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto
                    .getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),
                        respDto.getResponseMessage());
            }
            persisterTxn.save();
            if (contactRequestDTO.getClientType() != PTX_XDMDATA_INTF) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_CORP_CONTACTS);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBS_CONTACT_INFO_REQ_SUCC);
            }
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ",
                    "retrieving subscriber contacts - ", e);
            respDto = populateResponse(e, respDto,
                    KnOMConstants.XDM_NUM_GET_CORP_CONTACTS_FAILURE);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "retrieving subscriber contacts - ", new KnException(
                            ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto,
                    KnOMConstants.XDM_NUM_GET_CORP_CONTACTS_FAILURE);
        }
        return respDto;
    }

    public IXDMResponseDTO modifyCorpSubscContacts(KnMessage message) {
        String methodName = "modifyCorpSubscContacts(contactRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO contactRequestDTO = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                contactRequestDTO = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpContactListRequestDTO xdmRequestDTO = (KnXDMCorpContactListRequestDTO) contactRequestDTO;
            //validate corp Hierarchy
            if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())) {
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_MODIFY_REQ_RCVD);
            // Step : get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step : invoke Corp Mediator
            KnCorpResponseDTO corpRespDto = corpMediator.modifyCorpSubscContacts(contactRequestDTO, persisterTxn);
            respDto = populateXdmResponse(corpRespDto);
            knLogger.debug(methodName, "Response recieved - ", respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            // Step : save the transaction
            knLogger.debug(methodName, "Saving transaction");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(corpRespDto.getPeg());
            // send for job
            knLogger.debug(methodName, "Initiate job -");
            if ((corpRespDto.getEnabledDispatchMemList() != null && !corpRespDto.getEnabledDispatchMemList().isEmpty())
                    || (corpRespDto.getDisabledDispatchMemList() != null && !corpRespDto.getDisabledDispatchMemList().isEmpty())) {
                knLogger.debug(methodName, "Initiate job -");
                initiateDispatchGrpJob(corpRespDto.getEnabledDispatchMemList(),corpRespDto.getDisabledDispatchMemList(),
                        null, null, Integer.valueOf(xdmRequestDTO.getCorpId()));
            }
            // Step : prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpRespDto);
            knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
            notifier.setMaxNotfnsPerJob(2);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName, "Sending log LI request");
            KnLIEventHandler.logLI(corpRespDto.getLiEventList());
            knLogger.debug(methodName, "After log LI request sent");
            if (xcapMobileSync) {
                knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                commonMediator.startNotifyMicroServicesJob(corpRespDto.getChangeLogMap(), corpRespDto.getMdnCorpId());
            }
            boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(corpRespDto);
            knLogger.info(methodName, "Sending ProfileMdn notification Status: ", profileNotifyStatus);
        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "modifying subscriber contacts - ", e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "modifying subscriber contacts - ", e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "Modifying subscriber contacts - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

