    public IXDMResponseDTO addCorpContacts(KnMessage message) {
        String methodName = "addCorpContacts(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpRespDTO resp = new KnXDMCorpRespDTO();
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO contactRequestDTO = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                contactRequestDTO = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpExtContactListRequestDTO xdmRequestDTO = (KnXDMCorpExtContactListRequestDTO) contactRequestDTO;
            //validate corp Hierarchy
            if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())) {
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_CREATE_REQ_RCVD);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:

            // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
            if (contactRequestDTO.getOperationType() != null && !contactRequestDTO.getOperationType().isEmpty()) {
                Collection<KnXDMMdnInfoDTO> xdmContactList = xdmRequestDTO.getExternalContactList();
                if (xdmContactList != null && !xdmContactList.isEmpty()) {
                    // Extract MDNs from the contact list into a List<String>
                    List<String> mdns = xdmContactList.stream()
                            .map(KnXDMMdnInfoDTO::getMdn)  // Map each contact to its MDN
                            .toList();  // Collect the result into a List

                    // Validate authorization status for all MDNs
                    commonMediator.validateSubAuthStatus(mdns, persisterTxn);
                }
            }

            // invoke Corp Mediator
            respDto = corpMediator.addCorpContacts(contactRequestDTO, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getStatusCode(), respDto.getMessage());
            }
            //prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, persisterTxn, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName, "After call to add External Contacts to the corporate. Response - ", xdmRespDto);

            Collection<KnXDMMdnInfoDTO> xdmContactList = xdmRequestDTO.getExternalContactList();
            KnXDMExtSubsRequestDTO xdmExtSubsRequestDTO = new KnXDMExtSubsRequestDTO();
            if (xdmContactList != null) {
                List<KnXDMExtSubscriberDTO> extSubs = new ArrayList<>(xdmContactList.size());
                for (KnXDMMdnInfoDTO extContact : xdmContactList) {
                    int subsType = getSubsType(extContact.getSubsType());
                    if (subsType != KnMediatorConstants.CORP_EXTERNAL_SUBSTYPE_KODIAK_DB) {
                        KnXDMExtSubscriberDTO contact = new KnXDMExtSubscriberDTO();
                        contact.setMdn(extContact.getMdn());
                        contact.setProfileId(subsType);
                        extSubs.add(contact);
                    }
                }
                xdmExtSubsRequestDTO.setExtSubs(extSubs);
                if (!extSubs.isEmpty()) {
                    KnXDMRespDTO provResponse = provMediator.addOrModifyExtSubscribers(xdmExtSubsRequestDTO, persisterTxn);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == provResponse.getResponseStatus()) {
                        knLogger.error(methodName,"Exception occured in provisioning library ");
                        throw new KnXDMServerException(respDto.getStatusCode(), respDto.getMessage());
                    }
                }
            }
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_EXT_CORP_CONTACT_ADDED);
        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "adding external Contact - ", e);
            resp = populateResponse(e, xdmRespDto,KnOMConstants.XDM_NUM_EXT_CORP_CONTACT_ADD_FAILURE);
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "adding external Contact - ", e);
            resp = populateResponse(e, xdmRespDto, KnOMConstants.XDM_NUM_EXT_CORP_CONTACT_ADD_FAILURE);
            // populate the error info
        } catch (Throwable e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "Adding Ext contacts - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            // respDto = populateResponse(e, respDto,
            // KnOMConstants.XDM_NUM_EXT_CORP_CONTACT_ADD_FAILURE);
        }
        return xdmRespDto;
    }

