            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            KnCorpResponseDTO serverRespDto = corpMediator.removeCorpContacts(contactRequestDTO, persisterTxn);
