            knLogger.error(methodName, "UnexpectedException occured while ", "Removing Ext contacts - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto, KnOMConstants.XDM_NUM_EXT_CORP_CONTACT_DELETE_FAILURE);
