    public IXDMResponseDTO createSublist(KnMessage message) {
        String methodName = "createSublist(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpContactListRespDTO xdmRespDto = new KnXDMCorpContactListRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO sublistReqDto = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                sublistReqDto = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpSublistInfoRequestDTO xdmRequestDTO = (KnXDMCorpSublistInfoRequestDTO) sublistReqDto;
            //validate corp Hierarchy
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_CREATE_REQ_RCVD);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();

            // Step:
            // invoke Corp Mediator
            KnCorpSublistRespDTO respDto = corpMediator.createSublist(sublistReqDto, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto
                    .getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(),
                        xdmRespDto.getResponseMessage());
            }

            KnXDMCorpSublistInfoDTO xdmSublistInfoDTO = new KnXDMCorpSublistInfoDTO();
            KnCorpSublistDTO sublisDTO = respDto.getSublistDTO();
            xdmSublistInfoDTO.setSublistId(String.valueOf(sublisDTO
                    .getSublistId()));
            xdmSublistInfoDTO.setSublistName(sublisDTO.getSublistName());
            xdmSublistInfoDTO.setSublistType(String.valueOf(sublisDTO
                    .getSublistType()));
            xdmSublistInfoDTO.setMemberCount(String.valueOf(sublisDTO
                    .getMemberCount()));

            xdmRespDto.setContactListInfo(xdmSublistInfoDTO);

            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_CREATED);

            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            notifier.setMaxNotfnsPerJob(2);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);

            knLogger.debug(methodName, "Sending log LI request");
            KnLIEventHandler.logLI(respDto.getLiEventList());
            knLogger.debug(methodName, "After log LI request sent");

            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                commonMediator.startNotifyMicroServicesJob(respDto.getChangeLogMap(), respDto.getMdnCorpId());
            }

        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ",
                    "creating Sublist - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto,
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_CREATE_FAILURE);
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ",
                    "creating Sublist - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto,
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_CREATE_FAILURE);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "Creating sublists - ", new KnException(
                            ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto,
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_CREATE_FAILURE);
        }
        return xdmRespDto;
    }

    public IXDMResponseDTO modifySublist(KnMessage message) {
        String methodName = "modifySublist(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO sublistReqDto = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                sublistReqDto = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpSublistInfoRequestDTO xdmRequestDTO = (KnXDMCorpSublistInfoRequestDTO) sublistReqDto;
            //validate corp Hierarchy
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.TOTAL_NUM_CORP_MODIFY_REQ_RCVD);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();

            // Step:
            // invoke Corp Mediator
            KnCorpResponseDTO respDto = corpMediator.modifySublist(
                    sublistReqDto, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto
                    .getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(),
                        xdmRespDto.getResponseMessage());
            }
            xdmRespDto.setZonePositionAssignmentStatus(respDto.getZonePositionAssignmentStatus());
            xdmRespDto.setUnassignedMdns(respDto.getUnassignedMdns());

            // Step:

            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);

            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);

            //Changes to add new contact or remove conatct from sublist updating permission upm doc.
            String corpId = xdmRequestDTO.getCorpId();
            String sublistId = xdmRequestDTO.getSublistId();
            List<KnTargetMdnPermissionBitInfo> addedMdnList=new ArrayList<>();
            List<KnTargetMdnPermissionBitInfo> removedMdnList=new ArrayList<>();

            KnXDMCorpUserProfileRequestDTO userProfileRequestDTO=new KnXDMCorpUserProfileRequestDTO();
            userProfileRequestDTO.setCorpId(corpId);

            KnXDMUserProfileInfoDTO userProfileInfo=new KnXDMUserProfileInfoDTO();
            if(xdmRequestDTO.getMdnList()!=null&&!xdmRequestDTO.getMdnList().isEmpty()){
                for(String mdn:xdmRequestDTO.getMdnList()){
                    addedMdnList.add(new KnTargetMdnPermissionBitInfo(mdn,mdn));
                }
            }

            if(xdmRequestDTO.getRemovedMdnList()!=null&&!xdmRequestDTO.getRemovedMdnList().isEmpty()){
                for(String mdn:xdmRequestDTO.getRemovedMdnList()){
                    removedMdnList.add(new KnTargetMdnPermissionBitInfo(mdn,mdn));
                }
            }

            userProfileInfo.setAddedMdnPerms(addedMdnList);
            userProfileInfo.setRemovedMdnPerms(removedMdnList);
            userProfileInfo.setContactListId(sublistId);

            userProfileRequestDTO.setUserProfileInfo(userProfileInfo);
            corpMediator.updateImpactedTuPerms(userProfileRequestDTO,persisterTxn);

            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_UPDATED);
            // Step:
            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            notifier.setMaxNotfnsPerJob(2);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);

            knLogger.debug(methodName, "Sending log LI request");
            KnLIEventHandler.logLI(respDto.getLiEventList());
            knLogger.debug(methodName, "After log LI request sent");

            KnXDMCorpSublistInfoRequestDTO sublistInfo = (KnXDMCorpSublistInfoRequestDTO) sublistReqDto;
            if ((respDto.getEnabledDispatchMemList() != null && !respDto.getEnabledDispatchMemList().isEmpty())
                    || (respDto.getDisabledDispatchMemList() != null && !respDto.getDisabledDispatchMemList().isEmpty())
                    || (respDto.getRemovedLocWatcherList() != null && !respDto.getRemovedLocWatcherList().isEmpty())) {
                initiateDispatchGrpJob(respDto.getEnabledDispatchMemList(), respDto.getDisabledDispatchMemList(), null,
                        respDto.getRemovedLocWatcherList(), Integer.valueOf(sublistInfo.getCorpId()));
            }
            commonMediator.sendTGSModeChangeNotification(respDto.getTgsModeChgMap());

            knLogger.debug(methodName, "Publishing micro service notify - ");
            if(xcapMobileSync){
                commonMediator.startNotifyMicroServicesJob(respDto.getChangeLogMap(), Integer.parseInt(xdmRequestDTO.getCorpId()));
            }
            if(respDto != null){
                boolean status = commonMediator.prepareMcxNotifyForProfileMdns(respDto);
                knLogger.debug(methodName, "sending Profile notification Status: ", status);

                status = commonMediator.sendMCSGRPNotification(respDto,allMcsXcapUris,Integer.parseInt(xdmRequestDTO.getCorpId()));
                knLogger.debug(methodName, "sending Group notification Status: ", status);
            }
        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ",
                    "modifying Sublist - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto,
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_UPDATE_FAILURE);
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ",
                    "modifying Sublist - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto,
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_UPDATE_FAILURE);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "Modifying sublist - ", new KnException(
                            ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto,
                    KnOMConstants.XDM_NUM_CORP_SUBLIST_UPDATE_FAILURE);
        }
        return xdmRespDto;
    }

