    public IXDMResponseDTO     createCorpGroup(KnMessage message, Boolean isWithProfileReq) {
        String methodName = "createCorpGroup(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpGroupInfoRespDTO xdmRespDto = new KnXDMCorpGroupInfoRespDTO();
        KnIPCorpGroupInfoDTO groupInfoDTO = new KnIPCorpGroupInfoDTO();
        KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_CREATE_REQ_RCVD);
        int successPegId = KnOMConstants.XDM_NUM_CORP_POC_GRP_CREATED;
        int failurePegId = KnOMConstants.XDM_NUM_CORP_POC_GRP_CREATE_FAILURE;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO groupRequestDto = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                groupRequestDto = (IXDMRequestDTO) payLoad;
            }
            if (!(groupRequestDto instanceof KnXDMCorpGroupInfoRequestDTO)) {
                knLogger.error(methodName, "groupRequestDto not of type KnXDMCorpGroupInfoRequestDTO - requestDTO - ",
                        groupRequestDto.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnXDMCorpGroupInfoRequestDTO xdmRequestDto = (KnXDMCorpGroupInfoRequestDTO) groupRequestDto;
            knLogger.debug(methodName, "xdmRequestDto :: ", xdmRequestDto);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Client Intf Validation:
            commonMediator.clientIntfValidator(xdmRequestDto, persisterTxn);
            // Very large group system level flag validator
            commonMediator.veryLargeGrpFlagValidator(xdmRequestDto, persisterTxn);
            if(xdmRequestDto.getCorpId() != null) groupInfoDTO.setCorpId(Integer.valueOf(xdmRequestDto.getCorpId()));
            int groupType = xdmRequestDto.getGroupType();
            if (KnMediatorConstants.CORP_BROADCAST_GROUP_TYPE == groupType) {
                successPegId = KnOMConstants.XDM_NUM_CORP_POC_BROADCAST_GRP_CREATED;
                failurePegId = KnOMConstants.XDM_NUM_CORP_POC_BROADCAST_GRP_CREATE_FAILURE;
            }
            if(xdmRequestDto.getClientType() == AREA_BASED_DYNAMIC_GROUP){
                successPegId = KnOMConstants.XDM_NUM_CORP_POC_ABDG_GRP_CREATED;
                failurePegId = KnOMConstants.XDM_NUM_CORP_POC_ABDG_GRP_CREATE_FAILURE;
            }
            groupInfoDTO.setClientType(xdmRequestDto.getClientType());
            groupInfoDTO.setGroupType(groupType);
            //TP CGMT changes
            groupInfoDTO.setTpRequestMdn(xdmRequestDto.getTpRequestMdn());
            groupInfoDTO.setTpGroupOwner(xdmRequestDto.getOwnerMdn());
            groupInfoDTO.setTpVendorID(xdmRequestDto.getTpVendorID());
            groupInfoDTO.setGroupCreatedBy(xdmRequestDto.getGroupCreatedBy());
            Collection<KnXDMGroupMdnInfoDTO> groupSupervisor = xdmRequestDto.getGroupSupervisor();
            Collection<KnCorpGroupMemberDTO> groupSupervisorList = new ArrayList<>();
            if (groupSupervisor != null) {
                for (KnXDMGroupMdnInfoDTO corpContact : groupSupervisor) {
                    KnCorpGroupMemberDTO subsc = new KnCorpGroupMemberDTO();
                    subsc.setMdn(corpContact.getMdn());
                    subsc.setSupervisory(corpContact.getSupervisor());
                    subsc.setLocWatcher(corpContact.getLocWatcher());
                    subsc.setBroadcaster(corpContact.getBroadcaster());
                    subsc.setIsOSMAuthorize(corpContact.getIsOSMAuthorize());
                    subsc.setCallInitiatePermission(corpContact.getCallInitiatePermission());
                    subsc.setCallReceivePermission(corpContact.getCallReceivePermission());
                    subsc.setInCallPermission(corpContact.getInCallPermission());
                    subsc.setVideoCallInitiatePermission(corpContact.getVideoCallInitiatePermission());
                    subsc.setVideoCallReceivePermission(corpContact.getVideoCallReceivePermission());
                    subsc.setVideoInCallPermission(corpContact.getVideoInCallPermission());
                    groupSupervisorList.add(subsc);
                }
            }
            groupInfoDTO.setGroupSupervisor(groupSupervisorList);
            // groupInfoDTO.setGroupId(Integer.valueOf(xdmRequestDto.getGroupId()));
            groupInfoDTO.setGroupDisplayName(xdmRequestDto.getGroupName());
            groupInfoDTO.setAvatar(xdmRequestDto.getAvatar());
            groupInfoDTO.setVideoPermission(xdmRequestDto.getVideoPermission());
            groupInfoDTO.setOSMListId(xdmRequestDto.getOSMListId());
            Set<KnCorpContactDTO> groupMembers = new HashSet<KnCorpContactDTO>();
            Collection<KnXDMGroupMdnInfoDTO> addedMemberList = xdmRequestDto.getAddedMdnDTOList();
            if (addedMemberList != null) {
                for (KnXDMGroupMdnInfoDTO groupMdnDTO : addedMemberList) {
                    KnCorpContactDTO subsc = new KnCorpContactDTO();
                    subsc.setMdn(groupMdnDTO.getMdn());
                    subsc.setSupervisory(groupMdnDTO.getSupervisor());
                    subsc.setLocWatcher(groupMdnDTO.getLocWatcher());
                    subsc.setBroadcaster(groupMdnDTO.getBroadcaster());
                    subsc.setCallInitiatePermission(groupMdnDTO.getCallInitiatePermission());
                    subsc.setCallReceivePermission(groupMdnDTO.getCallReceivePermission());
                    subsc.setInCallPermission(groupMdnDTO.getInCallPermission());
                    subsc.setIsOSMAuthorize(groupMdnDTO.getIsOSMAuthorize());
                    subsc.setVideoCallInitiatePermission(groupMdnDTO.getVideoCallInitiatePermission());
                    subsc.setVideoCallReceivePermission(groupMdnDTO.getVideoCallReceivePermission());
                    subsc.setVideoInCallPermission(groupMdnDTO.getVideoInCallPermission());

                    if(xdmRequestDto.getClientType() != CLIENT_TYPE_CAT_UI) {
                        subsc.setGroupModifyPerm(groupMdnDTO.getGrpModifyPerm());
                    } else {
                        subsc.setGroupModifyPerm(DISABLED);
                    }
                    groupMembers.add(subsc);
                }
            }
            Collection<String> addedMemberStrList = xdmRequestDto.getAddedMdnList();
            if (addedMemberStrList != null) {
                for (String mdn : addedMemberStrList) {
                    KnCorpContactDTO subsc = new KnCorpContactDTO();
                    subsc.setMdn(mdn);
                    groupMembers.add(subsc);
                }
            }
            groupInfoDTO.setAddedMemberDTOMdns(groupMembers);
            Collection<String> sublistIdStrs = xdmRequestDto.getAddedSublistIds();
            Collection<Integer> sublistIds = new ArrayList<Integer>();
            if (sublistIdStrs != null) {
                for (String sublistId : sublistIdStrs) {
                    sublistIds.add(Integer.valueOf(sublistId));
                }
            }
            groupInfoDTO.setAddedSublistIds(sublistIds);
            groupInfoDTO.setContactPairing(xdmRequestDto.isContactPairing());
            groupInfoDTO.setCustomParamMap(xdmRequestDto.getCustomParamMap());
            groupInfoDTO.setOverrideDnd(xdmRequestDto.getOverrideDND());
            groupInfoDTO.setHierarchyType(xdmRequestDto.getHierarchyType());
            groupInfoDTO.setHangTimeOut(xdmRequestDto.getHangTimeOut());
            groupInfoDTO.setEmergHangTimeAddOn(xdmRequestDto.getEmergHangTimeAddOn());
            groupInfoDTO.setEmergOverrideDND(xdmRequestDto.getEmergOverrideDND());
            groupInfoDTO.setEmergAutoFloorTimer(xdmRequestDto.getEmergAutoFloorTimer());
            groupInfoDTO.setMcxGrpInd(xdmRequestDto.getMcxGrpInd());
            groupInfoDTO.setGroupServiceType(xdmRequestDto.getGrpServiceType());
            groupInfoDTO.setFeatureAllowed(xdmRequestDto.getFeatureAllowed());
            if(xdmRequestDto.getGrpProfileId() != null){
                groupInfoDTO.setGroupProfileId(String.valueOf(xdmRequestDto.getGrpProfileId()));
            }
            groupInfoDTO.setAudioCutIn(xdmRequestDto.getAudioCutIn());
            groupInfoDTO.setGrpShared(xdmRequestDto.getGrpShared());
            groupInfoDTO.setIsPreConfiguredGroup(xdmRequestDto.getIsPreConfiguredGroup());
            groupInfoDTO.setUgwInterop(xdmRequestDto.getUgwInterop());
            List<KnXDMCorpGrpSharedCorpListDTO> grpSharedCorpListDTOS = xdmRequestDto.getGrpSharedCopList();
            if(grpSharedCorpListDTOS !=null && grpSharedCorpListDTOS.size() !=0) {
                List<KnCorpSharedCorpInfo> corpSharedCorpInfos = new ArrayList<>();
                for (KnXDMCorpGrpSharedCorpListDTO dto : grpSharedCorpListDTOS) {
                    KnCorpSharedCorpInfo corpSharedCorpInfo = new KnCorpSharedCorpInfo();
                    corpSharedCorpInfo.setCorpId(dto.getIntCorpID());
                    corpSharedCorpInfo.setExtCorpId(dto.getExtCorpID());
                    corpSharedCorpInfo.setOwnerCorpId(Integer.valueOf(xdmRequestDto.getCorpId()));
                    // Map hierarchyList from request (exclusive to createGroup).
                    // sharedHierarchyId is always present and used directly.
                    // ownerHierarchyId is reserved for future use.
                    corpSharedCorpInfo.setHierarchyList(dto.getHierarchyList());
                    KnXDMGroupMdnInfoDTO grpMdnInfoDTO = dto.getGroupMemberProps();
                    if(grpMdnInfoDTO != null) {
                        com.kodiak.xdms.server.corpmgmt.dto.common.KnCorpGroupContactDTO grpContactDTO = new com.kodiak.xdms.server.corpmgmt.dto.common.KnCorpGroupContactDTO();
                        grpContactDTO.setCallInitiateAllowed(grpMdnInfoDTO.getCallInitiatePermission());
                        grpContactDTO.setCallTerminateAllowed(grpMdnInfoDTO.getCallReceivePermission());
                        grpContactDTO.setIncallAllowed(grpMdnInfoDTO.getInCallPermission());
                        grpContactDTO.setVideoCallInitiateAllowed(grpMdnInfoDTO.getVideoCallInitiatePermission());
                        grpContactDTO.setVideoCallReceiveAllowed(grpMdnInfoDTO.getVideoCallReceivePermission());
                        grpContactDTO.setVideoInCallAllowed(grpMdnInfoDTO.getVideoInCallPermission());
                        grpContactDTO.setIsBroadcaster(grpMdnInfoDTO.getBroadcaster());
                        grpContactDTO.setIsLocSupervisor(grpMdnInfoDTO.getSupervisor());
                        grpContactDTO.setIsOSMAuthorized(grpMdnInfoDTO.getIsOSMAuthorize());
                        corpSharedCorpInfo.setGrpMemProps(grpContactDTO);
                    }
                    corpSharedCorpInfos.add(corpSharedCorpInfo);
                }
                groupInfoDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
            }
            List<String> ownerIdList = xdmRequestDto.getOwnerIdList();
            if(ownerIdList!=null && !ownerIdList.isEmpty()){
                groupInfoDTO.setOwnerIdList(ownerIdList);
            }
            groupInfoDTO.setUgwInterop(xdmRequestDto.getUgwInterop());
            groupInfoDTO.setAuthorizedLargeTG(xdmRequestDto.getAuthorizedLargeTG());
            groupInfoDTO.setHierarchyId(xdmRequestDto.getHierarchyId());
            // Step:
            // invoke Corp Mediator
            KnCorpGroupInfoRespDTO respDto = corpMediator.createCorpGroup(groupInfoDTO, persisterTxn);
            xdmRespDto.setVideoPermission(respDto.getVideoPermission());
            knLogger.debug("VIDEORESULT");
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(), xdmRespDto.getResponseMessage());
            }
            if(xdmRequestDto.getMcxGrpInd()!=null) {
                respDto.setMcxGrpInd(xdmRequestDto.getMcxGrpInd());
            }
            // Step:
            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            //Get all mcsxcap uri for sending new grp notification for pv 18 & above
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            // save the transaction
            persisterTxn.save();
            if (!isWithProfileReq) {
                KnStatisticsManagerImpl.getInstance().increment(successPegId);
            }
            KnCorpGroupInfoDTO groupBasicInfoDTO = respDto.getGroupInfoDTO();
            xdmRespDto.setGroupId(String.valueOf(groupBasicInfoDTO.getGroupId()));
            xdmRespDto.setGroupName(groupBasicInfoDTO.getGroupDisplayName());
            xdmRespDto.setGroupMemberCount(groupBasicInfoDTO.getGroupMemberCount());
            xdmRespDto.setMaxGroupMemberLimitFlag(groupBasicInfoDTO.getMaxGroupMemLimitFlag());
            xdmRespDto.setGroupType(groupBasicInfoDTO.getGroupType());
            xdmRespDto.setAvatar(groupBasicInfoDTO.getAvatar());
            xdmRespDto.setZonePositionAssignmentStatus(respDto.getZonePositionAssignmentStatus());
            xdmRespDto.setUnassignedMdns(respDto.getUnassignedMdns());
            //modify corp mcs event
            KnCorporateExdmsNotifyDto modifyCorpMcsEvent = null;
            if (respDto.isCorpNotification()) {
                KnCorpProfileDTO corpProfile = new KnCorpProfileDTO();
                corpProfile.setCorpId(respDto.getIntCorpId());
                corpProfile.setExtCorpId(respDto.getExtCorpId());
                corpProfile.setNetworkName(respDto.getNetworkName());
                modifyCorpMcsEvent = commonInfoUtil.formCorpNotifyPayload(MODIFY_CORP.value()
                        , corpProfile, ENABLED, MICROSERVICES_NOTIFY_EVENT_TYPE.CORPORATE_EVENT.value());
                knLogger.info(methodName, "Publishing micro service notify for corp- ", modifyCorpMcsEvent);

            }
            if (null != modifyCorpMcsEvent) {
                commonMediator.startNotifyMicroServicesJob(List.of(modifyCorpMcsEvent));
            }

            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.info(methodName, "Notification status - ", isNotified);
            knLogger.info(methodName, "Returning Create group response - ", xdmRespDto);
            knLogger.debug(methodName, "Sending log LI request");
            KnLIEventHandler.logLI(respDto.getLiEventList());
            knLogger.debug(methodName, "After log LI request sent");
            if ((respDto.getEnabledDispatchMemList() != null && !respDto.getEnabledDispatchMemList().isEmpty())
                    || (respDto.getDisabledDispatchMemList() != null && !respDto.getDisabledDispatchMemList().isEmpty())
                    || (respDto.getAddedLocWatcherList() != null && !respDto.getAddedLocWatcherList().isEmpty())) {
                initiateDispatchGrpJob(respDto.getEnabledDispatchMemList(), respDto.getDisabledDispatchMemList(),
                        respDto.getAddedLocWatcherList(), null, respDto.getMdnCorpId());
            }
            if(xcapMobileSync){
                List<KnCorpEXDMSNotifyDto> grpNotifyDtoList = commonMediator.getGrpMicroSrvNotifyDto(respDto, respDto.getMdnCorpId());
                List<KnCorpEXDMSNotifyDto> contactNotifyDtoList = commonMediator.getContactMicroSrvNotifyDto(respDto.getChangeLogMap(), respDto.getMdnCorpId());
                grpNotifyDtoList.addAll(contactNotifyDtoList);
                knLogger.debug(methodName, "Publishing micro service notify");
                commonMediator.startNotifyMicroServicesJob(grpNotifyDtoList);
            }
            knLogger.debug(methodName, "sending MCSGrp notification");
            commonMediator.sendMCSGRPNotification(respDto,allMcsXcapUris,respDto.getMdnCorpId());

            String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
            if (null != respDto.getProfileMdnEtagMap()) {
                respDto = (KnCorpGroupInfoRespDTO) commonMediator.fetchActiveProfileMdns(respDto, xdmPttServerId);
                boolean status = commonMediator.prepareMcxNotifyForProfileMdns(respDto);
                knLogger.debug(methodName, "Sending Profile notification Status: ", status);
            }
        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "creating Group - ", e);
            if (isWithProfileReq) {
                xdmRespDto = populateResponse(e, xdmRespDto);
            } else {
                xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            }
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "creating Group - ", e);
            if (isWithProfileReq) {
                xdmRespDto = populateResponse(e, xdmRespDto);
            } else {
                xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            }
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "Creating group - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            if (isWithProfileReq) {
                xdmRespDto = populateResponse(e, xdmRespDto);
            } else {
                xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            }
        }
        return xdmRespDto;
    }

    public IXDMResponseDTO modifyCorpGroup(KnMessage message) {
        String methodName = "modifyCorpGroup(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        int successPegId = KnOMConstants.XDM_NUM_CORP_POC_GRP_UPDATED;
        int failurePegId = KnOMConstants.XDM_NUM_CORP_POC_GRP_UPDATE_FAILURE;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO groupInfoDTO = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                groupInfoDTO = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpGroupInfoRequestDTO xdmRequestDto = (KnXDMCorpGroupInfoRequestDTO) groupInfoDTO;
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Client Intf Validation:
            commonMediator.clientIntfValidator(xdmRequestDto, persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_MODIFY_REQ_RCVD);
            if(xdmRequestDto.getClientType() == AREA_BASED_DYNAMIC_GROUP){
                successPegId = KnOMConstants.XDM_NUM_CORP_POC_ABDG_GRP_UPDATED;
                failurePegId = KnOMConstants.XDM_NUM_CORP_POC_ABDG_GRP_UPDATE_FAILURE;
            }
            // Step:
            // invoke Corp Mediator
            respDto = corpMediator.modifyCorpGroup(groupInfoDTO, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(), xdmRespDto.getResponseMessage());
            }
            xdmRespDto.setZonePositionAssignmentStatus(respDto.getZonePositionAssignmentStatus());
            xdmRespDto.setUnassignedMdns(respDto.getUnassignedMdns());
            // Step:
            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            //Get all mcs xcap ur's
            Set<String> allMcsXcapUris = genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(successPegId);
            //modify corp mcs event
            KnCorporateExdmsNotifyDto modifyCorpMcsEvent = null;
            if (respDto.isCorpNotification()) {
                KnCorpProfileDTO corpProfile = new KnCorpProfileDTO();
                corpProfile.setCorpId(respDto.getIntCorpId());
                corpProfile.setExtCorpId(respDto.getExtCorpId());
                corpProfile.setNetworkName(respDto.getNetworkName());
                modifyCorpMcsEvent = commonInfoUtil.formCorpNotifyPayload(MODIFY_CORP.value()
                        , corpProfile, ENABLED, MICROSERVICES_NOTIFY_EVENT_TYPE.CORPORATE_EVENT.value());
                knLogger.info(methodName, "Publishing micro service notify for corp- ", modifyCorpMcsEvent);

            }
            if (null != modifyCorpMcsEvent) {
                commonMediator.startNotifyMicroServicesJob(List.of(modifyCorpMcsEvent));
            }
            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            // Filtering only active mdn's
            String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
            notifier.sendEtagMcsNotifications(xcapDiffList);
            xcapDiffList = commonMediator.fetchXcapDiffList(xcapDiffList, xdmPttServerId, null);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName, "Returning modify group Response - ", xdmRespDto);
            knLogger.debug(methodName, "Sending log LI request");
            KnLIEventHandler.logLI(respDto.getLiEventList());
            knLogger.debug(methodName, "After log LI request sent");

            if ((respDto.getEnabledDispatchMemList() != null && !respDto.getEnabledDispatchMemList().isEmpty())
                    || (respDto.getDisabledDispatchMemList() != null && !respDto.getDisabledDispatchMemList().isEmpty())
                    || (respDto.getAddedLocWatcherList() != null && !respDto.getAddedLocWatcherList().isEmpty())
                    || (respDto.getRemovedLocWatcherList() != null && !respDto.getRemovedLocWatcherList().isEmpty())) {
                initiateDispatchGrpJob(respDto.getEnabledDispatchMemList(),respDto.getDisabledDispatchMemList(),
                        respDto.getAddedLocWatcherList(),respDto.getRemovedLocWatcherList(), respDto.getMdnCorpId());
            }
            commonMediator.sendTGSModeChangeNotification(respDto.getTgsModeChgMap());
            knLogger.debug(methodName, "Publishing micro service notify - ");
            if (xcapMobileSync) {
                Map<Integer, KnCorpGroupInfoDTO> groupSharedMap = new HashMap<>(1);
                if (respDto.getGroupIds() != null) {
                    knLogger.debug(methodName, "respDto.getGroupIds() - ", respDto.getGroupIds());
                    Optional<Integer> groupIdOptional = respDto.getGroupIds().stream().findFirst();
                    Integer groupShared = xdmRequestDto.getGrpShared();
                    if (groupIdOptional.isPresent() && groupShared != null) {
                        int groupId = groupIdOptional.get();
                        KnCorpGroupInfoDTO groupInfo = new KnCorpGroupInfoDTO();
                        groupInfo.setCorpId(respDto.getMdnCorpId());
                        groupInfo.setGroupId(groupId);
                        groupInfo.setGrpShared(groupShared);
                        if (null != respDto.getNewGroupDisplayName()) {
                            groupInfo.setGroupDisplayName(respDto.getNewGroupDisplayName());
                        }
                        groupInfo.setETag(Integer.parseInt(respDto.getEtag()));
                        groupSharedMap.put(groupId, groupInfo);
                    }
                }
                commonMediator.startNotifyMicroServicesJobModifyGroup(respDto.getChangeLogMap(), respDto.getMdnCorpId(),
                        respDto.getGroupCreatedBy(), respDto.getLmrInteropFlag(), respDto.getMcxGrpInd(), groupSharedMap,
                        respDto.getGrpSIPUri(), respDto.getOldLmrInteropFlag(), respDto.getRecordingFs());
            }
            knLogger.debug(methodName, "sending McsxcapGrp notification");

            commonMediator.sendMCSGRPNotification(respDto, allMcsXcapUris, respDto.getMdnCorpId());
            if (null != respDto.getProfileMdnEtagMap()) {
                respDto = commonMediator.fetchActiveProfileMdns(respDto, xdmPttServerId);
            }
            boolean status = commonMediator.prepareMcxNotifyForProfileMdns(respDto);
            knLogger.debug(methodName, "sending Profile notification Status: ", status);

        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "modifying Group - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "modifying Group - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "Modifying Group - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
        }
        return xdmRespDto;
    }

    public IXDMResponseDTO deleteCorpGroup(KnMessage message) {
        String methodName = "deleteCorpGroup(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        int successPegId = KnOMConstants.XDM_NUM_CORP_POC_GRP_DELETED;
        int failurePegId = KnOMConstants.XDM_NUM_CORP_POC_GRP_DELETE_FAILURE;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO groupInfoDTO = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                groupInfoDTO = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpGroupInfoRequestDTO xdmRequestDto = (KnXDMCorpGroupInfoRequestDTO) groupInfoDTO;
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Client Intf Validation:
            commonMediator.clientIntfValidator(xdmRequestDto, persisterTxn);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_DELETE_REQ_RCVD);
            if(xdmRequestDto.getClientType() == AREA_BASED_DYNAMIC_GROUP){
                successPegId = KnOMConstants.XDM_NUM_CORP_POC_ABDG_GRP_DELETED;
                failurePegId = KnOMConstants.XDM_NUM_CORP_POC_ABDG_GRP_DELETE_FAILURE;
            }
            // Step:
            // invoke Corp Mediator
            KnCorpResponseDTO respDto = corpMediator.deleteCorpGroup(groupInfoDTO, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(), xdmRespDto.getResponseMessage());
            }

            //int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            // Step:
            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            //get all mcs xcap uri's
            Set<String> allMcsXcapUris = genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(successPegId);
            // Step:
            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName,"Returning delete corp Group response - ", xdmRespDto);
            knLogger.debug(methodName, "Sending log LI request");
            KnLIEventHandler.logLI(respDto.getLiEventList());
            knLogger.debug(methodName, "After log LI request sent");

            if ((respDto.getDisabledDispatchMemList() != null && !respDto.getDisabledDispatchMemList().isEmpty())
                    || (respDto.getRemovedLocWatcherList() != null && !respDto.getRemovedLocWatcherList().isEmpty())) {
                initiateDispatchGrpJob(null, respDto.getDisabledDispatchMemList(), null,
                        respDto.getRemovedLocWatcherList(), respDto.getMdnCorpId());
            }
            commonMediator.sendTGSModeChangeNotification(respDto.getTgsModeChgMap());

            if(xcapMobileSync){
                KnCorpEXDMSNotifyDto notifyDto = new KnCorpEXDMSNotifyDto();
                notifyDto.setType(DELETE_CORP_GROUP.value());
                notifyDto.setId(DELETE_CORP_GROUP.value() + "_" + respDto.getDeletedGroupId());
                notifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.GROUP_NOTIFY_EVENTS.value());
                notifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                notifyDto.setGrpSIPUri(respDto.getGrpSIPUri());
                notifyDto.setLmrInteropFlag(respDto.getLmrIntropCapable());
                notifyDto.setGrpUri(respDto.getGrpUri());
                notifyDto.setGrpId(respDto.getDeletedGroupId());
                notifyDto.setCorpid(respDto.getMdnCorpId());
                notifyDto.setCreatedBy(respDto.getGroupCreatedBy());
                notifyDto.setPocHome(respDto.getPocHome());
                notifyDto.setClusterId(respDto.getClusterId());
                List<KnCorpEXDMSNotifyDto> notifyDtoList = new ArrayList<>();
                notifyDtoList.add(notifyDto);
                knLogger.info(methodName,"poc home value : ",respDto.getPocHome());
                List<KnCorpEXDMSNotifyDto> contactNotifyDtoList =
                        commonMediator.getContactMicroSrvNotifyDto(respDto.getChangeLogMap(), respDto.getMdnCorpId());
                notifyDtoList.addAll(contactNotifyDtoList);
                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }

            knLogger.debug(methodName, "sending MCSGrp notification");
            commonMediator.sendMCSGRPNotification(respDto,allMcsXcapUris,respDto.getMdnCorpId() );
            knLogger.debug(methodName, "sending Profile notification");
            if(respDto != null){
                boolean status = commonMediator.prepareMcxNotifyForProfileMdns(respDto);
                knLogger.debug(methodName, "sending Profile notification Status: ", status);
            }
        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "deleting Group - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "deleting Group - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "Deleting Group - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
        }
        return xdmRespDto;
    }

    public IXDMResponseDTO getCorpGroupDetails(IXDMRequestDTO groupInfoDTO) {
        String methodName = "getCorpGroupDetails(IXDMRequestDTO)";
        KnXDMCorpGroupInfoRespDTO respDto = new KnXDMCorpGroupInfoRespDTO();
        KnPersisterTxn persisterTxn = null;
        int successPegId = KnOMConstants.XDM_NUM_GET_CORP_GRP_DETAILS;
        int failurePegId = KnOMConstants.XDM_NUM_GET_CORP_GRP_DETAILS_FAILURE;
        try {
            KnXDMCorpGroupInfoRequestDTO xdmRequestDto = (KnXDMCorpGroupInfoRequestDTO) groupInfoDTO;
            if (xdmRequestDto.getClientType() != PTX_XDMDATA_INTF) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_GET_REQ_RCVD);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_GROUP_DETAILS_REQ);
            }

            if (xdmRequestDto.getClientType() == PTX_XDMDATA_INTF) {
                successPegId = KnOMConstants.NUM_GET_GROUP_DETAILS_REQ_SUCC;
            }
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            knLogger.debug(methodName, "clusterId :", clusterId);
            Map<String, String> microSvcCommonMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            int clientType = groupInfoDTO.getClientType();
            if (DYNAMIC_CGMT_INTF == clientType) {
                knLogger.info(methodName, "request from Dynamic C&G interface");
                String dynamicBasedFlgValue = microSvcCommonMap.get(MICROSERVICES_COMMON_CONFIG.DYNAPI_SERVICE_ENABLED.value());
                boolean dynamicFlag = false;
                if (null != dynamicBasedFlgValue) {
                    dynamicFlag = Integer.parseInt(dynamicBasedFlgValue) == ENABLED;
                }
                if (!dynamicFlag) {
                    knLogger.error(methodName, "Dynamic C&G flag is not enabled for Dynamic group operations ", dynamicFlag);
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.DYNAMIC_FLAG_DISABLED,
                            "Dynamic C&G flag is disabled");
                }
            } else if (AREA_BASED_DYNAMIC_GROUP == xdmRequestDto.getClientType()) {
                knLogger.info(methodName, "request from Area Based Dynamic interface");
                successPegId = KnOMConstants.XDM_NUM_GET_ABDG_GRP_DETAILS;
                failurePegId = KnOMConstants.XDM_NUM_GET_ABDG_GRP_DETAILS_FAILURE;
                String areaBasedFlgValue = microSvcCommonMap.get(MICROSERVICES_COMMON_CONFIG.ABDGFEATUREFLAG.value());
                boolean areaBasedFlg = false;
                if (null != areaBasedFlgValue) {
                    areaBasedFlg = Integer.parseInt(areaBasedFlgValue) == ENABLED;
                }
                if (!areaBasedFlg) {
                    knLogger.error(methodName, "ABDG System flag is not enabled for ABDG group operations ", areaBasedFlg);
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.ABDG_FLAG_DISABLED,
                            "ABDG flag is disabled");
                }
            }

            if (CLIENT_TYPE_WCSR == clientType || CLIENT_TYPE_XCAP == clientType || CLIENT_TYPE_CAT_UI == clientType
                    || PTX_XDMDATA_INTF == clientType || DYNAMIC_CGMT_INTF == clientType || AREA_BASED_DYNAMIC_GROUP == clientType) {
                respDto = corpMediator.getSubsGroupDetails(groupInfoDTO, persisterTxn);
                if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == respDto.getResponseStatus() && respDto.getProtocolVersion() != null) {
                    String protocolVersion = respDto.getProtocolVersion();
                    int protocol = Integer.parseInt(protocolVersion.substring(0, protocolVersion.indexOf('.')));
                    if (protocol >= PROTOCOL_VERSION_7 && CLIENT_TYPE_XCAP == clientType) {
                        if (respDto.getGroupType() == 3) {
                            respDto.setGroupType(1);
                        } else if (respDto.getGroupType() == 1) {
                            respDto.setGroupType(0);
                        }
                    }
                    if (protocol < PROTOCOL_VERSION_9 && CLIENT_TYPE_XCAP == clientType) {
                        for (KnXDMCorpContactDTO member : respDto.getGroupMembers()) {
                            // set member new feature as 0
                            member.setCallInitiatePermission(0);
                            member.setCallReceivePermission(0);
                            member.setInCallPermission(0);
                            member.setVideoCallInitiatePermission(0);
                            member.setVideoCallReceivePermission(0);
                            member.setVideoInCallPermission(0);
                        }
                    }
                    if (protocol < PROTOCOL_VERSION_9 && CLIENT_TYPE_XCAP == clientType) {
                        respDto.setAvatar(null);
                    }
                }
            } else {
                //validate corp Hierarchy
                if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDto.getCorpId()), xdmRequestDto.getHierarchyType()))
                    knLogger.info(methodName, "Routing to mediator, clientType={}", clientType);
                respDto = corpMediator.getCorpGroupDetails(groupInfoDTO, persisterTxn);
            }
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            // Step:
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(successPegId);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "retrieving Group Details- ", e);
            respDto = populateResponse(e, respDto, failurePegId);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "retrieving group details - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto, failurePegId);
        }
        return respDto;
    }

