    public IXDMResponseDTO getCorpSubscriberGroupList(IXDMRequestDTO subscriberCorpInfo) {
        String methodName = "getCorpSubscriberGroupList(IXDMRequestDTO)";
        KnXDMCorpGroupListRespDTO respDto = new KnXDMCorpGroupListRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            KnXDMCorpSubscInfoRequestDTO xdmRequestDto = (KnXDMCorpSubscInfoRequestDTO) subscriberCorpInfo;

            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            knLogger.debug(methodName ,"clusterId :",clusterId);
            Map<String, String> microSvcCommonMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            //validate corp Hierarchy
            if (subscriberCorpInfo.getClientType() != PTX_XDMDATA_INTF) {
                if (subscriberCorpInfo.getClientType() == DYNAMIC_CGMT_INTF) {
                    knLogger.info(methodName, "request from Dynamic C&G interface");
                    String dynamicBasedFlgValue = microSvcCommonMap.get(MICROSERVICES_COMMON_CONFIG.DYNAPI_SERVICE_ENABLED.value());
                    boolean dynamicFlag = false;
                    if(null != dynamicBasedFlgValue) {
                        dynamicFlag = Integer.parseInt(dynamicBasedFlgValue) == ENABLED;
                    }
                    if (!dynamicFlag) {
                        knLogger.error(methodName, "Dynamic C&G flag is not enabled for Dynamic group operations ", dynamicFlag);
                        throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.DYNAMIC_FLAG_DISABLED,
                                "Dynamic C&G flag is disabled");
                    }

                } else if (subscriberCorpInfo.getClientType() == AREA_BASED_DYNAMIC_GROUP) {
                    knLogger.info(methodName, "request from Area Based Dynamic interface");
                    String areaBasedFlgValue = microSvcCommonMap.get(MICROSERVICES_COMMON_CONFIG.ABDGFEATUREFLAG.value());
                    boolean areaBasedFlg = false;
                    if(null != areaBasedFlgValue) {
                        areaBasedFlg = Integer.parseInt(areaBasedFlgValue) == ENABLED;
                    }
                    if (!areaBasedFlg) {
                        knLogger.error(methodName, "ABDG System flag is not enabled for ABDG group operations ", areaBasedFlg);
                        throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.ABDG_FLAG_DISABLED,
                                "ABDG flag is disabled");
                    }
                } else if (subscriberCorpInfo.getClientType() == CLIENT_TYPE_WCSR) {
                    knLogger.debug("Calling with CLIENT_TYPE_WCSR subscriberCorpInfo");
                } else {
                    if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDto.getCorpId()), xdmRequestDto.getHierarchyType())){
                        knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDto.getHierarchyType());
                        throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                                "Invalid Corp hierarchy passed");
                    }
                }
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_GET_REQ_RCVD);
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_GRP_LIST_REV_GRPMEM_MDN_REQ);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBSCR_GROUP_REQ);
            }
            // Step:
            // invoke Corp Mediator
            respDto = corpMediator.getCorpSubscriberGroupList(subscriberCorpInfo, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            // Step:
            // save the transaction
            persisterTxn.save();
            if (subscriberCorpInfo.getClientType() != PTX_XDMDATA_INTF) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_CORP_GROUPS);
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_GRP_LIST_REV_GRPMEM_MDN_SUCC_RESP);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBSCR_GROUP_REQ_SUCC);
            }
        }catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ",
                    "retrieving Corp Subscribers Group List- ", e);
            respDto = populateResponse(e, respDto,
                    KnOMConstants.XDM_NUM_GET_SUBSCR_CORP_GROUPS_FAILURE);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "retrieving Corp Subscribers Group List - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(),
                            e));
            respDto = populateResponse(e, respDto,
                    KnOMConstants.XDM_NUM_GET_SUBSCR_CORP_GROUPS_FAILURE);
        }
        return respDto;
    }

