    /**
     * Rollback the transaction
     *
     * @param txn transaction object
     */
    private void rollback(KnPersisterTxn txn) {
        try {
            knLogger.error("rollback()", "Rolling back transaction");
            if (txn != null) {
                txn.rollback();
            }
        } catch (Exception e) {
            knLogger.error("rollback(txn)",
                    "Failed to rollback the transaction.");
        }
    }

    // public IXDMResponseDTO populateResponse(Exception e, KnXDMCorpRespDTO
    // respDTO) {
    public <T> T populateResponse(Exception e, IXDMResponseDTO respDTO) {
        if (e instanceof KnException) {
            KnException xe = (KnException) e;
            respDTO.setResponseCode(xe.getErrorCode());
            respDTO.setResponseMessage(xe.getErrorMessage());
        } else {
            respDTO.setResponseCode(ERROR_CODE_INTERNAL_ERROR);
            respDTO.setResponseMessage(e.getMessage());
        }
        respDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
        return (T) respDTO;
    }

    public <T> T populateResponse(Exception e, IXDMResponseDTO respDTO,
                                  Integer omId) {
        KnStatisticsManagerImpl.getInstance().increment(omId);
        return (T) populateResponse(e, respDTO);
    }

    public <T> T populateResponse(Exception e, IXDMResponseDTO respDTO,
                                  Integer omId, int count) {
        KnStatisticsManagerImpl.getInstance().increment(omId, count);
        return (T) populateResponse(e, respDTO);
    }

