    // to send job for added members
    private void initiateDispatchGrpJob(Collection<String> addedMdnList, Collection<String> deletedMdnList, Collection<String> addedLocWatcher,
                                        Collection<String> removedLocWatcher, int corpId) {
        String methodName = "initiateDispatchGrpJob(Collection<String>,Collection<String>,int)";
        // If added members list id not null and not empty start job to update
        // DISPATCH_GROUP_MEMBER field
        KnDispGrpMemChecker dispGrpMemCheckerJob = new KnDispGrpMemChecker();
        if (addedMdnList != null && !addedMdnList.isEmpty()) {
            knLogger.debug(methodName, "Calling Dispatch group member job Added- ");
            dispGrpMemCheckerJob.setAddedMembers(addedMdnList);
        }
        if (deletedMdnList != null && !deletedMdnList.isEmpty()) {
            knLogger.debug(methodName, "Calling Dispatch group member job removed- ");
            dispGrpMemCheckerJob.setDeletedMembers(deletedMdnList);
        }
        if (addedLocWatcher != null && !addedLocWatcher.isEmpty()) {
            knLogger.debug(methodName, "Calling Dispatch group member job addedLoc- ");
            dispGrpMemCheckerJob.setAddedLocWatcher(addedLocWatcher);
        }
        if (removedLocWatcher != null && !removedLocWatcher.isEmpty()) {
            knLogger.debug(methodName, "Calling Dispatch group member job removedLoc- ");
            dispGrpMemCheckerJob.setRemovedLocWatcher(removedLocWatcher);
        }
        List<KnDispGrpMemChecker> jobList = new ArrayList<KnDispGrpMemChecker>(
                1);
        dispGrpMemCheckerJob.setMaxNotificationSize(msgTruncationLimit);
        // dispGrpMemCheckerJob.setSyncNotfyThresold(syncNotifyThresold);
        dispGrpMemCheckerJob.setCorpId(corpId);
        jobList.add(dispGrpMemCheckerJob);
        try {
            knLogger.debug(methodName, "Scheduling the Jobs - ", jobList);
            scheduler.addRamJob(jobList, KnJobConstants.JOB_GROUP_NAME);
        } catch (KnJobSchedulerException e) {
            knLogger.error(methodName,
                    "KnJobSchedulerException occurred while ",
                    "submitting Notification Job to Scheduler - " + e);
        }
    }

    /**
     * Method which creates the PAM Account Profile and populates to the
     * response commdto (between wrapper and the Server) and sends the response
     * back to the client (SOAP client etc.) through messaging fw MQ.
     *
     * @param message KnMessage
     */
    public IXDMResponseDTO createLicensePack(KnMessage message) {
        final String methodName = "createLicensePack(KnMessage)";
        knLogger.entry(methodName, message);
        KnPersisterTxn persisterTxn = null;
        KnXDMPAMRespDTO responseDTO = new KnXDMPAMRespDTO();
        String correlationID = null;
        String extCorpID = null;
        boolean isBulkProcessing = false;
        String transactionID = null;
        String billingNumber = null;
        Map<String, Object> notifyMap = null;
        String version=null;

        try {
            correlationID = message.getCorrelationId();
            KnXDMPAMAccInfoDTO pamSubStatusInfoDTO = (KnXDMPAMAccInfoDTO) message.getPayLoad();
            knLogger.debug(methodName,"[ KnXDMPAMAccInfoDTO PamSubStatusInfoDTO : ",pamSubStatusInfoDTO," ]");
            version=pamSubStatusInfoDTO.getVersion();
            knLogger.error( methodName,"web card version ", version);
            KnXDMPAMSubsProfInfoDTO pamProfInfoDTO = pamSubStatusInfoDTO.getProfileDetails();
            if (pamProfInfoDTO != null) {
                extCorpID = pamProfInfoDTO.getExtCorpId();
            }
            transactionID = pamSubStatusInfoDTO.getTransactionId();
            billingNumber = pamSubStatusInfoDTO.getBillingNumber();
            notifyMap = pamSubStatusInfoDTO.getOpMap();
            //vrifying if the  mdn hierarchy matches with the Interface hierarchy, If not matches then reject the  process. and send Response
            if(! KnGeneralProfileUtil.validatePamAccCCAndHierarchy(billingNumber ,pamSubStatusInfoDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the billingmdn : ", pamSubStatusInfoDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            // validate Hierarchyc
            if (!KnGeneralProfileUtil.validateExtCorpCCAndHierarchy(extCorpID, pamSubStatusInfoDTO.getHierarchyType())) {
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", pamSubStatusInfoDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            // auditing request
            this.auditRequest(correlationID, KnMediatorConstants.PAM_AUDIT_CREATE_LICENSE_PACK, billingNumber, extCorpID);
            //peg request
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_CREATE_PAM_ACCOUNT_REQ_RCVD);

            // Opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "Opening the Transaction");
            persisterTxn.open();
            Map<String, String> configMap = genInfoUtil.retrieveRTXConfigValues(persisterTxn);
            String batchSize = configMap.get(KnMediatorConstants.BULK_PROV_BATCH_SIZE);
            if (batchSize != null) {
                BULK_BATCH_SIZE = Integer.parseInt(batchSize);
            }

            if (pamSubStatusInfoDTO.getTotalNoOfLines() > BULK_BATCH_SIZE) {
                isBulkProcessing = true;
            }

            responseDTO = this.xdmPamHelper.createLicensePack(message, KnMediatorConstants.PAM_AUDIT_CREATE_LICENSE_PACK, responseDTO,
                    isBulkProcessing, persisterTxn);

            knLogger.debug(methodName, "Saving the transaction");
            //persisterTxn.save();


            knLogger.info(methodName, "Publishing micro responseDTO- ", responseDTO);
            KnProvInfoUtil knProvInfoUtil = new KnProvInfoUtil();
            KnOPSubsProfileInfoDTO knOPSubsProfileInfoDTO=knProvInfoUtil.selectSubsProfileInfo(responseDTO.getKnXDMPAMAccInfoDTO().getProfileDetails().getMdns(), false,  persisterTxn);
            for(Entry<String, KnSubsProfileDTO> s2:knOPSubsProfileInfoDTO.getSubsRespMap().entrySet()) {
                knLogger.info(methodName, "Publishing micro s2- ", s2);
                if (s2.getValue().getCorporateSubscriptionType() == KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
                        int corpId = s2.getValue().getCorpId();

                        boolean isRequiredCorpNotified = commonInfoUtil.isRequiredCorpNotified(s2.getValue().getSubsFS2(), corpId, persisterTxn);
                        knLogger.info(methodName, "Publishing micro isRequiredCorpNotified- ", isRequiredCorpNotified);
                        if (isRequiredCorpNotified) {

                            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, true, persisterTxn);
                            knLogger.debug(methodName, "Corporate Profile - ", corpProfile);

                            //Update the UGWINTEROP
                            commonInfoUtil.updateLmrInterOpInDB(corpId, ENABLED, persisterTxn);

                            //Notify to MCS
                            KnCorporateExdmsNotifyDto corporateExdmsNotifyDto = commonInfoUtil.formCorpNotifyPayload(CREATE_CORP.value(), corpProfile, ENABLED, MICROSERVICES_NOTIFY_EVENT_TYPE.CORPORATE_EVENT.value());
                            knLogger.info(methodName, "Publishing micro service notify for corp- ", corporateExdmsNotifyDto);
                            commonMediator.startNotifyMicroServicesJob(List.of(corporateExdmsNotifyDto));
                        }
                }
            }
            //send notofication if it a non bulk sync operation
            if (!isBulkProcessing) {
                this.xdmPamHelper.setNotifyParams(transactionID, billingNumber, notifyMap, responseDTO);
                this.commonMediator.sendResponse(responseDTO, message, null,version);
            }
            persisterTxn.save();
        } catch (KnPersistenceException | KnXDMServerException e) {
            knLogger.error(methodName, "Failed to create PAM account ", e);
            this.xdmPamHelper.setNotifyParams(transactionID, billingNumber, notifyMap, responseDTO);
            this.rollback(persisterTxn);

            if (version!=null && version.matches(KnConstants.VERSION)) {
                knLogger.debug(methodName, "web card version - ", version);
                this.commonMediator.getFailureResponse(responseDTO,e);
                KnNotificationService.notifyResponse(responseDTO,version);
            } else {

                this.commonMediator.sendFailureResponse(responseDTO, message, e);
            }
            this.auditFailure(correlationID, KnMediatorConstants.PAM_AUDIT_CREATE_LICENSE_PACK, billingNumber, extCorpID, e.getErrorCode());
            responseDTO = null;

        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred ", e);
            this.xdmPamHelper.setNotifyParams(transactionID, billingNumber, notifyMap, responseDTO);
            this.rollback(persisterTxn);

            if (version!=null && version.matches(KnConstants.VERSION)) {
                knLogger.debug(methodName, "web card version - ", version);
                this.commonMediator.getFailureResponse(responseDTO,e);
                KnNotificationService.notifyResponse(responseDTO,version);
            } else {
                this.commonMediator.genericFailureResponse(responseDTO, message, e);
            }
            this.auditFailure(correlationID, KnMediatorConstants.PAM_AUDIT_CREATE_LICENSE_PACK, billingNumber, extCorpID, responseDTO.getResponseCode());
            responseDTO = null;

        }
        knLogger.exit(methodName, responseDTO);
        return responseDTO;
    }

    public IXDMResponseDTO upgradeLicensePack(KnMessage message) {
        final String methodName = "upgradeLicensePack(KnMessage)";
        knLogger.entry(methodName, message);
        KnPersisterTxn persisterTxn = null;
        KnXDMPAMRespDTO responseDTO = new KnXDMPAMRespDTO();
        String correlationID = message.getCorrelationId();
        String extCorpID = null;
        boolean isBulkProcessing = false;
        String transactionID = null;
        String billingNumber = null;
        Map<String, Object> notifyMap = null;
        String version=null;
        try {
            KnXDMPAMAccInfoDTO pamSubStatusInfoDTO = (KnXDMPAMAccInfoDTO) message.getPayLoad();
            KnXDMPAMSubsProfInfoDTO pamProfInfoDTO = pamSubStatusInfoDTO.getProfileDetails();
            if (pamProfInfoDTO != null) {
                extCorpID = pamProfInfoDTO.getExtCorpId();
            }

            transactionID = pamSubStatusInfoDTO.getTransactionId();
            billingNumber = pamSubStatusInfoDTO.getBillingNumber();
            notifyMap = pamSubStatusInfoDTO.getOpMap();
            version=pamSubStatusInfoDTO.getVersion();
            knLogger.error( methodName,"web card version ", version);
            //vrifying if the  mdn hierarchy matches with the Interface hierarchy, If not matches then reject the  process. and send Response
            if(! KnGeneralProfileUtil.validatePamAccCCAndHierarchy(billingNumber ,pamSubStatusInfoDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the billingmdn : ", pamSubStatusInfoDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            // auditing request
            auditRequest(correlationID, KnMediatorConstants.PAM_AUDIT_UPGRADE_LICENSE_PACK, billingNumber, extCorpID);
            //peg request
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_UPDATE_RATE_PLAN_REQ_RCVD);

            // Opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "Opening the Transaction");
            persisterTxn.open();
            Map<String, String> configMap = genInfoUtil.retrieveRTXConfigValues(persisterTxn);
            String batchSize = configMap.get(KnMediatorConstants.BULK_PROV_BATCH_SIZE);
            if (batchSize != null) {
                BULK_BATCH_SIZE = Integer.parseInt(batchSize);
            }
            int extpamSubsCount = this.xdmPamHelper.retrievePAMSubsCount(pamSubStatusInfoDTO.getBillingNumber(), persisterTxn);

            if ((pamSubStatusInfoDTO.getTotalNoOfLines() - extpamSubsCount) > BULK_BATCH_SIZE) {
                isBulkProcessing = true;
            }

            responseDTO = this.xdmPamHelper.upgradeLicensePack(message, KnMediatorConstants.PAM_AUDIT_UPGRADE_LICENSE_PACK, responseDTO, isBulkProcessing, persisterTxn);

            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            //send notofication if it a non bulk sync operation
            if (!isBulkProcessing) {
                this.xdmPamHelper.setNotifyParams(transactionID, billingNumber, notifyMap, responseDTO);
                this.commonMediator.sendResponse(responseDTO, message, null,version);
            }
        } catch (KnPersistenceException | KnXDMServerException e) {
            knLogger.error(methodName, "Failed to upgrade PAM Account", e);
            this.xdmPamHelper.setNotifyParams(transactionID, billingNumber, notifyMap, responseDTO);
            this.rollback(persisterTxn);

            if (version!=null && version.matches(KnConstants.VERSION)) {
                knLogger.debug(methodName, "web card version - ", version);
                this.commonMediator.getFailureResponse(responseDTO,e);
                KnNotificationService.notifyResponse(responseDTO,version);
            } else {
                this.commonMediator.sendFailureResponse(responseDTO, message, e);
            }
            this.auditFailure(correlationID, KnMediatorConstants.PAM_AUDIT_UPGRADE_LICENSE_PACK, billingNumber, extCorpID, e.getErrorCode());
            responseDTO = null;

        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred ", e);
            this.xdmPamHelper.setNotifyParams(transactionID, billingNumber, notifyMap, responseDTO);
            this.rollback(persisterTxn);

            if (version!=null && version.matches(KnConstants.VERSION)) {
                knLogger.debug(methodName, "web card version - ", version);
                this.commonMediator.getFailureResponse(responseDTO,e);
                KnNotificationService.notifyResponse(responseDTO,version);
            } else {
                this.commonMediator.genericFailureResponse(responseDTO, message, e);
            }
            this.auditFailure(correlationID, KnMediatorConstants.PAM_AUDIT_UPGRADE_LICENSE_PACK, billingNumber, extCorpID, responseDTO.getResponseCode());
            responseDTO = null;

        }
        knLogger.exit(methodName, "update PAM Account - ", responseDTO);
        return responseDTO;
    }

