    @Override
    public IXDMResponseDTO modifySubscriberScanList(KnMessage message) {
        String methodName = "modifySubscriberScanList(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_TGSC_LIST_REQ);
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (requestDTO instanceof KnXDMTalkGroupRequestDTO) {
                KnXDMTalkGroupRequestDTO talkGrpDTO = (KnXDMTalkGroupRequestDTO) requestDTO;
                //validate corp Hierarchy
                if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(talkGrpDTO.getCorpId()), talkGrpDTO.getHierarchyType())){
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", talkGrpDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }

                corpResponseDTO = corpMediator.modifySubscriberScanList(requestDTO, persisterTxn);
                populateXdmResponse(respDto, corpResponseDTO);
                if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                    throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
                }
                if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == corpResponseDTO.getStatus()) {
                    commonMediator.sendTGSModeChangeNotification(corpResponseDTO.getTgsModeChgMap());
                }
                // Step : prepare notification and send to notification mgr
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResponseDTO);
                knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
                notifier.setMaxNotfnsPerJob(2);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                notificationParamDTO.setPriority(KnConstants.NOTIFICATION_PRIORITY.HIGH.value());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, persisterTxn, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
                persisterTxn.save();
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_TGSC_LIST_SUCC_RESP);
            }
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while modifying Subscriber Scan List", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while modifying Subscriber Scan List", new KnException(ERROR_CODE_INTERNAL_ERROR,
                    e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    @Override
    public IXDMResponseDTO getSubscriberScanList(IXDMRequestDTO requestDTO) {
        String methodName = "getSubscriberScanList(IXDMRequestDTO)";
        IXDMResponseDTO respDto = null;
        KnPersisterTxn persisterTxn = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_TGSC_LIST_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (requestDTO instanceof KnXDMScanlistInfoDTO) {
                KnXDMScanlistInfoDTO scanlistInfoDTO = (KnXDMScanlistInfoDTO) requestDTO;
                respDto = new KnXDMScanlistResponseDTO();
                // retrieving the subscriber profile
                knLogger.debug(methodName,"retrieving the subscriber profile for mdn ");
                KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
                subscriberInfoDTO.setMdn(scanlistInfoDTO.getMdn());
                KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
                knLogger.debug(methodName,"retrieving the subscriber profile for mdn ");
                long corpId = subsProfileInfoDTO.getCorpId();
                scanlistInfoDTO.setHierarchyType(subsProfileInfoDTO.getHierarchyType());
                respDto = pubDocMediator.getScanList(scanlistInfoDTO, corpId, persisterTxn);
                if(subsProfileInfoDTO.getClientPVmajorVer() < com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_9){
                    KnXDMScanlistResponseDTO resp =(KnXDMScanlistResponseDTO) respDto;
                    resp.setCampModeCap(null);
                    if(resp.getScanList() != null){
                        for(KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO :resp.getScanList()){
                            xdmTalkGroupInfoDTO.setChannel(null);
                        }
                    }
                }
            } else {
                KnXDMTalkGroupRequestDTO talkGrpDTO = (KnXDMTalkGroupRequestDTO) requestDTO;
                //validate corp Hierarchy
                respDto = new KnXDMTalkGroupRespDTO();
                if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(talkGrpDTO.getCorpId()), talkGrpDTO.getHierarchyType())){
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", talkGrpDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }

                respDto = corpMediator.getSubscriberScanList(requestDTO, persisterTxn);
            }
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_TGSC_LIST_SUCC_RESP);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName,"KnPersistenceException occurred while getting Subscriber Scan List", e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName,"UnexpectedException occurred while getting Subscriber Scan List",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    public IXDMResponseDTO deleteExternalSubscriber(KnMessage message) {
        final String methodName = "deleteExternalSubscriber(IXDMRequestDTO)";
        knLogger.entry(methodName, "ENTRY:Delete External Subscriber ");
        IXDMResponseDTO responseDTO = new KnXDMRespDTO();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        if (payLoad instanceof IXDMRequestDTO) {
            requestDTO = (IXDMRequestDTO) payLoad;
        }
        knLogger.info(methodName, "Delete External Subscriber with request ", requestDTO);
        KnXDMExtSubsRequestDTO extSubsRequestDTO = (KnXDMExtSubsRequestDTO) requestDTO;
        KnXDMExtSubsResponseDTO extSubsResponseDTO = null;
        String mdn = null;
        KnPersisterTxn persisterTxn = null;
        List<Integer> listofCorpIds = null;
        KnCorpResponseDTO corpResponseDTO = null;
        Map<String, KnOPDirChgDTO> changeLogMapResponse = new HashMap<>();
        Map<Integer, Map<String, KnOPDirChgDTO>> changeLongMapForMicroServices = new HashMap<>();
        LinkedList<KnLIEventDTO> liEventList = new LinkedList<KnLIEventDTO>();
        try {

            //Validating the  MDN Hirarchy
            List<KnXDMExtSubscriberDTO> listOfXDMExtSubscriberDTO = extSubsRequestDTO.getExtSubs();
            KnXDMExtSubscriberDTO extSubscriberDTO = listOfXDMExtSubscriberDTO.get(0);
            if(!KnGeneralProfileUtil.validateMDNCCAndHierarchy(extSubscriberDTO.getMdn(), extSubsRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the mdn : ", extSubsRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST, "Invalid MDN hierarchy passed");
            }

            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "Opening the Transaction");
            persisterTxn.open();
            knLogger.debug(methodName, "Entering into getExtSubscriberInfo Request With DTO", requestDTO);
            extSubsResponseDTO = provMediator.getExtSubscriberInfo(extSubsRequestDTO, persisterTxn);
            knLogger.debug(methodName, "Response From getExtSubcriberInfo Request Successfully received ", extSubsResponseDTO);
            if (!extSubsResponseDTO.getExtSubs().isEmpty()) {
                for (KnXDMExtSubscriberDTO xdmExtSubscriberDTO : extSubsResponseDTO.getExtSubs()) {
                    mdn = xdmExtSubscriberDTO.getMdn();
                    knLogger.debug(methodName, "Entering into getCorpIdsForExtSubscriber Request For mdn", KnGDPRTemplate.mdn(mdn));
                    listofCorpIds = provMediator.getCorpIdsForExtSubscriber(mdn, persisterTxn);
                    knLogger.debug(methodName, "Response From getCorpIdsForExtSubscriber Request Successfully received with CorpId list", listofCorpIds);
                    Collection<KnXDMMdnInfoDTO> mdnInfoList = new ArrayList<>(1);
                    KnXDMMdnInfoDTO mdnInfoDTO = new KnXDMMdnInfoDTO();
                    mdnInfoDTO.setMdn(mdn);
                    mdnInfoList.add(mdnInfoDTO);

                    for (Integer corpId : listofCorpIds) {
                        KnXDMCorpExtContactListRequestDTO contactListRequestDTO = new KnXDMCorpExtContactListRequestDTO();
                        contactListRequestDTO.setExternalContactList(mdnInfoList);
                        contactListRequestDTO.setCorpId(String.valueOf(corpId));
                        knLogger.debug(methodName, "Entering into removeCorpContacts Request With DTO", contactListRequestDTO);
                        corpResponseDTO = corpMediator.removeCorpContacts(contactListRequestDTO, persisterTxn);

                        knLogger.debug(methodName, "Response From removeCorpContacts Request Successfully received ", corpResponseDTO);
                        if (corpResponseDTO.getStatus() != 0) {
                            throw new KnXDMServerException(corpResponseDTO.getStatusCode(), corpResponseDTO.getMessage());
                        }
                        if (corpResponseDTO.getChangeLogMap() != null) {
                            changeLogMapResponse.putAll(corpResponseDTO.getChangeLogMap());
                            changeLongMapForMicroServices.put(corpId, corpResponseDTO.getChangeLogMap());
                        }
                        if (corpResponseDTO.getLiEventList() != null) {
                            liEventList.addAll(corpResponseDTO.getLiEventList());
                        }
                    }
                }
                responseDTO = provMediator.deleteExtSubscriber(extSubsRequestDTO, persisterTxn);
            } else {
                throw new KnXDMServerException(KnErrorCodes.BOEntity.SUBSCRIBER_NOT_EXISTS_AS_EXT_SUBS,
                        "Subscriber does not exist as an External Subscriber");
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            knLogger.debug(methodName, "Successfully Deleted External Subscriber Profile with resp DTO - ", responseDTO);
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();
            if (!changeLogMapResponse.isEmpty()) {
                corpResponseDTO = new KnCorpResponseDTO();
                corpResponseDTO.setChangeLogMap(changeLogMapResponse);
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResponseDTO);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
                knLogger.debug(methodName, "Sending log LI request");
                KnLIEventHandler.logLI(liEventList);
                knLogger.debug(methodName, "After log LI request sent");
                if(xcapMobileSync){
                    for(Map.Entry<Integer, Map<String, KnOPDirChgDTO>> entry : changeLongMapForMicroServices.entrySet()){
                        knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                        commonMediator.startNotifyMicroServicesJob(entry.getValue(), entry.getKey());
                    }
                }
            }
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction");
            knLogger.error(methodName, e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Delete External Subscriber ");
            knLogger.error(methodName, e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred ");
            knLogger.error(methodName, e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        }
        knLogger.info(methodName, "EXIT: create Subscriber - ", responseDTO);
        return responseDTO;

    }

    /**
     * this method is to map the request substype to DB profile ID
     *
     * @param subsType
     * @return
     */
    private int getSubsType(int subsType) {
        int dbSubsType = 0;
        if (KnMediatorConstants.CORP_EXTERNAL_SUBSTYPE_MPTT_REQUEST == subsType) {
            dbSubsType = KnMediatorConstants.CORP_EXTERNAL_SUBSTYPE_MPTT_DB;
        } else if (KnMediatorConstants.CORP_EXTERNAL_SUBSTYPE_KODIAK_REQUEST == subsType) {
            dbSubsType = KnMediatorConstants.CORP_EXTERNAL_SUBSTYPE_KODIAK_DB;
        }
        return dbSubsType;
    }

    // Populating XDM response
    private KnXDMCorpRespDTO populateXdmResponse(KnCorpResponseDTO respDto) {

        String methodName="populateXdmResponse(KnCorpResponseDTO respDto)";
        knLogger.entry(methodName);
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        int status = respDto.getStatus();
        xdmRespDto.setResponseStatus(status);
        xdmRespDto.setResponseCode(respDto.getStatusCode());
        xdmRespDto.setResponseMessage(respDto.getMessage());
        Collection<KnCorpFailedData> failedDataList = respDto
                .getFailedDataList();
        String etag = respDto.getEtag();
        Collection<KnXDMFailureRespDTO> failureDetails= respDto.getFailureDetails();
        if (status == KnConstants.RESPONSE_STATUS.SUCCESS.value()) {
            if (failedDataList != null && !failedDataList.isEmpty()) {
                xdmRespDto
                        .setFailureDetails(populateFailureDetails(failedDataList));
            }
            if (etag != null) {
                xdmRespDto.setEtag(etag);
            }
        } else {
            if (failedDataList != null && !failedDataList.isEmpty()) {
                xdmRespDto.setFailureDetails(populateFailureDetails(failedDataList));
            }
            // validation fw consolidation error codes changes
            if (failureDetails != null && !failureDetails.isEmpty()) {
                Collection<KnXDMFailureRespDTO> finalFailureDetails = xdmRespDto.getFailureDetails();
                if (finalFailureDetails == null) {
                    xdmRespDto.setFailureDetails(failureDetails);
                } else {
                    finalFailureDetails.addAll(failureDetails);
                }
            }
        }
        knLogger.exit(methodName);
        return xdmRespDto;
    }

    @Override
    public IXDMResponseDTO updateScanList(IXDMRequestDTO requestDTO) {
        String methodName = "updateScanList(IXDMRequestDTO)";
        knLogger.entry(methodName);
        IXDMResponseDTO responseDTO = new KnXDMScanlistResponseDTO();
        ;
        KnXDMScanlistInfoDTO scanListInfoDTO = null;
        KnPersisterTxn persisterTxn = null;
        try {

            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.NUM_MODIFY_TGSC_LIST_REQ);
            scanListInfoDTO = (KnXDMScanlistInfoDTO) requestDTO;
            knLogger.debug(methodName, "received DTO for update ScanList - ",
                    scanListInfoDTO.getScanList());

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            // retrieving the subscriber profile
            knLogger.debug(methodName,
                    "retrieving the subscriber profile for mdn ");
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(scanListInfoDTO.getMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf
                    .getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            knLogger.debug(methodName,
                    "retrieved the subscriber profile for mdn ",
                    subsProfileInfoDTO);
            long corpId = subsProfileInfoDTO.getCorpId();
            knLogger.debug(methodName, "CorpId for the  mdn  ", corpId);
            // populate dto for delete ScanList.

            KnIPTalkGroupDTO iPSubsDTO = new KnIPTalkGroupDTO();
            iPSubsDTO.setMdn(subsProfileInfoDTO.getMdn());
            iPSubsDTO.setClientType(scanListInfoDTO.getClientType());
            iPSubsDTO.setOperationType(scanListInfoDTO.getOperationType());
            iPSubsDTO.setCorpId(String.valueOf(corpId));
            iPSubsDTO.setHierarchyType(subsProfileInfoDTO.getHierarchyType());

            // cleaning up ScanList before creating or modify ScanList

            knLogger.debug(methodName, "Get Scan List Request",
                    subsProfileInfoDTO);
            KnXDMTalkGroupServerRespDTO corpGetResp = corpClientIntf
                    .getSubscriberScanListXcap(iPSubsDTO, persisterTxn);
            knLogger.debug(methodName, "Get Scan List Request status",
                    corpGetResp);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == corpGetResp
                    .getStatus()) {
                knLogger.error("Get Scan List before Update ScanList failed",
                        corpGetResp);
                throw new KnXDMServerException(corpGetResp.getStatusCode(),
                        corpGetResp.getMessage());
            }

            // Create and Modify Scan List from input data
            knLogger.debug(methodName, "Update Scan List Request ",
                    subsProfileInfoDTO);
            scanListInfoDTO.setHierarchyType(subsProfileInfoDTO.getHierarchyType());
            responseDTO = pubDocMediator.updateScanList(scanListInfoDTO,
                    corpGetResp, corpId, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO
                    .getResponseStatus()) {
                knLogger.error("ScanList update request failed", responseDTO);
                throw new KnXDMServerException(responseDTO.getResponseCode(),
                        responseDTO.getResponseMessage());
            }

            knLogger.debug(methodName, "saving the transaction ");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.NUM_MODIFY_TGSC_LIST_SUCC_RESP);

        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Failed to get the Transaction", e);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Failed to Update Scan List ", e);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        }
        return responseDTO;
    }

