    /**
     * Method to remove all the contacts for the subscribers
     *
     * @param message KnMessage
     * @return
     */
    @Override
    public IXDMResponseDTO removeSubscribersContacts(KnMessage message) {
        String methodName = "removeSubscribersContacts(IXDMRequestDTO)";
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO corpSubsInfo = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                corpSubsInfo = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpSubscInfoRequestDTO xdmRequestDTO = (KnXDMCorpSubscInfoRequestDTO) corpSubsInfo;
            //validate corp Hierarchy
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_REMOVE_ALL_CONTACTS_FOR_SUBSCR_REQ);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            KnCorpResponseDTO respDto = corpMediator.removeSubscribersContacts(corpSubsInfo, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(), xdmRespDto.getResponseMessage());
            }

            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            // Step:
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_REMOVE_ALL_CONTACTS_FOR_SUBSCR_SUCC_RESP);
            // Step:
            // prepare notification and send to notification mgr
            knLogger.debug(methodName, "Initiate job -");
            if (respDto.getDisabledDispatchMemList() != null && !respDto.getDisabledDispatchMemList().isEmpty()) {
                initiateDispatchGrpJob(null, respDto.getDisabledDispatchMemList(), null, null, respDto.getMdnCorpId());
            }
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName, "Returning removeSubscribersContacts response - ", xdmRespDto);
            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                commonMediator.startNotifyMicroServicesJob(respDto.getChangeLogMap(), respDto.getMdnCorpId());
            }
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "retrieving external contacts - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "retrieving contact details - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto);
        }
        return xdmRespDto;
    }

    /**
     * Method to remove the subscriber from all the shared sublist where he is a member.
     *
     * @param message KnMessage
     * @return
     */
    @Override
    public IXDMResponseDTO removeSubscribersAllSublist(KnMessage message) {
        String methodName = "removeSubscribersAllSublist(IXDMRequestDTO)";
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO corpSubsInfo = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                corpSubsInfo = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpSubscInfoRequestDTO xdmRequestDTO = (KnXDMCorpSubscInfoRequestDTO) corpSubsInfo;
            //validate corp Hierarchy
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_REMOVE_ALL_SUBLISTS_FOR_SUBSCR_REQ);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            KnCorpResponseDTO respDto = corpMediator.removeSubscribersAllSublist(corpSubsInfo, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(), xdmRespDto.getResponseMessage());
            }

            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            //Get the RMQ configurations
            // Step:
            // save the transaction
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_REMOVE_ALL_SUBLISTS_FOR_SUBSCR_SUCC_RESP);
            // Step:
            // prepare notification and send to notification mgr
            knLogger.debug(methodName, "Initiate job -");
            if (respDto.getDisabledDispatchMemList() != null && !respDto.getDisabledDispatchMemList().isEmpty()
                    || (respDto.getRemovedLocWatcherList() != null && !respDto.getRemovedLocWatcherList().isEmpty())) {
                initiateDispatchGrpJob(null, respDto.getDisabledDispatchMemList(), null,
                        respDto.getRemovedLocWatcherList(), respDto.getMdnCorpId());
            }
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName, "Returning removeSubscribersAllSublist response - ", xdmRespDto);
            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                commonMediator.startNotifyMicroServicesJob(respDto.getChangeLogMap(), respDto.getMdnCorpId());
            }
            if(respDto!=null){
                boolean status = commonMediator.sendMCSGRPNotification(respDto,allMcsXcapUris,respDto.getMdnCorpId());
                knLogger.debug(methodName, "sending Group notification Status: ", status);
            }

        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "retrieving external contacts - ", e);
            xdmRespDto = populateResponse(e, xdmRespDto);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "retrieving contact details - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto);
        }
        return xdmRespDto;
    }

