        final String methodName = "generateTPActivationCode(IXDMRequestDTO)";
        knLogger.entry(methodName, requestDTO);
        KnPersisterTxn persisterTxn = null;
        KnXDMTPUserInfoRespDTO responseDTO = new KnXDMTPUserInfoRespDTO();

