    @Override
    public IXDMResponseDTO updateCorpAdminFS(KnMessage message) {
        String methodName = "updateCorpAdminFS()";
        knLogger.debug(methodName, "ENTRY");
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_MODIFY_REQ_RCVD);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            // Step:
            // invoke Corp Mediator
            KnCorpResponseDTO libRespDto = corpMediator.updateCorpAdminFS(requestDTO, persisterTxn);
            populateXdmResponse(respDto, libRespDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),
                        respDto.getResponseMessage());
            }
            // Step:
            // save the transaction
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync",xcapMobileSync);
            knLogger.debug(methodName, "Saving Transaction");
            persisterTxn.save();
            // KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_ALL_CORP_GROUPS);
            List<KnOPDirChgDTO> dirChgDTOs = libRespDto.getDirChgDTOs();
            knLogger.debug(methodName, "dirChgDTOs ", dirChgDTOs);
            List<KnXcapDiffNotifyDTO> xcapDiffList = new ArrayList<KnXcapDiffNotifyDTO>();
            for (KnOPDirChgDTO opDirChgDTO : dirChgDTOs) {
                KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) opDirChgDTO.getDocChgDTO();
                knLogger.debug(methodName, "chgDocList - ", chgDocList);
                for (KnOPDocChgDTO chgDTO : chgDocList) {
                    KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                    xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                    xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                    xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                    xcapDocList.add(xcapDiffDocDTO);
                }
                xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                xcapDiffNotifyDTO.setDirNewEtag(opDirChgDTO.getDirNewEtag());
                xcapDiffNotifyDTO.setDirPrevEtag(opDirChgDTO.getDirPrevEtag());
                xcapDiffNotifyDTO.setDirURI(opDirChgDTO.getDirUri());
                xcapDiffNotifyDTO.setXcapRootUri(opDirChgDTO.getXcapRootURI());
                xcapDiffNotifyDTO.setProtocolVersion(opDirChgDTO.getProtoVersion());
                xcapDiffNotifyDTO.setPocHome(opDirChgDTO.getPocHome());
                xcapDiffNotifyDTO.setPresenceHome(opDirChgDTO.getPresenceHome());
                xcapDiffList.add(xcapDiffNotifyDTO);
            }
            knLogger.debug(methodName, "xcapDiffList - ", xcapDiffList);
            notifier.setMaxNotfnsPerJob(KnMediatorConstants.DEFAULT_NOTIFY_SIZE);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            // For CorpResourceList notification - ActiveFS change.
            Collection<KnXcapDiffDirChgNotifyDTO> xcapCorpDiffList = commonMediator.prepareNotification(libRespDto);
            boolean isCorpNotified = notifier.sendXcapDiffNotifications(xcapCorpDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isCorpNotified);
            Map<String, KnOPDispatchDirChgDTO> mdnDispatchChgDTOMap = libRespDto.getMsDtoMap();
            List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
            Map<String, Boolean> mdnListMap = new HashMap<>();
            for (String mdn : mdnDispatchChgDTOMap.keySet()) {
                KnOPDispatchDirChgDTO opDispatchDirChgDTO = mdnDispatchChgDTOMap.get(mdn);
                mdnListMap.put(mdn, opDispatchDirChgDTO.isActiveFSChanged());
                int pv = 1;
                if(opDispatchDirChgDTO.getProtoVersion()!=null){
                    pv = Integer.parseInt(opDispatchDirChgDTO.getProtoVersion());
                }
                boolean xcapCouchClient = KnGeneralUtil.getFeatureBitValue(opDispatchDirChgDTO.getActiveFS2(),FEATURE_SET.XCAPCOUCHCLIENT.value());
                knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClient," PV:",pv);
                if (xcapMobileSync && (xcapCouchClient || pv >= PROTOCOL_VERSION_18 )) {
                    KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                    subscrEXDMSNotifyDto.setMdn(mdn);
                    subscrEXDMSNotifyDto.setCorpid(opDispatchDirChgDTO.getCorpId());
                    subscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(opDispatchDirChgDTO.getActiveFS2()));
                    subscrEXDMSNotifyDto.setActiveFS2(opDispatchDirChgDTO.getActiveFS2());
                    subscrEXDMSNotifyDto.setOldActiveFS(opDispatchDirChgDTO.getOldActiveFS());
                    subscrEXDMSNotifyDto.setPv(opDispatchDirChgDTO.getProtoVersion());
                    subscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                    subscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                    subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                    subscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                    subscrEXDMSNotifyDto.setLastProfileUpdateTime(opDispatchDirChgDTO.getLastProfileUpdateTime());
                    notifyDtoList.add(subscrEXDMSNotifyDto);

                    if(libRespDto.getProfileMdnActiveFsMap()!=null&&!libRespDto.getProfileMdnActiveFsMap().isEmpty())
                    {
                        for (Entry profileMdnFsMap : libRespDto.getProfileMdnActiveFsMap().entrySet()) {
                            KnSubscrEXDMSNotifyDto profileMdnSubscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                            profileMdnSubscrEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                            profileMdnSubscrEXDMSNotifyDto.setCorpid(opDispatchDirChgDTO.getCorpId());
                            profileMdnSubscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(profileMdnFsMap.getValue().toString()));
                            profileMdnSubscrEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                            profileMdnSubscrEXDMSNotifyDto.setPv(opDispatchDirChgDTO.getProtoVersion());
                            if(null!=libRespDto.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFs()) {
                                profileMdnSubscrEXDMSNotifyDto.setOldActiveFS(libRespDto.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFs());
                            }
                            profileMdnSubscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + profileMdnFsMap.getKey().toString());
                            profileMdnSubscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                            profileMdnSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                            profileMdnSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                            profileMdnSubscrEXDMSNotifyDto.setLastProfileUpdateTime(opDispatchDirChgDTO.getLastProfileUpdateTime());
                            notifyDtoList.add(profileMdnSubscrEXDMSNotifyDto);
                        }

                    }
                }
            }
            knLogger.debug(methodName, "notifyDtoList :", notifyDtoList);
            knLogger.info(methodName, "Publishing micro service notify  for User event - ");
            commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            // Starting a thread for resourceList/GroupEtag/DirectoryEtag.
            commonMediator.initiateEtagMgmtJob(mdnListMap);
            if(libRespDto != null){
                boolean status = commonMediator.prepareMcxNotifyForProfileMdns(libRespDto);
                knLogger.debug(methodName, "sending Profile notification Status: ", status);
            }
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while in updateCorpAdminFS ", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured in updateCorpAdminFS - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

