    @Override
    public IXDMResponseDTO getCorpSubscriberDetails(IXDMRequestDTO requestDTO) {
        String methodName = "getCorpSubscriberDetails(IXDMRequestDTO)";
        KnCorpSubsInfoRespDTO respDto = new KnCorpSubsInfoRespDTO();
        KnPersisterTxn persisterTxn = null;
        KnCorpSubsResquestDTO subsInfoDTO = null;
        KnXDMCorpRespDTO xdmCorpRespDTO = null;
        try {
            //TODO KnStatisticsManagerImpl.getInstance().increment(KnOMConstants);
            // Open the transaction
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_DETAILS);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            knLogger.debug(methodName, "Received input DTO - ", requestDTO);
            if (requestDTO instanceof KnCorpSubsResquestDTO) {
                subsInfoDTO = (KnCorpSubsResquestDTO) requestDTO;
                knLogger.debug(methodName, "received DTO for get Subscriber Details - ", subsInfoDTO);
            } else {
                knLogger.error(methodName, "received an Invalid DTO for get subscriber Details op - ", requestDTO);
                respDto.setResponseMessage("Invalid DTO is passed");
                respDto.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                respDto.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return respDto;
            }

            // Ensure that the operation type is not null or empty, then validate the subscriber's authorization status.
            if (subsInfoDTO.getOperationType() != null && !subsInfoDTO.getOperationType().isEmpty()) {
                commonMediator.validateSubAuthStatus(Collections.singletonList(subsInfoDTO.getSubscriberMdn()), persisterTxn);
            }

            // invoke Corp Mediator
            xdmCorpRespDTO = corpMediator.getCorpSubscriberDetails(requestDTO, true, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmCorpRespDTO.getResponseStatus()) {
                throw new KnXDMServerException(xdmCorpRespDTO.getResponseCode(), xdmCorpRespDTO.getResponseMessage());
            }else{
                KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
                KnOPSubsProfileInfoDTO subsProfileInfoDTO = null;
                // populating the prov library DTO
                String mdn = subsInfoDTO.getSubscriberMdn();
                subscriberInfoDTO.setMdn(mdn);
                subscriberInfoDTO.setAliasMdn(subsInfoDTO.getAliasMdn());
                subscriberInfoDTO.setUserId(subsInfoDTO.getUserId());
                // invoking teh prov library api
                subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
                knLogger.debug(methodName, "Retrieved Subscriber Details - ", subsProfileInfoDTO);
                subsProfileInfoDTO.setBillingMDN(subsProfileInfoDTO.getMdn());

                if (subsProfileInfoDTO.getPamAccId() != null && subsProfileInfoDTO.getPamAccId() != 0) {
                    KnOPPAMAccInfoDTO pamAccInfo = provClientIntf.getPAMAccInfoFromId(subsProfileInfoDTO.getPamAccId(), true, persisterTxn);
                    KnOPPAMAccInfoDTO cpamAccInfo = provClientIntf.getPAMAccInfoFromId(subsProfileInfoDTO.getPamAccId(), true, persisterTxn);
                    knLogger.info(methodName,"Updating the custom map for getBillingMdn - ", KnGDPRTemplate.mdn(pamAccInfo.getBillingMdn()));
                    subsProfileInfoDTO.setBillingMDN(pamAccInfo.getBillingMdn());
                }
                String pttSettingDocId = commonMediator.getDefaultPTTSettingDocValue(subsProfileInfoDTO,persisterTxn);
                subsProfileInfoDTO.setPttSettingDocId(pttSettingDocId);

                respDto = corpMediator.populateRespSubscriberProfile(respDto, subsProfileInfoDTO);
                String userId = null;
                if((String.valueOf(subsProfileInfoDTO.getSubsClientType()).matches(CLIENT_TYPE_WIFI_CROSS_NORMAL_RADIO)
                        || subsProfileInfoDTO.getLicenseType() == ENABLED)){
                    if(subsProfileInfoDTO.getClientPVmajorVer() == PROTOCOL_VERSION_0 || subsProfileInfoDTO.getClientPVmajorVer() > PROTOCOL_VERSION_13){
                        if(subsProfileInfoDTO.getAliasMdn() != null){
                            userId = subsProfileInfoDTO.getAliasMdn();
                        } else {
                            userId = subsProfileInfoDTO.getMdn();
                        }
                        KnOidcTmpPwdDTO oidcTmpPwdDTO = commonMediator.getDecryptedPwd(userId);
                        if(oidcTmpPwdDTO != null){
                            respDto.setTmpPwd(oidcTmpPwdDTO.getTmpPwd());
                            respDto.setTmpPwdExpiry(oidcTmpPwdDTO.getTmpPwdExpiry());
                        }
                    } else {
                        KnIPCorpActivationDTO ipReqDto = new KnIPCorpActivationDTO();
                        ipReqDto.setMdn(subsProfileInfoDTO.getMdn());
                        KnXDMCorpClientActResponseDTO responseDTO = corpMediator.getTempPwdForLegacy(ipReqDto, persisterTxn);
                        if (responseDTO != null && responseDTO.getResponseStatus() == KnMediatorConstants.SUCCESS) {
                            respDto.setTmpPwd(responseDTO.getActivationCode());
                            respDto.setTmpPwdExpiry(responseDTO.getExpiryTimestamp());
                        }
                    }

                }
                // Invoking the Custom Invoker for Custom data:
                if (subsInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                    KnXDMSubsProvInfoDTO subsProvInfoDTO = new KnXDMSubsProvInfoDTO();
                    subsProvInfoDTO.setMdn(subsInfoDTO.getSubscriberMdn());
                    Map<String, Object> customReqMap = new HashMap<String, Object>();
                    customReqMap.put(KnMediatorConstants.CUSTOM_PROV_ACTION, KnMediatorConstants.CUSTOM_PROV_VIEW_OP);
                    subsProvInfoDTO.setCustomParamMap(customReqMap);
                    Object customResp = KnProcessInvokerImpl.getInstance().invokeHook(KnMediatorConstants.CUSTOM_PROV_INVOKER, subsProvInfoDTO);
                    knLogger.debug(methodName, "Response from the Custom Prov - ", customResp);
                    if (customResp instanceof KnXDMRespDTO) {
                        KnXDMRespDTO customResponseDTO = (KnXDMRespDTO) customResp;
                        if (customResponseDTO.getResponseStatus() == KnConstants.RESPONSE_STATUS.SUCCESS.value()) {
                            respDto.setCustomParamMap(customResponseDTO.getCustomParamMap());
                        }
                    }

                }
                respDto.setFailureDetails(xdmCorpRespDTO.getFailureDetails());
                respDto.setResponseStatus(xdmCorpRespDTO.getResponseStatus());
                respDto.setResponseCode(xdmCorpRespDTO.getResponseCode());
            }

            knLogger.debug(methodName, "Saving the transaction");
            // save the transaction
            persisterTxn.save();
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "getting subscriber info - " + e);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_DETAILS_FAILURE);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "getting activation codes - ",
                    new KnException( ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_SUBSCR_DETAILS_FAILURE);
            respDto = populateResponse(e, respDto);
        }
        knLogger.debug(methodName, "sending response", respDto);
        return respDto;
    }

    /**
     * Method which get the externalContact for corporate in XDM Server and populates to the commdto
     * (between wrapper and the Server) and sends the response back to the restClient(XDMDataIntf)
     * through messaging fw RMQ.
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO getCorpExtContactDetails(IXDMRequestDTO requestDTO) {
        String methodName = "getCorpExtContactDetails(IXDMRequestDTO)";
        KnXDMCorpContactListRespDTO respDto = new KnXDMCorpContactListRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_CORP_EXT_CONTACT_INFO_REQ);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // invoke Corp Mediator
            int clientType = requestDTO.getClientType();
            if (PTX_XDMDATA_INTF == clientType) {
                respDto = corpMediator.getCorpExtContactDetails(requestDTO, persisterTxn);
            }

            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_CORP_EXT_CONTACT_INFO_REQ_SUCC);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "retrieving CorpExtContact details - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    /**
     * Method which get the pubGroupList for Owner MDN in XDM Server and populates to the commdto
     * (between wrapper and the Server) and sends the response back to the restClient(XDMDataIntf)
     * through messaging fw RMQ.
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    public IXDMResponseDTO getPubGroupList(KnMessage message) {
        String methodName = "getPubGroupList";
        KnXDMSubsInfoDTO subsDTO;
        KnPersisterTxn persisterTxn = null;
        KnXDMGroupListRespDTO responseDTO = new KnXDMGroupListRespDTO();
        IXDMRequestDTO pubGroupInfoDTO = null;
        try {
            pubGroupInfoDTO = (IXDMRequestDTO) message.getPayLoad();
            if (!(pubGroupInfoDTO instanceof KnXDMSubsInfoDTO)) {
                knLogger.error(methodName, "Invalid DTO - ", pubGroupInfoDTO);
                responseDTO = new KnXDMGroupListRespDTO();
                responseDTO.setResponseMessage("Invalid DTO passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                commonMediator.sendFailureResponse(responseDTO, message, null);
                return responseDTO;
            }
            subsDTO = (KnXDMSubsInfoDTO) pubGroupInfoDTO;
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBSCR_PUB_GROUP_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            responseDTO = pubMediator.getGroupList(subsDTO, persisterTxn);
            knLogger.debug(methodName, "Get Group List Resp : ", responseDTO);
            persisterTxn.save();
            commonMediator.getSuccessResponse(responseDTO);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBSCR_PUB_GROUP_REQ_SUCC);
        } catch (Exception ex) {
            knLogger.error(methodName, "Failed to Get Pub Group List ");
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", ex);
            responseDTO = new KnXDMGroupListRespDTO();
            commonMediator.getFailureResponse(responseDTO, ex);
        }
        return responseDTO;
    }

    /**
     * Method which get the CorporateProfile configured in XDM Server and populates to the commdto
     * (between wrapper and the Server) and sends the response back to the restClient(XDMDataIntf)
     * through messaging fw RMQ.
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO getCorporateProfile(IXDMRequestDTO requestDTO) {
        String methodName = "getCorporateProfile(IXDMRequestDTO)";
        KnXDMCorpProfileInfoRespDTO respDto = new KnXDMCorpProfileInfoRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_CORPORATE_PROFILE_REQ);
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // invoke Corp Mediator
            int clientType = requestDTO.getClientType();
            if (PTX_XDMDATA_INTF == clientType) {
                respDto = corpMediator.getCorporateProfile(requestDTO, persisterTxn);
            }
            if (respDto != null && KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_CORPORATE_PROFILE_REQ_SUCC);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "retrieving corporateProfile - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    /**
     * Method which update the Subscriber's clientProfile, from "existing to PTTRadio" and vice versa and
     * populates to the commdto (between wrapper and the Server) and sends the response back to the client
     * (SOAP client etc.) through messaging fw RMQ.
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO switchConvergedClient(KnMessage message) {
        String methodName = "switchConvergedClient()";
        knLogger.debug(methodName, "ENTRY");
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        KnCorpResponseDTO corpRespDTO = new KnCorpResponseDTO();
        KnOPUpdateSubsInfoDTO provRespDTO = new KnOPUpdateSubsInfoDTO();
        LinkedList<KnLIEventDTO> eventDTOList = new LinkedList<KnLIEventDTO>();
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_SUBSCR_CLIENT_TYPE);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
             /* Step: 1 : invoke Corp Mediator : Only Validation
                Step: 2 : invoke Prov Mediator : Only Provisioning Changes(Without any validation).
                          E.g ClientType Change, FeatureBit Change, ClientTypeChange Notification etc.
                Step: 3 : invoke Corp Mediator : ClientType Change related to corpChange(Without any validation).
                          E.g group/Contact notification, directory/resource eTag change etc.*/

            //Step:
            KnCorpResponseDTO corpRespDto = null;
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (!(requestDTO instanceof KnXDMSubsProvInfoDTO)) {
                knLogger.error(methodName, "xdmRequestDTO not of type KnXDMSubsProvInfoDTO - xdmRequestDTO - ",
                        requestDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnXDMSubsProvInfoDTO xdmRequestDTO = (KnXDMSubsProvInfoDTO) requestDTO;
            String mdn = xdmRequestDTO.getMdn();
            String corpId = xdmRequestDTO.getCorpId();
            boolean xcapCouchClient = false;
            // invoking the corporate library : Only Validation
            KnCorpResponseDTO corpValidationRespDto = corpMediator.switchConvergedClient(xdmRequestDTO, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == corpValidationRespDto.getStatus()) {
                KnIPSubsProvInfoDTO subsProvInfoDTO = new KnIPSubsProvInfoDTO();
                subsProvInfoDTO.setMdn(mdn);
                subsProvInfoDTO.setEnablePttRadio(xdmRequestDTO.isEnablePttRadio());
                // invoking the provisioning library
                provRespDTO = provClientIntf.switchConvergedClient(subsProvInfoDTO, persisterTxn);
                knLogger.debug(methodName, "Prov Response received from Server - ", provRespDTO);
                if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == provRespDTO.getResponseStatus()) {
                    KnXDMCorpSubscInfoRequestDTO corpSubsRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
                    corpSubsRequestDTO.setSubscriberMdn(mdn);
                    corpSubsRequestDTO.setCorpId(corpId);
                    corpSubsRequestDTO.setClientType(provRespDTO.getSubsClientType());
                    corpSubsRequestDTO.setNewClientType(provRespDTO.getNewSubsClientType());
                    corpSubsRequestDTO.setNewCorpId(Integer.parseInt(xdmRequestDTO.getCorpId()));
                    // invoking the corporate library
                    corpRespDTO = corpMediator.updateSubscriber(corpSubsRequestDTO, persisterTxn);
                    knLogger.debug(methodName, "Corp Response received from Server - ", corpRespDTO);
                } else {
                    knLogger.error(methodName, "Provisioning operation failed for convergedCLient - ", provRespDTO);
                    throw new KnXDMServerException(provRespDTO.getResponseCode(), provRespDTO.getResponseMessage());
                }
                // Calling EventDTO List for LI Notification.
                eventDTOList = commonMediator.getEventDTOList(mdn, KnProvOperationTypes.UPDATE_SUBSCRIBER, persisterTxn);
                knLogger.debug(methodName, "Li EventDTO List - ", eventDTOList);
                //Broadcaster Bit validation:
                boolean OldGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(provRespDTO.getOldActiveFS2(), FEATURE_SET.BROADCASTGROUPSERVICE.value());
                boolean newGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(), FEATURE_SET.BROADCASTGROUPSERVICE.value());
                if (!newGrpBroadcastBit && OldGrpBroadcastBit) {
                    corpRespDto = corpMediator.updateGrpBroadcasters(mdn, persisterTxn);
                    knLogger.debug(methodName, "disabled group broadcast members corp Library response - ", corpRespDto);
                    if (corpRespDto.getStatus() != 0) {
                        throw new KnXDMServerException(corpRespDto.getStatusCode(), corpRespDto.getMessage());
                    }
                }
                //Initalizing the KnSubscriberInfoDTO
                KnSubscriberInfoDTO subscriberInfoDTO = new KnSubscriberInfoDTO();
                //Fetching the boolean value for 45th bit,
                // If it is true then we will call the new REST API.
                xcapCouchClient = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
                //checking if 45th bit is 0/false or 1/true. If 0/false then we should not make the rest call
                knLogger.debug(methodName, "xcapCouchClient ", xcapCouchClient);
                if (xcapCouchClient) {
                    //Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                    subscriberInfoDTO.setMdn(mdn);
                    subscriberInfoDTO.setPassword(provRespDTO.getClientPassword());
                    subscriberInfoDTO.setDisabled(true);
                    if (provRespDTO.getServiceAuthStatus() == KnConstants.SERVICE_AUTH_STATUS.ACTIVATED.value()) {
                        subscriberInfoDTO.setDisabled(false);
                    }
                    knLogger.debug(methodName, "ServiceAuthStatus", provRespDTO.getServiceAuthStatus(), "subscriberInfoDTO- ", subscriberInfoDTO);
                    //Storing the list of bucket urls in a list
                    Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                    knLogger.debug(methodName, "bucketUrlList : ",bucketUrlList);
                    KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                    failedCBTxnLogDTO.setMdn(subscriberInfoDTO.getMdn());
                    genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                        List<String> bucketUrl = new ArrayList<>();
                        Integer curClusterId = entry.getKey();
                        knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                        bucketUrl.add(entry.getValue());
                        //REST call for profile creation starts here.
                        KnSyncResponseDTO syncResponseDTO = KnManageSyncUserProfileUtil.getInstance().updateSyncDocument(subscriberInfoDTO, bucketUrl);
                        knLogger.debug(methodName, "KnSyncResponseDTO status : ", syncResponseDTO.getStatus());
                        if (syncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                            failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                            failedCBTxnLogDTO.setMdn(subscriberInfoDTO.getMdn());
                            failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                            failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_UPDATE.value());
                            genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                        }
                    }
                }
            } else {
                knLogger.error(methodName, "CorpValidation failed for convergedCLient - ", corpValidationRespDto);
                KnXDMCorpRespDTO corpResp = populateXdmResponse(corpValidationRespDto);
                throw new KnXDMServerException(corpResp.getResponseCode(), corpResp.getResponseMessage());
            }

            if (corpRespDto != null) {
                Map<String, KnOPDirChgDTO> updateSubcriberChangeLogMap = corpRespDTO.getChangeLogMap();
                knLogger.debug(methodName, "updateSubcriberChangeLogMap ", KnGDPRTemplate.mapKeyMdn(updateSubcriberChangeLogMap));
                LinkedList<KnLIEventDTO> updateGrpBroadcasterLiEventList = corpRespDto.getLiEventList();
                knLogger.debug(methodName, "LI event list from the update grp broadcast call - ", updateGrpBroadcasterLiEventList);
                if (updateGrpBroadcasterLiEventList != null) {
                    eventDTOList.addAll(updateGrpBroadcasterLiEventList);
                }
                Map<String, KnOPDirChgDTO> updateGrpBroadcastersChangeLogMap = corpRespDto.getChangeLogMap();
                knLogger.debug(methodName, "updateGrpBroadcastersChangeLogMap ", KnGDPRTemplate.mapKeyMdn(updateGrpBroadcastersChangeLogMap));
                Map<String, KnOPDirChgDTO> combinedChangeLogMap = new HashMap<>();
                if (updateSubcriberChangeLogMap != null) {
                    combinedChangeLogMap.putAll(updateSubcriberChangeLogMap);
                }
                if (updateGrpBroadcastersChangeLogMap != null) {
                    for (Map.Entry<String, KnOPDirChgDTO> entry : updateGrpBroadcastersChangeLogMap.entrySet()) {
                        if (combinedChangeLogMap.get(entry.getKey()) != null) {
                            KnOPDirChgDTO subsDirChgDTO = combinedChangeLogMap.get(entry.getKey());
                            Collection<KnOPDocChgDTO> docChgDTO = subsDirChgDTO.getDocChgDTO();
                            KnOPDirChgDTO broadcastSubsChgDTO = entry.getValue();
                            subsDirChgDTO.setDirPrevEtag(broadcastSubsChgDTO.getDirPrevEtag());
                            subsDirChgDTO.setDirNewEtag(broadcastSubsChgDTO.getDirNewEtag());
                            Collection<KnOPDocChgDTO> broadcastChgDTO = broadcastSubsChgDTO.getDocChgDTO();
                            if (broadcastChgDTO != null) {
                                docChgDTO.addAll(broadcastChgDTO);
                            }
                        } else {
                            combinedChangeLogMap.putAll(updateGrpBroadcastersChangeLogMap);
                        }
                        knLogger.debug(methodName, "combinedChangeLogMap ",KnGDPRTemplate.mapKeyMdn(combinedChangeLogMap));
                    }
                }
                corpRespDTO.setChangeLogMap(combinedChangeLogMap);
            }
            knLogger.debug(methodName, "corpRespDTO && eventDTOList ", corpRespDTO, eventDTOList);
            populateXdmResponse(respDto, corpRespDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);

            String subsPV = String.valueOf(provRespDTO.getClientPvMajorVersion());
            knLogger.debug(methodName, "subsPV ", subsPV);

            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(mdn,provRespDTO.getActiveFS2(),provRespDTO.getOldActiveFS2(),persisterTxn);

            if(opProvDTO.getDirChgDTO()!=null){
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), subsPV);
            }

            // save the transaction
            knLogger.debug(methodName, "Saving Transaction");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_SUBSCR_CLIENT_TYPE_SUCC_RESP);
            // sending the notification
            if ((subsPV.matches(com.kodiak.common.resources.KnConstants.PROTOCOL_VERSION_REGEX))
                    && (provRespDTO.isActiveFSChanged() || provRespDTO.isClientTypeChanged())) {
                KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                if (provRespDTO.isActiveFSChanged()) {
                    profileNotifyDTO.setActiveFeatureSetChange(mdn);
                }
                if (provRespDTO.isClientTypeChanged()) {
                    profileNotifyDTO.setNewClientTypeChange(String.valueOf(provRespDTO.getNewSubsClientType()));
                    profileNotifyDTO.setClientTypeChange(String.valueOf(provRespDTO.getSubsClientType()));
                }
                profileNotifyDTO.setMdn(mdn);
                profileNotifyDTO.setPocHome(provRespDTO.getDirChgDTO().getPocHome());
                profileNotifyDTO.setPresenceHome(provRespDTO.getDirChgDTO().getPresenceHome());
                profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());
                commonMediator.sendProfileNotification(profileNotifyDTO, provRespDTO.getDirChgDTO(), subsPV);
                knLogger.debug(methodName, "ProfileNotification Sent ");
            }

            LinkedList<KnLIEventDTO> liEventlist = corpRespDTO.getLiEventList();
            knLogger.debug(methodName, "LI event list from the corporate module - ", liEventlist);
            if (liEventlist != null) {
                eventDTOList.addAll(liEventlist);
            }
            knLogger.debug(methodName, "eventDTOList final in end - ", eventDTOList);
            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpRespDTO);
            knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
            notifier.setMaxNotfnsPerJob(2);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            commonMediator.sendTGSModeChangeNotification(corpRespDTO.getTgsModeChgMap());
            if (xcapMobileSync) {
                knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                commonMediator.startNotifyMicroServicesJob(corpRespDTO.getChangeLogMap(), provRespDTO.getCorpId());
                knLogger.debug(methodName, "micro service notify for Group event - Sent");
            }
            // Do not delete below Error code, in future may be enhancement requirement will come.
            /*//Notification to microservices
            if (xcapMobileSync &&  xcapCouchClient) {
                KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                subscrEXDMSNotifyDto.setMdn(mdn);
                subscrEXDMSNotifyDto.setCorpid(Integer.parseInt(corpId));
                subscrEXDMSNotifyDto.setClientType(provRespDTO.getNewSubsClientType());
                subscrEXDMSNotifyDto.setActiveFS(provRespDTO.getActiveFS1());
                subscrEXDMSNotifyDto.setId(MICROSERVICES_EVENT_TYPE.CLIENT_TYPE_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                subscrEXDMSNotifyDto.setType(MICROSERVICES_EVENT_TYPE.CLIENT_TYPE_CHANGE.value());
                subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                subscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
                notifyDtoList.add(subscrEXDMSNotifyDto);
                knLogger.debug(methodName, "notifyDtoList, rmqInfoDto :", notifyDtoList, rmqInfoDto);
                knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList, rmqInfoDto);
                knLogger.debug(methodName, "micro service notify for clientTypeChange event - Sent");
            }*/
            if (provRespDTO.isActiveFSChanged()) {
                /// Starting a thread for resourceList/GroupEtag/DirectoryEtag.
                Map<String, Boolean> mdnListMap = new HashMap<>();
                mdnListMap.put(mdn, !provRespDTO.getOldActiveFS2().equals(provRespDTO.getActiveFS2()));
                commonMediator.initiateEtagMgmtJob(mdnListMap);
                //MicroserviceNotify for featureBit change.
                boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
                knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClientBit," PV:",provRespDTO.getClientPvMajorVersion());
                if (xcapMobileSync && (xcapCouchClientBit || provRespDTO.getClientPvMajorVersion() >=PROTOCOL_VERSION_18)) {
                    KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                    subscrEXDMSNotifyDto.setMdn(mdn);
                    subscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                    subscrEXDMSNotifyDto.setActiveFS2(provRespDTO.getActiveFS2());
                    subscrEXDMSNotifyDto.setOldActiveFS(provRespDTO.getOldActiveFS2());
                    subscrEXDMSNotifyDto.setPv(provRespDTO.getClientPvMajorVersion() + "." + provRespDTO.getClientPvMinorVersion());
                    subscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                    subscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                    subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                    subscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                    subscrEXDMSNotifyDto.setLastProfileUpdateTime(provRespDTO.getLastProfileUpdateTime());
                    List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
                    notifyDtoList.add(subscrEXDMSNotifyDto);

                    if(provRespDTO.getProfileMdnActivsFsMap()!=null&&!provRespDTO.getProfileMdnActivsFsMap().isEmpty())
                    {
                        List<String> mdnList = new ArrayList<>(Optional.ofNullable(provRespDTO.getProfileMdnActivsFsMap())
                                .map(Map::keySet)
                                .orElse(Collections.emptySet()));
                        Map<String, String> onlineSubscribersListByMdn = KnGeneralCacheUtil.getInstance()
                                .getOnlineSubcribersListByMdn(mdnList);
                        List<String> listActiveMdns = new ArrayList<>(onlineSubscribersListByMdn.keySet());
                        provRespDTO.getProfileMdnActivsFsMap().entrySet().removeIf(entry -> !listActiveMdns.contains(entry.getKey()));
                        for (Entry profileMdnFsMap : provRespDTO.getProfileMdnActivsFsMap().entrySet()) {
                            KnSubscrEXDMSNotifyDto profileMdnSubscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                            profileMdnSubscrEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                            profileMdnSubscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                            profileMdnSubscrEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                            //  profileMdnSubscrEXDMSNotifyDto.setOldActiveFS(activateResponse.getOldActiveFS2());
                            if(null!=provRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS()) {
                                profileMdnSubscrEXDMSNotifyDto.setOldActiveFS(provRespDTO.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS());
                            }
                            profileMdnSubscrEXDMSNotifyDto.setPv(provRespDTO.getClientPvMajorVersion() + "." + provRespDTO.getClientPvMinorVersion());
                            profileMdnSubscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + profileMdnFsMap.getKey().toString());
                            profileMdnSubscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                            profileMdnSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                            profileMdnSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                            profileMdnSubscrEXDMSNotifyDto.setLastProfileUpdateTime(provRespDTO.getLastProfileUpdateTime());
                            notifyDtoList.add(profileMdnSubscrEXDMSNotifyDto);
                        }
                    }
                    knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                    commonMediator.startNotifyMicroServicesJob(notifyDtoList);
                    knLogger.debug(methodName, "micro service notify for activeFs change event - Sent");
                }
            }
            // after success sending LI notification ..
            // send the dto .as of LI Notification . ...
            KnLIEventHandler.logLI(eventDTOList);
            // updating the Pegs
            Collection<Integer> successPegs = new ArrayList<Integer>();
            successPegs.add(KnOMConstants.XDM_NUM_SUBSCR_UPDATED);
            Collection<Integer> listOfPegs = provRespDTO.getSuccessPegs();
            if (listOfPegs != null && !listOfPegs.isEmpty()) {
                for (int pegId : listOfPegs) {
                    successPegs.add(pegId);
                }
            }

            KnStatisticsManagerImpl.getInstance().increment(successPegs);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while in updateCorpAdminFS ", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured in updateCorpAdminFS - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        knLogger.debug(methodName, "sending response", respDto);
        return respDto;
    }

