    /**
     * Method which get the UserDetails from IDM Interface, before getting details it will first do the business
     * validation in CorpLiberary and populates to the commdto (between wrapper and the Server) and sends the
     * response back to the client (SOAP client etc.) through messaging fw RMQ.
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO getCorpSubsUserProfile(IXDMRequestDTO requestDTO) {
        String methodName = "getCorpSubsUserProfile(IXDMRequestDTO)";
        KnCorpResponseDTO corpResponseDTO = new KnCorpResponseDTO();
        KnCorpSubsUserDetailsRespDTO respDto = new KnCorpSubsUserDetailsRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_USER_PROFILE_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            corpResponseDTO = corpMediator.getCorpSubsUserProfile(requestDTO, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == corpResponseDTO.getStatus()) {
                KnIPSubscriberInfoDTO subscrInfoDTO = new KnIPSubscriberInfoDTO();
                KnCorpSubsResquestDTO reqDto = (KnCorpSubsResquestDTO) requestDTO;
                subscrInfoDTO.setMdn(reqDto.getSubscriberMdn());
                subscrInfoDTO.setUserId(reqDto.getUserId());
                subscrInfoDTO.setAliasMdn(reqDto.getAliasMdn());
                KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscrInfoDTO, persisterTxn);
                String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
                KnXDMSubsAliasDetailsRespDTO oidcResponse = null;
                boolean isOIDCApplicable = generalCacheUtil.isOIDCApplicable(subsProfileInfoDTO.getCorpId(), WEBDISPATCHER);
                String appId = subsProfileInfoDTO.getDispatchType() == DISPATCH_TYPE_WEB ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                if ((subsProfileInfoDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_13)
                        || (subsProfileInfoDTO.getServiceAuthStatus() != ACTIVATED.value() && subsProfileInfoDTO.getClientPVmajorVer() == 0 && isOIDCApplicable)
                        || (subsProfileInfoDTO.getClientPVmajorVer() == 0 && (subsProfileInfoDTO.getLicenseType() == ENABLED || String.valueOf(subsProfileInfoDTO.getSubsClientType()).matches(CLIENT_TYPE_WIFI_CROSS_NORMAL_RADIO)))
                        || (isOIDCApplicable && appId.equals(APP_ID.DISPATCHER.value())) || (appId.equals(APP_ID.HANDSET_STANDARD.value()))) {
                    KnXDMSubsAliasDetailsReqDTO oidcSubsDto = new KnXDMSubsAliasDetailsReqDTO();
                    if (reqDto.getSubscriberMdn() != null) {
                        oidcSubsDto.setUserid(reqDto.getSubscriberMdn());
                    } else if (reqDto.getAliasMdn() != null) {
                        oidcSubsDto.setUserid(reqDto.getAliasMdn());
                    } else {
                        oidcSubsDto.setUserid(subsProfileInfoDTO.getMdn());
                    }
                    if(subsProfileInfoDTO.getSubsClientType()==DISPATCH_CLIENT){
                        oidcSubsDto.setUserid(subsProfileInfoDTO.getUserId());
                    }
                    oidcResponse = KnManageSyncUserProfileUtil.getInstance()
                            .notifyIDMIntfForOIDCMgmt(oidcSubsDto, appId, idmFqdn, null, HttpMethod.GET);
                    if (HttpStatus.NOT_FOUND.equals(oidcResponse.getStatusCode())
                            && (subsProfileInfoDTO.getServiceAuthStatus() != ACTIVATED.value() && subsProfileInfoDTO.getClientPVmajorVer() == 0
                            && isOIDCApplicable && APP_ID.DISPATCHER.value().equals(appId))) {
                        KnXDMCorpUserDetailsRespDTO idmSubscriberDTO = new KnXDMCorpUserDetailsRespDTO();
                        idmSubscriberDTO.setUserId(subsProfileInfoDTO.getUserId());
                        knLogger.debug(methodName, "idmSubscriberDTO - ", idmSubscriberDTO, "idmFqdn - ", idmFqdn);
                        respDto = KnManageSyncUserProfileUtil.getInstance().notifyIDMIntf(idmSubscriberDTO, idmFqdn, null, HttpMethod.GET);
                    }
                } else if ((subsProfileInfoDTO.getClientPVmajorVer() != 0 && subsProfileInfoDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13)
                        || (subsProfileInfoDTO.getClientPVmajorVer() == 0 && !isOIDCApplicable)) {
                    KnXDMCorpUserDetailsRespDTO idmSubscriberDTO = new KnXDMCorpUserDetailsRespDTO();
                    idmSubscriberDTO.setUserId(subsProfileInfoDTO.getUserId());
                    if(subsProfileInfoDTO.getSubsClientType()==DISPATCH_CLIENT){
                        idmSubscriberDTO.setUserId(subsProfileInfoDTO.getUserId());
                    }
                    knLogger.debug(methodName, "idmSubscriberDTO - ", idmSubscriberDTO, "idmFqdn - ", idmFqdn);
                    respDto = KnManageSyncUserProfileUtil.getInstance().notifyIDMIntf(idmSubscriberDTO, idmFqdn, null, HttpMethod.GET);
                }
                if (HttpStatus.OK.equals(respDto.getStatusCode()) && respDto.getIdmSubscriberDTO() != null) {
                    String decodedUserId = commonMediator.decodeBase64(respDto.getIdmSubscriberDTO().getUserId());
                    KnXDMCorpUserDetailsRespDTO userDetails = respDto.getIdmSubscriberDTO();
                    userDetails.setUserId(decodedUserId);
                } else {
                    respDto.setIdmSubscriberDTO(new KnXDMCorpUserDetailsRespDTO()); // for 8.3 Load.
                }
                knLogger.debug(methodName, "userDetails", respDto);
                if(oidcResponse != null) commonMediator.populateRespIDMProfile(respDto, oidcResponse);
                if(respDto.getIdmSubscriberDTO() != null){
                    if(subsProfileInfoDTO.getDispatchType() == DISPATCH_TYPE_WEB){
                        respDto.getIdmSubscriberDTO().setUserType(String.valueOf(OIDC_USER_TYPE.DISPATCHER.value()));
                    } else {
                        respDto.getIdmSubscriberDTO().setUserType(String.valueOf(OIDC_USER_TYPE.OTHERS.value()));
                    }

                    if(reqDto.getAliasMdn() != null){
                        respDto.getIdmSubscriberDTO().setMdn(subsProfileInfoDTO.getMdn());
                        respDto.getIdmSubscriberDTO().setAliasMdn(subsProfileInfoDTO.getAliasMdn());
                    } else if(respDto.getIdmSubscriberDTO().getMdn() == null){
                        respDto.getIdmSubscriberDTO().setMdn(subsProfileInfoDTO.getMdn());
                    }
                }

                if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getStatus()) {
                    knLogger.error(methodName, "Error for Fetching profile from IDM - ", respDto.getStatus());
                    respDto.setResponseCode(KnMediatorConstants.ERROR_CODE_INTERNAL_ERROR);
                    respDto.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                    throw new KnXDMServerException(respDto.getResponseCode(), "Unable to Fetch records from IDM-OIDC Intf");
                }
            }
            populateXdmResponse(respDto, corpResponseDTO);
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_USER_PROFILE_REQ_SUCC);
            knLogger.info(methodName, "Sending response", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while getCorpSubsUserProfile", e);
            respDto = populateResponse(e, respDto);

        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while getCorpSubsUserProfile",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    /**
     * Interface to initiate the reset email for resetting the forgotten password of a user. User must be registered
     * and in verified / activated state with the Kodiak IDM service to be able to send password email. The email may
     * be self email or other user’s email if the user has permission to initiate send password mail respectively,
     * before doing operation it will first do the business validation in CorpLiberary and populates to the
     * commdto (between wrapper and the Server) and sends the response back to the client (SOAP client etc.)
     * through messaging fw RMQ.
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
