    /**
     * Interface to set a mapping for Authorized MDNs with the corresponding Targets MDNs and allowed permissions for
     * performing feature control by Authorized User, before doing operation it will first do the business validation
     * in CorpLiberary and populates to the commdto (between wrapper and the Server) and sends the response back to the
     * client (SOAP client etc.) through messaging fw RMQ.
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO setTargetPermissions(KnMessage message) {
        String methodName = "setTargetPermissions(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_SET_MCPTT_PERMISSION_REQ);
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (!(requestDTO instanceof KnCorpSubMCPTTInfoRequestDTO)) {
                knLogger.error(methodName, "requestDTO not of type KnCorpSubMCPTTInfoRequestDTO - requestDTO - ",
                        requestDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnCorpSubMCPTTInfoRequestDTO xdmRequestDTO = (KnCorpSubMCPTTInfoRequestDTO) requestDTO;
            knLogger.debug(methodName, "xdmRequestDto :: ", xdmRequestDTO);
            //validate corp Hierarchy
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            Collection<KnTargetMdnPermissionBitInfo> tuPermInfoList = xdmRequestDTO.getTargetMdnPermissionBitInfoList();
            List<KnTargetMdnPermissionBitInfo> tuProfileMdnPermInfoList=new ArrayList<>();
            //adding all the profile mdns for the base mdn in req to tu list.
            for(KnTargetMdnPermissionBitInfo tu:tuPermInfoList){
                List<String> profileMdns = provMediator.getMdnForUPM(tu.getMdn(), persisterTxn);
                //removing base mdn from profileMdns list
                profileMdns.remove(tu.getMdn());
                for(String profileMdn:profileMdns){
                    tuProfileMdnPermInfoList.add(new KnTargetMdnPermissionBitInfo(profileMdn
                            ,tu.getSubsName(),tu.getAmbientListening()
                            ,tu.getDiscreteListening(),tu.getUserCheck(),tu.getUserEnable()
                            ,tu.getEmergPermission(),tu.getMcVideoUnConfirmedPull()));
                }
            }
            xdmRequestDTO.setTargetMdnPermissionBitInfoList(tuPermInfoList);
            xdmRequestDTO.setTargetProfileMdnPermissionBitInfoList(tuProfileMdnPermInfoList);
            KnCorpResponseDTO libRespDto = corpMediator.setTargetPermissions(xdmRequestDTO, persisterTxn);
            populateXdmResponse(respDto, libRespDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),
                        respDto.getResponseMessage());
            }
            // Step:
            // save the transaction
            knLogger.debug(methodName, "Saving Transaction");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_SET_MCPTT_PERMISSION_REQ_SUCC);
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(libRespDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.info(methodName, "Notification status - ", isNotified);
            //forming notification on success
            knLogger.info(methodName, "--->Before: xcapDiffList- ", xcapDiffList);
            knLogger.info(methodName, "Notification status starts - ");
            KnXcapDiffNotifier xcapDiffNotifier = KnXcapDiffNotifier.getInstance();
            //if(libRespDto.isProfileChanged()){
            List<KnOPDirChgDTO> dirChgDTOs = libRespDto.getDirChgDTOs();
            knLogger.debug(methodName, "--->dirChgDTOs ", dirChgDTOs);
            List<KnXcapDiffNotifyDTO> xcapConfigDiffList = new ArrayList<KnXcapDiffNotifyDTO>();
            if(dirChgDTOs!= null) {
                for (KnOPDirChgDTO opDirChgDTO : dirChgDTOs) {
                    // if (opDirChgDTO.isProfileChanged()){
                    KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                    Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                    ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) opDirChgDTO.getDocChgDTO();
                    knLogger.debug(methodName, "chgDocList - ", chgDocList);
                    if (opDirChgDTO.isPrivacyReasonRequired() == true) {
                        knLogger.debug(methodName, "--->Privacy opt in reason will be coming since opDirChgDTO.isPrivacyReasonRequired() - ", opDirChgDTO.isPrivacyReasonRequired());
                        xcapDiffNotifyDTO.setReason(KnConstants.REASON.PRIVACY_OPT_IN.value());
                    }
                    for (KnOPDocChgDTO chgDTO : chgDocList) {
                        KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                        xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                        xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                        xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                        xcapDocList.add(xcapDiffDocDTO);
                        knLogger.debug(methodName, "--->chgDTO::" + chgDTO + " xcapDiffDocDTO::" + xcapDiffDocDTO + " xcapDocList::" + xcapDocList);
                    }
                    xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                    xcapDiffNotifyDTO.setDirNewEtag(opDirChgDTO.getDirNewEtag());
                    xcapDiffNotifyDTO.setDirPrevEtag(opDirChgDTO.getDirPrevEtag());
                    xcapDiffNotifyDTO.setDirURI(opDirChgDTO.getDirUri());
                    xcapDiffNotifyDTO.setXcapRootUri(opDirChgDTO.getXcapRootURI());
                    xcapDiffNotifyDTO.setProtocolVersion(opDirChgDTO.getProtoVersion());
                    xcapDiffNotifyDTO.setPocHome(opDirChgDTO.getPocHome());
                    xcapDiffNotifyDTO.setPresenceHome(opDirChgDTO.getPresenceHome());
                    //xcapDiffNotifyDTO.setSubscribeNotify(true);
                    xcapConfigDiffList.add(xcapDiffNotifyDTO);
                    // boolean notificationStatus = xcapDiffNotifier.generateDirNotification(xcapDiffNotifyDTO);

                    knLogger.debug(methodName, "--->After : xcapDiffNotifyDTO::" + xcapDiffNotifyDTO + " xcapConfigDiffList::" + xcapConfigDiffList);

               /* if (notificationStatus) {
                    knLogger.debug(methodName, "Successfully sent the notification");
                } */
                    //  }
                }

                knLogger.debug(methodName, "xcapDiffList - ", xcapConfigDiffList);
                notifier.setMaxNotfnsPerJob(KnMediatorConstants.DEFAULT_NOTIFY_SIZE);
                boolean isConfigNotified = notifier.sendXcapDiffNotifications(xcapConfigDiffList, notificationParamDTO);
                knLogger.debug(methodName, "Notification status for isConfigNotified - ", isConfigNotified);
                // }
            }
            //notification ends
            knLogger.info(methodName, "Returning setTargetPermissions response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error( methodName, "KnPersistenceException occured while setTargetPermissions", e);
            respDto = populateResponse(e, respDto);

        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while setTargetPermissions",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    /**
     * Interface to get the mapping for an Authorized MDN with the corresponding Targets MDNs and allowed permissions,
     * before doing operation it will first do the business validation in CorpLiberary and populates to the commdto
     * (between wrapper and the Server) and sends the response back to the client (SOAP client etc.) through messaging fw RMQ.
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO getTargetPermissions(KnMessage message) {
        String methodName = "getTargetPermissions(IXDMRequestDTO)";
        KnXDMCorpAuthUserPermissionRespDTO respDto = new KnXDMCorpAuthUserPermissionRespDTO();
        KnPersisterTxn persisterTxn = null;
        IXDMRequestDTO requestDTO = null;
        Object payLoad = message.getPayLoad();
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (!(requestDTO instanceof KnCorpSubsResquestDTO)) {
                knLogger.error(methodName, "requestDTO not of type KnCorpSubsResquestDTO - requestDTO - ",
                        requestDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnCorpSubsResquestDTO xdmRequestDTO = (KnCorpSubsResquestDTO) requestDTO;
            knLogger.debug(methodName, "xdmRequestDto :: ", xdmRequestDTO);
            //validate corp Hierarchy
            int clientIntf = xdmRequestDTO.getClientType();
            if(CLIENT_TYPE_SOAP == clientIntf){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_MCPTT_PERMISSION_REQ);
                if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            respDto = corpMediator.getTargetPermissions(requestDTO, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                throw new KnXDMServerException(respDto.getResponseCode(),
                        respDto.getResponseMessage());
            }
            knLogger.info(methodName,"Sending response", respDto);
            persisterTxn.save();
            if(CLIENT_TYPE_SOAP == clientIntf){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_MCPTT_PERMISSION_REQ_SUCC);
            }
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error( methodName, "KnPersistenceException occured while getTargetPermissions", e);
            respDto = populateResponse(e, respDto);

        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while getTargetPermissions",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

