    @Override
    public IXDMResponseDTO updateAuthorizationList(KnMessage message) {
        String methodName = "updateAuthorizationList(IXDMRequestDTO)";
        knLogger.entry(methodName);
        IXDMResponseDTO responseDTO = new KnXDMAuthListResponseDTO();
        KnXDMAuthListRequestDTO xdmAuthListRequestDTO = null;
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_UPDATE_AUTH_REQ);
            xdmAuthListRequestDTO = (KnXDMAuthListRequestDTO) requestDTO;
            knLogger.debug(methodName, "received DTO for update auth list - ", xdmAuthListRequestDTO.getTargetInfo());
            String featureStatus = xdmAuthListRequestDTO.getTargetInfo().iterator().next().getFeatureStatus();
            String[] fstatus = featureStatus.split(",");
            int userServStatusflag = Integer.parseInt(fstatus[0]);
            int discreetListenerStatus = Integer.parseInt(fstatus[1]);

            if (userServStatusflag == 0) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_USER_DISABLE_REQ);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_USER_ENABLE_REQ);
            }

            if (discreetListenerStatus == 0) {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_DISCREET_DISABLE_REQ);
            } else {
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_DISCREET_ENABLE_REQ);
            }

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            // Create and Modify auth List from input data
            knLogger.debug(methodName, "Update Auth List Request ", xdmAuthListRequestDTO);
            KnOpPubResponse response = pubDocMediator.updateAuthList(xdmAuthListRequestDTO, persisterTxn);
            List<KnOPDirChgDTO> dirChgDTOs = response.getDirChgDTOs();
            knLogger.debug(methodName, "Response from public library ", response);
            KnXDMPubRespDTO pubResp = new KnXDMPubRespDTO();
            pubResp.setDocEtag(response.getDocEtag());
            responseDTO = commonMediator.getSuccessResponse(pubResp);

            KnSubscriberInfoDTO knSubscriberInfoDTO = new KnSubscriberInfoDTO();

            //Fetching the boolean value for 45th bit,
            // If it is true then we will call the new REST API.
            boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(response.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
            knLogger.debug(methodName, "xcapCouchClientBit ",xcapCouchClientBit);


            String targetMdn = xdmAuthListRequestDTO.getTargetInfo().iterator().next().getTargetMdn();

            //checking if 45th bit is 0/false or 1/true. If not 0/false then we make the rest call
            if(xcapCouchClientBit){
                //Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                knSubscriberInfoDTO.setMdn(targetMdn);
                //knSubscriberInfoDTO.setDisabled(provRespDTO.isSyncDisabled());
                knLogger.debug(methodName, "knSubscriberInfoDTO : mdn",KnGDPRTemplate.mdn(knSubscriberInfoDTO.getMdn()));
                knLogger.debug(methodName, "knSubscriberInfoDTO : sync",knSubscriberInfoDTO.isDisabled());

                //Storing the list of bucket urls in a list
                Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                knLogger.debug(methodName, "bucketUrlList : ",bucketUrlList);
                KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                    List<String> bucketUrl = new ArrayList<>();
                    Integer curClusterId = entry.getKey();
                    knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                    bucketUrl.add(entry.getValue());
                    //REST call for profile creation starts here.
                    KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().updateSyncDocument(knSubscriberInfoDTO, bucketUrl);
                    knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                    if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                        failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                        failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                        failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                        failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_ENABLE.value());
                        if(knSubscriberInfoDTO.isDisabled()) {
                            failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DISABLE.value());
                        }
                        genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    }
                }
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync",xcapMobileSync);
            if(xcapMobileSync){
                KnSubscrEXDMSNotifyBulkDTO knSubscrEXDMSNotifyBulkDTO=new KnSubscrEXDMSNotifyBulkDTO();
                //  List contain description of the data: variable name is mdnList as json o/p req
                List<KnSubscrEXDMSNotifyBulkDTO> KnSubscrEXDMSNotifyBulkDToList=new ArrayList<KnSubscrEXDMSNotifyBulkDTO>();

                knSubscrEXDMSNotifyBulkDTO.setId(CHANGE_SERVICE_AUTH_STATUS.value());
                knSubscrEXDMSNotifyBulkDTO.setType(CHANGE_SERVICE_AUTH_STATUS.value());
                knSubscrEXDMSNotifyBulkDTO.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knSubscrEXDMSNotifyBulkDTO.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());

                List<KnSubscrEXDMSNotifyDto> notifyDtoList= new ArrayList<KnSubscrEXDMSNotifyDto>();
                KnSubscrEXDMSNotifyDto knSubscrEXDMSNotifyDTO=new KnSubscrEXDMSNotifyDto();
                knSubscrEXDMSNotifyDTO.setMdn(targetMdn);
                //knSubscrEXDMSNotifyDTO.setCorpid(provRespDTO.getCorpid());
                //knSubscrEXDMSNotifyDTO.setAuthStatus(provRespDTO.getAuthStatus());
                //knSubscrEXDMSNotifyDTO.setClientType(subsClientType);

                knSubscrEXDMSNotifyDTO.setAuthStatus(response.getServiceAuthStatus());
                knSubscrEXDMSNotifyDTO.setLastProfileUpdateTime(Long.parseLong(response.getDocEtag()));
                notifyDtoList.add(knSubscrEXDMSNotifyDTO);
                knSubscrEXDMSNotifyBulkDTO.setMdnList(notifyDtoList);
                KnSubscrEXDMSNotifyBulkDToList.add(knSubscrEXDMSNotifyBulkDTO);

                if(response.getProfileMdnList()!=null)
                {
                    for (String mdn : response.getProfileMdnList()) {
                        KnSubscrEXDMSNotifyDto profileMdnNotifyDto = new KnSubscrEXDMSNotifyDto();
                        profileMdnNotifyDto.setMdn(mdn);
                        /*List<KnSubscrEXDMSNotifyDto> notifyProfileMdnDtoList= new ArrayList<KnSubscrEXDMSNotifyDto>();
						notifyProfileMdnDtoList.add(knSubscrEXDMSNotifyDto);
						KnSubscrEXDMSNotifyBulkDTO knSubscrEXDMSNotifyBulkDto=new KnSubscrEXDMSNotifyBulkDTO();
						knSubscrEXDMSNotifyBulkDto.setId(MICROSERVICES_EVENT_TYPE.CHANGE_SERVICE_AUTH_STATUS.value() + KnConstants.LINE_SAPERATOR + mdn);
						knSubscrEXDMSNotifyBulkDto.setType(MICROSERVICES_EVENT_TYPE.CHANGE_SERVICE_AUTH_STATUS.value());
						knSubscrEXDMSNotifyBulkDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
						knSubscrEXDMSNotifyBulkDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());*/
                        //setting service auth status and etag of base mdns to profile mdns
                        profileMdnNotifyDto.setAuthStatus(response.getServiceAuthStatus());
                        profileMdnNotifyDto.setLastProfileUpdateTime(Long.parseLong(response.getDocEtag()));
                        notifyDtoList.add(profileMdnNotifyDto);
                        knSubscrEXDMSNotifyBulkDTO.setMdnList(notifyDtoList);
                        KnSubscrEXDMSNotifyBulkDToList.add(knSubscrEXDMSNotifyBulkDTO);


                    }
                }
                knLogger.debug(methodName,"KnSubscrEXDMSNotifyBulkDToList :",KnSubscrEXDMSNotifyBulkDToList);

                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(KnSubscrEXDMSNotifyBulkDToList);
            }

            knLogger.debug(methodName, "saving the transaction ");
            persisterTxn.save();

            int i = 0;
            knLogger.debug(methodName, "mdn length :", response.getMdnList().size());
            knLogger.debug(methodName, "dirChgDTOs :", dirChgDTOs.size());
            List<KnXcapDiffNotifyDTO> dirNotList = new ArrayList<>();
            int serviceStatusAuthUser = response.getServiceStatusAuthUser();
            int serviceAuthStatus = response.getServiceAuthStatus();
            KnXcapDiffNotifyDTO xcapDiffNotifyDTO;
            List<KnXcapDiffNotifyDTO> xcapDiffList = new ArrayList<>();
            for (String mdn : response.getMdnList()) {
                xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                if (dirChgDTOs.size() != 0) {
                    if ((mdn.equals(xdmAuthListRequestDTO.getTargetInfo().get(0).getTargetMdn())
                            ||(response.getProfileMdnList()!=null&&response.getProfileMdnList().contains(mdn)))
                            &&KnConstants.SERVICE_AUTH_STATUS.DEACTIVATED.value()==serviceAuthStatus){
                        xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_DEACTIVATE_AUTH.value());
                        KnDeRegisterNotifyDTO deRegisterNotifyDTO = new KnDeRegisterNotifyDTO();
                        xcapDiffNotifyDTO.setDeRegisterNotify(true);
                        deRegisterNotifyDTO.setMdn(mdn.trim());
                        deRegisterNotifyDTO.setPocHome(dirChgDTOs.get(i).getPocHome());
                        deRegisterNotifyDTO.setPresenceHome(dirChgDTOs.get(i).getPresenceHome());
                        deRegisterNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.USER_DEACTIVATE.value());
                        //xcapDiffNotifyDTO.setProtocolVersion("9");
                        xcapDiffNotifyDTO.setDeRegisterNotifyDTO(deRegisterNotifyDTO);
                    }
                    Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<>();
                    ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) dirChgDTOs.get(i).getDocChgDTO();
                    for (KnOPDocChgDTO chgDTO : chgDocList) {
                        KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                        xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                        xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                        xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                        xcapDocList.add(xcapDiffDocDTO);
                    }

                    xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                    xcapDiffNotifyDTO.setDirNewEtag(dirChgDTOs.get(i).getDirNewEtag());
                    xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTOs.get(i).getDirPrevEtag());
                    xcapDiffNotifyDTO.setDirURI(dirChgDTOs.get(i).getDirUri());
                    xcapDiffNotifyDTO.setXcapRootUri(dirChgDTOs.get(i).getXcapRootURI());
                    xcapDiffNotifyDTO.setProtocolVersion(dirChgDTOs.get(i).getProtoVersion());
                    xcapDiffNotifyDTO.setPocHome(dirChgDTOs.get(i).getPocHome());
                    xcapDiffNotifyDTO.setPresenceHome(dirChgDTOs.get(i).getPresenceHome());

                    xcapDiffList.add(xcapDiffNotifyDTO);
                    i++;
                }
            }

            if(!xcapDiffList.isEmpty()) {
                knLogger.debug(methodName, "Notification DTO generated - ", xcapDiffList);
                notifier.setMaxNotfnsPerJob(KnProvConstants.DEFAULT_NOTIFY_SIZE);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                notificationParamDTO.setPriority(KnConstants.NOTIFICATION_PRIORITY.HIGH.value());
                boolean status = notifier.sendXcapDiffNotifications(xcapDiffList, notificationParamDTO);
                knLogger.info(methodName, "Notification status - ", status);
            }

            if(response != null){
                boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(response.getProfileMdnEtagMap(),response.getMcsXcapRootUriMap());
                knLogger.debug(methodName, "sending Profile notification Status: ", profileNotifyStatus);
            }

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_UPDATE_AUTH_REQ_SUCCESS);

            if(response.isDiscreetChanged() && discreetListenerStatus == 0){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_DISCREET_DISABLE_REQ_SUCCESS);
            }else if(response.isDiscreetChanged() && discreetListenerStatus == 1){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_DISCREET_ENABLE_REQ_SUCCESS);
            }

            if(response.isServiceAuthChange() && userServStatusflag == 0){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_USER_DISABLE_REQ_SUCCESS);
            }else if(response.isServiceAuthChange() && userServStatusflag == 1){
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_USER_ENABLE_REQ_SUCCESS);
            }

            //REST call for updating profile in OidcIDM
            if (response.isServiceAuthChange()) {
                String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
                String appId = (response.getDispatchType() == DISPATCH_TYPE_WEB) ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                int state = response.getServiceAuthStatus() == KnConstants.SERVICE_STATUS_AUTHUSER.ACTIVATED.value() ? IDM_ACCOUNT_STATUS.ENABLE.value() : IDM_ACCOUNT_STATUS.DISABLE.value();
                Map<String, Object> attributes = Map.of(ACCOUNT_STATUS, String.valueOf(state));
                KnXDMSubsAliasDetailsReqDTO oidcSubsDto = new KnXDMSubsAliasDetailsReqDTO();
                oidcSubsDto.setUserid(targetMdn);
                oidcSubsDto.setAttributes(attributes);
                KnXDMSubsAliasDetailsRespDTO oidcRespDto = KnManageSyncUserProfileUtil.getInstance().notifyIDMIntfForOIDCMgmt(oidcSubsDto, appId, idmFqdn, com.kodiak.common.resources.KnConstants.CHANGE_SERVICE_AUTH_STATUS, HttpMethod.PUT);
                if (oidcRespDto != null && oidcRespDto.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()) {
                    knLogger.error(methodName, "Exception occurred while updating profile in OidcIDM - ", oidcRespDto.getStatus());
                    throw new KnProvBOException(KnErrorCodes.BOEntity.INTERNAL_ERROR, "Exception occurred while updating subscriber account status in OIDC IDM");
                }
            }
        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Failed to get the Transaction", e);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Failed to Update Scan List ", e);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        }
        return responseDTO;
    }


