    /**
     * @param message
     */
    public IXDMResponseDTO getPubContactList(KnMessage message) {
        String methodName = "getPubContactList";
        KnXDMContactListInfoDTO contactDTO;
        KnPersisterTxn persisterTxn = null;
        KnXDMContactListInfoRespDTO responseDTO = new KnXDMContactListInfoRespDTO();
        IXDMRequestDTO pubContInfoDTO = null;
        try {
            pubContInfoDTO = (IXDMRequestDTO) message.getPayLoad();
            if (!(pubContInfoDTO instanceof KnXDMContactListInfoDTO)) {
                knLogger.error(methodName, "Invalid DTO - ", pubContInfoDTO);
                responseDTO.setResponseMessage("Invalid DTO passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                commonMediator.sendFailureResponse(responseDTO, message, null);
                KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_CONTACT_LIST_DOC_RETRIEVE_FAILURE);
                return responseDTO;
            }
            contactDTO = (KnXDMContactListInfoDTO) pubContInfoDTO;
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_PUB_GROUP_DETAILS_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            responseDTO = pubDocMediator.getContactListDetails(contactDTO, persisterTxn);
            knLogger.debug(methodName, "Get Pub Contact List Resp : ", responseDTO);
            persisterTxn.save();
            commonMediator.getSuccessResponse(responseDTO);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_CONTACT_LIST_DOC_RETRIEVED);
        } catch (Exception ex) {
            knLogger.error(methodName, "Failed to Get Pub Contact List ");
            rollback(persisterTxn);
            knLogger.error(methodName, "Un-Expected Exception occurred - ", ex);
            responseDTO = new KnXDMContactListInfoRespDTO();
            commonMediator.getFailureResponse(responseDTO, ex);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_PUBLIC_CONTACT_LIST_DOC_RETRIEVE_FAILURE);
        }
        return responseDTO;
    }

    /**
     * Method which update the subscribers alias entities
     * and populates to the commdto (between wrapper and the Server) and sends the response back to the client
     * (SOAP client etc.) through messaging fw RMQ.
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    @Override
    @Deprecated
    //Incomplete Method as of now, need to address OIDC integartion in future.
    public IXDMResponseDTO updateSubsAliasEntities(KnMessage message) {
        String methodName = "updateSubsAliasEntities(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_SUBSCR_PROFILE);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Getting the Subscriber profile:
            knLogger.debug(methodName, "retrieving the subscriber profile for mdn ");
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            KnIPSubscriberInfoDTO subscrInfoDTO = new KnIPSubscriberInfoDTO();
            KnCorpSubsResquestDTO reqDto = (KnCorpSubsResquestDTO) requestDTO;
            subscrInfoDTO.setMdn(reqDto.getSubscriberMdn());
            // This call may required to get the data for OIDC call.
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscrInfoDTO, persisterTxn);
            // Calling the corpLibrary for the business operation:
            corpResponseDTO = corpMediator.updateSubsAliasEntities(requestDTO, persisterTxn);
            populateXdmResponse(respDto, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            if(corpResponseDTO.isUserIdChanged() || corpResponseDTO.isAliasMdnChanged()) {
                String oidcFqdn = genInfoUtil.getOIDCInternalFqdn(persisterTxn);
                knLogger.debug(methodName, "oidcFqdn - ", oidcFqdn);
                //todo: OIDC Integration


            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            knLogger.debug(methodName, "xcapMobileSync - ", xcapMobileSync);
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_SUBSCR_PROFILE_SUCC_RESP);
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResponseDTO);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            if(corpResponseDTO.isProfileChanged()) {
                List<KnOPDirChgDTO> dirChgDTOs = corpResponseDTO.getDirChgDTOs();
                knLogger.debug(methodName, "dirChgDTOs ", dirChgDTOs);
                List<KnXcapDiffNotifyDTO> xcapConfigDiffList = new ArrayList<KnXcapDiffNotifyDTO>();
                for (KnOPDirChgDTO opDirChgDTO : dirChgDTOs) {
                    KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                    Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                    ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) opDirChgDTO.getDocChgDTO();
                    knLogger.debug(methodName, "chgDocList - ", chgDocList);
                    for (KnOPDocChgDTO chgDTO : chgDocList) {
                        KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                        xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                        xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                        xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                        xcapDocList.add(xcapDiffDocDTO);
                    }
                    xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                    xcapDiffNotifyDTO.setDirNewEtag(opDirChgDTO.getDirNewEtag());
                    xcapDiffNotifyDTO.setDirPrevEtag(opDirChgDTO.getDirPrevEtag());
                    xcapDiffNotifyDTO.setDirURI(opDirChgDTO.getDirUri());
                    xcapDiffNotifyDTO.setXcapRootUri(opDirChgDTO.getXcapRootURI());
                    xcapDiffNotifyDTO.setProtocolVersion(opDirChgDTO.getProtoVersion());
                    xcapDiffNotifyDTO.setPocHome(opDirChgDTO.getPocHome());
                    xcapDiffNotifyDTO.setPresenceHome(opDirChgDTO.getPresenceHome());
                    xcapConfigDiffList.add(xcapDiffNotifyDTO);
                }
                knLogger.debug(methodName, "xcapDiffList - ", xcapConfigDiffList);
                notifier.setMaxNotfnsPerJob(KnMediatorConstants.DEFAULT_NOTIFY_SIZE);
                boolean isConfigNotified = notifier.sendXcapDiffNotifications(xcapConfigDiffList, notificationParamDTO);
                knLogger.debug(methodName, "Notification status for isConfigNotified - ", isConfigNotified);
            }
            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify for Group event - ");
                commonMediator.startNotifyMicroServicesJob(corpResponseDTO.getChangeLogMap(), corpResponseDTO.getMdnCorpId());
            }
            knLogger.info(methodName,"Sending response", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error( methodName, "KnPersistenceException occured while updateSubsAliasEntities", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while updateSubsAliasEntities",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

