    /**
     * Method which generate temp password for MDN
     * and populates to the commdto (between wrapper and the Server) and sends the response back to the client
     * (SOAP client etc.) through messaging fw RMQ.
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO generateTempPassword(KnMessage message) {
        String methodName = "generateTempPassword(IXDMRequestDTO)";
        KnCorpSubsInfoRespDTO xdmRespDto = new KnCorpSubsInfoRespDTO();
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        KnXDMSubsAliasDetailsRespDTO oidcRespDto = null;
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            // Getting the Subscriber profile:
            knLogger.debug(methodName, "retrieving the subscriber profile for mdn ");
            KnIPSubscriberInfoDTO subscrInfoDTO = new KnIPSubscriberInfoDTO();
            KnCorpSubsResquestDTO reqDto = (KnCorpSubsResquestDTO) requestDTO;
            subscrInfoDTO.setMdn(reqDto.getSubscriberMdn());
            // This call may required to get the data for OIDC call.
            respDto = corpMediator.generateTempPassword(requestDTO, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == respDto.getStatus()) {
                String tmpPwd = null;
                String pwdExpiryInMilli = null;
                KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscrInfoDTO, persisterTxn);
                String appId = subsProfileInfoDTO.getDispatchType() == DISPATCH_TYPE_WEB ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                KnXDMSubsAliasDetailsReqDTO oidcSubsDto = new KnXDMSubsAliasDetailsReqDTO();
                if (subsProfileInfoDTO.getAliasMdn() != null) {
                    oidcSubsDto.setUserid(subsProfileInfoDTO.getAliasMdn());
                    xdmRespDto.setAliasMdn(subsProfileInfoDTO.getAliasMdn());
                    generalCacheUtil.deleteOldOidcTmpPwd(reqDto.getSubscriberMdn());
                } else {
                    oidcSubsDto.setUserid(reqDto.getSubscriberMdn());
                    xdmRespDto.setMdn(reqDto.getSubscriberMdn());
                }
                Map<String, Object> oidcAttributes = new HashMap<>();
                oidcAttributes.put(MCPTT_ID_OIDC, subsProfileInfoDTO.getMdn());
                oidcAttributes.put(MCVIDEO_ID_OIDC, subsProfileInfoDTO.getMcVideoId());
                oidcAttributes.put(MCDATA_ID_OIDC, subsProfileInfoDTO.getMcDataId());
                oidcSubsDto.setAttributes(oidcAttributes);
                String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
                oidcRespDto = KnManageSyncUserProfileUtil.getInstance()
                        .notifyIDMIntfForOIDCMgmt(oidcSubsDto, appId, idmFqdn, null, HttpMethod.GET);
                int clusterId = Integer.parseInt(System.getenv(com.kodiak.common.resources.KnConstants.CLUSTERID_ENV_NAME));
                Map<String, String> microServicesParamNameValueMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
                String pwdExpiry = microServicesParamNameValueMap.get(TEMP_PASSWORD_EXPIRY);
                int passwordExpiry = 0;
                if (pwdExpiry != null) passwordExpiry = Integer.parseInt(pwdExpiry);
                long currentTimeInMilliSecond = System.currentTimeMillis();
                pwdExpiryInMilli = String.valueOf(currentTimeInMilliSecond + (1000 * 60 * passwordExpiry));
                int statusCode = oidcRespDto.getStatusCode();
                if (statusCode == HttpStatus.NOT_FOUND.value()) {
                    tmpPwd = pwdUtil.generatePassword(com.kodiak.common.resources.KnConstants.MAX_OIDC_PASSWORD_LENGTH, appId);
                    oidcSubsDto.setTemppwd(Boolean.TRUE);
                    oidcSubsDto.setPwd(tmpPwd);
                    oidcSubsDto.setGeneratepwd(tmpPwd == null);
                    oidcSubsDto.setEmail(subsProfileInfoDTO.getUserId());
                    oidcSubsDto.setAttributes(oidcAttributes);
                    oidcRespDto = KnManageSyncUserProfileUtil.getInstance().createIDMUserForOIDCMgmt(oidcSubsDto, appId,
                            idmFqdn, false, null);
                    knLogger.debug(methodName, "oidcRespDto ", oidcRespDto);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == oidcRespDto.getStatus()) {
                        knLogger.error(methodName, "Profile Creation Failed to OIDC ");
                        throw new KnXDMServerException(oidcRespDto.getResponseCode(), oidcRespDto.getResponseMessage());
                    }
                } else {
                    tmpPwd = pwdUtil.generatePassword(com.kodiak.common.resources.KnConstants.MAX_OIDC_PASSWORD_LENGTH, appId);
                    oidcSubsDto = new KnXDMSubsAliasDetailsReqDTO();
                    oidcSubsDto.setUserid(oidcRespDto.getUserid());
                    oidcSubsDto.setPwd(tmpPwd);
                    oidcSubsDto.setGeneratepwd(tmpPwd == null);
                    oidcSubsDto.setTemppwd(Boolean.TRUE);
                    oidcRespDto = KnManageSyncUserProfileUtil.getInstance()
                            .notifyIDMIntfForOIDCMgmt(oidcSubsDto, appId, idmFqdn, UPDATE_USER_PASSWORD, HttpMethod.PUT);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == oidcRespDto.getStatus()) {
                        knLogger.error(methodName, "UPDATE_USER_PASSWORD Failed to OIDC ");
                        throw new KnXDMServerException(oidcRespDto.getResponseCode(), oidcRespDto.getResponseMessage());
                    }
                }
                String saltForPwd = oidcSubsDto.getUserid();
                generalCacheUtil.deleteOldOidcTmpPwd(saltForPwd);
                KnOidcTmpPwdDTO oidcTmpPwdDTO = new KnOidcTmpPwdDTO();
                if(tmpPwd != null){
                    knLogger.debug(methodName, "saltForPwd & tmpPwd ", saltForPwd, tmpPwd);
                    String encryptedPwd = encryptionDecryptionUtil.encrypt(saltForPwd, tmpPwd);
                    knLogger.debug(methodName, "encryptedPwd-- ", encryptedPwd);
                    String derivedKey = KnGeneralUtil.convertToHex(encryptedPwd.getBytes());
                    oidcTmpPwdDTO.setTmpPwd(KnGeneralUtil.convertHexToAscii(derivedKey));
                    oidcTmpPwdDTO.setMdn(saltForPwd);
                    oidcTmpPwdDTO.setTmpPwdCreationTS(String.valueOf(currentTimeInMilliSecond));
                    oidcTmpPwdDTO.setTmpPwdExpiry(pwdExpiryInMilli);
                    generalCacheUtil.insertOidcTmpPwd(oidcTmpPwdDTO);
                }
                if(PROTOCOL_VERSION_0 != subsProfileInfoDTO.getClientPVmajorVer() && subsProfileInfoDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13){
                    xdmRespDto.setMdn(reqDto.getSubscriberMdn());
                    tmpPwd = pwdUtil.generatePassword(com.kodiak.common.resources.KnConstants.MAX_OIDC_PASSWORD_LENGTH, appId);
                    KnXDMCorpClientActRequestDTO clientActRequestDTO = new KnXDMCorpClientActRequestDTO();
                    clientActRequestDTO.setMdn(reqDto.getSubscriberMdn());
                    clientActRequestDTO.setCorpId(String.valueOf(reqDto.getCorpId()));
                    clientActRequestDTO.setCustomParamMap(reqDto.getCustomParamMap());
                    clientActRequestDTO.setClientType(reqDto.getClientType());
                    clientActRequestDTO.setHierarchyType(reqDto.getHierarchyType());
                    clientActRequestDTO.setTmpPwd(tmpPwd);
                    KnXDMCorpClientActResponseDTO actRespDto = corpMediator.getSubscriberEmailId(clientActRequestDTO, persisterTxn);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == actRespDto.getResponseStatus()) {
                        throw new KnXDMServerException(actRespDto.getResponseCode(), actRespDto.getResponseMessage());
                    }
                    pwdExpiryInMilli = actRespDto.getExpiryTimestamp();
                    // Step:
                    KnXDMSubsStatusInfoDTO subsStatusInfoDTO = new KnXDMSubsStatusInfoDTO();
                    String mdn = reqDto.getSubscriberMdn();
                    subsStatusInfoDTO.setMdn(mdn);
                    subsStatusInfoDTO.setClientType(com.kodiak.common.resources.KnConstants.CLIENT_TYPE_CAT_UI);
                    subsStatusInfoDTO.setServiceAuthStatus(KnMediatorConstants.SUBSCRIBER_PROVISIONED);
                    KnXDMRespDTO provResponse = (KnXDMRespDTO) changeServiceAuthStatus(subsStatusInfoDTO, persisterTxn,
                            KnConstants.MESSAGE_TYPE.USER_CREDENTIAL_CHANGE);
                    // If failuere in provisioning library
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == provResponse.getResponseStatus()) {
                        knLogger.error(methodName, "Exception occured in provisioning library ");
                        throw new KnXDMServerException(provResponse.getResponseCode(), provResponse.getResponseMessage());
                    }
                }
                xdmRespDto.setTmpPwd(tmpPwd);
                xdmRespDto.setTmpPwdExpiry(pwdExpiryInMilli);
            } else {
                throw new KnXDMServerException(xdmRespDto.getResponseCode(), xdmRespDto.getResponseMessage());
            }
            persisterTxn.save();
            List<KnOPDirChgDTO> dirChgDTOs = respDto.getDirChgDTOs();
            knLogger.debug(methodName, "dirChgDTOs ", dirChgDTOs);
            KnXcapDiffNotifier xcapDiffNotifier = KnXcapDiffNotifier.getInstance();
            List<KnXcapDiffNotifyDTO> xcapConfigDiffList = new ArrayList<KnXcapDiffNotifyDTO>();
            KnNotificationParamDTO knNotificationParamDTO = new KnNotificationParamDTO();
            knNotificationParamDTO.setCid(message.getCorrelationId());
            knNotificationParamDTO.setPriority(NOTIFICATION_PRIORITY.HIGH.value());
            for (KnOPDirChgDTO opDirChgDTO : dirChgDTOs) {
                KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                Map<String, String> updateTimeMap = respDto.getUpdateTimeMap();
                Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) opDirChgDTO.getDocChgDTO();
                knLogger.debug(methodName, "chgDocList - ", chgDocList);
                KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                profileNotifyDTO.setCredentialChange(reqDto.getSubscriberMdn());
                profileNotifyDTO.setLastProfileUpdateTimestamp(updateTimeMap.get(reqDto.getSubscriberMdn()));
                xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_CREDENTIAL_CHANGE.value());
                xcapDiffNotifyDTO.setProfileNotify(true);
                profileNotifyDTO.setMdn(reqDto.getSubscriberMdn());
                profileNotifyDTO.setPocHome(opDirChgDTO.getPocHome());
                profileNotifyDTO.setPresenceHome(opDirChgDTO.getPresenceHome());
                profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());
                xcapDiffNotifyDTO.setProfileNotifyDTO(profileNotifyDTO);
                for (KnOPDocChgDTO chgDTO : chgDocList) {
                    KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                    xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                    xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                    xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                    xcapDocList.add(xcapDiffDocDTO);
                }
                xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                xcapDiffNotifyDTO.setDirNewEtag(opDirChgDTO.getDirNewEtag());
                xcapDiffNotifyDTO.setDirPrevEtag(opDirChgDTO.getDirPrevEtag());
                xcapDiffNotifyDTO.setDirURI(opDirChgDTO.getDirUri());
                xcapDiffNotifyDTO.setXcapRootUri(opDirChgDTO.getXcapRootURI());
                xcapDiffNotifyDTO.setProtocolVersion(opDirChgDTO.getProtoVersion());
                xcapDiffNotifyDTO.setPocHome(opDirChgDTO.getPocHome());
                xcapDiffNotifyDTO.setPresenceHome(opDirChgDTO.getPresenceHome());
                xcapDiffNotifyDTO.setNtfyOnAnyMDN(opDirChgDTO.getNtfyOnAnyMDN());
                xcapConfigDiffList.add(xcapDiffNotifyDTO);
                boolean notificationStatus = notifier.sendXcapDiffNotifications(xcapDiffNotifyDTO, knNotificationParamDTO);
                if (notificationStatus) {
                    knLogger.debug(methodName, "Successfully sent the notification");
                }
            }
            if (null != respDto.getProfileMdnDirChgDTOs() && !respDto.getProfileMdnDirChgDTOs().isEmpty()) {
                List<KnOPDirChgDTO> profileDirChgDTOs = respDto.getProfileMdnDirChgDTOs();
                for (KnOPDirChgDTO opDirChgDTO : profileDirChgDTOs) {
                    KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                    Map<String, String> updateTimeMap = respDto.getUpdateTimeMap();
                    Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<KnXcapDiffDocDTO>();
                    ArrayList<KnOPDocChgDTO> chgDocList = (ArrayList<KnOPDocChgDTO>) opDirChgDTO.getDocChgDTO();
                    KnProfileNotifyDTO profileNotifyDTO = new KnProfileNotifyDTO();
                    profileNotifyDTO.setCredentialChange(opDirChgDTO.getMdn());
                    profileNotifyDTO.setLastProfileUpdateTimestamp(updateTimeMap.get(reqDto.getSubscriberMdn()));
                    xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_CREDENTIAL_CHANGE.value());
                    xcapDiffNotifyDTO.setProfileNotify(true);
                    profileNotifyDTO.setMdn(opDirChgDTO.getMdn());
                    profileNotifyDTO.setPocHome(opDirChgDTO.getPocHome());
                    profileNotifyDTO.setPresenceHome(opDirChgDTO.getPresenceHome());
                    profileNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.SUBSCR_PROFILE_CHANGE.value());
                    xcapDiffNotifyDTO.setProfileNotifyDTO(profileNotifyDTO);
                    for (KnOPDocChgDTO chgDTO : chgDocList) {
                        KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                        xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                        xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                        xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                        xcapDocList.add(xcapDiffDocDTO);
                    }
                    xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                    xcapDiffNotifyDTO.setDirNewEtag(opDirChgDTO.getDirNewEtag());
                    xcapDiffNotifyDTO.setDirPrevEtag(opDirChgDTO.getDirPrevEtag());
                    xcapDiffNotifyDTO.setDirURI(opDirChgDTO.getDirUri());
                    xcapDiffNotifyDTO.setXcapRootUri(opDirChgDTO.getXcapRootURI());
                    xcapDiffNotifyDTO.setProtocolVersion(opDirChgDTO.getProtoVersion());
                    xcapDiffNotifyDTO.setPocHome(opDirChgDTO.getPocHome());
                    xcapDiffNotifyDTO.setPresenceHome(opDirChgDTO.getPresenceHome());
                    xcapDiffNotifyDTO.setNtfyOnAnyMDN(opDirChgDTO.getNtfyOnAnyMDN());
                    xcapConfigDiffList.add(xcapDiffNotifyDTO);
                }
            }
            knLogger.debug(methodName, "xcapDiffList - ", xcapConfigDiffList);
            notifier.setMaxNotfnsPerJob(KnMediatorConstants.DEFAULT_NOTIFY_SIZE);
            boolean isConfigNotified = notifier.sendXcapDiffNotifications(xcapConfigDiffList, knNotificationParamDTO);
            knLogger.debug(methodName, "Notification status for isConfigNotified - ", isConfigNotified);
            knLogger.info(methodName, "Sending response", xdmRespDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while generateTempPassword", e);
            xdmRespDto = populateResponse(e, xdmRespDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while generateTempPassword",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto);
        }
        return xdmRespDto;
    }

    /**
     * Method which get the mdn list for provided emergency destination for input destination type.
     * and populates to the commdto (between wrapper and the Server) and sends the response back to the client
     * (SOAP client etc.) through messaging fw RMQ.
     *
     * @param requestDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO getUserEmergDest(IXDMRequestDTO requestDTO) {
        String methodName = "getUserEmergDest(IXDMRequestDTO)";
        KnUserEmergDestResponseDTO respDto = new KnUserEmergDestResponseDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            //KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_SET_EMERGENCY_ATTRIBUTES_REQ);
            if (!(requestDTO instanceof KnCorpSubsEmergencyRequestDTO)) {
                knLogger.error(methodName, "requestDTO not of type KnCorpSubsEmergencyRequestDTO - requestDTO - ",
                        requestDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnCorpSubsEmergencyRequestDTO xdmRequestDTO = (KnCorpSubsEmergencyRequestDTO) requestDTO;
            knLogger.debug(methodName, "xdmRequestDto :: ", xdmRequestDTO);
            //validate corp Hierarchy
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            respDto = corpMediator.getUserEmergDest(requestDTO, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),
                        respDto.getResponseMessage());
            }
            // Step:
            // save the transaction
            knLogger.debug(methodName, "Saving Transaction");
            persisterTxn.save();
            //KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_SET_EMERGENCY_ATTRIBUTES_REQ_SUCC);
            knLogger.info(methodName, "Returning getUserEmergDest response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error( methodName, "KnPersistenceException occured while getUserEmergDest", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while getUserEmergDest",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    /**
     * Device activation
     *
     * @param requestDTO
     * @return
     */
    @Override
    public IXDMResponseDTO deviceActivation(IXDMRequestDTO requestDTO) {
        String methodName = "deviceActivation()";
        knLogger.info(methodName, "ENTRY: device activation ");
        KnPersisterTxn persisterTxn = null;
        KnXDMActivateInfoDTO activateInfoDTO;
        KnDeviceActResponseDTO responseDTO = new KnDeviceActResponseDTO();
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DEVICE_ACTIVATE_REQ);
            // verify if the received DTO is of type KnXDMActivateInfoDTO
            activateInfoDTO = (KnXDMActivateInfoDTO) requestDTO;
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            //Search temp vaskey table and validate key and find MDN
            clientIntf = new KnActivationClientIntf();
            KnIPClientRegistryDTO ipClientRegistryDTO = new KnIPClientRegistryDTO();
            ipClientRegistryDTO.setActivationKey(activateInfoDTO.getActivationKey());
            ipClientRegistryDTO.setAuthKey(activateInfoDTO.getAuthKey());
            ipClientRegistryDTO.setImeiNum(activateInfoDTO.getIMEI());
            ipClientRegistryDTO.setSwType(String.valueOf(activateInfoDTO.getSwType()));
            ipClientRegistryDTO.setPlatformType(String.valueOf(activateInfoDTO.getPlatformType()));
            ipClientRegistryDTO.setUserAgentDTO(activateInfoDTO.getUserAgentDTO());

            KnDeviceInfoDTO deviceInfoDTO = clientIntf.getActClientManager().deviceActivation(ipClientRegistryDTO);

            //Populate response responseDTO from library response
            responseDTO.setDeviceId(deviceInfoDTO.getMdn());
            responseDTO.setLoginType(deviceInfoDTO.getLoginType());
            responseDTO.setUserId(deviceInfoDTO.getUserId());
            responseDTO.setClientId(deviceInfoDTO.getClientId());
            responseDTO.setClientSecret(deviceInfoDTO.getClientSecret());
            knLogger.info(methodName, "EXIT: activate Subscriber - ", responseDTO);

            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(deviceInfoDTO.getMdn());
            // invoking the prov library api
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            // KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_DEVICE_ACTIVATE_SUCCESS);


            int pv = 13;
            if (ipClientRegistryDTO.getUserAgentDTO()!= null){
                pv = Integer.parseInt(ipClientRegistryDTO.getUserAgentDTO().getProtocolVersion().split("\\.")[0]);
            }
            int clusterId = Integer.parseInt(System.getenv(com.kodiak.common.resources.KnConstants.CLUSTERID_ENV_NAME));

            KnIPSubscriberInfoDTO subscrInfoDTO = new KnIPSubscriberInfoDTO();
            subscrInfoDTO.setMdn(deviceInfoDTO.getMdn());
            int subsClientType = deviceInfoDTO.getClientType();
            String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
            String appId = subsClientType == SUBSCRIBERS_CLIENT_TYPE.DISPATCH.value() ? APP_ID.APDConsole.value() : APP_ID.HANDSET_STANDARD.value();
            KnManageSyncUserProfileUtil syncUserProfileUtil = KnManageSyncUserProfileUtil.getInstance();
            KnXDMSubsAliasDetailsReqDTO userAliasDetailsRespDTO = null;
            KnXDMSubsAliasDetailsRespDTO oidcRespDto = null;

            if (subsProfileInfoDTO.getMcId() == null) {
                KnSubsProfilePersistDTO knSubsProfilePersistDTO= new KnSubsProfilePersistDTO();
                knSubsProfilePersistDTO.setMcId(TELURI + subsProfileInfoDTO.getMdn());
                knSubsProfilePersistDTO.setMcpttId(TELURI + subsProfileInfoDTO.getMdn());
                knSubsProfilePersistDTO.setMcVideoId(TELURI + subsProfileInfoDTO.getMdn());
                knSubsProfilePersistDTO.setMcDataId(TELURI + subsProfileInfoDTO.getMdn());
                knSubsProfilePersistDTO.setMdn(subsProfileInfoDTO.getMdn());
                provClientIntf.updateMCSIds(persisterTxn, knSubsProfilePersistDTO);
                subsProfileInfoDTO.setMcId(TELURI + subsProfileInfoDTO.getMdn());
                subsProfileInfoDTO.setMcpttId(TELURI + subsProfileInfoDTO.getMdn());
                subsProfileInfoDTO.setMcVideoId(TELURI + subsProfileInfoDTO.getMdn());
                subsProfileInfoDTO.setMcDataId(TELURI + subsProfileInfoDTO.getMdn());
            }
            if (subsProfileInfoDTO.getLicenseType() != ENABLED) {
                userAliasDetailsRespDTO = new KnXDMSubsAliasDetailsReqDTO();
                userAliasDetailsRespDTO.setUserid(deviceInfoDTO.getMdn());
                String pwd = commonMediator.genTempPassword(activateInfoDTO.getAuthKey(), pv, appId);
                userAliasDetailsRespDTO.setPwd(pwd);
                userAliasDetailsRespDTO.setGeneratepwd(pwd == null);
                responseDTO.setPasswd(pwd);
                userAliasDetailsRespDTO.setTemppwd(false);
                Map<String, Object> attributes = new HashMap<>();
                attributes.put(MCPTT_ID_OIDC, /*(subsProfileInfoDTO.getMcpttCompliance() != 0) ? subsProfileInfoDTO.getMcpttId() : */deviceInfoDTO.getMdn());
                userAliasDetailsRespDTO.setAttributes(attributes);
                String corpId=String.valueOf(subsProfileInfoDTO.getCorpId());
                userAliasDetailsRespDTO.setCorpId(corpId);
                KnXDMSubsAliasDetailsRespDTO syncResponseDTO = syncUserProfileUtil.createIDMUserForOIDCMgmt(userAliasDetailsRespDTO, appId,
                        idmFqdn, false, null);
                if (syncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()) {
                    knLogger.error(methodName, "Error for Creating profile in IDM - ", syncResponseDTO.getStatus());
                    responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INTERNAL_ERROR);
                    responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                    throw new KnXDMServerException(responseDTO.getResponseCode(), "Unable to Create IDM Profile");
                }
            } else if (subsProfileInfoDTO.getLicenseType() == ENABLED) {
                userAliasDetailsRespDTO = new KnXDMSubsAliasDetailsReqDTO();
                String userId = subsProfileInfoDTO.getAliasMdn() != null ? subsProfileInfoDTO.getAliasMdn() : subsProfileInfoDTO.getMdn();
                userAliasDetailsRespDTO.setUserid(userId);
                String tmpPwd = null;
                long pwdExpiryInMilli = 0l;
                if (subsProfileInfoDTO.getAliasMdn() != null) {
                    userAliasDetailsRespDTO.setUserid(subsProfileInfoDTO.getAliasMdn());
                    generalCacheUtil.deleteOldOidcTmpPwd(subsProfileInfoDTO.getAliasMdn());
                } else {
                    userAliasDetailsRespDTO.setUserid(subsProfileInfoDTO.getMdn());
                }
                Map<String, Object> oidcAttributes = new HashMap<>();
                oidcAttributes.put(MCPTT_ID_OIDC, subsProfileInfoDTO.getMdn());
                oidcAttributes.put(MCVIDEO_ID_OIDC, subsProfileInfoDTO.getMcVideoId());
                oidcAttributes.put(MCDATA_ID_OIDC, subsProfileInfoDTO.getMcDataId());
                userAliasDetailsRespDTO.setAttributes(oidcAttributes);
                oidcRespDto = KnManageSyncUserProfileUtil.getInstance()
                        .notifyIDMIntfForOIDCMgmt(userAliasDetailsRespDTO, appId, idmFqdn, null, HttpMethod.GET);
                Map<String, String> microServicesParamNameValueMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
                String pwdExpiry = microServicesParamNameValueMap.get(TEMP_PASSWORD_EXPIRY);
                int passwordExpiry = 0;
                if (pwdExpiry != null) passwordExpiry = Integer.parseInt(pwdExpiry);
                long currentTimeInMilliSecond = System.currentTimeMillis();
                pwdExpiryInMilli = currentTimeInMilliSecond + (1000 * 60 * passwordExpiry);
                int statusCode = oidcRespDto.getStatusCode();
                if (statusCode == HttpStatus.NOT_FOUND.value())
                /*if (oidcRespDto.getStatusCode() == (HttpStatus.NOT_FOUND))*/ {
                    tmpPwd = pwdUtil.generatePassword(com.kodiak.common.resources.KnConstants.MAX_OIDC_PASSWORD_LENGTH, appId);
                    userAliasDetailsRespDTO.setTemppwd(Boolean.TRUE);
                    userAliasDetailsRespDTO.setPwd(tmpPwd);
                    userAliasDetailsRespDTO.setGeneratepwd(tmpPwd == null);
                    userAliasDetailsRespDTO.setEmail(subsProfileInfoDTO.getUserId());
                    userAliasDetailsRespDTO.setAttributes(oidcAttributes);
                    oidcRespDto = KnManageSyncUserProfileUtil.getInstance().createIDMUserForOIDCMgmt(userAliasDetailsRespDTO, appId,
                            idmFqdn, false, null);
                    knLogger.debug(methodName, "oidcRespDto ", oidcRespDto);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == oidcRespDto.getStatus()) {
                        knLogger.error(methodName, "Profile Creation Failed to OIDC ");
                        throw new KnXDMServerException(oidcRespDto.getResponseCode(), oidcRespDto.getResponseMessage());
                    }
                } else {
                    tmpPwd = pwdUtil.generatePassword(com.kodiak.common.resources.KnConstants.MAX_OIDC_PASSWORD_LENGTH, appId);
                    userAliasDetailsRespDTO = new KnXDMSubsAliasDetailsReqDTO();
                    userAliasDetailsRespDTO.setUserid(oidcRespDto.getUserid());
                    userAliasDetailsRespDTO.setPwd(tmpPwd);
                    userAliasDetailsRespDTO.setGeneratepwd(tmpPwd == null);
                    userAliasDetailsRespDTO.setPwdexpiry(pwdExpiryInMilli);
                    userAliasDetailsRespDTO.setTemppwd(Boolean.TRUE);
                    oidcRespDto = KnManageSyncUserProfileUtil.getInstance()
                            .notifyIDMIntfForOIDCMgmt(userAliasDetailsRespDTO, appId, idmFqdn, UPDATE_USER_PASSWORD, HttpMethod.PUT);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == oidcRespDto.getStatus()) {
                        knLogger.error(methodName, "UPDATE_USER_PASSWORD Failed to OIDC ");
                        throw new KnXDMServerException(oidcRespDto.getResponseCode(), oidcRespDto.getResponseMessage());
                    }
                }
                String saltForPwd = userAliasDetailsRespDTO.getUserid();
                generalCacheUtil.deleteOldOidcTmpPwd(saltForPwd);
                KnOidcTmpPwdDTO oidcTmpPwdDTO = new KnOidcTmpPwdDTO();
                knLogger.debug(methodName, "saltForPwd & tmpPwd ", saltForPwd, tmpPwd);
                String encryptedPwd = encryptionDecryptionUtil.encrypt(saltForPwd, tmpPwd);
                knLogger.debug(methodName, "encryptedPwd-- ", encryptedPwd);
                String derivedKey = KnGeneralUtil.convertToHex(encryptedPwd.getBytes());
                oidcTmpPwdDTO.setTmpPwd(KnGeneralUtil.convertHexToAscii(derivedKey));
                oidcTmpPwdDTO.setMdn(saltForPwd);
                oidcTmpPwdDTO.setTmpPwdCreationTS(String.valueOf(currentTimeInMilliSecond));
                oidcTmpPwdDTO.setTmpPwdExpiry(String.valueOf(pwdExpiryInMilli));
                generalCacheUtil.insertOidcTmpPwd(oidcTmpPwdDTO);
            }
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_DEVICE_ACTIVATE_REQ_SUCCESS);
            return commonMediator.getSuccessResponse(responseDTO);
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to activate device ", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

    /**
     * User login
     *
     * @param message KnMessage
     * @return
     */
    @Override
    public IXDMResponseDTO userLogin(KnMessage message) {
        String methodName = "userLogin()";
        KnPersisterTxn persisterTxn = null;
        KnXDMActivateInfoDTO activateInfoDTO = null;
        KnXDMSubsInfoDTO subsInfoDTO = null;
        KnUserLoginResponseDTO responseDTO = new KnUserLoginResponseDTO();
        KnOPSubsProfileInfoDTO subsProfileInfoDTO = new KnOPSubsProfileInfoDTO();
        int serviceAuthStatusFlag = 0;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_USER_LOGIN_REQ);
            // verify if the received DTO is of type KnXDMActivateInfoDTO
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMActivateInfoDTO) {
                activateInfoDTO = (KnXDMActivateInfoDTO) requestDTO;
                knLogger.debug(methodName, "Received input DTO to activate subscriber - ", activateInfoDTO);
            } else {
                knLogger.error(methodName, "received and Invalid DTO for activate subscriber op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return responseDTO;
            }
            knLogger.info(methodName, "ENTRY: - MDN" , activateInfoDTO.getMdn());
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();

            String mdn = activateInfoDTO.getMdn();

            // populating the library DTO
            KnIPActivateMDNInfoDTO activateMdnInputInfo = new KnIPActivateMDNInfoDTO();
            activateMdnInputInfo.setMdn(mdn);
            activateMdnInputInfo.setIMEI(activateInfoDTO.getIMEI());
            activateMdnInputInfo.setRealm(activateInfoDTO.getRealm());
            activateMdnInputInfo.setUserAgent(activateInfoDTO.getUserAgent());
            activateMdnInputInfo.setUserAgentDTO(activateInfoDTO.getUserAgentDTO());
            activateMdnInputInfo.setSubsClientType(activateInfoDTO.getSubsClientType());
            activateMdnInputInfo.setVocoderIdMap(activateInfoDTO.getVocoderIdMap());
            String clientFS=activateInfoDTO.getClientFeatureSet2()!=null ? activateInfoDTO.getClientFeatureSet2() :KnGeneralUtil.convertLongToHexString(activateInfoDTO.getClientFeatureSet());
            activateMdnInputInfo.setClientFS2(clientFS);
            activateMdnInputInfo.setApnName(activateInfoDTO.getApnName());
            if (activateInfoDTO.getSwType() != null) {
                activateMdnInputInfo.setSwType(activateInfoDTO.getSwType());
            }
            if (activateInfoDTO.getPlatformType() != null) {
                activateMdnInputInfo.setPlatformType(activateInfoDTO.getPlatformType());
            }

            // invoking the prov library API
            knLogger.debug(methodName, "Invoking prov lib with dto - ", activateMdnInputInfo);
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(mdn);

            // invoking the prov library api
            subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);

            KnAuthDTO authDto = new KnAuthDTO();
            authDto.setPassword(activateInfoDTO.getAuthDTO().getPassword());
            activateMdnInputInfo.setAuthDTO(authDto);
            activateMdnInputInfo.setMdn(subsProfileInfoDTO.getMdn());

            KnOPActivationInfoDTO activateResponse = provClientIntf.activateSubscriber(activateMdnInputInfo, persisterTxn);
            knLogger.info(methodName, "response from the server - ", activateResponse);

            if (activateResponse.isCleanUpTGSData()) {
                KnCorpTalkGroupRespDTO respDTO = corpMediator.cleanUpSubsCampedGrps(subsProfileInfoDTO.getMdn(), persisterTxn);
                if (respDTO.isModeChange()) {
                    KnTGSModeChgDTO tgsModeChgDTO = new KnTGSModeChgDTO();
                    tgsModeChgDTO.setPocHome(activateResponse.getPocHome());
                    tgsModeChgDTO.setPresenceHome(activateResponse.getPresHome());
                    tgsModeChgDTO.setTgsMode(KnMediatorConstants.OFF_MODE);
                    Map<String, KnTGSModeChgDTO> sehMap = new HashMap<String, KnTGSModeChgDTO>();
                    sehMap.put(subsProfileInfoDTO.getMdn(), tgsModeChgDTO);
                    commonMediator.sendTGSModeChangeNotification(sehMap);
                    knLogger.info(methodName, "sending SEH notification ", KnGDPRTemplate.mapKeyMdn(sehMap));
                } else {
                    knLogger.info(methodName,
                            " No records are deleted not sending SEH notification ");
                }
            }
            boolean OldGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(activateResponse.getOldActiveFS2(), FEATURE_SET.BROADCASTGROUPSERVICE.value());
            boolean newGrpBroadcastBit = KnGeneralUtil.getFeatureBitValue(activateResponse.getActiveFS2(), FEATURE_SET.BROADCASTGROUPSERVICE.value());
            KnCorpResponseDTO corpRespDto = null;

            if (!newGrpBroadcastBit && OldGrpBroadcastBit) {
                corpRespDto = corpMediator.updateGrpBroadcasters(activateMdnInputInfo.getMdn(), persisterTxn);
                knLogger.debug(methodName, "disabled group broadcast members corp Library response - ",
                        corpRespDto);
                if (corpRespDto.getStatus() != 0) {
                    throw new KnXDMServerException(corpRespDto.getStatusCode(), corpRespDto.getMessage());
                }
            }
            //new PV
            //Privacy Opt Status starts

            boolean oldReGroupBit = KnGeneralUtil.getFeatureBitValue(
                    activateResponse.getOldActiveFS2(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            boolean newReGroupBit = KnGeneralUtil.getFeatureBitValue(
                    activateResponse.getActiveFS2(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            if(oldReGroupBit != newReGroupBit){
                knLogger.info(methodName,"notification for preconfigure group");
                KnCorpResponseDTO groupNotifyResp = corpMediator.groupNotifyOnActiveFsChange(subsProfileInfoDTO.getCorpId(),
                        subsProfileInfoDTO.getMdn(), activateResponse.getActiveFS2(), activateResponse.getOldActiveFS2(), persisterTxn);
                if(corpRespDto!=null){
                    corpRespDto.getChangeLogMap().putAll(groupNotifyResp.getChangeLogMap());
                }else{
                    corpRespDto = new KnCorpResponseDTO();
                    corpRespDto.setChangeLogMap(groupNotifyResp.getChangeLogMap());
                }
            }

            int newMajorPV =0;
            if (activateMdnInputInfo.getUserAgentDTO() != null) {
                String protocolVersion = activateMdnInputInfo.getUserAgentDTO().getProtocolVersion();
                if (protocolVersion != null) {
                    String[] pv = protocolVersion.split("\\.");
                    if (pv != null && pv[0] != null) {
                        newMajorPV = Integer.parseInt(pv[0]);
                    }
                }
            }
            //Privacy Opt Status ends
            knLogger.debug(methodName, "--->newMajorPVForPrivacy  - ", newMajorPV);
            //new PV
            // knLogger.info(methodName, "subsProfileInfoDTO.getClientPVmajorVer() -:: ",
            //       subsProfileInfoDTO.getClientPVmajorVer());
            Integer listener=0;
            Integer privacyExecute=activateResponse.getPrivacyValueToExecute();
            if(privacyExecute != null && privacyExecute == 1 && newMajorPV >= PROTOCOL_VERSION_16) {
                knLogger.info(methodName, "--->mdn -:: ",
                        KnGDPRTemplate.mdn(mdn));

                listener = findPrivacyOptStatus(mdn, false, persisterTxn);

                knLogger.debug(methodName, "--->listener -:: ",
                        listener);
                knLogger.debug(methodName, "--->before: responseDTO -:: ",
                        responseDTO);
            }
            // sending the response to the client
            responseDTO.setMdn(activateResponse.getMdn());
            responseDTO.setXcapRootUri(activateResponse.getXcapRootUri());
            responseDTO.setXcapRootUriWifi(activateResponse.getXcapRootUri_Wifi());
            responseDTO.setXui(activateResponse.getXui());
            responseDTO.setActiveFS1(KnGeneralUtil.convertHexStringToLong(activateResponse.getActiveFS2()));
            responseDTO.setActiveFS2(activateResponse.getActiveFS2());
            responseDTO.setApn(activateResponse.getApnName());
            responseDTO.setSgwRUriC(activateResponse.getSgwRootUriCellular());
            responseDTO.setSgwRUriW(activateResponse.getSgwRootUriWifi());
            responseDTO.setAuthUriC(activateResponse.getAuthUriCellular());
            responseDTO.setAuthUriW(activateResponse.getAuthUriWifi());
            responseDTO.setCbBI(activateResponse.getCbBukInfo());
            responseDTO.setSgwAM(activateResponse.getSgwAuthMec());
            responseDTO.setIpVC(Integer.parseInt(activateResponse.getIpvc()));
            responseDTO.setIpVPrefC(Integer.parseInt(activateResponse.getIpvcPrefC()));
            responseDTO.setIpVPrefW(Integer.parseInt(activateResponse.getIpvcPrefW()));
                if (newMajorPV >= PROTOCOL_VERSION_29 && activateResponse.getIpvcMulti() != null && activateResponse.getIpvcPrefMulti() != null) {
                responseDTO.setIpVMulti(Integer.parseInt(activateResponse.getIpvcMulti()));
                responseDTO.setIpVPrefMulti(Integer.parseInt(activateResponse.getIpvcPrefMulti()));
            }
            responseDTO.setSgwLUriC(activateResponse.getSgwLocUriCellular());
            responseDTO.setSgwLUriW(activateResponse.getSgwLocUriWifi());
            responseDTO.setToken(activateResponse.getToken());
            responseDTO.setSubsClientType(activateResponse.getClientType());
            //pv 18
            responseDTO.setMcsXcapRootUri(activateResponse.getMcsXcapRootUri());
            responseDTO.setMcsXcapRootUriWifi(activateResponse.getMcsXcapRootUriWifi());
            responseDTO.setKmsUri(activateResponse.getKmsUri());
            responseDTO.setKmsUriWifi(activateResponse.getKmsUriWifi());
            responseDTO.setMcsXui(activateResponse.getMcsXui());

            if(privacyExecute != null && privacyExecute == 1 && newMajorPV >= PROTOCOL_VERSION_16) {
                responseDTO.setIsOptInNeeded(listener);

                knLogger.debug(methodName, "--->after: responseDTO - ::",
                        responseDTO);
            }

            boolean pvchanged = false;
            knLogger.debug(methodName,"Existing ClientPVmajorVersion= ",subsProfileInfoDTO.getClientPVmajorVer()," New ClientPVmajorVersion = ",newMajorPV);
            if(subsProfileInfoDTO.getClientPVmajorVer() != newMajorPV ){
                pvchanged = true;
                if(subsProfileInfoDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13 && newMajorPV >= PROTOCOL_VERSION_13 ){
                    knLogger.debug(methodName, "Update public group context from kodiak-poc to oidcxcap - ");
                    pubDocMediator.modifyGroupUriContext(activateResponse.getMdn(), KnDBUtil.getPttServerId(), persisterTxn);
                }
                //MINT-29418
                clientIntf = new KnActivationClientIntf();
                KnDeviceInfoPersistDTO knDeviceInfoPersistDTO = clientIntf.getActClientManager().getDeviceInfo(subsProfileInfoDTO.getMdn(), persisterTxn);
                if (subsProfileInfoDTO.getClientPVmajorVer() < PROTOCOL_VERSION_18 && newMajorPV >= PROTOCOL_VERSION_18
                        && subsProfileInfoDTO.getClientPVmajorVer() < newMajorPV
                        && knDeviceInfoPersistDTO != null && knDeviceInfoPersistDTO.getDeviceDigestPassword() == null) {
                    clientIntf.getActClientManager().updateDeviceInfo(subsProfileInfoDTO.getMdn(),
                            subsProfileInfoDTO.getClientPassword(), persisterTxn);
                }
                // Modified for sending Notification to Microservice thru RMQ
                knLogger.debug(methodName, "If protocol version mismatch then notifying microservice via RMQ -");
                sendNotificationForPVUpgrade(subsProfileInfoDTO,persisterTxn,newMajorPV);
            }

            // Initalizing the KnSubscriberInfoDTO
            KnSubscriberInfoDTO knSubscriberInfoDTO = new KnSubscriberInfoDTO();
            // Fetching the boolean value for 45th bit,
            // If it is true then we will call the new REST API.
            boolean xcapCouchClient = KnGeneralUtil.getFeatureBitValue(activateResponse.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
            boolean oldxcapCouchClient = KnGeneralUtil.getFeatureBitValue(subsProfileInfoDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
            boolean xcapCouchClientChanged = false;
            if(oldxcapCouchClient != xcapCouchClient){
                xcapCouchClientChanged = true;
            }
            boolean isPasswordUpdated=!activateResponse.getPassword().equalsIgnoreCase(subsProfileInfoDTO.getClientPassword());
            knLogger.info(methodName, "xcapCouchClient - ", xcapCouchClient, " isPasswordUpdated = ",isPasswordUpdated," xcapCouchClientChanged = ",xcapCouchClientChanged);
            if (xcapCouchClient && (isPasswordUpdated ||  pvchanged || xcapCouchClientChanged)){
                // Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                knSubscriberInfoDTO.setMdn(activateResponse.getMdn());
                knSubscriberInfoDTO.setEmail(activateResponse.getEmail());
                knSubscriberInfoDTO.setDisabled(false);
                knSubscriberInfoDTO.setPassword(activateResponse.getPassword());
                knLogger.debug(methodName, "knSubscriberInfoDTO  ", knSubscriberInfoDTO);

                // Storing the list of bucket urls in a list
                Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                //bucketUrlList.add("http://10.2.1.35:4985/pttdata/_user/");
                knLogger.debug(methodName, "bucketUrlList : ", bucketUrlList);
                KnFailedCBTxnLogDTO failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                for (Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                    List<String> bucketUrl = new ArrayList<>();
                    Integer curClusterId = entry.getKey();
                    knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                    bucketUrl.add(entry.getValue());
                    //REST call for profile creation starts here.
                    KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().updateSyncDocument(knSubscriberInfoDTO, bucketUrl);
                    knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                    if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()) {
                        failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                        failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                        failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                        failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_UPDATE.value());
                        genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    }
                }

            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);

            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            knLogger.debug(methodName ,"clusterId :",clusterId);
            Map<String, String> microSvcCommonMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            String deviceSharingFlag = microSvcCommonMap.get(DEVICE_SHARING_FEATURE_FLAG);
            if(deviceSharingFlag != null && Integer.parseInt(deviceSharingFlag) == ENABLED && subsProfileInfoDTO.getOnBoardingEmailReqd() == ON_BOARDING_MAIL.REQUIRED.value() &&
                    (subsProfileInfoDTO.getLastActivationTime() == null || subsProfileInfoDTO.getLastActivationTime() == 0)){
                if((String.valueOf(activateResponse.getClientType()).matches(CLIENT_TYPE_WIFI_CROSS_NORMAL_RADIO)) || subsProfileInfoDTO.getLicenseType() == ENABLED){
                    // IDM Call:
                    String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
                    String appId = subsProfileInfoDTO.getDispatchType() == DISPATCH_TYPE_WEB ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                    KnXDMSubsAliasDetailsReqDTO oidcSubsDto = new KnXDMSubsAliasDetailsReqDTO();
                    Map<String, Object> oidcAttributes = new HashMap<>();
                    List<String> tmpPwdMode = new ArrayList<>();
                    if(subsProfileInfoDTO.getAliasMdn() != null && subsProfileInfoDTO.getUserId() != null){
                        tmpPwdMode.add(TMP_PWD_MODE.WELCOME_SMS.value());
                        tmpPwdMode.add(TMP_PWD_MODE.WELCOME_MAIL.value());
                        oidcSubsDto.setUserid(subsProfileInfoDTO.getAliasMdn());
                    } else if(subsProfileInfoDTO.getAliasMdn() != null){
                        tmpPwdMode.add(TMP_PWD_MODE.WELCOME_SMS.value());
                        oidcSubsDto.setUserid(subsProfileInfoDTO.getAliasMdn());
                    } else if(subsProfileInfoDTO.getUserId() != null){
                        tmpPwdMode.add(TMP_PWD_MODE.WELCOME_MAIL.value());
                        oidcSubsDto.setUserid(subsProfileInfoDTO.getUserId());
                    }
                    oidcAttributes.put(ACTIONS, tmpPwdMode);
                    oidcSubsDto.setAttributes(oidcAttributes);
                    KnXDMSubsAliasDetailsRespDTO oidcRespDto = KnManageSyncUserProfileUtil.getInstance()
                            .notifyIDMIntfForOIDCMgmt(oidcSubsDto, appId, idmFqdn, INVOKE_ACTION, HttpMethod.POST);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == oidcRespDto.getStatus()) {
                        knLogger.error(methodName, "Invoke Action Failed to OIDC ");
                        throw new KnXDMServerException(oidcRespDto.getResponseCode(), oidcRespDto.getResponseMessage());
                    }
                }
            }

            List<String> userIds = new ArrayList<>();
            if(subsProfileInfoDTO.getAliasMdn() != null) userIds.add(subsProfileInfoDTO.getAliasMdn());
            userIds.add(mdn);
            generalCacheUtil.deleteExpPasswordMDNs(userIds);

            KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(activateResponse.getMdn(),activateResponse.getActiveFS2(),activateResponse.getOldActiveFS2(),persisterTxn);

            //just for testing not for checking - in
            //  KnOPProvDTO opProvDTO = provClientIntf.actionOnTGSSDoc(mdn,2321887083030904833L,2321605608054194177L,persisterTxn);

            if(opProvDTO.getDirChgDTO()!=null){
                commonMediator.sendXcapNotification(opProvDTO.getDirChgDTO(), String.valueOf(subsProfileInfoDTO.getClientPVmajorVer()));
            }


            // saving the transaction
            //Get All profile MDNs for given Real MDN
            List<String> UserProfileMdns= new ArrayList<String>();
            UserProfileMdns = provMediator.getMdnForUPM(subsProfileInfoDTO.getMdn().toString(), persisterTxn);
            UserProfileMdns.remove(subsProfileInfoDTO.getMdn().toString());
            knLogger.info(methodName, "UserProfileMdns ",  KnGDPRTemplate.mdnList(UserProfileMdns));

            knLogger.info(methodName, "Saving the Transaction ");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_POC_CLIENT_USER_LOGIN_REQ_SUCCESS);

            //MC DEVICE NOTIFY
            if(activateResponse.isDeleteDeviceNotify()){
                sendDeleteDeviceNotification(TEL_URI_TEMPLATE + activateResponse.getMdn());
            }

            //call fro the micro services notification
            knLogger.info(methodName, "xcapMobileSync:",xcapMobileSync," xcapCouchClientBit:", xcapCouchClient," PV:",newMajorPV);
            if (xcapMobileSync && (xcapCouchClient || newMajorPV >= PROTOCOL_VERSION_18 )) {

                KnActiEXDMSNotifyDto knActiEXDMSNotifyDto = new KnActiEXDMSNotifyDto();
                knActiEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(activateResponse.getActiveFS2()));
                knActiEXDMSNotifyDto.setActiveFS2(activateResponse.getActiveFS2());
                knActiEXDMSNotifyDto.setOldActiveFS(subsProfileInfoDTO.getActiveFS2());
                knActiEXDMSNotifyDto.setMdn(activateResponse.getMdn());
                knActiEXDMSNotifyDto.setCorpid(activateResponse.getCorpId());
                knActiEXDMSNotifyDto.setId(CLIENT_ACTIVATION.value() + KnConstants.LINE_SAPERATOR + activateResponse.getMdn());
                knActiEXDMSNotifyDto.setType(CLIENT_ACTIVATION.value());
                knActiEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knActiEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                knActiEXDMSNotifyDto.setPv(activateResponse.getPvVersion());
                knActiEXDMSNotifyDto.setClientType(subsProfileInfoDTO.getSubsClientType());
                knActiEXDMSNotifyDto.setDispatchType(subsProfileInfoDTO.getDispatchType());
                knActiEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                if (isPasswordUpdated) {
                    knActiEXDMSNotifyDto.setSyncGwProfileCreated(KnConstants.SYNCGWPROFILECREATED.ENABLED.value());
                } else {
                    knActiEXDMSNotifyDto.setSyncGwProfileCreated(KnConstants.SYNCGWPROFILECREATED.DISABLED.value());
                }
                knActiEXDMSNotifyDto.setSubsFS2(subsProfileInfoDTO.getSubsFS2());
                knActiEXDMSNotifyDto.setMcId(subsProfileInfoDTO.getMcId());
                knActiEXDMSNotifyDto.setMcdataId(subsProfileInfoDTO.getMcDataId());
                knActiEXDMSNotifyDto.setMcpttId(subsProfileInfoDTO.getMcpttId());
                knActiEXDMSNotifyDto.setMcvideoId(subsProfileInfoDTO.getMcVideoId());
                knActiEXDMSNotifyDto.setNetworkName(subsProfileInfoDTO.getNetworkName());
                //TO-DO: Need to check what should be deviceId.
                knActiEXDMSNotifyDto.setDeviceId(activateResponse.getMdn());
                List<KnActiEXDMSNotifyDto> notifyDtoList = new ArrayList<KnActiEXDMSNotifyDto>();
                notifyDtoList.add(knActiEXDMSNotifyDto);

                //Feature Bit notification
                if (!Objects.equals(activateResponse.getOldActiveFS2(), activateResponse.getActiveFS2())) {
                    KnActiEXDMSNotifyDto featureBitChangeNotify = new KnActiEXDMSNotifyDto();
                    featureBitChangeNotify.setActiveFS(KnGeneralUtil.convertHexStringToLong(activateResponse.getActiveFS2()));
                    featureBitChangeNotify.setActiveFS2(activateResponse.getActiveFS2());
                    featureBitChangeNotify.setOldActiveFS(activateResponse.getOldActiveFS2());
                    featureBitChangeNotify.setMdn(activateResponse.getMdn());
                    featureBitChangeNotify.setCorpid(activateResponse.getCorpId());
                    featureBitChangeNotify.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                    featureBitChangeNotify.setType(FEATURE_BIT_CHANGE.value());
                    featureBitChangeNotify.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                    featureBitChangeNotify.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                    featureBitChangeNotify.setPv(activateResponse.getPvVersion());
                    featureBitChangeNotify.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                    notifyDtoList.add(featureBitChangeNotify);
                }

                if(activateResponse.getProfileMdnActivsFsMap()!=null&&!activateResponse.getProfileMdnActivsFsMap().isEmpty())
                {
                    List<String> mdnList = new ArrayList<>(Optional.ofNullable(activateResponse.getProfileMdnActivsFsMap())
                            .map(Map::keySet)
                            .orElse(Collections.emptySet()));
                    Map<String, String> onlineSubscribersListByMdn = KnGeneralCacheUtil.getInstance()
                            .getOnlineSubcribersListByMdn(mdnList);
                    List<String> listActiveMdns = new ArrayList<>(onlineSubscribersListByMdn.keySet());
                    activateResponse.getProfileMdnActivsFsMap().entrySet().removeIf(entry -> !listActiveMdns.contains(entry.getKey()));
                    for (Entry profileMdnFsMap : activateResponse.getProfileMdnActivsFsMap().entrySet()) {
                        KnActiEXDMSNotifyDto profileMdnActiEXDMSNotifyDto = new KnActiEXDMSNotifyDto();
                        profileMdnActiEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(profileMdnFsMap.getValue().toString()));
                        profileMdnActiEXDMSNotifyDto.setActiveFS2(profileMdnFsMap.getValue().toString());
                        if(null!=activateResponse.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS()) {
                            profileMdnActiEXDMSNotifyDto.setOldActiveFS(activateResponse.getMdnUpmFsMap().get(profileMdnFsMap.getKey().toString()).getOldActiveFS());
                        }
                        profileMdnActiEXDMSNotifyDto.setMdn(profileMdnFsMap.getKey().toString());
                        profileMdnActiEXDMSNotifyDto.setCorpid(activateResponse.getCorpId());
                        profileMdnActiEXDMSNotifyDto.setId(CLIENT_ACTIVATION.value() + KnConstants.LINE_SAPERATOR+ profileMdnFsMap.getKey().toString());
                        profileMdnActiEXDMSNotifyDto.setType(CLIENT_ACTIVATION.value());
                        profileMdnActiEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                        profileMdnActiEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                        profileMdnActiEXDMSNotifyDto.setPv(activateResponse.getPvVersion());
                        profileMdnActiEXDMSNotifyDto.setClientType(subsProfileInfoDTO.getSubsClientType());
                        profileMdnActiEXDMSNotifyDto.setDispatchType(subsProfileInfoDTO.getDispatchType());
                        profileMdnActiEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                        profileMdnActiEXDMSNotifyDto.setSubsFS2(subsProfileInfoDTO.getSubsFS2());
                        profileMdnActiEXDMSNotifyDto.setMcId(subsProfileInfoDTO.getMcId());
                        profileMdnActiEXDMSNotifyDto.setMcdataId(subsProfileInfoDTO.getMcDataId());
                        profileMdnActiEXDMSNotifyDto.setMcpttId(subsProfileInfoDTO.getMcpttId());
                        profileMdnActiEXDMSNotifyDto.setMcvideoId(subsProfileInfoDTO.getMcVideoId());
                        profileMdnActiEXDMSNotifyDto.setNetworkName(subsProfileInfoDTO.getNetworkName());
                        //TO-DO: Need to check what should be deviceId.
                        profileMdnActiEXDMSNotifyDto.setDeviceId(profileMdnFsMap.getKey().toString());
                        profileMdnActiEXDMSNotifyDto.setSyncGwProfileCreated(isPasswordUpdated ?
                                KnConstants.SYNCGWPROFILECREATED.ENABLED.value() : KnConstants.SYNCGWPROFILECREATED.DISABLED.value());

                        notifyDtoList.add(profileMdnActiEXDMSNotifyDto);
                    }
                }

                knLogger.info(methodName, "Publishing micro service notify for user - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }
            if (corpRespDto != null) {
                // prepare notification and send to notification mgr
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpRespDto);
                knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
                notifier.setMaxNotfnsPerJob(2);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
            }

            if(activateResponse != null){
                boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(activateResponse.getProfileMdnEtagMap(),activateResponse.getMcsXcapRootUriMap());
                knLogger.debug(methodName, "sending Profile notification Status: ", profileNotifyStatus);
            }
            // Starting a thread for resourceList/GroupEtag/DirectoryEtag.
            Map<String, Boolean> mdnListMap = new HashMap<>();
            mdnListMap.put(activateResponse.getMdn(), activateResponse.getOldActiveFS1() != activateResponse.getActiveFS1());
            commonMediator.initiateEtagMgmtJob(mdnListMap,USER_LOGIN);
            boolean upmBit = KnGeneralUtil.getFeatureBitValue(activateResponse.getSubscriberFS2(), USER_PROFILE_MGMT_BIT);
            knLogger.debug(methodName, "upmBit is enabled - ", upmBit);
            if(!upmBit)
            {
                //check if it is a Real mdn
                if (subsProfileInfoDTO.getUserProfileIndex()==null||subsProfileInfoDTO.getUserProfileIndex().equals(USER_PROFILE_INDEX)) {

                    if (!UserProfileMdns.isEmpty()) {

                        KnIPUserProfileDTO ipUserProfileDTO=new KnIPUserProfileDTO();
                        ipUserProfileDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
                        ipUserProfileDTO.setUserProfileMdns(UserProfileMdns);

                        String deleteUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfileDTO);
                        Long transactionId = System.currentTimeMillis();
                        knLogger.debug(methodName, "transactionId - ", transactionId);
                        KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(String.valueOf(subsProfileInfoDTO.getCorpId()), transactionId.toString()
                                , null, UPM_OPERATION_TYPE.DELETE_USER_PROFILE_MDN.Value(), subsProfileInfoDTO.getMdn().toString(),
                                UPM_RESOURCE_TYPE.MDN.Value(), deleteUpmJsonString, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                        upmJobScheduler.addJob(knAsyncJobDTO);

                    }
                }
            }
            if(newMajorPV >= KnConstants.PROTOCOL_VERSION_20) {
                knLogger.info(methodName, "Setting GMS and MCX Value For PV >=20", activateResponse.getMCXDOMAINID()+" "+activateResponse.getGMSDOMAINID());

                responseDTO.setMdsiUri(activateResponse.getMCXDOMAINID());
                responseDTO.setGmsUri(activateResponse.getGMSDOMAINID());
            }

            knLogger.info(methodName, "EXIT: activate Subscriber - ", responseDTO);
            return commonMediator.getSuccessResponse(responseDTO);
        } catch (KnAuthenticationException e) {
            knLogger.error(methodName, "Autherization failed", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnAASException e) {
            knLogger.error(methodName, "Autherization failed", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to login ", e);
            rollback(persisterTxn);
            if (e.getMessage().contains(KnConstants.LOCK_REQUEST_DENIED_ERROR_MSG)) {
                return lockRequestErrorProcessor(subsProfileInfoDTO, activateInfoDTO);
            }
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        }


    }
    /**
     * method to prepare the userLogin response for Lock Request denied error
     *
     * @param KnOPSubsProfileInfoDTO subscriberDTO
     * @param KnXDMActivateInfoDTO   activateInfoDTO
     * @return IXDMResponseDTO
     * @Note Since the CID is not available in mediator for userLoginAPI,
     * mdn is added instead for CID for audit log message
     */

    private IXDMResponseDTO lockRequestErrorProcessor(KnOPSubsProfileInfoDTO subsProfileInfoDTO, KnXDMActivateInfoDTO activateInfoDTO) {

        KnPersisterTxn persisterTxn = null;
        String methodName = "lockRequestErrorProcessor";
        knLogger.info(methodName, "ENTRY: - " ,"subsProfileInfoDTO" ,KnGDPRTemplate.mdn(subsProfileInfoDTO.getMdn()),"activateInfoDTO",KnGDPRTemplate.mdn(activateInfoDTO.getMdn()));
        KnUserLoginResponseDTO responseDTO = new KnUserLoginResponseDTO();

        try {
            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            //Since the CID is not available in mediator,mdn is added instead for CID for audit log message
            auditPublic.writeAuditMessage("CID:" + subsProfileInfoDTO.getMdn(), methodName, KnAuditHelper.STATUS.REQUEST, "Request received for - " + activateInfoDTO.getMdn());
            responseDTO = provClientIntf.lockRequestErrorProcessor(subsProfileInfoDTO, activateInfoDTO, persisterTxn);

            auditPublic.writeAuditMessage("CID:" + subsProfileInfoDTO.getMdn(),
                    methodName, KnAuditHelper.STATUS.SUCCESS,
                    "Operation Successful - ");
            persisterTxn.save();
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            auditPublic.writeAuditMessage("CID:" + subsProfileInfoDTO.getMdn(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnProvException e) {
            knLogger.error(methodName, "KnProv Exception occurred :", e);
            rollback(persisterTxn);
            auditPublic.writeAuditMessage("CID:" + subsProfileInfoDTO.getMdn(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Exception occurred while prepare response for Lock Request Error");
            rollback(persisterTxn);
            auditPublic.writeAuditMessage("CID:" + subsProfileInfoDTO.getMdn(),
                    methodName, KnAuditHelper.STATUS.FAILURE,
                    "Operation failed ", responseDTO.getResponseCode());
            return commonMediator.getFailureResponse(responseDTO, e);
        }
        return commonMediator.getSuccessResponse(responseDTO);
    }


    /* @autor Shashank -Code for Client PV Upgrade Notification to RMQ */
    private void sendNotificationForPVUpgrade(KnOPSubsProfileInfoDTO subsProfileInfoDTO,KnPersisterTxn persisterTxn,int newMajorPV) throws KnException{
        String methodName = "sendNotificationForPVUpgrade";
        knLogger.debug(methodName + " :  Started ");
        KnActiEXDMSNotifyDto knActiEXDMSNotifyDto = new KnActiEXDMSNotifyDto();
        knActiEXDMSNotifyDto.setMdn(subsProfileInfoDTO.getMdn());
        knActiEXDMSNotifyDto.setId(CLIENT_PV_UPGRADE.value() + KnConstants.LINE_SAPERATOR + subsProfileInfoDTO.getMdn());
        knActiEXDMSNotifyDto.setType(CLIENT_PV_UPGRADE.value());
        knActiEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
        knActiEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.CLIENT_PV_UPGARDE.value());
        knActiEXDMSNotifyDto.setOldPV(String.valueOf(subsProfileInfoDTO.getClientPVmajorVer()));
        knActiEXDMSNotifyDto.setPv(String.valueOf(newMajorPV));
        List<KnActiEXDMSNotifyDto> notifyDtoList = new ArrayList<KnActiEXDMSNotifyDto>();
        notifyDtoList.add(knActiEXDMSNotifyDto);
        knLogger.info(methodName, "Publishing micro service notify for Client PV Upgrade - ");
        commonMediator.startNotifyMicroServicesJob(notifyDtoList);
        knLogger.info(methodName, "Published micro service notify  for Client PV Upgrade - ");
        knLogger.debug(methodName + " :  End ");
    }


    @Override
    public IXDMResponseDTO modifySubscriberTGList(KnMessage message) {
        String methodName = "modifySubscriberTGList(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_PTTRADIOTG_LIST_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMAddlTalkGroupRequestDTO) {
                KnXDMAddlTalkGroupRequestDTO addlTalkGroupRequestDTO = (KnXDMAddlTalkGroupRequestDTO) requestDTO;
                //validate corp Hierarchy
                if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(addlTalkGroupRequestDTO.getCorpId()),
                        addlTalkGroupRequestDTO.getHierarchyType())) {
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", addlTalkGroupRequestDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
            }
            corpResponseDTO = corpMediator.modifySubscriberTGList(requestDTO, persisterTxn);
            populateXdmResponse(respDto, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            // Step : prepare notification and send to notification mgr
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_PTTRADIOTG_LIST_SUCC_RESP);
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResponseDTO);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.info(methodName, "Notification status - ", isNotified);
            knLogger.info(methodName, "Returning modifySubscriberTGList response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while modifying Subscriber TG List", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while modifying Subscriber TG List",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

