    @Override
    public IXDMResponseDTO sendSMS(IXDMRequestDTO requestDTO) {
        String methodName = "sendSMS(IXDMRequestDTO)";
        KnXDMCorpClientActResponseDTO respDto = new KnXDMCorpClientActResponseDTO();
        KnPersisterTxn persisterTxn = null;
        Map<String, Object> responseMap = new HashMap<>();
        try {
            //KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_USER_PROFILE_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (!(requestDTO instanceof KnXDMCorpClientActRequestDTO)) {
                knLogger.error(methodName, "requestDTO not of type KnCorpSubsResquestDTO, requestDTO ", requestDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnXDMCorpClientActRequestDTO subsResquestDTO = (KnXDMCorpClientActRequestDTO) requestDTO;
            knLogger.debug(methodName, "Sending subsResquestDTO", subsResquestDTO);
            KnSMSDTO corpSMSDTO = new KnSMSDTO();
            if(OIDC_TMP_PASSWORD_GENERATION == Integer.parseInt(subsResquestDTO.getMsgId())){
                corpSMSDTO.setTmpPwd(subsResquestDTO.getTmpPwd());
                corpSMSDTO.setTmpPwdExpiry(subsResquestDTO.getTmpPwdExpiry());
            }
            corpSMSDTO.setMsgNotificationId(Integer.parseInt(subsResquestDTO.getMsgId()));
            corpSMSDTO.setMdn(subsResquestDTO.getMdn());
            KnSMSUtil smsUtil = new KnSMSUtil();
            smsUtil.sendSMS(corpSMSDTO, persisterTxn);
            populate(respDto);
            responseMap.put(STATUS, String.valueOf(respDto.getResponseStatus()));
            responseMap.put(STATUS_CODE, respDto.getResponseCode());
            responseMap.put(MESSAGE, respDto.getResponseMessage());
            persisterTxn.save();
            knLogger.info(methodName, "Sending response", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while sendSMS", e);
            respDto = populateResponse(e, respDto);
            responseMap.put(STATUS, String.valueOf(respDto.getResponseStatus()));
            responseMap.put(STATUS_CODE, respDto.getResponseCode());
            responseMap.put(MESSAGE, respDto.getResponseMessage());
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while sendSMS",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
            responseMap.put(STATUS, String.valueOf(respDto.getResponseStatus()));
            responseMap.put(STATUS_CODE, respDto.getResponseCode());
            responseMap.put(MESSAGE, respDto.getResponseMessage());
        }
        respDto.setResponseMap(responseMap);
        return respDto;
    }

    @Override
    public IXDMResponseDTO sendTempPassword(IXDMRequestDTO requestDTO) {
        String methodName = "sendTempPassword(IXDMRequestDTO)";
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        KnXDMSubsAliasDetailsRespDTO oidcRespDto = null;
        KnPersisterTxn persisterTxn = null;
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Getting the Subscriber profile:
            knLogger.debug(methodName, "retrieving the subscriber profile for mdn ");
            KnIPSubscriberInfoDTO subscrInfoDTO = new KnIPSubscriberInfoDTO();
            KnCorpSubsResquestDTO reqDto = (KnCorpSubsResquestDTO) requestDTO;
            subscrInfoDTO.setMdn(reqDto.getSubscriberMdn());
            subscrInfoDTO.setAliasMdn(reqDto.getAliasMdn());
            // This call may required to get the data for OIDC call.
            respDto = corpMediator.sendTempPassword(requestDTO, persisterTxn);
            if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == respDto.getStatus()) {
                String tmpPwd = reqDto.getTmpPwd();
                KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscrInfoDTO, persisterTxn);
                String appId = subsProfileInfoDTO.getDispatchType() == DISPATCH_TYPE_WEB ? APP_ID.DISPATCHER.value() : APP_ID.HANDSET_STANDARD.value();
                if (PROTOCOL_VERSION_0 == subsProfileInfoDTO.getClientPVmajorVer() || subsProfileInfoDTO.getClientPVmajorVer() > PROTOCOL_VERSION_13) {
                    KnXDMSubsAliasDetailsReqDTO oidcSubsDto = new KnXDMSubsAliasDetailsReqDTO();
                    oidcSubsDto.setUserid(reqDto.getSubscriberMdn());
                    if (reqDto.getAliasMdn() != null)
                        oidcSubsDto.setUserid(reqDto.getAliasMdn());
                    String idmFqdn = genInfoUtil.getIDMInternalFqdn(persisterTxn);
                    String pwdExpiry = reqDto.getTmpPwdExpiry();
                    oidcSubsDto.setPwd(tmpPwd);
                    oidcSubsDto.setPwdexpiry(Long.parseLong(pwdExpiry));
                    Map<String, Object> oidcAttributes = new HashMap<>();
                    List<String> tmpPwdMode = new ArrayList<>();
                    if (reqDto.getTmpPwdMode() == SEND_PWD_MODE.MAIL.value()) {
                        tmpPwdMode.add(TMP_PWD_MODE.PASSWORD_INFO_MAIL.value());
                    } else if (reqDto.getTmpPwdMode() == SEND_PWD_MODE.SMS.value()) {
                        tmpPwdMode.add(TMP_PWD_MODE.PASSWORD_INFO_SMS.value());
                    } else if (reqDto.getTmpPwdMode() == SEND_PWD_MODE.BOTH.value()) {
                        tmpPwdMode.add(TMP_PWD_MODE.PASSWORD_INFO_MAIL.value());
                        tmpPwdMode.add(TMP_PWD_MODE.PASSWORD_INFO_SMS.value());
                    }
                    oidcAttributes.put(ACTIONS, tmpPwdMode);
                    oidcSubsDto.setAttributes(oidcAttributes);

                    //oveeriding oidc attributes if mc
                    if(subsProfileInfoDTO.getMcpttCompliance() == MCPTT_COMPLIANCE_ENABLED) {
                        oidcAttributes = new HashMap<>();
                        oidcAttributes.put(ACTIONS, tmpPwdMode);
                        oidcAttributes.put(MC_ID_OIDC,subsProfileInfoDTO.getMcId() );
                        oidcAttributes.put(MCPTT_ID_OIDC, subsProfileInfoDTO.getMcpttId());
                        oidcAttributes.put(MCVIDEO_ID_OIDC, subsProfileInfoDTO.getMcVideoId());
                        oidcAttributes.put(MCDATA_ID_OIDC, subsProfileInfoDTO.getMcDataId());
                        oidcAttributes.put(NETWORK_NAME,subsProfileInfoDTO.getNetworkName() );
                        oidcAttributes.put(MCS_SCOPES_OIDC,KnGeneralUtil.populateOidcScopes(subsProfileInfoDTO.getActiveFS2()));
                    }
                    oidcRespDto = KnManageSyncUserProfileUtil.getInstance()
                            .notifyIDMIntfForOIDCMgmt(oidcSubsDto, appId, idmFqdn, INVOKE_ACTION, HttpMethod.POST);
                    if (KnConstants.RESPONSE_STATUS.FAILURE.value() == oidcRespDto.getStatus()) {
                        knLogger.error(methodName, "Send_USER_PASSWORD Failed to OIDC ");
                        throw new KnXDMServerException(oidcRespDto.getResponseCode(), oidcRespDto.getResponseMessage());
                    }
                }
            }
            populateXdmResponse(xdmRespDto, respDto);
            persisterTxn.save();
            knLogger.info(methodName, "Sending response", xdmRespDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while sendTempPassword", e);
            xdmRespDto = populateResponse(e, xdmRespDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while sendTempPassword",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto);
        }
        return xdmRespDto;
    }

