    public IXDMResponseDTO getTGSSList(IXDMRequestDTO requestDTO) {
        String methodName = "getTGSSList()";
        knLogger.info(methodName, "ENTRY:  ");
        KnPersisterTxn persisterTxn = null;
        KnXDMTGSSListResponseDTO responseDTO = new KnXDMTGSSListResponseDTO();
        KnXDMTGSSListRequestDTO reqDto = null;
        KnIPTGSSListDTO knIPTGSSListDTO = null;

        if (!(requestDTO instanceof KnXDMTGSSListRequestDTO)) {
            knLogger.error(methodName, "received and Invalid DTO for activate subscriber op - ", requestDTO);
            responseDTO.setResponseMessage("Invalid DTO is passed");
            responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
            responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
            return responseDTO;
        }
        try {
            reqDto = (KnXDMTGSSListRequestDTO) requestDTO;
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SIMULTANEOUS_SESSION_DOC_REQ);
            persisterTxn.open();
            knIPTGSSListDTO = pubDocMediator.getTGSSList(reqDto, persisterTxn);
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SIMULTANEOUS_SESSION_DOC_REQ_SUCC);

            responseDTO.setMdn(knIPTGSSListDTO.getMdn());
            responseDTO.setDocEtag(knIPTGSSListDTO.getDocEtag());
            responseDTO.setCorpId(knIPTGSSListDTO.getCorpId());
            responseDTO.setGroupIds(knIPTGSSListDTO.getGroupIds());
            responseDTO.setGroupIdCorpInfo(knIPTGSSListDTO.getGroupIdCorpInfo());
            responseDTO.setResponseCode(KnMediatorConstants.SUCCESS_CODE);
            responseDTO.setResponseMessage("SUCCESSFULLY executed the operation");
            responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.SUCCESS.value());
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, e.getErrorMessage(), e);
            //return success even when no data found
            if(e.getErrorMessage().equalsIgnoreCase("No SS Channel Group Info Found")){
                responseDTO.setResponseCode(KnMediatorConstants.SUCCESS_CODE);
                responseDTO.setResponseMessage("SUCCESSFULLY executed the operation");
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.SUCCESS.value());
            }else {
                responseDTO = populateResponse(e, responseDTO);
            }
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "retrieving Talk Group Simulatainous Session List - ", new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            responseDTO = populateResponse(e, responseDTO);
        }

        knLogger.info(methodName, "EXIT");
        return responseDTO;
    }

