    private static boolean isContactNotModified(KnIPCorpSubscContactListDTO contactListDTO) {
        return contactListDTO.getAddedMdnList().isEmpty() && contactListDTO.getRemovedMdnList().isEmpty()
                && contactListDTO.getAddedSublistIds().isEmpty() && contactListDTO.getRemovedSublistIds().isEmpty()
                && contactListDTO.getRemoveCommonContactList().isEmpty();
    }

    private void getXDMResponseDTO(KnXDMCorpRespDTO respDto, KnCorpResponseDTO corpRespDto) throws KnXDMServerException {
        String methodName = "getXDMResponseDTO";
        populateXdmResponse(respDto, corpRespDto);
        if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
            knLogger.error(methodName, "Operation Failed");
            throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
        }
    }

    private KnCorpResponseDTO setTargetPermissionForToMdn(KnCorpSubsResquestDTO xdmRequestDTO, KnPersisterTxn persisterTxn, KnIPCorpSubscCloningListDTO corpSubscCloningListDTO) throws KnXDMServerException {
        String methodName = "setTargetPermissionForToMdn()";
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        KnIPAuthUserPermissionInfoDTO ipAuthUserPermissionInfoDTO = corpSubscCloningListDTO.getIpAuthUserPermissionInfoDTO();
        if (ipAuthUserPermissionInfoDTO.getTargetMdnPermissionBitInfoList().isEmpty())
            return populate(respDto);
        respDto = corpClientIntf.setBulkTargetPermissions(ipAuthUserPermissionInfoDTO, persisterTxn);
        knLogger.debug(methodName, "assignPermission response:", respDto);
        if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getStatus()) {
            knLogger.error(methodName, "assignContact Operation Failed");
            throw new KnXDMServerException(respDto.getStatusCode(), respDto.getMessage());
        }
        knLogger.debug(methodName, "Returning assignUPM's setTargetPermissions response - ", respDto);
        return respDto;
    }


    private KnIPAuthUserPermissionInfoDTO getKnIPAuthUserPermissionInfoDTO(KnCorpSubsResquestDTO xdmRequestDTO, KnPersisterTxn persisterTxn, Collection<KnTargetMdnPermBitInfo> finalTargetMdnPermissionBitInfoList) throws KnProvException {
        List<KnTargetMdnPermBitInfo> tuProfileMdnPermInfoList = new ArrayList<>();

        //adding all the profile mdns for the base mdn in req to tu list.
        for (KnTargetMdnPermBitInfo tu : finalTargetMdnPermissionBitInfoList) {
            List<String> profileMdns = provMediator.getMdnForUPM(tu.getMdn(), persisterTxn);
            //removing base mdn from profileMdns list
            profileMdns.remove(tu.getMdn());
            for (String profileMdn : profileMdns) {
                tuProfileMdnPermInfoList.add(new KnTargetMdnPermBitInfo(profileMdn
                        , tu.getSubsName(), tu.getAmbientListening()
                        , tu.getDiscreteListening(), tu.getUserCheck(), tu.getUserEnable()
                        , tu.getEmergPermission(), tu.getMcVideoUnConfirmedPull(),tu.getPermBitSet(),tu.getDiscreteEnabled()));
            }
        }

        Collection<KnTargetMdnPermBitInfo> targetProfileMdnPermBitInfos = new ArrayList<>();
        if (null != tuProfileMdnPermInfoList && !tuProfileMdnPermInfoList.isEmpty()) {
            for (KnTargetMdnPermBitInfo profileMdns : tuProfileMdnPermInfoList) {
                targetProfileMdnPermBitInfos.add(new KnTargetMdnPermBitInfo(profileMdns.getMdn()
                        , profileMdns.getSubsName()
                        , profileMdns.getAmbientListening(), profileMdns.getDiscreteListening()
                        , profileMdns.getUserCheck(), profileMdns.getUserEnable()
                        , profileMdns.getEmergPermission(), profileMdns.getMcVideoUnConfirmedPull()
                        , profileMdns.getPermBitSet(), profileMdns.getDiscreteEnabled()));
            }
        }
        KnIPAuthUserPermissionInfoDTO ipAuthUserPermissionInfoDTO = new KnIPAuthUserPermissionInfoDTO();
        ipAuthUserPermissionInfoDTO.setTargetMdnPermissionBitInfoList(finalTargetMdnPermissionBitInfoList);
        ipAuthUserPermissionInfoDTO.setTargetProfileMdnPermissionBitInfoList(targetProfileMdnPermBitInfos);
        ipAuthUserPermissionInfoDTO.setCorpId(Integer.parseInt(xdmRequestDTO.getCorpId()));
        ipAuthUserPermissionInfoDTO.setAuthorizedMdn(xdmRequestDTO.getToMdn());
        return ipAuthUserPermissionInfoDTO;
    }

    @Override
    public IXDMResponseDTO createSubsATGScanList(KnMessage message) {
        String methodName = "createSubsATGScanList(KnMessage)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_CREATE_SUBS_ATG_SCAN_LIST);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMAddlTalkGroupRequestDTO) {
                KnXDMAddlTalkGroupRequestDTO addlTalkGroupRequestDTO = (KnXDMAddlTalkGroupRequestDTO) requestDTO;
                //validate corp Hierarchy
                if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(addlTalkGroupRequestDTO.getCorpId()),
                        addlTalkGroupRequestDTO.getHierarchyType())) {
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", addlTalkGroupRequestDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
            }
            corpResponseDTO = corpMediator.createSubsATGScanList(requestDTO, persisterTxn);
            populateXdmResponse(respDto, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            // Step : prepare notification and send to notification mgr
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_CREATE_SUBS_ATG_SCAN_LIST_SUCC_RESP);
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResponseDTO);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.info(methodName, "Notification status - ", isNotified);
            knLogger.info(methodName, "Returning createSubsATGScanList response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while createSubsATGScanList", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while createSubsATGScanList",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

