    @Override
    public IXDMResponseDTO deleteOSMList(KnMessage message) {

        String methodName = "deleteOSMList(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            int corpId = 0;
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (requestDTO instanceof KnXDMCorpOSMRequestDTO) {
                KnXDMCorpOSMRequestDTO corpOSMRequestDTO = (KnXDMCorpOSMRequestDTO) requestDTO;
                //validate corp Hierarchy
                corpId = Integer.parseInt(corpOSMRequestDTO.getCorpId());
                if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(corpId, corpOSMRequestDTO.getHierarchyType())) {
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", corpOSMRequestDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
            }
            corpResponseDTO = corpMediator.deleteOSMList(requestDTO, persisterTxn);
            populateXdmResponse(respDto, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            // save the transaction
            persisterTxn.save();
            //sending notification with member mdn for updated group etag.
            if(corpResponseDTO.getChangeLogMap()!=null&&!corpResponseDTO.getChangeLogMap().isEmpty()){
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResponseDTO);
                knLogger.info(methodName, "preparing notification - ", xcapDiffList);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.info(methodName, "sendXcapDiffNotifications  isNotified- ", isNotified);
            }
            if (xcapMobileSync) {
                commonMediator.startNotifyMicroServicesJob(corpResponseDTO.getChangeLogMap(), corpId,
                        corpResponseDTO.getGroupCreatedBy(), corpResponseDTO.getLmrIntropCapable(), corpResponseDTO.getMcxGrpInd());
            }
            knLogger.debug(methodName, "sending MCSGrp notification");
            boolean notifyStatus = commonMediator.sendMCSGRPNotification(corpResponseDTO,allMcsXcapUris,corpId);
            knLogger.info(methodName, "sendMCSGRPNotification  isNotified- - ", notifyStatus);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_OSM_LIST_DELETED);
            knLogger.info(methodName, "Returning deleteOSMList response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while deleteOSMList", e);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_OSM_LIST_DELETED_FAILURE);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while deleteOSMList",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_OSM_LIST_DELETED_FAILURE);
            respDto = populateResponse(e, respDto);
        }
        return respDto;

    }

