    private void initiateBulkGrpJob(String mdn, Collection<Integer> grpIds, int corpId) {
        String methodName = "initiateBulkGrpJob(String, Collection<Integer>, int)";
        KnBulkGroupContactAssignJob bulkGroupContactAssignJob = new KnBulkGroupContactAssignJob();
        if (grpIds != null && !grpIds.isEmpty()) {
            knLogger.debug(methodName, "Calling Bulk group member job - ");
            bulkGroupContactAssignJob.setGrpIds(grpIds);
        }
        List<KnBulkGroupContactAssignJob> jobList = new ArrayList<KnBulkGroupContactAssignJob>(1);
        bulkGroupContactAssignJob.setMaxNotificationSize(msgTruncationLimit);
        bulkGroupContactAssignJob.setCorpId(corpId);
        bulkGroupContactAssignJob.setMdn(mdn);
        jobList.add(bulkGroupContactAssignJob);
        try {
            knLogger.debug(methodName, "Scheduling the Jobs - ", jobList);
            scheduler.addRamJob(jobList, KnJobConstants.BULK_GROUP_JOB_FOR_CONTACT);
        } catch (KnJobSchedulerException e) {
            knLogger.error(methodName,
                    "KnJobSchedulerException occurred while ",
                    "submitting Notification Job to Scheduler - " + e);
        }
    }

    public IXDMResponseDTO searchCorpAddressBook(IXDMRequestDTO subscriberInfo) {
        String methodName = "searchCorpAddressBook(IXDMRequestDTO)";
        KnXDMSearchCorpAddressBookResDTO respDto = new KnXDMSearchCorpAddressBookResDTO();
        KnPersisterTxn persisterTxn = null;
        KnXDMSearchCorpAddressBookRequestDTO xdmRequestDto = null;
        knLogger.debug(methodName, "Received input DTO - ", subscriberInfo);
        KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SEARCH_CONTACT_REQ);
        try {
            if (subscriberInfo instanceof KnXDMSearchCorpAddressBookRequestDTO) {
                xdmRequestDto = (KnXDMSearchCorpAddressBookRequestDTO) subscriberInfo;
                knLogger.debug(methodName, "received DTO for searchCorpAddressBook - ", xdmRequestDto);
            } else {
                knLogger.error(methodName, "received an Invalid DTO for searchCorpAddressBook op - ", subscriberInfo);
                respDto.setResponseMessage("Invalid DTO is passed");
                respDto.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                respDto.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return respDto;
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(xdmRequestDto.getMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO,
                    persisterTxn);
            knLogger.debug(methodName, "Retrieved Subscriber Details - ", subsProfileInfoDTO);

            if (subsProfileInfoDTO.getServiceAuthStatus() != KnConstants.SERVICE_AUTH_STATUS.ACTIVATED.value()) {
                knLogger.debug(methodName, "Subscriber is not activated");
                throw new KnXDMServerException(KnErrorCodes.BOEntity.SUBS_IS_NOT_ACTIVATED,
                        "Subscriber is not activated");
            }

            if (subsProfileInfoDTO.getCorporateSubscriptionType() != KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {
                knLogger.debug(methodName, "Invalid Subscription type");
                throw new KnXDMServerException(KnErrorCodes.BOEntity.INVALID_SUBSCRIPTION_TYPE,
                        "Invalid Subscription type");
            }
            int clinetPV=subsProfileInfoDTO.getClientPVmajorVer();
            subscriberInfoDTO.setCorpId(subsProfileInfoDTO.getCorpId());
            subscriberInfoDTO.setPageId(xdmRequestDto.getPageId());
            subscriberInfoDTO.setMaxPageSize(xdmRequestDto.getMaxPageSize());
            subscriberInfoDTO.setSearchString(xdmRequestDto.getSearchString());
            subscriberInfoDTO.setMcPttId(xdmRequestDto.getMcpttId());
            subsProfileInfoDTO=provClientIntf.searchCorpAddressBook(subscriberInfoDTO, persisterTxn);
            respDto = (KnXDMSearchCorpAddressBookResDTO) populateAddressBookResponse(respDto,subsProfileInfoDTO,clinetPV);
            respDto.setPageId(xdmRequestDto.getPageId());
            respDto.setTxnId(xdmRequestDto.getTxnId());
            knLogger.debug(methodName, "Saving the transaction");
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_SEARCH_CONTACT_REQ_SUCCESS);
            persisterTxn.save();

        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, e.getErrorMessage(), e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        }catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "retrieving Subscribers Group List - ",new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

