    //MCSXCAP MCPTT APIs
    public IXDMResponseDTO getMCPTTUEConfig(IXDMRequestDTO requestDTO) {
        String methodName = "getMCPTTUEConfig(IXDMRequestDTO)";
        knLogger.debug( methodName, "--->requestDTO::"+requestDTO);
        //IXDMResponseDTO respDto = new KnXDMRespDTO();
        KnMCSXCAPRespDTO mcsxcapRespDTO = new KnMCSXCAPRespDTO();
        KnXDMMcPttUEConfigRespDTO respDto=new KnXDMMcPttUEConfigRespDTO();
        KnPersisterTxn persisterTxn = null;
        KnXDMMcsReqDTO xdmRequestDto = null;
        knLogger.debug(methodName, "--->Received input DTO - ", requestDTO);
        KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.GET_MCPTT_UE_CONFIG_DOC_REQ);
        try {
            if (requestDTO instanceof KnXDMMcsReqDTO) {
                xdmRequestDto = (KnXDMMcsReqDTO) requestDTO;
                knLogger.debug(methodName, "--->received DTO for getMCPTTUEConfig - ", xdmRequestDto);
            } else {
                knLogger.error(methodName, "--->received an Invalid DTO for getMCPTTUECOnfig op - ", requestDTO);
                respDto.setResponseMessage("Invalid DTO is passed");
                respDto.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                respDto.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                knLogger.debug(methodName, "--->OnFailure respDto - ", respDto);
                return respDto;
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            KnXDMMcsReqDTO subscriberInfoDTO = new KnXDMMcsReqDTO();
            subscriberInfoDTO.setMcId(xdmRequestDto.getMcId());
            subscriberInfoDTO.setMcpttID(xdmRequestDto.getMcpttID());
            subscriberInfoDTO.setUserAgent(xdmRequestDto.getUserAgent());
            knLogger.debug(methodName, "--->after Set :subscriberInfoDTO - ", subscriberInfoDTO);
            mcsxcapRespDTO = pubDocMediator.getMCPTTUEConfig(subscriberInfoDTO, persisterTxn);
            respDto = mcsxcapRespDTO.getPttUEConfigRespDTO();
            knLogger.debug(methodName, "--->knXDMMcPttUEConfigRespDTO - ", respDto);

            //  respDto.setResponseMessage(knXDMMcPttUEConfigRespDTO.getResponseMessage());
            //  respDto.setResponseCode(knXDMMcPttUEConfigRespDTO.getResponseCode());
            //  respDto.setResponseStatus(knXDMMcPttUEConfigRespDTO.getResponseStatus());
            //((KnXDMRespDTO) respDto).setKnXDMMcPttUEConfigRespDTO(knXDMMcPttUEConfigRespDTO);

            // if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == knXDMMcPttUEConfigRespDTO.getResponseStatus()) {
            respDto = (KnXDMMcPttUEConfigRespDTO)commonMediator.getSuccessResponse(respDto);
            // }
            knLogger.debug(methodName, "Saving the transaction");
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.GET_MCPTT_UE_CONFIG_DOC_REQ_SUCCESS);
            persisterTxn.save();
            com.kodiak.xdms.server.common.dto.common.KnSubsProfileDTO subsProfileDTO = mcsxcapRespDTO.getSubsProfileDTO();
            if(subsProfileDTO !=null && subsProfileDTO.isActiveFSUpdated()){
                List<KnSubscrEXDMSNotifyDto> notifyDtoList = prepareMicroServiceNotification(subsProfileDTO);
                knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
                knLogger.debug(methodName, "micro service notify for activeFs change event - Sent");
            }

        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, e.getErrorMessage(), e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        }catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "getMCPTTUEConfig - ",new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        knLogger.debug(methodName, "--->respDto - ", respDto);
        return respDto;
    }

    public IXDMResponseDTO getMCPTTUserProfile(KnMessage message) {
        String methodName = "getMCPTTUserProfile(IXDMRequestDTO)";
        // IXDMResponseDTO respDto = new KnXDMRespDTO();
        KnMCSXCAPRespDTO mcsxcapRespDTO = new KnMCSXCAPRespDTO();
        KnXDMMcPttUserProfileRespDTO respDto=new KnXDMMcPttUserProfileRespDTO();
        KnPersisterTxn persisterTxn = null;
        KnXDMMcsReqDTO xdmRequestDto = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.GET_MCPTT_USER_PROFILE_CONFIG_DOC_REQ);
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            knLogger.debug(methodName, "--->Received input DTO - ", requestDTO);
            if (requestDTO instanceof KnXDMMcsReqDTO) {
                xdmRequestDto = (KnXDMMcsReqDTO) requestDTO;
                knLogger.debug(methodName, "--->received DTO for getMCPTTUserProfile - ", xdmRequestDto);
            } else {
                knLogger.error(methodName, "--->received an Invalid DTO for getMCPTTUserProfile op - ", requestDTO);
                respDto.setResponseMessage("Invalid DTO is passed");
                respDto.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                respDto.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                knLogger.debug(methodName, "--->OnFailure respDto - ", respDto);
                return respDto;
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            KnXDMMcsReqDTO subscriberInfoDTO = new KnXDMMcsReqDTO();
            subscriberInfoDTO.setMcId(xdmRequestDto.getMcId());
            subscriberInfoDTO.setMcpttID(xdmRequestDto.getMcpttID());
            subscriberInfoDTO.setUserAgent(xdmRequestDto.getUserAgent());
            subscriberInfoDTO.setFileName(xdmRequestDto.getFileName());
            subscriberInfoDTO.setClientFS2(xdmRequestDto.getClientFS2());
            knLogger.debug(methodName, "--->after Set :subscriberInfoDTO - ", subscriberInfoDTO);
            mcsxcapRespDTO = pubDocMediator.getMCPTTUserProfile(subscriberInfoDTO, persisterTxn);
            respDto = mcsxcapRespDTO.getPttUserProfileRespDTO();
            knLogger.debug(methodName, "--->knXDMMcPttUserProfileRespDTO - ", respDto);

            // respDto.setResponseMessage(knXDMMcPttUserProfileRespDTO.getResponseMessage());
            // respDto.setResponseCode(knXDMMcPttUserProfileRespDTO.getResponseCode());
            // respDto.setResponseStatus(knXDMMcPttUserProfileRespDTO.getResponseStatus());
            //((KnXDMRespDTO) respDto).setKnXDMMcPttUserProfileRespDTO(knXDMMcPttUserProfileRespDTO);

            //if (KnConstants.RESPONSE_STATUS.SUCCESS.value() == knXDMMcPttUserProfileRespDTO.getResponseStatus()) {
            respDto = (KnXDMMcPttUserProfileRespDTO)commonMediator.getSuccessResponse(respDto);
            //}
            KnCorpResponseDTO oidcXcapNotify=null;
            boolean oldReGroupBit = respDto.getOldActiveFS()!=null && KnGeneralUtil.getFeatureBitValue(
                    respDto.getOldActiveFS(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            boolean newReGroupBit = respDto.getActiveFS()!=null && KnGeneralUtil.getFeatureBitValue(
                    respDto.getActiveFS(),
                    FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            knLogger.debug(methodName," details::",respDto.getCorpId(),respDto.getAliasMdn(), respDto.getActiveFS(), respDto.getOldActiveFS());
            if(oldReGroupBit != newReGroupBit){
                knLogger.info(methodName,"notification for preconfigure group");
                KnCorpResponseDTO groupNotifyResp = corpMediator.groupNotifyOnActiveFsChange(respDto.getCorpId(),
                        respDto.getAliasMdn(), respDto.getActiveFS(), respDto.getOldActiveFS(), persisterTxn);
                oidcXcapNotify=new KnCorpResponseDTO();
                oidcXcapNotify.setChangeLogMap(groupNotifyResp.getChangeLogMap());
            }

            knLogger.debug(methodName, "Saving the transaction");
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.GET_MCPTT_USER_PROFILE_CONFIG_DOC_REQ_SUCCESS);
            persisterTxn.save();
            com.kodiak.xdms.server.common.dto.common.KnSubsProfileDTO subsProfileDTO = mcsxcapRespDTO.getSubsProfileDTO();
            if(subsProfileDTO !=null && subsProfileDTO.isActiveFSUpdated()){
                List<KnSubscrEXDMSNotifyDto> notifyDtoList = prepareMicroServiceNotification(subsProfileDTO);
                knLogger.info(methodName, "Publishing micro service notify  for User event - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
                knLogger.debug(methodName, "micro service notify for activeFs change event - Sent");
            }
            if (oidcXcapNotify != null) {
                // prepare notification and send to notification mgr
                Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(oidcXcapNotify);
                knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
                notifier.setMaxNotfnsPerJob(2);
                KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                notificationParamDTO.setCid(message.getCorrelationId());
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                knLogger.debug(methodName, "Notification status - ", isNotified);
            }

        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, e.getErrorMessage(), e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        }catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ",
                    "getMCPTTUserProfile - ",new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        knLogger.debug(methodName, "--->respDto - ", respDto);
        return respDto;
    }


