    @Override
    public IXDMResponseDTO createUserProfile(IXDMRequestDTO requestDTO) {

        String methodName = "createUserProfile(IXDMRequestDTO)";
//        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnXDMCorpUserProfileRespDTO respDto = new KnXDMCorpUserProfileRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        knLogger.info(methodName, "Entry requestDTO- ", requestDTO);
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_CREATE_USER_PROFILE_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            String corpId = null;
            if (requestDTO instanceof KnXDMCorpUserProfileRequestDTO) {
                KnXDMCorpUserProfileRequestDTO userProfile = (KnXDMCorpUserProfileRequestDTO) requestDTO;
                //validate corp Hierarchy
                corpId = userProfile.getCorpId();
                if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(userProfile.getCorpId()),
                        userProfile.getHierarchyType())) {
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", userProfile.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
            }


            corpResponseDTO = corpMediator.createUserProfile(requestDTO, persisterTxn);
            KnXDMCorpUserProfileDTO userProfileDTO = new KnXDMCorpUserProfileDTO();
            userProfileDTO.setProfileId(corpResponseDTO.getUserProfileId());
            respDto.setUserProfileInfo(userProfileDTO);
            populateXdmResponse(respDto, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            if (corpResponseDTO.getMcxGrpMemberShipMap()!=null && !corpResponseDTO.getMcxGrpMemberShipMap().isEmpty()) {
                List<KnCorpEXDMSNotifyDto> microserviceNotify = new ArrayList<>();
                Map<Integer, KnCorpGroupContactDTO>  mcxgroupMap = corpResponseDTO.getMcxGrpMemberShipMap();
                for(Integer key : mcxgroupMap.keySet()) {
                    List<KnCorpEXDMSNotifyDto> grpNotifyDtoList = commonMediator.getModifyMcxGrpMicroSrvNotifyDto(corpResponseDTO, Integer.parseInt(corpId), key, corpResponseDTO.getUserProfileId(), mcxgroupMap.get(key), null);
                    microserviceNotify.addAll(grpNotifyDtoList);
                }
                if (!microserviceNotify.isEmpty()){
                    commonMediator.startNotifyMicroServicesJob(microserviceNotify);
                }
            }
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_CREATE_USER_PROFILE_REQ_SUCC);
            knLogger.info(methodName, "Returning createUserProfile response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while createUserProfile", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while createUserProfile",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    @Override
    public IXDMResponseDTO updateUserProfile(IXDMRequestDTO requestDTO) {
        String methodName = "updateUserProfile(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        knLogger.info(methodName, "Entry requestDTO- ", requestDTO);
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_USER_PROFILE_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (requestDTO instanceof KnXDMCorpUserProfileRequestDTO) {
                KnXDMCorpUserProfileRequestDTO userProfile = (KnXDMCorpUserProfileRequestDTO) requestDTO;
                //validate corp Hierarchy
                if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(userProfile.getCorpId()),
                        userProfile.getHierarchyType())) {
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", userProfile.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
            }

            corpResponseDTO = corpMediator.updateUserProfile(requestDTO, persisterTxn);
            populateXdmResponse(respDto, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }

            KnXDMCorpUserProfileRequestDTO userProfileReqDto=null;
            if (requestDTO instanceof KnXDMCorpUserProfileRequestDTO) {
                userProfileReqDto = (KnXDMCorpUserProfileRequestDTO) requestDTO;
            }

            KnIPUserProfileDTO ipUserProfileDTO=new KnIPUserProfileDTO();
            ipUserProfileDTO.setHierarchyType(userProfileReqDto.getHierarchyType());
            ipUserProfileDTO.setCustomParamMap(userProfileReqDto.getCustomParamMap());
            ipUserProfileDTO.setCorpId(userProfileReqDto.getCorpId());
            ipUserProfileDTO.setProfileId(userProfileReqDto.getUserProfileId());
            ipUserProfileDTO.setAddedOwnerIDList(userProfileReqDto.getAddedOwnerIdList());
            ipUserProfileDTO.setRemovedOwnerIDList(userProfileReqDto.getRemovedOwnerIdList());
            userProfileReqDto.getUserProfileInfo().setTgscMode(corpResponseDTO.getTgscMode());
            KnCorpModifyUserProfileDTO modifyUpmReq = KnCorpCommonInfoUtil.modifyUpmTransform(userProfileReqDto);
            ipUserProfileDTO.setModifiedUserProfileDTO(modifyUpmReq);
            ipUserProfileDTO.setUserProfileName(userProfileReqDto.getUserProfileInfo().getProfileName());
            //seeting upmfs
            if(userProfileReqDto.getUserProfileInfo().getUserProfileFS()!=null) {
                KnXDMUserProfileFSDTO xdmUpmFs = userProfileReqDto.getUserProfileInfo().getUserProfileFS();
                KnUserProfileFSDTO ipUpmFs=new KnUserProfileFSDTO();
                ipUpmFs.setAmbientListening(xdmUpmFs.getAmbientListening());
                ipUpmFs.setBrdcrmb(xdmUpmFs.getBrdcrmb());
                ipUpmFs.setDiscreteListening(xdmUpmFs.getDiscreteListening());
                ipUpmFs.setGeofnc(xdmUpmFs.getGeofnc());
                ipUpmFs.setLocPublish(xdmUpmFs.getLocPublish());
                ipUpmFs.setMcVideoConfirmedPull(xdmUpmFs.getMcVideoConfirmedPull());
                ipUpmFs.setMcVideoGroupRx(xdmUpmFs.getMcVideoGroupRx());
                ipUpmFs.setMcVideoRx(xdmUpmFs.getMcVideoRx());
                ipUpmFs.setMcVideoTx(xdmUpmFs.getMcVideoTx());
                ipUpmFs.setPtloc(xdmUpmFs.getPtloc());
                ipUpmFs.setPtmd(xdmUpmFs.getPtmd());
                ipUpmFs.setPtx(xdmUpmFs.getPtx());
                ipUpmFs.setTgsclnt(xdmUpmFs.getTgsclnt());
                ipUpmFs.setUserCheck(xdmUpmFs.getUserCheck());
                ipUpmFs.setUserEnable(xdmUpmFs.getUserEnable());
                ipUpmFs.setOsm(xdmUpmFs.getOsm());
                ipUpmFs.setEmergency(xdmUpmFs.getEmergency());
                ipUpmFs.setSelfDnDPrivilege(xdmUpmFs.getSelfDnDPrivilege());
                ipUserProfileDTO.setUserProfileFSDto(ipUpmFs);
            }


            String modifyUpmJsonString = KnCorpCommonInfoUtil.ObjToJson(ipUserProfileDTO);
            KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(userProfileReqDto.getCorpId(), userProfileReqDto.getTransactionId()
                    , userProfileReqDto.getUserProfileId(), UPM_OPERATION_TYPE.MODIFY_USER_PROFILE.Value(), userProfileReqDto.getMdn(),
                    UPM_RESOURCE_TYPE.MDN.Value(), modifyUpmJsonString, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
            upmJobScheduler.addJob(knAsyncJobDTO);

            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_MODIFY_USER_PROFILE_REQ_SUCC);
            knLogger.info(methodName, "Returning updateUserProfile response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while updateUserProfile", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while updateUserProfile",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

