    @Override
    public IXDMResponseDTO assignUserProfile(IXDMRequestDTO requestDTO) {
        String methodName = "assignUserProfile(IXDMRequestDTO)";
        KnXDMCorpUserProfileRequestDTO userProfileReqDto = null;
        if (requestDTO instanceof KnXDMCorpUserProfileRequestDTO) {
            userProfileReqDto = (KnXDMCorpUserProfileRequestDTO) requestDTO;
        }
        KnPersisterTxn persisterTxn = null;
        IXDMResponseDTO responseDTO = new KnXDMCorpRespDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnXDMSubsProvInfoDTO subsProvInputDTO = null;
        KnXDMCorpRespDTO corpRespDTO = new KnXDMCorpRespDTO();
        try {

            knLogger.debug(methodName, "KnXDMCorpUserProfileRequestDTO :", userProfileReqDto);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_ASSIGN_USER_PROFILE_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();

            corpResponseDTO = corpMediator.assignUserProfile(requestDTO, persisterTxn);
            populateXdmResponse(corpRespDTO, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == corpRespDTO.getResponseStatus()) {
                knLogger.error(methodName, "assignUserProfile Operation Failed");
                throw new KnXDMServerException(corpRespDTO.getResponseCode(), corpRespDTO.getResponseMessage());
            }
            KnIPUserProfileDTO ipUserProfileDTO=new KnIPUserProfileDTO();
            ipUserProfileDTO.setHierarchyType(userProfileReqDto.getHierarchyType());
            ipUserProfileDTO.setIsDefaultProfile(userProfileReqDto.getIsDefaultProfile());

            String assignUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfileDTO);
            KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(userProfileReqDto.getCorpId(), userProfileReqDto.getTransactionId()
                    , userProfileReqDto.getUserProfileId(), UPM_OPERATION_TYPE.ASSIGN_USER_PROFILE.Value(), userProfileReqDto.getMdn(),
                    UPM_RESOURCE_TYPE.MDN.Value(),assignUpmJsonString,KnConstants.UPM_JOB_STATUS.NEW.Value(),null);

            upmJobScheduler.addJob(knAsyncJobDTO);

            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_ASSIGN_USER_PROFILE_REQ_SUCC);
            responseDTO = commonMediator.getSuccessResponse(responseDTO);
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed assign upm ", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred ", e);
            rollback(persisterTxn);
        }
        knLogger.info(methodName, "EXIT: assign upm - ", responseDTO);
        return responseDTO;
    }

    public void addingBulkZoneChannelPriorityPerGroup(KnXDMCorpUserProfileRespDTO userProfile, KnPersisterTxn persisterTxn) throws KnXDMServerException {
        String methodName = "addingBulkZoneChannelPriorityPerGroup()";
        knLogger.debug(methodName, "Entry :: ", userProfile);
        if (userProfile.getUserProfileInfo() != null
                && userProfile.getUserProfileInfo().getGroupListInfo() != null
                && !userProfile.getUserProfileInfo().getGroupListInfo().isEmpty()) {
            Set<KnXDMGroupListInfoDTO> upmGroups = userProfile.getUserProfileInfo().getGroupListInfo();
            KnIPCorpGroupInfoDTO groupInfoDTO = new KnIPCorpGroupInfoDTO();
            List<String> upmGroupIds = upmGroups.stream().map(KnXDMGroupListInfoDTO::getGroupId).collect(Collectors.toList());
            List<Integer> intUpmGroupIds = upmGroupIds.stream().map(Integer::parseInt).collect(Collectors.toList());
            groupInfoDTO.setGroupIds(intUpmGroupIds);
            KnCorpGrpListInfoRespDto groupInfoResp = corpClientIntf.getListOfGroupInfo(groupInfoDTO, persisterTxn);
            knLogger.debug(methodName, "groupInfoResp :", groupInfoResp);
            List<KnCorpGrpBasicInfoRespDto> groupInfoList = groupInfoResp.getGroupListInfo();
            Map<Integer, Integer> groupIdNTypeMap = groupInfoList.stream().collect(
                    Collectors.toMap(KnCorpGrpBasicInfoRespDto::getGroupId, KnCorpGrpBasicInfoRespDto::getGrpType));
            knLogger.debug(methodName, "groupIdNTypeMap ", groupIdNTypeMap);
            KnXDMTalkGroupRequestDTO campedGroupReq = new KnXDMTalkGroupRequestDTO();
            List<KnXDMTalkGroupInfoDTO> addedCampGrpList = new ArrayList<>();
            List<KnXDMTalkGroupInfoDTO> modifyTalkGroupInfo = new ArrayList<>();
            List<KnXDMTalkGroupInfoDTO> removeTalkGroupInfo = new ArrayList<>();
            for (KnXDMGroupListInfoDTO groupInfo : upmGroups) {
                KnXDMTalkGroupInfoDTO CampGrpInfo = new KnXDMTalkGroupInfoDTO();
                Integer groupId = Integer.valueOf(groupInfo.getGroupId());
                if (groupInfo.getZoneId() != null && groupInfo.getChannelId() != null && groupInfo.getPriority() != null
                        && !groupIdNTypeMap.isEmpty()
                        && !groupIdNTypeMap.get(groupId).equals(3)) { //broadcaster
                    Integer priority = Integer.valueOf(groupInfo.getPriority());
                    CampGrpInfo.setPriority(priority);
                    CampGrpInfo.setGroupId(groupId);
                    addedCampGrpList.add(CampGrpInfo);
                }
            }
            campedGroupReq.setCorpId(userProfile.getCorpId());
            campedGroupReq.setMdn(userProfile.getProfileMdn());
            if (userProfile.getUserProfileInfo().getTgscMode() != null) {
                campedGroupReq.setMode(Integer.parseInt(userProfile.getUserProfileInfo().getTgscMode()));
            }
            campedGroupReq.setETag("-9999");
            campedGroupReq.setAddedCampGrpList(addedCampGrpList);
            campedGroupReq.setModifiedCampGrpList(modifyTalkGroupInfo);
            campedGroupReq.setRemovedCampGrpList(removeTalkGroupInfo);
            KnCorpResponseDTO assignPriorityResp = corpMediator.modifyBulkSubscriberScanList(campedGroupReq, persisterTxn);
            knLogger.debug(methodName, "assignPriorityResp :", assignPriorityResp);
            if (com.kodiak.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == assignPriorityResp.getStatus()) {
                knLogger.debug(methodName, "assign priority Operation Failed :");
                throw new KnXDMServerException(assignPriorityResp.getStatusCode(), assignPriorityResp.getMessage());
            }
        }
    }
    public void addingBulkZoneAndChannelPerGroup(KnXDMCorpUserProfileRespDTO userProfile, KnPersisterTxn persisterTxn) throws KnXDMServerException {
        String methodName = "addingBulkZoneAndChannelPerGroup()";
        knLogger.debug(methodName, "Entry :: ", userProfile);
        if (userProfile.getUserProfileInfo() != null
                && userProfile.getUserProfileInfo().getGroupListInfo() != null
                && !userProfile.getUserProfileInfo().getGroupListInfo().isEmpty()) {
            Set<KnXDMGroupListInfoDTO> upmGroups = userProfile.getUserProfileInfo().getGroupListInfo();
            List<KnXDMAddlTalkGroupInfoDTO> addedTGList = new ArrayList<>();
            Collection<KnXDMAddlTalkGroupInfoDTO> modifyTGList = new ArrayList<>();
            KnXDMAddlTalkGroupRequestDTO addlTalkGrpDTO = new KnXDMAddlTalkGroupRequestDTO();
            for (KnXDMGroupListInfoDTO groupInfo : upmGroups) {
                Integer groupId = Integer.valueOf(groupInfo.getGroupId());
                if (groupInfo.getZoneId() != null && groupInfo.getChannelId() != null) {
                    Integer zoneId = Integer.valueOf(groupInfo.getZoneId());
                    Integer channelId = Integer.valueOf(groupInfo.getChannelId());
                    KnXDMAddlTalkGroupInfoDTO tgGroupInfo = new KnXDMAddlTalkGroupInfoDTO();
                    tgGroupInfo.setMdn(userProfile.getProfileMdn());
                    tgGroupInfo.setGroupId(groupId);
                    tgGroupInfo.setZoneId(zoneId);
                    tgGroupInfo.setChannelId(channelId);
                    addedTGList.add(tgGroupInfo);
                }
            }
            addlTalkGrpDTO.setAddedAddlTgList(addedTGList);
            addlTalkGrpDTO.setCorpId(userProfile.getCorpId());
            addlTalkGrpDTO.setModifiedAddlTgList(modifyTGList);
            addlTalkGrpDTO.setMdn(userProfile.getProfileMdn());
            knLogger.debug(methodName, "assign zone/channel request: ", addlTalkGrpDTO);
            KnCorpResponseDTO assignZoneChannelResp = corpMediator.modifyBulkSubscriberTGList(addlTalkGrpDTO, persisterTxn);
            knLogger.debug(methodName, "assignZoneChannelResp :", assignZoneChannelResp);
            if (com.kodiak.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == assignZoneChannelResp.getStatus()) {
                knLogger.debug(methodName, "assign zone/channel Operation Failed :");
                throw new KnXDMServerException(assignZoneChannelResp.getStatusCode(), assignZoneChannelResp.getMessage());
            }
        }
    }



    /**
     * This method is used to create a new subscriber profile and assign it to the subscriber.
     * It performs various operations such as setting up the subscriber's profile,
     * creating the corporate profile if the subscriber is a corporate user,
     * setting up the feature set for the subscriber,
     * creating the subscriber's roaming profile,
     * adding the subscriber to the contact list,
     * and sending a welcome SMS notification if required.
     *
     * @param userProfileReqDto This is the input DTO containing the details of the user profile to be created.
     * @param persisterTxn This is the transaction object for the database operations.
     * @return KnOPCreateSubsInfoDTO This returns the response DTO containing the status of the operation and any additional information.
     * @throws KnException This exception is thrown if there is any error during the operation.
     */
    public KnOPCreateSubsInfoDTO createSubscriberForAssignUserProfile(KnXDMCorpUserProfileRequestDTO userProfileReqDto, KnPersisterTxn persisterTxn) throws KnException {
        String methodName = "createSubscriberForAssignUserProfile(KnXDMSubsProvDTO, KnPersisterTxn)";
        KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
        //provMediator.getSubscriberDetails(subscriberInfoDTO,persisterTxn);
        subscriberInfoDTO.setMdn(userProfileReqDto.getMdn());
        KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
        String userProfileId = userProfileReqDto.getUserProfileId();
        String corpId = String.valueOf(userProfileReqDto.getCorpId());
        KnIPUserProfileDTO ipUserProfileDTO = new KnIPUserProfileDTO();
        ipUserProfileDTO.setCorpId(corpId);
        ipUserProfileDTO.setProfileId(userProfileId);
        KnCorpResponseDTO userProfileDetails = corpClientIntf.getUserProfileDetails(ipUserProfileDTO, true, persisterTxn);

        KnIPSubsProvInfoDTO subsProvInfoDTO = provMediator.populateSubsProvInfoDTOForAssignUser(subsProfileInfoDTO);
        Integer subsClientType = subsProvInfoDTO.getSubsClientType();
        // checking if any the client type = null then add the default client type
        if (subsClientType == null) {
            subsClientType = KnProvConstants.SUBS_CLIENT_TYPE.HANDSET.value();
            subsProvInfoDTO.setSubsClientType(subsClientType);
        }
        knLogger.debug(methodName, "Subscriber Client type- ", subsClientType);
        //retriving from db/cache client type config check is enable or disable
        //LMR client type changes
        if (subsClientType == com.kodiak.xdms.server.common.resources.KnConstants.SUBSCRIBERS_CLIENT_TYPE.MOBILE_CLIENT.value() || subsClientType == com.kodiak.xdms.server.common.resources.KnConstants.SUBSCRIBERS_CLIENT_TYPE.THIRDPARTYDISPATCHERCLIENT.value()
                || subsClientType == com.kodiak.xdms.server.common.resources.KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value() || subsClientType == com.kodiak.xdms.server.common.resources.KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value()
                || subsClientType == com.kodiak.xdms.server.common.resources.KnConstants.SUBSCRIBERS_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value()
                || subsClientType == com.kodiak.xdms.server.common.resources.KnConstants.SUBSCRIBERS_CLIENT_TYPE.SGMDNPATCH.value()) {

            KnClientTypeConfigDTO clientTypeConfigDTO = genInfoUtil.getClientTypeConfig(subsClientType, persisterTxn);
            if (clientTypeConfigDTO.getIsEnable() != KnProvConstants.CLIENT_TYPE_CONFIGURATION.ENABLED.value()) {
                knLogger.error(methodName, "Client type is disabled");
                throw new KnProvBOException(KnErrorCodes.BOEntity.CLIENT_TYPE_DISABLED, "Subscriber Client Type is disabled");
            }
        }
        // calling the Prov Library
        subsProvInfoDTO.setUserProfileId(userProfileId);
        ipUserProfileDTO.setHierarchyType(userProfileReqDto.getHierarchyType());
        ipUserProfileDTO.setIsDefaultProfile(userProfileReqDto.getIsDefaultProfile());

        String assignUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfileDTO);
        KnIPUserProfileDTO ipUserProfilePermDTO = KnCorpCommonInfoUtil.jsonToObject(assignUpmJsonString, KnIPUserProfileDTO.class);
        String hierarchyType = String.valueOf(ipUserProfilePermDTO.getHierarchyType().value());
        String reqDefaultProfile = ipUserProfilePermDTO.getIsDefaultProfile();
        knLogger.info(methodName, "hierarchyType: ", hierarchyType, "reqDefaultProfile: ", reqDefaultProfile);
//                KnCorpResponseDTO userProfileDetails = userProfile;
        subsProvInfoDTO.setTgscMode(userProfileDetails.getUserProfile().getTgscMode());
        subsProvInfoDTO.setUserProfileIndex(userProfileDetails.getUserProfile().getUserProfileIndex());
        if (reqDefaultProfile != null) {
            subsProvInfoDTO.setIsDefaultProfile(Integer.parseInt(reqDefaultProfile));
        } else {
            subsProvInfoDTO.setIsDefaultProfile(Integer.parseInt(DEFAULT_PROFILE));
        }
        subsProvInfoDTO.setUserProfileFS2(userProfileDetails.getUserProfile().getFeatureBS());
        subsProvInfoDTO.setUserProfileName(userProfileDetails.getUserProfile().getUserProfileName());
        subsProvInfoDTO.setSelfDnDPrivilege(userProfileDetails.getUserProfile().getSelfDnDPrivilege());
        knLogger.debug(methodName, " createSubscriberForAssignUserProfile :", subsProvInfoDTO);
        KnOPCreateSubsInfoDTO profileMdnCreatedResp = provClientIntf.createSubscriberForAssignUserProfile(subsProvInfoDTO, persisterTxn);
        knLogger.debug(methodName, "Profile mdn created - ", profileMdnCreatedResp);
        String xdmPttServerId = null;
        try {
            xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
        } catch (KnBOException e) {
            knLogger.error(methodName, "failed to retrieve xdm Ptt Sever Id");
        }
        List<String> allCommonContactMdns = sublistInfoUtil.getCommonContactListForMdns(userProfileReqDto.getMdn(), xdmPttServerId, persisterTxn);
        if (allCommonContactMdns != null && !allCommonContactMdns.isEmpty()) {
            Map<String, KnMcpttPermissionDTO> mcpttPermissions = corpSubsProvInfoUtil.getAuthUserPermissions(userProfileReqDto.getMdn(), xdmPttServerId, persisterTxn);
            List<KnMcpttPermissionDTO> permissions = new ArrayList<>(mcpttPermissions.values());
            if (!permissions.isEmpty()) {
                Predicate<KnMcpttPermissionDTO> condition = perm -> !(perm.getCommonAu() != null && perm.getCommonAu() == 1);
                permissions.removeIf(condition);
                List<String> profileMdn = new ArrayList<>();
                profileMdn.add(profileMdnCreatedResp.getAliasMdnForAssign());
                corpSubsProvInfoUtil.insertIntoMcpttPermInfoForProfileMdns(permissions, profileMdn, xdmPttServerId, persisterTxn);
            }
        }

        // verify if the Corporate Subscription type is enabled
        // if enabled check the pairing ind is enabled to perform the
        // internal contact pairing
        int corporateSubscriptionType = -1;
        corporateSubscriptionType = subsProvInfoDTO.getCorporateSubscriptionType();
        KnXDMCorpRespDTO corpResp = null;
        KnCorpResponseDTO corpResponseDTO = null;
        if (corporateSubscriptionType == com.kodiak.xdms.server.common.resources.KnConstants.CORP_SUBSCRIPTION_TYPE.CORPORATE.value()) {

            // calling corp library to perform Corp Auto pairing
            Boolean corpAutoParing = profileMdnCreatedResp.getCorpAutoPairing();
            Boolean isOldCorp = profileMdnCreatedResp.getIsOldCorp();

            if (corpAutoParing != null && isOldCorp != null) {
                if (isOldCorp) {
                    knLogger.debug(methodName, "Corp exist. call enable/disable for corp Auto pairing");
                    if (corpAutoParing) {
                        KnXDMCorpSubscInfoRequestDTO contactRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
                        contactRequestDTO.setCorpId(String.valueOf(profileMdnCreatedResp.getCorpId()));
                        contactRequestDTO.setSubscriberMdn(subsProvInfoDTO.getMdn());
                        contactRequestDTO.setName(subsProvInfoDTO.getNetworkName());
                        contactRequestDTO.setHierarchyType(subsProvInfoDTO.getHierarchyType());
                        corpResp = corpMediator.addToPairingList(contactRequestDTO, persisterTxn);
                    } else {
                        // disable auto pairing
                        KnXDMCorpInfoRequestDTO corpInfoRequestDTO = new KnXDMCorpInfoRequestDTO();
                        corpInfoRequestDTO.setEnableAutoPair(Boolean.FALSE);
                        corpInfoRequestDTO.setCorpId(String.valueOf(profileMdnCreatedResp.getCorpId()));
                        corpInfoRequestDTO.setHierarchyType(subsProvInfoDTO.getHierarchyType());
                        corpResp = corpMediator.updateCorpAutoPairing(corpInfoRequestDTO, persisterTxn);
                    }
                } else { //corporate not exist
                    if (corpAutoParing) {
                        knLogger.debug(methodName, "Corp does exist hence created new. call enable auto pairing");
                        KnXDMCorpInfoRequestDTO corpInfoRequestDTO = new KnXDMCorpInfoRequestDTO();
                        corpInfoRequestDTO.setEnableAutoPair(Boolean.TRUE);
                        corpInfoRequestDTO.setCorpId(String.valueOf(profileMdnCreatedResp.getCorpId()));
                        corpInfoRequestDTO.setHierarchyType(subsProvInfoDTO.getHierarchyType());
                        corpResp = corpMediator.updateCorpAutoPairing(corpInfoRequestDTO, persisterTxn);
                    }
                }

                knLogger.debug(methodName, "Corp Autopairing response - ", corpResp);
                if (corpResp != null && corpResp.getResponseStatus() != KnMediatorConstants.SUCCESS) {
                    throw new KnXDMServerException(corpResp.getResponseCode(), corpResp.getResponseMessage());
                }
            }
        }
        return profileMdnCreatedResp;
    }

    @Override
    public IXDMResponseDTO unassignUserProfile(KnMessage message) {
        String methodName = "unassignUserProfile(IXDMRequestDTO)";
        KnXDMCorpUserProfileRequestDTO userProfile=null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        if (payLoad instanceof IXDMRequestDTO) {
            requestDTO = (IXDMRequestDTO) payLoad;
        }
        if (requestDTO instanceof KnXDMCorpUserProfileRequestDTO) {
            userProfile = (KnXDMCorpUserProfileRequestDTO) requestDTO;
        }
        KnPersisterTxn persisterTxn = null;
        IXDMResponseDTO responseDTO = new KnXDMCorpRespDTO();
        KnXDMCorpRespDTO corpRespDTO=new KnXDMCorpRespDTO();
        String mdnForUnassign=null;

        try {
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(userProfile.getCorpId()), userProfile.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", userProfile.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_UNASSIGN_USER_PROFILE_REQ);
            String baseMdn = userProfile.getMdn();
            String userProfileId=userProfile.getUserProfileId();

            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction ");
            persisterTxn.open();

            //unassignController call
            KnCorpResponseDTO corpResponseDTO = corpMediator.unassignUserProfile(userProfile,persisterTxn);
            populateXdmResponse(corpRespDTO, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == corpRespDTO.getResponseStatus()) {
                knLogger.error(methodName, "assignUserProfile Operation Failed");
                throw new KnXDMServerException(corpRespDTO.getResponseCode(), corpRespDTO.getResponseMessage());
            }

            mdnForUnassign = provClientIntf.getMdnForUnassign(baseMdn, userProfileId, persisterTxn);
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(mdnForUnassign);
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);
            //Check if the profile is default if so, mark the base mdn as default profile.
            if(subsProfileInfoDTO.getIsDefaultProfile()==1)
            {
                KnXDMCorpUserProfileRequestDTO corpUserProfileRequestDTO = new KnXDMCorpUserProfileRequestDTO();
                corpUserProfileRequestDTO.setMdn(baseMdn);
                corpUserProfileRequestDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
                corpUserProfileRequestDTO.setUserProfileId(userProfileId);
                corpUserProfileRequestDTO.setHierarchyType(userProfile.getHierarchyType());
                corpUserProfileRequestDTO.setIsDefaultProfile("0");
                corpMediator.updateDefaultProfile(corpUserProfileRequestDTO, persisterTxn);
            }
            //check if the mdn is a pseudo mdn then restrict the operation
            knLogger.info(methodName, "invoking the corporate library ");
            // populating the corporate Library DTO
            KnXDMCorpSubscInfoRequestDTO contactRequestDTO = new KnXDMCorpSubscInfoRequestDTO();
            contactRequestDTO.setSubscriberMdn(mdnForUnassign);
            contactRequestDTO.setHierarchyType(userProfile.getHierarchyType());
            contactRequestDTO.setUpmCall(true);
            KnCorpResponseDTO corpResp = corpMediator.deleteSubscriber(contactRequestDTO, persisterTxn);
            int status = corpResp.getStatus();
            knLogger.debug(methodName, " corp Library response - ", corpResp);
            if (status != 0) {
                throw new KnXDMServerException(corpResp.getStatusCode(), corpResp.getMessage());
            }
            knLogger.debug(methodName, "deleted the corporate data for mdn ");
            //profile mdn notify
            boolean profileMdnNotifystatus = commonMediator.prepareMcxNotifyForProfileMdns(corpResp);
            knLogger.debug(methodName,"profileMdnNotifystatus :",profileMdnNotifystatus);

            //prepare notification and send to notification mgrKnCorpRestMgmtGGService
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpResp);
            knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, persisterTxn, notificationParamDTO);
            knLogger.info(methodName, "Notification status - ", isNotified);
            Collection<String> deletedMemberList = corpResp.getDisabledDispatchMemList();
            knLogger.debug(methodName, "deletedMemberList - ", KnGDPRTemplate.mdnList(deletedMemberList));
            commonMediator.sendTGSModeChangeNotification(corpResp.getTgsModeChgMap());
            knLogger.debug(methodName, "Sending LI notifications - ");
            KnLIEventHandler.logLI(corpResp.getLiEventList());
            knLogger.debug(methodName, "Li Notification Send status - ");
            int publicSubscriptionType = subsProfileInfoDTO.getPublicSubscriptionType();
            if (publicSubscriptionType == KnConstants.PUBLIC_SUBSCRIPTION_TYPE.PUBLIC.value()) {
                knLogger.info(methodName, "invoking the public library");
                pubDocMediator.deleteAllContactsAndGroups(mdnForUnassign, persisterTxn);
                knLogger.debug(methodName, "deleted public data for mdn ");
            }
            // invoking the prov library for Deleting subscriber profile
            KnOPDeleteSubsRespDTO provRespDTO = provClientIntf.deleteSubscriber(subscriberInfoDTO, persisterTxn);
            knLogger.debug(methodName,"Delete Subscriber operation response - ", provRespDTO);
            // Initializing the KnSubscriberInfoDTO for base RestAPI
            KnSubscriberInfoDTO knSubscriberInfoDTO= new KnSubscriberInfoDTO();
            // Fetching the boolean value for 45th bit, If it is true then we will call the new REST API.
            boolean xcapCouchClient = KnGeneralUtil.getFeatureBitValue(provRespDTO.getActiveFS2(), FEATURE_SET.XCAPCOUCHCLIENT.value());
            knLogger.debug(methodName, "xcapCouchClient ", xcapCouchClient);
            // checking if 45th bit is 0/false or 1/true. If not 0/false then we make the rest call
            if(xcapCouchClient){
                // Populating the data KnSubscriberInfoDTO knSubscriberInfoDTO.
                knSubscriberInfoDTO.setMdn(provRespDTO.getMdn());
                knLogger.debug(methodName, "knSubscriberInfoDTO : mdn",knSubscriberInfoDTO);
                // Fetching the bucket URLS
                Map<Integer, String> bucketUrlList = genInfoUtil.retrievePTXbucketUrls(persisterTxn);
                knLogger.debug(methodName, "bucketUrlList : ", bucketUrlList);
                KnFailedCBTxnLogDTO  failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                genInfoUtil.deleteCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                for(Map.Entry<Integer, String> entry : bucketUrlList.entrySet()) {
                    List<String> bucketUrl = new ArrayList<>();
                    Integer curClusterId = entry.getKey();
                    knLogger.debug(methodName, "Updating/deleting profile in clusterId - ", curClusterId);
                    bucketUrl.add(entry.getValue());
                    //REST call for profile creation starts here.
                    KnSyncResponseDTO knSyncResponseDTO = KnManageSyncUserProfileUtil.getInstance().deleteSyncDocument(knSubscriberInfoDTO, bucketUrl);
                    knLogger.debug(methodName, "KnSyncResponseDTO status : ", knSyncResponseDTO.getStatus());
                    if (knSyncResponseDTO.getStatus() == KnConstants.RESPONSE_STATUS.FAILURE.value()){
                        failedCBTxnLogDTO = new KnFailedCBTxnLogDTO();
                        failedCBTxnLogDTO.setMdn(knSubscriberInfoDTO.getMdn());
                        failedCBTxnLogDTO.setImpactedClusterId(entry.getKey());
                        failedCBTxnLogDTO.setTxnType(KnConstants.CB_PROFILE_TXN_TYPE.PROFILE_DELETE.value());
                        genInfoUtil.insertCBTxnFailLog(failedCBTxnLogDTO, persisterTxn);
                    }
                }
            }
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);

            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();

            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_UNASSIGN_USER_PROFILE_REQ_SUCC);
            // sending the notification
            // populate the KnXcapDiffNotifyDTO
            // Notification requires the following params
            // 1. Dir Uri, 2. Dir prev etag,
            if (subsProfileInfoDTO.getSubsClientType() != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Alias_MDN.value()
                    && subsProfileInfoDTO.getSubsClientType() != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Group_MDN.value()) {
                KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                KnOPDirChgDTO dirChgDTO = provRespDTO.getDirChgDTO();
                xcapDiffNotifyDTO.setDeRegisterNotify(true);
                KnDeRegisterNotifyDTO deRegisterNotifyDTO = new KnDeRegisterNotifyDTO();
                deRegisterNotifyDTO.setMdn(provRespDTO.getMdn());
                deRegisterNotifyDTO.setPocHome(provRespDTO.getPocServerHome());
                deRegisterNotifyDTO.setPresenceHome(provRespDTO.getPresenceServerHome());
                deRegisterNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.USER_DELETE.value());
                xcapDiffNotifyDTO.setDeRegisterNotifyDTO(deRegisterNotifyDTO);
                // Collection<KnXcapDiffDocDTO> xcapDocList = new
                // ArrayList<KnXcapDiffDocDTO>();
                // xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                // xcapDiffNotifyDTO.setDirNewEtag(dirChgDTO.getDirNewEtag());
                xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTO.getDirPrevEtag());
                xcapDiffNotifyDTO.setDirURI(dirChgDTO.getDirUri());
                xcapDiffNotifyDTO.setXcapRootUri(dirChgDTO.getXcapRootURI());
                xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_DELETE.value());
                xcapDiffNotifyDTO.setProtocolVersion(dirChgDTO.getProtoVersion());
                xcapDiffNotifyDTO.setPocHome(provRespDTO.getPocServerHome());
                xcapDiffNotifyDTO.setPresenceHome(provRespDTO.getPresenceServerHome());
                knLogger.debug(methodName, "Notification DTO generated - ", xcapDiffNotifyDTO);
                KnXcapDiffNotifier xcapDiffNotifier = KnXcapDiffNotifier.getInstance();
                boolean notificationStatus = notifier.sendXcapDiffNotifications(xcapDiffNotifyDTO);
                if (notificationStatus) {
                    knLogger.debug(methodName, "Successfully sent the notification");
                }
            }
            if(xcapMobileSync){
                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(corpResp.getChangeLogMap(), subsProfileInfoDTO.getCorpId());
            }
            knLogger.debug(methodName, "xcapMobileSync:",xcapMobileSync);
            if(xcapMobileSync){
                KnSubscrEXDMSNotifyDto knSubscrEXDMSNotifyDto= new KnSubscrEXDMSNotifyDto();
                knSubscrEXDMSNotifyDto.setCorpid(provRespDTO.getCorpId());
                knSubscrEXDMSNotifyDto.setMdn(provRespDTO.getMdn());
                knSubscrEXDMSNotifyDto.setId(DELETE_SUBSCR.value() + KnConstants.LINE_SAPERATOR + provRespDTO.getMdn());
                knSubscrEXDMSNotifyDto.setType(DELETE_SUBSCR.value());
                knSubscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                knSubscrEXDMSNotifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                knSubscrEXDMSNotifyDto.setClientType(subsProfileInfoDTO.getSubsClientType());
                knSubscrEXDMSNotifyDto.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                knSubscrEXDMSNotifyDto.setBaseMdn(baseMdn);
                knSubscrEXDMSNotifyDto.setMcpttId(subsProfileInfoDTO.getMcpttId());
                knSubscrEXDMSNotifyDto.setPocPttId(subsProfileInfoDTO.getPoCHome());
                knSubscrEXDMSNotifyDto.setSubsFS2(subsProfileInfoDTO.getSubsFS2());
                knSubscrEXDMSNotifyDto.setMcvideoId(subsProfileInfoDTO.getMcVideoId());
                knSubscrEXDMSNotifyDto.setMcId(subsProfileInfoDTO.getMcId());
                knSubscrEXDMSNotifyDto.setMcdataId(subsProfileInfoDTO.getMcDataId());
                knSubscrEXDMSNotifyDto.setNetworkName(subsProfileInfoDTO.getNetworkName());
                if(null!=subsProfileInfoDTO.getDeviceId())
                knSubscrEXDMSNotifyDto.setDeviceId(subsProfileInfoDTO.getDeviceId());
                List<KnSubscrEXDMSNotifyDto> notifyDtoList= new ArrayList<KnSubscrEXDMSNotifyDto>();
                notifyDtoList.add(knSubscrEXDMSNotifyDto);
                knLogger.debug(methodName,"notifyDtoList :",notifyDtoList);
                knLogger.info(methodName, "Publishing micro service notify for user- ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }
            // updating the pegs
            Collection<Integer> successPegs = new ArrayList<Integer>();
            //successPegs.add(KnOMConstants.XDM_NUM_SUBSCR_DELETED);
            Collection<Integer> listOfPegs = provRespDTO.getSuccessPegs();
            if (listOfPegs != null && !listOfPegs.isEmpty()) {
                for (int pegId : listOfPegs) {
                    successPegs.add(pegId);
                }
            }
            KnStatisticsManagerImpl.getInstance().increment(successPegs);
            // sending the response to the Client
            responseDTO = commonMediator.getSuccessResponse(responseDTO);
            /*
             * Spawning a new thread for update of the DISPATCH_GRP_MEMBER FLAG
             * of Members of the dispatch groups that has been deleted
             */
            knLogger.debug(methodName, "deletedMemberList - ", KnGDPRTemplate.mdnList(deletedMemberList));
            // If deleted members list id not null and not empty start job to
            // update DISPATCH_GROUP_MEMBER field
            if (deletedMemberList != null && !deletedMemberList.isEmpty()) {
                knLogger.debug(methodName,"Calling Dispatch group member job - ");
                List<KnDispGrpMemChecker> jobList = new ArrayList<KnDispGrpMemChecker>(1);
                KnDispGrpMemChecker dispGrpMemCheckerJob = new KnDispGrpMemChecker();
                dispGrpMemCheckerJob.setMaxNotificationSize(maxNotificationSize);
                // dispGrpMemCheckerJob.setSyncNotfyThresold(500);
                dispGrpMemCheckerJob.setCorpId(subsProfileInfoDTO.getCorpId());
                dispGrpMemCheckerJob.setDeletedMembers(corpResp.getDisabledDispatchMemList());
                dispGrpMemCheckerJob.setAddedMembers(corpResp.getEnabledDispatchMemList());
                knLogger.info("corpResp.getEnabledDispatchMemList()", corpResp.getEnabledDispatchMemList(),
                        "corpResp.getDisabledDispatchMemList()", corpResp.getDisabledDispatchMemList());
                jobList.add(dispGrpMemCheckerJob);
                try {
                    knLogger.debug(methodName, "Scheduling the Jobs - ", jobList);
                    scheduler.addRamJob(jobList, KnJobConstants.JOB_GROUP_NAME);
                } catch (KnJobSchedulerException e) {
                    knLogger.error(methodName,"KnJobSchedulerException occurred while ", "submitting Notification Job to Scheduler - " + e);
                    knLogger.error(methodName, e);
                }
            }
            if(corpResp != null){
                boolean upmProfileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(corpResp);
                knLogger.debug(methodName, "sending Profile notification Status: ", upmProfileNotifyStatus);
            }


            List<KnUnAssignEXDMSNotifyDto> notifyDtoList = new ArrayList<KnUnAssignEXDMSNotifyDto>();
            boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(subsProfileInfoDTO.getActiveFS2(),
                    com.kodiak.common.resources.KnConstants.FEATURE_SET.XCAPCOUCHCLIENT.value());
            if (xcapMobileSync) {
                KnUnAssignEXDMSNotifyDto unAssignEXDMSNotifyDto = new KnUnAssignEXDMSNotifyDto();
                unAssignEXDMSNotifyDto.setId(UNASSIGN_USER_PROFILE.value() + KnConstants.LINE_SAPERATOR + baseMdn);
                unAssignEXDMSNotifyDto.setType(UNASSIGN_USER_PROFILE.value());
                unAssignEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                unAssignEXDMSNotifyDto.setCorpid(subsProfileInfoDTO.getCorpId());
                unAssignEXDMSNotifyDto.setClientType(subsProfileInfoDTO.getSubsClientType());
                unAssignEXDMSNotifyDto.setPv(subsProfileInfoDTO.getClientPVmajorVer() + "." + subsProfileInfoDTO.getClientPVminorVer());
                KnMDNDetailsDTO bMdn = new KnMDNDetailsDTO();
                bMdn.setMdn(baseMdn);
                bMdn.setActiveFS(subsProfileInfoDTO.getActiveFS2());
                bMdn.setLastProfileUpdateTime(subsProfileInfoDTO.getLastProfileUpdateTime());
                unAssignEXDMSNotifyDto.setBaseMdn(bMdn);
                unAssignEXDMSNotifyDto.setNotifyEventType(USER_NOTIFY_EVENTS.value());
                unAssignEXDMSNotifyDto.setProfileMdns(corpResp.getProfileMdnEtagMap() != null ? new ArrayList<>(corpResp.getProfileMdnEtagMap().keySet()) : null);
                notifyDtoList.add(unAssignEXDMSNotifyDto);
            }
            if(!notifyDtoList.isEmpty()){
                knLogger.info(methodName, "Publishing micro service notify  for User event unAssign- ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);
            }

            //place async jobs for clean up of user profile if any.
            Map<Integer,String> delGrpPocHomeMap = corpResp.getDelGrpPocHomeMap();
            if(delGrpPocHomeMap!=null && !delGrpPocHomeMap.isEmpty()) {
                Set<Integer> grpIdList = delGrpPocHomeMap.keySet();
                for(Integer grpId:grpIdList) {
                    Long transactionId = System.nanoTime();
                    knLogger.debug(methodName, "transactionId - ", transactionId);
                    KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(String.valueOf(corpResp.getMdnCorpId()), transactionId.toString()
                            , null, UPM_OPERATION_TYPE.DELETE_GROUP_FROM_PROFILE.Value(), String.valueOf(grpId),
                            UPM_RESOURCE_TYPE.GROUP.Value(), null, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                    upmJobScheduler.addJob(knAsyncJobDTO);
                }
            }


            //Send deleteGroup notify events on last group member deletetion while doing unAssign user profile
            if (xcapMobileSync) {
                List<KnCorpEXDMSNotifyDto> delGrpNotifyList = commonMediator.getDeleteGrpMicroSrvNotifyDto(corpResp);
                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(delGrpNotifyList);

            }

        }
        catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to create Subscriber ", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred ", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        }
        knLogger.info(methodName, "EXIT: unAssignUPM ", responseDTO);
        return responseDTO;
    }

    @Override
    public IXDMResponseDTO getSubscriberUserProfileList(IXDMRequestDTO requestDTO) {

        String methodName = "getSubscriberUserProfileList(IXDMRequestDTO)";
        KnXDMCorpUserProfileRespDTO respDto = new KnXDMCorpUserProfileRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBSCR_USER_PROFILE_LIST_REQ);
            KnXDMCorpUserProfileRequestDTO xdmRequestDTO = (KnXDMCorpUserProfileRequestDTO) requestDTO;
            //validate corp Hierarchy
            if(!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())){
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }

            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            knLogger.debug(methodName, "--->requestDTO - ", requestDTO);
            respDto = corpMediator.getSubscriberUserProfileList(requestDTO, persisterTxn);
            knLogger.debug(methodName, "--->respDto - ", respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto
                    .getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),
                        respDto.getResponseMessage());
            }
            // Step:
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.NUM_GET_SUBSCR_USER_PROFILE_LIST_REQ_SUCC);
            knLogger.info(methodName, "Returning getSubscriberUserProfileList response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while getSubscriberUserProfileList", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while getSubscriberUserProfileList",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;

    }

