    @Override
    public IXDMResponseDTO createDevice(IXDMRequestDTO requestDTO) {
        String methodName = "createDevice(KnMessage)";
        knLogger.info(methodName, "ENTRY: create device with input - ", requestDTO);
        KnPersisterTxn persisterTxn = null;
        KnXDMDeviceProvInfoDTO deviceProvInputDTO = null;
        IXDMResponseDTO responseDTO = new KnXDMRespDTO();
        KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_DEVICE_PROFILE_REQ);
        try {
            // verify if the input DTO is KnXDMSubsProvInfoDTO
            // inputDTO = (IXDMRequestDTO) message.getPayLoad();
            if (requestDTO instanceof KnXDMDeviceProvInfoDTO) {
                deviceProvInputDTO = (KnXDMDeviceProvInfoDTO) requestDTO;
                knLogger.debug(methodName, "received DTO for create device profile - ", deviceProvInputDTO);
            } else {
                knLogger.error(methodName, "received and Invalid DTO for create device profile op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return responseDTO;
            }

            // Opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "Opening the Transaction");
            persisterTxn.open();
            // calling the Prov Library
            KnOPCreateSubsInfoDTO respDTO = provClientIntf.createDevice(deviceProvInputDTO, persisterTxn);
            knLogger.debug(methodName, "Successfully Create device Profile with resp DTO - ", respDTO);

            //Start notification for device
            // retrieving the subscriber profile
            knLogger.debug(methodName, "retrieving the subscriber profile for mdn ");
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(deviceProvInputDTO.getDeviceSubscrMdn());
            KnOPSubsProfileInfoDTO subsProfileInfoDTO = subscriberInfoDTO.getMdn() != null ?
                    provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn) : null;
            if (null != respDTO) {
                deviceProvInputDTO.setCorpId(respDTO.getCorpId());
                deviceProvInputDTO.setDeviceLastUsed(respDTO.getLastUpdateprofileTime());
            }
            boolean lmrInteropFlag = subsProfileInfoDTO != null ? commonInfoUtil.lmrInterFlagValidate(subsProfileInfoDTO.getSubsFS2()) : Boolean.FALSE;
            int lmrInterOpFlagInt =  lmrInteropFlag ? ENABLED : DISABLED;

            KnDeviceExdmsNotifyDto deviceExdmsNotifyDto = commonInfoUtil.formDeviceNotifyPayload(CREATE_DEVICE.value(), deviceProvInputDTO,
                    lmrInterOpFlagInt, MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value(), deviceProvInputDTO.getDeviceId());
            knLogger.info(methodName, "Publishing micro service notify for device- ", deviceExdmsNotifyDto);
            commonMediator.startNotifyMicroServicesJob(List.of(deviceExdmsNotifyDto));

            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_DEVICE_PROFILE_REQ_SUCC);
            responseDTO = commonMediator.getSuccessResponse(responseDTO);
            if (responseDTO instanceof KnXDMRespDTO && null != respDTO.getInternalDeviceId()) {
                ((KnXDMRespDTO) responseDTO).setInternalDeviceId(respDTO.getInternalDeviceId());
            }
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to Create device ", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred ", e);
            rollback(persisterTxn);
            responseDTO = commonMediator.getFailureResponse(responseDTO, e);
        }
        knLogger.info(methodName, "EXIT: Create device - ", responseDTO);
        return responseDTO;
    }

