    @Override
    public IXDMResponseDTO deleteDeviceInfo(IXDMRequestDTO requestDTO) {
        String methodName = "deleteDeviceInfo(KnMessage)";
        knLogger.info(methodName, "ENTRY: delete device Details ");
        KnPersisterTxn persisterTxn = null;
        String deviceId = null;
        KnXDMDeviceInfoRespDTO responseDTO = new KnXDMDeviceInfoRespDTO();
        KnXDMDeviceProvInfoDTO deviceInfoDTO = null;
        KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DELETE_DEVICE_PROFILE_REQ);
        try {

            knLogger.debug(methodName, "Received input DTO - ", requestDTO);
            if (requestDTO instanceof KnXDMDeviceProvInfoDTO) {
                deviceInfoDTO = (KnXDMDeviceProvInfoDTO) requestDTO;
                knLogger.debug(methodName, "received DTO for delete device Details - ", deviceInfoDTO);
            } else {
                knLogger.error(methodName, "received an Invalid DTO for delete device Details op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return responseDTO;
            }

            // opening the transaction
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();
            deviceId = deviceInfoDTO.getDeviceId();
            // invoking teh prov library api
            KnXDMDeviceProvDTO deviceProfileInfoDTO = provClientIntf.getDeviceInfo(deviceId, persisterTxn);
            knLogger.debug(methodName, "Retrieved device Details - ", deviceProfileInfoDTO);
            KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
            subscriberInfoDTO.setMdn(deviceProfileInfoDTO.getDeviceSubscrMdn());

            KnOPSubsProfileInfoDTO subsProfileInfoDTO = subscriberInfoDTO.getMdn() != null ?
                    provClientIntf.getSubscriberIfExist(subscriberInfoDTO.getMdn(), persisterTxn) : null;
            provClientIntf.deleteDeviceInfo(deviceProfileInfoDTO, persisterTxn);
            knLogger.debug(methodName, "Successfully deleted device Profile");
            if (provInfoUtil.isDeleteCorporateProfile(deviceProfileInfoDTO.getCorpId(), persisterTxn)) {
                KnXDMCorpInfoDTO corpAccountReqDTO = new KnXDMCorpInfoDTO();
                corpAccountReqDTO.setAccountId(deviceProfileInfoDTO.getAccountId());
                corpAccountReqDTO.setTransactionId(deviceInfoDTO.getTransactionId());
                // calling the Corp Library.
                KnCorpResponseDTO corpRespDTO = corpMediator.deleteCorporateData(corpAccountReqDTO, persisterTxn);
                // calling the Prov Library
                if (corpRespDTO.getStatus() == 1) {
                    throw new KnXDMServerException(corpRespDTO.getStatusCode(), corpRespDTO.getMessage());
                }
                knLogger.info(methodName, " Successfully deleted the corpaccount groups,sublists, OSM configuration Data for corp :", deviceProfileInfoDTO.getAccountId(), "corpRespDTO" , corpRespDTO);
                KnOPDeleteSubsRespDTO respDTO = provClientIntf.deleteCorpAccount(corpAccountReqDTO, persisterTxn);
                knLogger.info(methodName, "Successfully deleted the corpAccount - ", respDTO);
            }
            sendDeleteDeviceNotification(deviceProfileInfoDTO.getDeviceIMPI());

            boolean lmrInteropFlag = subsProfileInfoDTO != null ? commonInfoUtil.lmrInterFlagValidate(subsProfileInfoDTO.getSubsFS2()) : Boolean.FALSE;
            int lmrInterOpFlagInt = lmrInteropFlag ? ENABLED : DISABLED;
            KnDeviceExdmsNotifyDto deviceExdmsNotifyDto = commonInfoUtil.formDeviceNotifyPayload(DELETE_DEVICE.value(), deviceProfileInfoDTO,
                    lmrInterOpFlagInt, MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value(), deviceProfileInfoDTO.getReqDeviceId());
            knLogger.info(methodName, "Publishing micro service notify for device- ", deviceExdmsNotifyDto);
            commonMediator.startNotifyMicroServicesJob(List.of(deviceExdmsNotifyDto));
            persisterTxn.save();

            commonMediator.getSuccessResponse(responseDTO);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DELETE_DEVICE_PROFILE_REQ_SUCC);
            knLogger.info(methodName, "EXIT: delete device details - ", responseDTO);
            return responseDTO;
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to delete device Profile Info", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

