    @Override
    public IXDMResponseDTO getSubsGroupMembershipDetails(IXDMRequestDTO requestDTO) {
        String methodName = "getSubsGroupMembershipDetails(IXDMRequestDTO)";
        KnXDMGroupMemberShipRespDTO respDto = new KnXDMGroupMemberShipRespDTO();
        KnPersisterTxn persisterTxn = null;
        int successPegId = KnOMConstants.XDM_NUM_GET_CORP_GRP_DETAILS;
        int failurePegId = KnOMConstants.XDM_NUM_GET_CORP_GRP_DETAILS_FAILURE;
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            knLogger.debug(methodName, "opening the transaction");
            persisterTxn.open();
            if (requestDTO.getClientType() == PTX_XDMDATA_INTF) {
                //Step:
                if (!(requestDTO instanceof KnXDMGroupMemberShipRequestDTO)) {
                    knLogger.error(methodName, "xdmRequestDTO not of type KnXDMGroupMemberShipRequestDTO - requestDTO - ",
                            requestDTO.getClass());
                    throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
                }
                KnXDMGroupMemberShipRequestDTO groupMemberShipRequestDTO = (KnXDMGroupMemberShipRequestDTO) requestDTO;
                knLogger.debug(methodName, "ENTRY ", groupMemberShipRequestDTO);
                knLogger.debug(methodName, "retrieving the subscriber profile for mdn ");
                KnIPSubscriberInfoDTO subscriberInfoDTO = new KnIPSubscriberInfoDTO();
                subscriberInfoDTO.setMdn(groupMemberShipRequestDTO.getMdn());
                KnOPSubsProfileInfoDTO subsProfileInfoDTO = provClientIntf.getSubscriberDetails(subscriberInfoDTO, persisterTxn);

             /*   if (subsProfileInfoDTO == null) {
                    knLogger.error(methodName, "Profile MDN not found -  ",
                            groupMemberShipRequestDTO.getMdn());
                    throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DATA, "Invalid Data");
                }
            */
                com.kodiak.xdms.server.corpmgmt.dto.clientdat.KnIPSubscriberInfoDTO ipSubscriberInfoDTO =
                        new com.kodiak.xdms.server.corpmgmt.dto.clientdat.KnIPSubscriberInfoDTO();
                ipSubscriberInfoDTO.setGroupIds(groupMemberShipRequestDTO.getGroupIdList());
                ipSubscriberInfoDTO.setMdn(groupMemberShipRequestDTO.getMdn());
                ipSubscriberInfoDTO.setCorpId(String.valueOf(subsProfileInfoDTO.getCorpId()));
                ipSubscriberInfoDTO.setUserProfileId(subsProfileInfoDTO.getUserProfileId());

                respDto = corpMediator.getSubsGroupMemberShipDetails(ipSubscriberInfoDTO, persisterTxn);
            }
            // KnStatisticsManagerImpl.getInstance().increment(re);
            knLogger.debug(methodName, "Saving the transaction");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(successPegId);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "retrieving group membership Details- ", e);
            KnStatisticsManagerImpl.getInstance().increment(failurePegId);
            respDto = populateResponse(e, respDto, failurePegId);

        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "retrieving group membershipdetails - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            KnStatisticsManagerImpl.getInstance().increment(failurePegId);
            respDto = populateResponse(e, respDto, failurePegId);
        }
        return respDto;
    }


    @Override
    public IXDMResponseDTO createBulkCorpGroup(IXDMRequestDTO requestDTO) {
        String methodName = "createBulkCorpGroup(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
//        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        KnXDMCorpGroupListRespDTO xdmRespDto = new KnXDMCorpGroupListRespDTO();

        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_BULK_GROUPS_GROUP_PROFILE_REQ);

            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            /*// Client Intf Validation:
            commonMediator.clientIntfValidator(xdmRequestDto, persisterTxn);
            // Very large group system level flag validator
            commonMediator.veryLargeGrpFlagValidator(xdmRequestDto, persisterTxn);*/

            // invoke Corp Mediator
            KnCorpGroupInfoRespDTO respDto = corpMediator.createBulkCorpGroup(requestDTO, persisterTxn);
            knLogger.info(methodName,"XDM response from controller for create bulk group :: ",respDto);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto.getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(), xdmRespDto.getResponseMessage());
            }

            List<KnXDMCorpGroupDTO> xdmCorpGroupDTOList = null;
            if(respDto.getGroupInfoDTOList() != null && !respDto.getGroupInfoDTOList().isEmpty()){
            knLogger.info(methodName, "Building XDM response with created group IDs");
                xdmCorpGroupDTOList = new ArrayList<>();
                for(KnCorpGroupInfoDTO corpGroup : respDto.getGroupInfoDTOList()){
                    KnXDMCorpGroupDTO xdmCorpGroupDTO = new KnXDMCorpGroupDTO();
                    xdmCorpGroupDTO.setCorpId(String.valueOf(corpGroup.getCorpId()));
                    xdmCorpGroupDTO.setGroupId(String.valueOf(corpGroup.getGroupId()));
                    xdmCorpGroupDTOList.add(xdmCorpGroupDTO);
                }
            }
            xdmRespDto.setGroupList(xdmCorpGroupDTOList);
            knLogger.info(methodName, "Total groups created and added to response: ", xdmCorpGroupDTOList != null ? xdmCorpGroupDTOList.size() : 0);
            knLogger.info(methodName,"XDM final response passed from mediator for create bulk group :: ",respDto);

            // Step:
            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            //Get the RMQ configurations
            KnMqServiceConfig rmqInfoDto = commonMediator.retrieveServerConfDetails(persisterTxn);
            //Get all mcsxcap uri for sending new grp notification for pv 18 & above
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_BULK_GROUPS_PROFILE_REQ_SUCC);

            if(xcapMobileSync){
                List<KnCorpEXDMSNotifyDto> grpNotifyDtoList = commonMediator.getBulkGrpMicroSrvNotifyDto(respDto, respDto.getMdnCorpId());
                knLogger.debug(methodName, "Publishing micro service notify");
                commonMediator.startNotifyMicroServicesJob(grpNotifyDtoList);
            }
            knLogger.debug(methodName, "sending MCSGrp notification");
            commonMediator.sendMCSGRPNotification(respDto,allMcsXcapUris,respDto.getMdnCorpId());

        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "creating Group - ", e);
            // populate the error info
            xdmRespDto = populateResponse(e, xdmRespDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "creating Group - ", e);
            // populate the error info
            xdmRespDto = populateResponse(e, xdmRespDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "Creating group - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            // populate the error info
            xdmRespDto = populateResponse(e, xdmRespDto);
        }
        return xdmRespDto;
    }

