    @Override
    public IXDMResponseDTO createGroupProfile(IXDMRequestDTO requestDTO) {
        String methodName = "createGroupProfile(IXDMRequestDTO)";
//        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnXDMCorpGroupProfileResponseDTO respDto = new KnXDMCorpGroupProfileResponseDTO();
        KnCorpResponseDTO corpResponseDTO = null;
        KnPersisterTxn persisterTxn = null;
        knLogger.info(methodName, "Entry requestDTO- ", requestDTO);
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_GROUP_PROFILE_REQ);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (requestDTO instanceof KnXDMCorpGroupProfileRequestDTO) {
                KnXDMCorpGroupProfileRequestDTO xdmRequestDTO = (KnXDMCorpGroupProfileRequestDTO) requestDTO;
                //validate corp Hierarchy
                if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()),
                        xdmRequestDTO.getHierarchyType())) {
                    knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                    throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                            "Invalid Corp hierarchy passed");
                }
            }

            corpResponseDTO = corpMediator.createGroupProfile(requestDTO, persisterTxn);
            KnXDMCorpGroupProfileDTO groupProfileDTO = new KnXDMCorpGroupProfileDTO();
            groupProfileDTO.setGrpProfileId(corpResponseDTO.getGrpProfileId());
            List<KnXDMCorpGroupProfileDTO> groupProfile = new ArrayList<>();
            groupProfile.add(groupProfileDTO);
            respDto.setGroupProfile(groupProfile);
            populateXdmResponse(respDto, corpResponseDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(), respDto.getResponseMessage());
            }
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_GROUP_PROFILE_REQ_SUCC);
            knLogger.info(methodName, "Returning createGroupProfile response - ", respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while createGroupProfile", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while createGroupProfile",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

