    @Override
    public IXDMResponseDTO createCorpGroupWithProfile(KnMessage message) {
        String methodName = "createCorpGroupWithProfile(IXDMRequestDTO)";
        IXDMResponseDTO xdmRespDto = null;
        // try {
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;

        if (payLoad instanceof IXDMRequestDTO) {
            requestDTO = (IXDMRequestDTO) payLoad;
        }
        KnXDMCorpGroupInfoRequestDTO xdmRequestDto = (KnXDMCorpGroupInfoRequestDTO) requestDTO;
        knLogger.debug(methodName, "xdmRequestDto :: ", xdmRequestDto);

        KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_GROUP_WITH_MEM_GROUP_PROFILE_REQ);
        //Get the group profile details
        KnXDMCorpGroupProfileRequestDTO profileReq = new KnXDMCorpGroupProfileRequestDTO();
        profileReq.setHierarchyType(xdmRequestDto.getHierarchyType());
        profileReq.setCustomParamMap(xdmRequestDto.getCustomParamMap());
        profileReq.setCorpId(xdmRequestDto.getCorpId());
        profileReq.setGrpProfileId(xdmRequestDto.getGrpProfileId());
        profileReq.setGrpProfileName(xdmRequestDto.getGrpProfileName());
        KnXDMCorpGroupProfileResponseDTO xdmGrpProfileResp  = (KnXDMCorpGroupProfileResponseDTO)getGroupProfileDetails(profileReq);
        knLogger.debug(methodName, "xdmGrpProfileResp :: ", xdmGrpProfileResp);
        //If the get group profile success, create corp group with the profile details.
        if (KnConstants.RESPONSE_STATUS.FAILURE.value() != xdmGrpProfileResp.getResponseStatus()){
            KnXDMCorpGroupProfileDTO grpProfileDetail = xdmGrpProfileResp.getGroupProfile().get(0);
            knLogger.debug(methodName, "grpProfileDetail :: ", grpProfileDetail);
            xdmRequestDto.setGroupType(grpProfileDetail.getGrpType());
            xdmRequestDto.setAvatar(grpProfileDetail.getGrpAvatar());
            xdmRequestDto.setMcxGrpInd(grpProfileDetail.getMcxGroup());
            xdmRequestDto.setOSMListId(grpProfileDetail.getGrpOSMListId());
            if(grpProfileDetail.getOverrideDND() != null){
                xdmRequestDto.setOverrideDND(grpProfileDetail.getOverrideDND());
            }
            xdmRequestDto.setFeatureAllowed(grpProfileDetail.getFeatureAllowed());
            xdmRequestDto.setAudioCutIn(grpProfileDetail.getAudioCutIn());
            xdmRequestDto.setGrpServiceType(grpProfileDetail.getGrpServiceType());
            // Use request-level sharing if provided; otherwise inherit from profile
            if (xdmRequestDto.getGrpShared() == null) {
                xdmRequestDto.setGrpShared(grpProfileDetail.getGrpShared());
            }
            if (xdmRequestDto.getGrpSharedCopList() == null || xdmRequestDto.getGrpSharedCopList().isEmpty()) {
                xdmRequestDto.setGrpSharedCopList(grpProfileDetail.getSharedCorpList());
            }
            xdmRequestDto.setUgwInterop(grpProfileDetail.getUgwInterop());
            if (null == xdmRequestDto.getAuthorizedLargeTG()) {
                xdmRequestDto.setAuthorizedLargeTG(com.kodiak.common.resources.KnConstants.AUTHORIZED_LARGE_TG_DEFAULT_VALUE);
            }
            knLogger.info(methodName, "Initiating create group API call");
            message.setPayLoad(xdmRequestDto);
            xdmRespDto = this.createCorpGroup(message, Boolean.TRUE);
        }else {
            knLogger.info(methodName, "get profile failed");
            xdmRespDto = new KnXDMCorpGroupInfoRespDTO();
            xdmRespDto.setResponseStatus(xdmGrpProfileResp.getResponseStatus());
            xdmRespDto.setResponseCode(xdmGrpProfileResp.getResponseCode());
            xdmRespDto.setResponseMessage(xdmGrpProfileResp.getResponseMessage());
        }
        knLogger.debug(methodName, "xdmRespDto -", xdmRespDto);
        if(KnConstants.RESPONSE_STATUS.SUCCESS.value() == xdmRespDto.getResponseStatus()){
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_CREATE_GROUP_WITH_MEM_GROUP_PROFILE_REQ_SUCC);
        }
        return xdmRespDto;
    }

    @Override
    public IXDMResponseDTO modifyGroupProfile(KnMessage message) {
        String methodName = "modifyGroupProfile(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_MODIFY_REQ_RCVD);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_MODIFY_GROUP_PROFILE_REQ);
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (!(requestDTO instanceof KnXDMCorpGroupProfileRequestDTO)) {
                knLogger.error(methodName, "Request dto is not of type KnXDMCorpGroupProfileRequestDTO - requestDTO - ",
                        requestDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnXDMCorpGroupProfileRequestDTO xdmRequestDTO = (KnXDMCorpGroupProfileRequestDTO) requestDTO;
            //validate corp Hierarchy
            if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())) {
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            knLogger.debug(methodName, "--->requestDTO - ", requestDTO);
            KnCorpResponseDTO corpLibRespDto = corpMediator.modifyGroupProfile(xdmRequestDTO, persisterTxn);
            knLogger.debug(methodName, "--->corpLibRespDto - ", corpLibRespDto);
            populateXdmResponse(respDto, corpLibRespDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),respDto.getResponseMessage());
            }
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);

            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            // Step:
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_MODIFY_GROUP_PROFILE_REQ_SUCC);

            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpLibRespDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.info(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName, "sending MCSGrp notification");
            commonMediator.sendMCSGRPNotification(corpLibRespDto,allMcsXcapUris, Integer.parseInt(xdmRequestDTO.getCorpId()));
            boolean status = commonMediator.prepareMcxNotifyForProfileMdns(corpLibRespDto);
            knLogger.debug(methodName, "MCX Notification status - ", status);

            if (xcapMobileSync) {
                commonMediator.startNotifyMicroServicesJobModifyGroup(corpLibRespDto.getChangeLogMap(), corpLibRespDto.getMdnCorpId(),
                        corpLibRespDto.getGroupCreatedBy(), corpLibRespDto.getLmrIntropCapable(),
                        corpLibRespDto.getMcxGrpInd(), corpLibRespDto.getGroupSharedMap(), corpLibRespDto.getGrpSIPUri(),
                        corpLibRespDto.getOldLmrInteropFlag(), corpLibRespDto.getRecordingFs());
            }
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occurred", e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occurred",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

    @Override
    public IXDMResponseDTO deleteBulkCorpGroup(KnMessage message) {
        String methodName = "deleteBulkCorpGroup(IXDMRequestDTO)";
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO requestDTO = null;
        try {
            //KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.TOTAL_NUM_CORP_DELETE_REQ_RCVD);
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DELETE_BULK_GROUPS_PROFILE_REQ);
            if (payLoad instanceof IXDMRequestDTO) {
                requestDTO = (IXDMRequestDTO) payLoad;
            }
            if (!(requestDTO instanceof KnXDMDeleteBulkGroupReqDTO)) {
                knLogger.error(methodName, "Request dto is not of type KnXDMCorpGroupProfileRequestDTO - requestDTO - ",
                        requestDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnXDMDeleteBulkGroupReqDTO xdmRequestDTO = (KnXDMDeleteBulkGroupReqDTO) requestDTO;
            //validate corp Hierarchy
            if (!KnGeneralProfileUtil.validateIntCorpCCAndHierarchy(Integer.parseInt(xdmRequestDTO.getCorpId()), xdmRequestDTO.getHierarchyType())) {
                knLogger.error(methodName, "Hierarchy flag not valid for the corp : ", xdmRequestDTO.getHierarchyType());
                throw new KnXDMServerException(com.kodiak.xdms.server.common.resources.KnErrorCodes.BOEntity.INVALID_HIERARCHY_REQUEST,
                        "Invalid Corp hierarchy passed");
            }
            // Step:
            // get the Transaction object ready
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            // Step:
            // invoke Corp Mediator
            knLogger.debug(methodName, "--->requestDTO - ", requestDTO);
            KnCorpResponseDTO corpLibRespDto = corpMediator.deleteBulkCorpGroup(xdmRequestDTO, persisterTxn);
            knLogger.debug(methodName, "--->corpLibRespDto - ", corpLibRespDto);
            populateXdmResponse(respDto, corpLibRespDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),respDto.getResponseMessage());
            }
            Set<String> allMcsXcapUris =  genInfoUtil.getMCSXCAPRootURIs(persisterTxn);

            //Get the XCAP Mobile sync flag from microservice config table.
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);

            // Step:
            // save the transaction
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_DELETE_BULK_GROUPS_PROFILE_REQ_SUCC);

            //place async jobs for clean up of user profile if any.
            Collection<Integer> groupIdList = corpLibRespDto.getGroupIds();
            Map<Integer, List<Integer>> grpSharedCorpListMap = corpLibRespDto.getGroupIdSharedCorpListMap();
            if(groupIdList!=null && !groupIdList.isEmpty()) {
                for(Integer grpId:groupIdList) {
                    Long transactionId = System.nanoTime();
                    knLogger.debug(methodName, "transactionId - ", transactionId);
                    List<Integer> corpIds = grpSharedCorpListMap.get(grpId);
                    String corpIdsInString = commonMediator.getCommaSeparated(corpIds);
                    KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(String.valueOf(xdmRequestDTO.getCorpId()), transactionId.toString()
                            , corpIdsInString, UPM_OPERATION_TYPE.DELETE_GROUP_FROM_PROFILE.Value(), String.valueOf(grpId),
                            UPM_RESOURCE_TYPE.GROUP.Value(), null, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                    upmJobScheduler.addJob(knAsyncJobDTO);
                }
            }

            // prepare notification and send to notification mgr
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(corpLibRespDto);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.info(methodName, "Notification status - ", isNotified);
            knLogger.debug(methodName, "sending MCSGrp notification");
            commonMediator.sendMCSGRPNotification(corpLibRespDto,allMcsXcapUris, Integer.parseInt(xdmRequestDTO.getCorpId()));
            boolean status = commonMediator.prepareMcxNotifyForProfileMdns(corpLibRespDto);
            knLogger.debug(methodName, "MCX Notification status - ", status);

            List<KnCorpEXDMSNotifyDto> notifyDtoList = new ArrayList<>();
            if (xcapMobileSync) {
                if (groupIdList != null && !groupIdList.isEmpty()) {
                    for (Integer grpId : groupIdList) {
                        KnCorpEXDMSNotifyDto notifyDto = new KnCorpEXDMSNotifyDto();
                        notifyDto.setType(DELETE_CORP_GROUP.value());
                        notifyDto.setId(DELETE_CORP_GROUP.value() + "_" + grpId);
                        notifyDto.setNotifyEventType(MICROSERVICES_NOTIFY_EVENT_TYPE.GROUP_NOTIFY_EVENTS.value());
                        notifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                        notifyDto.setGrpId(grpId);
                        notifyDto.setCorpid(corpLibRespDto.getMdnCorpId());
                        notifyDto.setCreatedBy(corpLibRespDto.getGroupCreatedBy());
                        notifyDto.setPocHome(corpLibRespDto.getPocHome());
                        notifyDtoList.add(notifyDto);
                    }
                }
                knLogger.info(methodName, "poc home value : ", corpLibRespDto.getPocHome());
                List<KnCorpEXDMSNotifyDto> contactNotifyDtoList =
                        commonMediator.getContactMicroSrvNotifyDto(corpLibRespDto.getChangeLogMap(), corpLibRespDto.getMdnCorpId());
                notifyDtoList.addAll(contactNotifyDtoList);

                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(notifyDtoList);

                // commonMediator.startNotifyMicroServicesJob(corpLibRespDto.getChangeLogMap(), corpLibRespDto.getMdnCorpId(), rmqInfoDto,
                //       corpLibRespDto.getGroupCreatedBy(), corpLibRespDto.getLmrIntropCapable(), corpLibRespDto.getMcxGrpInd());

            }


        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occurred", e);
            respDto = populateResponse(e, respDto);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occurred",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }
        return respDto;
    }

