    @Override
    public IXDMResponseDTO getAuthorizedUserList(IXDMRequestDTO requestDTO) {
        final String methodName="getAuthorizedUserList()";
        KnXDMAuthUserListResponseDTO responseDTO = new KnXDMAuthUserListResponseDTO();
        KnPersisterTxn persisterTxn = null;
        KnXDMGetAuthorizedUserListDTO getAuthorizedUserListDTO=new KnXDMGetAuthorizedUserListDTO();
        try {
            //KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_SELECTED_PROFILE_MDN_REQ);
            if (requestDTO instanceof KnXDMGetAuthorizedUserListDTO) {
                getAuthorizedUserListDTO = (KnXDMGetAuthorizedUserListDTO) requestDTO;
                knLogger.debug(methodName, "Received input DTO to getAUList - ", getAuthorizedUserListDTO);
            } else {
                knLogger.error(methodName, "received and Invalid DTO for getAUList op - ", requestDTO);
                responseDTO.setResponseMessage("Invalid DTO is passed");
                responseDTO.setResponseCode(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED);
                responseDTO.setResponseStatus(KnConstants.RESPONSE_STATUS.FAILURE.value());
                return responseDTO;
            }

            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();

            KnIPMCPTTPermissionDTO tuInfo=new KnIPMCPTTPermissionDTO();
            tuInfo.setMdn(getAuthorizedUserListDTO.getMdn());
            tuInfo.setTargetUser(getAuthorizedUserListDTO.getTargetUser());
            tuInfo.setMcptt_id(getAuthorizedUserListDTO.getMcptt_id());
            knLogger.debug(methodName, "The Mcptt_id is",KnGDPRTemplate.mcpttId(getAuthorizedUserListDTO.getMcptt_id()));
            KnOPMCPTTPermissionDTO onlineAUSubscriberList = provClientIntf.getAuthorizedUserList(tuInfo, persisterTxn);
            responseDTO.setAutorizationMdnList(onlineAUSubscriberList.getAutorizedMdnList());
            persisterTxn.save();
            //KnStatisticsManagerImpl.getInstance().increment( KnOMConstants.XDM_NUM_SELECTED_PROFILE_MDN_SUCCESS);
            knLogger.info(methodName, "EXIT: ", responseDTO);
            return commonMediator.getSuccessResponse(responseDTO);
        } catch (KnAuthenticationException e) {
            knLogger.error(methodName, "Autherization failed", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnAASException e) {
            knLogger.error(methodName, "Autherization failed", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnPersistenceException e) {
            knLogger.error(methodName, "Failed to get the Transaction", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (KnXDMServerException e) {
            knLogger.error(methodName, "Failed to login ", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Un-Expected Exception occurred - ", e);
            rollback(persisterTxn);
            return commonMediator.getFailureResponse(responseDTO, e);
        }
    }

