    public IXDMResponseDTO modifyGroupsUGWConfig(KnMessage message) {
        String methodName = "modifyGroupsUGWConfig(IXDMRequestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpRespDTO xdmRespDto = new KnXDMCorpRespDTO();
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        int successPegId = KnOMConstants.XDM_NUM_MODIFY_GROUP_UGWCONFIG_REQ_SUCC;
        int failurePegId = KnOMConstants.XDM_NUM_MODIFY_GROUP_UGWCONFIG_REQ_FAILURE;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO groupInfoDTO = null;
        try {
            if (payLoad instanceof IXDMRequestDTO) {
                groupInfoDTO = (IXDMRequestDTO) payLoad;
            }
            KnXDMCorpGroupInfoRequestDTO xdmRequestDto = (KnXDMCorpGroupInfoRequestDTO) groupInfoDTO;
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            //opening transaction
            persisterTxn.open();
            knLogger.debug(methodName, "Received from the input DTO - ", xdmRequestDto);
            //call to corp mediator
            respDto = corpMediator.modifyGroupsUGWConfig(groupInfoDTO, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            //Get all mcs xcap ur's
            Set<String> allMcsXcapUris = genInfoUtil.getMCSXCAPRootURIs(persisterTxn);
            //saving transaction
            persisterTxn.save();
            //preparing xcap notify
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            //sending or adding xcap notify to job
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, persisterTxn, notificationParamDTO);
            knLogger.debug(methodName," isNotified :",isNotified);
            //preparing mcsxcap group notify
            commonMediator.sendMCSGRPNotification(respDto,allMcsXcapUris,respDto.getMdnCorpId() );
            //sending or adding mcsxcap group notify to job
            boolean status = commonMediator.prepareMcxNotifyForProfileMdns(respDto);
            knLogger.debug(methodName," status :",status);
            KnStatisticsManagerImpl.getInstance().increment(successPegId);
        } catch (KnPersistenceException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occured while ", "modifying Group - ", e);
            KnStatisticsManagerImpl.getInstance().increment(failurePegId);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            // populate the error info
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "modifying Group - ", e);
            KnStatisticsManagerImpl.getInstance().increment(failurePegId);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
            // populate the error info
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "Modifying Group - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            KnStatisticsManagerImpl.getInstance().increment(failurePegId);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
        }
        knLogger.debug(methodName," xdmRespDto:",xdmRespDto);
        return xdmRespDto;
    }

    /**
     * method for the getGroupsUGWConfig
     *
     * @param groupInfoDTO IXDMRequestDTO
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO getGroupsUGWConfig(IXDMRequestDTO groupInfoDTO) {
        String methodName = "getCorpGroupDetails(IXDMRequestDTO)";
        KnXDMCorpGroupUgwConfigInfoRespDTO xdmRespDto = new KnXDMCorpGroupUgwConfigInfoRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_GROUP_UGWCONFIG_REQ);
            if (!(groupInfoDTO instanceof KnXDMCorpGroupInfoRequestDTO)) {
                knLogger.error(methodName, "groupDTO not of type KnXDMCorpGroupInfoRequestDTO - requestDTO - ",
                        groupInfoDTO.getClass());
                throw new KnXDMServerException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid DTO");
            }
            KnXDMCorpGroupInfoRequestDTO xdmRequestDto = (KnXDMCorpGroupInfoRequestDTO) groupInfoDTO;
            KnIPCorpGroupInfoDTO groupDTO = new KnIPCorpGroupInfoDTO();
            if (!isNullOrEmpty(xdmRequestDto.getCorpId())) {
                groupDTO.setCorpId(Integer.valueOf(xdmRequestDto.getCorpId()));
            }
            groupDTO.setGroupId(Integer.valueOf(xdmRequestDto.getGroupId()));

            knLogger.debug(methodName, "Get Corp Group UGWConfig request - ", groupDTO);
            KnCorpGroupInfoRespDTO corpGroupInfoRespDTO = corpClientIntf.getCorpGrpLmrExtn(groupDTO, persisterTxn);
            knLogger.debug(methodName, "Get Corp Group UGWConfig response - ", corpGroupInfoRespDTO);
            persisterTxn.save();
            populateXdmResponse(xdmRespDto, corpGroupInfoRespDTO);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == corpGroupInfoRespDTO.getStatus()) {
                knLogger.error(methodName, "Returning Failure response");
                return xdmRespDto;
            }
            KnCorpGrpLmrExtnDTO corpGrpLmrExtnDTO = corpGroupInfoRespDTO.getGrpLmrExtnDTO();
            xdmRespDto.setCorpId(String.valueOf(xdmRequestDto.getCorpId()));
            xdmRespDto.setGroupId(String.valueOf(xdmRequestDto.getGroupId()));
            xdmRespDto.setUgwConfig(new String(corpGrpLmrExtnDTO.getLmrExtn()));
            KnStatisticsManagerImpl.getInstance().increment(KnOMConstants.XDM_NUM_GET_GROUP_UGWCONFIG_REQ_SUCC);
            knLogger.debug(methodName, "Returning get corp Group Details response - ", xdmRespDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "retrieving Group Details- ", e);
            xdmRespDto = populateResponse(e, xdmRespDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "retrieving group details - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            xdmRespDto = populateResponse(e, xdmRespDto);
        }
        return xdmRespDto;
    }
    /**
     * method for the assignCommonContactList
     *
     * @param message KnMessage
     * @return IXDMResponseDTO Object
     */
    @Override
    public IXDMResponseDTO assignCommonContactList(KnMessage message) {
        String methodName = "assignCommonContactList(IXDMRequestDTO)";
        KnXDMCorpContactListRespDTO xdmRespDto = new KnXDMCorpContactListRespDTO();
        KnPersisterTxn persisterTxn = null;
        Object payLoad = message.getPayLoad();
        IXDMRequestDTO sublistReqDto = null;
        int successPegId = KnOMConstants.XDM_NUM_CORP_ASSIGN_COMMONCONTACTLIST_REQ_SUCCESS; //Need to implement KnOMConstants.XDM_NUM_GET_CORP_GRP_DETAILS;
        int failurePegId = KnOMConstants.XDM_NUM_CORP_ASSIGN_COMMONCONTACTLIST_REQ_FAILURE;// Need to implemenet  KnOMConstants.XDM_NUM_GET_CORP_GRP_DETAILS_FAILURE;
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            if (payLoad instanceof IXDMRequestDTO) {
                sublistReqDto = (IXDMRequestDTO) payLoad;
            }
            // invoke Corp Mediator
            KnCorpResponseDTO respDto = corpMediator.assignCommonContactList(sublistReqDto, persisterTxn);
            populateXdmResponse(xdmRespDto, respDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmRespDto
                    .getResponseStatus()) {
                knLogger.debug(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmRespDto.getResponseCode(),
                        xdmRespDto.getResponseMessage());
            }

            knLogger.debug(methodName, "assigned common-contact-list to subsrs response - ", respDto);
            //Get the xcap mobile sync flag
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(successPegId);
            //micro service events to all mdns(profile+base)
            if (xcapMobileSync) {
                knLogger.debug(methodName, "Publishing micro service notify - ");
                commonMediator.startNotifyMicroServicesJob(respDto.getChangeLogMap(), respDto.getMdnCorpId());
            }
            //notification xcap notification to all online mdns
            Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
            knLogger.debug(methodName, "Sending notifications - ", xcapDiffList);
            KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
            notificationParamDTO.setCid(message.getCorrelationId());
            boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
            knLogger.debug(methodName, "Notification status - ", isNotified);
            //profile mdn notfication
            boolean profileNotifyStatus = commonMediator.prepareMcxNotifyForProfileMdns(respDto);
            knLogger.debug(methodName, "sending Profile notification Status: ", profileNotifyStatus);
            knLogger.debug(methodName, "Returning assigned common-contact-list to subsrs  response - ", xdmRespDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occured while ", "assigned common-contact-list Details- ", e);
            KnStatisticsManagerImpl.getInstance().increment(failurePegId);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occured while ", "assigned common-contact-list - ",
                    new KnException(ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            KnStatisticsManagerImpl.getInstance().increment(failurePegId);
            xdmRespDto = populateResponse(e, xdmRespDto, failurePegId);
        }
        return xdmRespDto;
    }

