    public boolean sendGroupWatcherNotificationForAddGroup(KnAsyncJobDTO knAsyncJobDTO) throws KnXDMServerException, KnPersistenceException {
        String methodName = "sendGroupWatcherNotificationForAddGroup(IXDMRequestDTO)";
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        try {
            Set<String> txnIdsSet = new HashSet<>();
            txnIdsSet.add(knAsyncJobDTO.getTxnId());
            int opStatus = knAsyncJobDTO.getOpStatus();
            int corpId = knAsyncJobDTO.getCorpId();
            String userProfileId = knAsyncJobDTO.getUserProfileId();
            if (opStatus == 10) {
                KnIPUserProfileDTO ipUserProfilePermDTO = jsonToObject(knAsyncJobDTO.getPayLoad(), KnIPUserProfileDTO.class);
                String addedMem = ipUserProfilePermDTO.getAddedMember();
                Set<Integer> addedGroupIds = ipUserProfilePermDTO.getAddedGroupIds();
                for (int groupId : addedGroupIds) {
                    Set<Integer> addedGroupIdList = new HashSet<>();
                    addedGroupIdList.add(groupId);
                    KnIPUserProfileDTO ipUserProfileDTO = new KnIPUserProfileDTO();
                    ipUserProfileDTO.setAddedMember(addedMem);
                    ipUserProfileDTO.setAddedGroupIds(addedGroupIdList);
                    String assignUpmJsonString = KnCorpCommonInfoUtil.ObjToJson(ipUserProfileDTO);
                    KnAsyncJobDTO knAsyncJobWatcherDTO = commonMediator.createJobNotifyDTO(String.valueOf(corpId), null
                            , userProfileId, 0, null,
                            0, assignUpmJsonString, opStatus,
                            null);
                    respDto = corpMediator.groupWatcherNotifyForAddGroup(knAsyncJobWatcherDTO);
                    knLogger.info(methodName, "response recived - ", respDto);
                    // prepare notification and send to notification mgr
                    Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
                    String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
                    xcapDiffList = commonMediator.fetchXcapDiffList(xcapDiffList, xdmPttServerId, null);
                    KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                    notificationParamDTO.setCid(null);
                    boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                    knLogger.info(methodName, "Notification status - ", isNotified);
                }
            } else if (opStatus == 13) {
                String payload = knAsyncJobDTO.getPayLoad();
                KnIPUserProfileDTO ipUserProfilePermDTO = jsonToObject(payload, KnIPUserProfileDTO.class);
                String addedMem = ipUserProfilePermDTO.getAddedMember();
                // Extract the value of "addedGroupList"
                Set<KnCorpGroupListInfoDTO> addedGroupList = ipUserProfilePermDTO.getAddedGroupList();
                for (KnCorpGroupListInfoDTO groupInfo : addedGroupList) {
                    KnIPUserProfileDTO ipUserProfilesDTO = new KnIPUserProfileDTO();
                    Set<KnCorpGroupListInfoDTO> addUpmGroupIds = new HashSet<>();
                    addUpmGroupIds.add(groupInfo);
                    ipUserProfilesDTO.setAddedGroupList(addUpmGroupIds);
                    ipUserProfilesDTO.setAddedMember(addedMem);
                    String assignUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfilesDTO);
                    KnAsyncJobDTO knAsyncJobWatcherDTO = commonMediator.createJobNotifyDTO(String.valueOf(corpId), null
                            , userProfileId, 0, null,
                            0, assignUpmJsonString, opStatus,
                            null);

                    respDto = corpMediator.groupWatcherNotifyForAddGroup(knAsyncJobWatcherDTO);
                    knLogger.info(methodName, "response recived - ", respDto);
                    // prepare notification and send to notification mgr
                    Collection<KnXcapDiffDirChgNotifyDTO> xcapDiffList = commonMediator.prepareNotification(respDto);
                    String xdmPttServerId = genInfoUtil.retrieveLocalXDMPttServerId();
                    xcapDiffList = commonMediator.fetchXcapDiffList(xcapDiffList, xdmPttServerId, null);
                    KnNotificationParamDTO notificationParamDTO = new KnNotificationParamDTO();
                    notificationParamDTO.setCid(null);
                    boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, null, notificationParamDTO);
                    knLogger.info(methodName, "Notification status - ", isNotified);
                }
            }
            //once notification sent , updating the status in GG cache for currect transaction.
            int count = generalCacheUtil.updateWatcherState(txnIdsSet, 2);

            knLogger.info(methodName, "Exit----->");
            return true;
        } catch (Exception e) {
            try {
                generalCacheUtil.updateAsyncJobStatus(knAsyncJobDTO.getTxnId(), UPM_JOB_STATUS.FAILURE.Value());
            } catch (KnDAOException ex) {
                knLogger.error(methodName, "KnDAOException occured in job for txnId-", knAsyncJobDTO.getTxnId(), " error msg:", e.getMessage());
            }
            knLogger.error(methodName, "UnexpectedException occured while ", "SendNotification - ", new KnException(
                    ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            throw new KnXDMServerException(ERROR_CODE_INTERNAL_ERROR, "Unexpected exception occurred in SendNotification", e);
        }
    }

