    public void processLocationEnabledCorporateJob(List<String> baseAndProfileMdnsInBatch) throws KnPersistenceException {
        String methodName = "processLocationEnabledJob";
        KnPersisterTxn persisterTxn = null;
        KnSubsProvController provController = new KnSubsProvController();
        try {
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            for (String mdn : baseAndProfileMdnsInBatch) {
                KnLocationEnabledCorporateSubscriberDetails subsDetails = provController.getLocationEnabledCorporateSubscriberDetails(mdn, persisterTxn);
                String newactiveFS2 = provController.processLocationEnabledCorporateJob(subsDetails);
                knLogger.debug(methodName, "Success from Controller", newactiveFS2);
                List<KnSubscrEXDMSNotifyDto> notifyDtoList = new ArrayList<KnSubscrEXDMSNotifyDto>();
                if (null != newactiveFS2 && !newactiveFS2.isEmpty()) {
                    boolean xcapCouchClientBit = KnGeneralUtil.getFeatureBitValue(subsDetails.getActiveFS2(), com.kodiak.common.resources.KnConstants.FEATURE_SET.XCAPCOUCHCLIENT.value());
                    if (xcapMobileSync && (xcapCouchClientBit || subsDetails.getProtocolVersion() >= PROTOCOL_VERSION_18)) {
                        KnSubscrEXDMSNotifyDto subscrEXDMSNotifyDto = new KnSubscrEXDMSNotifyDto();
                        subscrEXDMSNotifyDto.setMdn(mdn);
                        subscrEXDMSNotifyDto.setCorpid(subsDetails.getCorpId());
                        subscrEXDMSNotifyDto.setActiveFS(KnGeneralUtil.convertHexStringToLong(newactiveFS2));
                        subscrEXDMSNotifyDto.setActiveFS2(newactiveFS2);
                        subscrEXDMSNotifyDto.setOldActiveFS(subsDetails.getActiveFS2());
                        subscrEXDMSNotifyDto.setPv(String.valueOf(subsDetails.getProtocolVersion()));
                        subscrEXDMSNotifyDto.setId(FEATURE_BIT_CHANGE.value() + KnConstants.LINE_SAPERATOR + mdn);
                        subscrEXDMSNotifyDto.setType(FEATURE_BIT_CHANGE.value());
                        subscrEXDMSNotifyDto.setVer(MICROSERVICE_NOTIFY_DOC_VER);
                        subscrEXDMSNotifyDto.setNotifyEventType(com.kodiak.common.resources.KnConstants.MICROSERVICES_NOTIFY_EVENT_TYPE.USER_NOTIFY_EVENTS.value());
                        subscrEXDMSNotifyDto.setLastProfileUpdateTime(subsDetails.getLastUpdateTime());
                        notifyDtoList.add(subscrEXDMSNotifyDto);
                    }
                    commonMediator.startNotifyMicroServicesJob(notifyDtoList);
                    knLogger.debug(methodName, "Notify gone");
                }
                Thread.sleep(1000);
            }
            persisterTxn.save();
        } catch (Exception e) {
            persisterTxn.rollback();
            knLogger.debug("Exception happened for processLocationEnabledJob", e);
        }
    }

