    @Override
    public IXDMResponseDTO unAllocateSubs(IXDMRequestDTO requestDTO) {
        String methodName = "unAllocateSubs(requestDTO)";
        KnPersisterTxn persisterTxn = null;
        KnXDMCorpRespDTO respDto = new KnXDMCorpRespDTO();
        try {
            KnXDMUnAllocateSubscriberRequestDto xdmRequestDTO = (KnXDMUnAllocateSubscriberRequestDto) requestDTO;
            knLogger.debug(methodName, "unAllocateSubs: ", xdmRequestDTO);
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.TOTAL_NUM_UNALLOCATE_REQ_RCVD);
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();

            KnCorpResponseDTO libRespDto = corpMediator.unAllocateSubs(requestDTO, persisterTxn);
            populateXdmResponse(respDto, libRespDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == respDto.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(respDto.getResponseCode(),
                        respDto.getResponseMessage());
            }
            // Step:2
            // save the transaction
            knLogger.debug(methodName, "Saving transaction");
            persisterTxn.save();
            KnStatisticsManagerImpl.getInstance().increment(
                    KnOMConstants.TOTAL_NUM_UNALLOCATE_REQ_SUCCESS);

            // Schedule async UPM cleanup job for linked user profile MDNs
            List<String> userProfileMdns = libRespDto.getUserProfileMdns();
            if (userProfileMdns != null && !userProfileMdns.isEmpty()) {
                KnIPUserProfileDTO ipUserProfileDTO = new KnIPUserProfileDTO();
                ipUserProfileDTO.setCorpId(xdmRequestDTO.getCorpId());
                ipUserProfileDTO.setUserProfileMdns(userProfileMdns);

                String deleteUpmJsonString = commonInfoUtil.ObjToJson(ipUserProfileDTO);
                Long transactionId = System.currentTimeMillis();
                knLogger.debug(methodName, "Scheduling DELETE_USER_PROFILE_MDN job - transactionId: ", transactionId,
                        ", userProfileMdns: ", KnGDPRTemplate.mdnList(userProfileMdns));
                KnAsyncJobDTO knAsyncJobDTO = commonMediator.createJobNotifyDTO(xdmRequestDTO.getCorpId(), transactionId.toString()
                        , null, UPM_OPERATION_TYPE.DELETE_USER_PROFILE_MDN.Value(), null,
                        UPM_RESOURCE_TYPE.MDN.Value(), deleteUpmJsonString, KnConstants.UPM_JOB_STATUS.NEW.Value(), null);
                upmJobScheduler.addJob(knAsyncJobDTO);
            }

            // Send deRegister self-notification ONLY for each unallocated MDN
            // Note: Not sending notifications to affected users (contacts/groups) as per requirement
            KnNotificationParamDTO knNotificationParamDTO = new KnNotificationParamDTO();
            knNotificationParamDTO.setPriority(NOTIFICATION_PRIORITY.HIGH.value());
            List<KnXcapDiffNotifyDTO> xcapDiffList = new ArrayList<>();
            List<KnOPDirChgDTO> dirChgDTOs = libRespDto.getDirChgDTOs();
            if (dirChgDTOs != null && !dirChgDTOs.isEmpty()) {
                for (KnOPDirChgDTO dirChgDTO : dirChgDTOs) {
                    if (dirChgDTO.getClientType() != null
                            && dirChgDTO.getClientType() != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Alias_MDN.value()
                            && dirChgDTO.getClientType() != KnProvConstants.SUBS_CLIENT_TYPE.POC_NNI_Group_MDN.value()
                            && dirChgDTO.getClientType() != KnProvConstants.SUBS_CLIENT_TYPE.DATAGROUPMDN.value()) {
                        KnXcapDiffNotifyDTO xcapDiffNotifyDTO = new KnXcapDiffNotifyDTO();
                        xcapDiffNotifyDTO.setDeRegisterNotify(true);
                        KnDeRegisterNotifyDTO deRegisterNotifyDTO = new KnDeRegisterNotifyDTO();
                        deRegisterNotifyDTO.setMdn(dirChgDTO.getMdn());
                        deRegisterNotifyDTO.setPocHome(dirChgDTO.getPocHome());
                        deRegisterNotifyDTO.setPresenceHome(dirChgDTO.getPresenceHome());
                        deRegisterNotifyDTO.setAction(KnConstants.MESSAGE_TYPE.USER_DELETE.value());
                        xcapDiffNotifyDTO.setDeRegisterNotifyDTO(deRegisterNotifyDTO);
                        xcapDiffNotifyDTO.setReason(KnConstants.REASON.USER_DELETE.value());

                        // Build DocDiffObj from dirChgDTO's DocChgDTO list (same as changeServiceAuthStatus)
                        Collection<KnXcapDiffDocDTO> xcapDocList = new ArrayList<>();
                        Collection<KnOPDocChgDTO> chgDocList = dirChgDTO.getDocChgDTO();
                        if (chgDocList != null && !chgDocList.isEmpty()) {
                            for (KnOPDocChgDTO chgDTO : chgDocList) {
                                KnXcapDiffDocDTO xcapDiffDocDTO = new KnXcapDiffDocDTO();
                                xcapDiffDocDTO.setDocChangeType(chgDTO.getDocumentChgType());
                                xcapDiffDocDTO.setDocEtag(chgDTO.getNewEtag());
                                xcapDiffDocDTO.setDocumentSelector(chgDTO.getDocUri());
                                xcapDocList.add(xcapDiffDocDTO);
                            }
                        }

                        xcapDiffNotifyDTO.setDocDiffObj(xcapDocList);
                        xcapDiffNotifyDTO.setDirNewEtag(dirChgDTO.getDirNewEtag());
                        xcapDiffNotifyDTO.setDirPrevEtag(dirChgDTO.getDirPrevEtag());
                        xcapDiffNotifyDTO.setDirURI(dirChgDTO.getDirUri());
                        xcapDiffNotifyDTO.setXcapRootUri(dirChgDTO.getXcapRootURI());
                        xcapDiffNotifyDTO.setProtocolVersion(dirChgDTO.getProtoVersion());
                        xcapDiffNotifyDTO.setPocHome(dirChgDTO.getPocHome());
                        xcapDiffNotifyDTO.setPresenceHome(dirChgDTO.getPresenceHome());
                        xcapDiffList.add(xcapDiffNotifyDTO);
                    }
                }
                knLogger.debug(methodName, "Sending deRegister notifications - ", xcapDiffList, ":::", knNotificationParamDTO);
                boolean isNotified = notifier.sendXcapDiffNotifications(xcapDiffList, knNotificationParamDTO);
                knLogger.debug(methodName, "DeRegister Notification status - ", isNotified);
            }

        } catch (KnValidationException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnValidationException occurred while unAllocateSubs", e);
            respDto = populateResponse(e, respDto);
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnPersistenceException occurred while ",
                    "unAllocateSubs - ", e);
            respDto = populateResponse(e, respDto);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "UnexpectedException occurred while ",
                    "unAllocateSubs - ", new KnException(
                            ERROR_CODE_INTERNAL_ERROR, e.getMessage(), e));
            respDto = populateResponse(e, respDto);
        }

        return respDto;
    }


