    @Override
    public IXDMResponseDTO groupRehome(KnMessage message) {
        String methodName = "groupRehome(KnMessage)";
        knLogger.info(methodName, "ENTRY");
        KnXDMCorpRespDTO xdmResponseDTO = new KnXDMCorpRespDTO();
        KnPersisterTxn persisterTxn = null;
        try {
            Object payLoad = message.getPayLoad();
            IXDMRequestDTO groupInfoDTO = null;
            if (payLoad instanceof IXDMRequestDTO) {
                groupInfoDTO = (IXDMRequestDTO) payLoad;
            }
            if (groupInfoDTO == null) {
                knLogger.error(methodName, "Failed to parse message for groupRehome");
                return commonMediator.getFailureResponse(xdmResponseDTO, new KnException(KnMediatorConstants.ERROR_CODE_INVALID_DTO_PASSED, "Invalid or null request DTO"));
            }
            persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();
            boolean xcapMobileSync = commonMediator.getXcapMobileSyncFlag(persisterTxn);
            KnCorpResponseDTO corpRespDto = corpMediator.groupRehome(groupInfoDTO, persisterTxn);
            knLogger.info(methodName, "groupRehome corpResponse - ", corpRespDto);
            populateXdmResponse(xdmResponseDTO, corpRespDto);
            if (KnConstants.RESPONSE_STATUS.FAILURE.value() == xdmResponseDTO.getResponseStatus()) {
                knLogger.error(methodName, "Operation Failed");
                throw new KnXDMServerException(xdmResponseDTO.getResponseCode(), xdmResponseDTO.getResponseMessage());
            }
            persisterTxn.save();

            //2. Send Microservice Notification (XDMDataIntf)
            if (xcapMobileSync && corpRespDto.getChangeLogMap() != null && !corpRespDto.getChangeLogMap().isEmpty()) {
                knLogger.info(methodName, "Publishing micro service notification for group rehome");
                commonMediator.startNotifyMicroServicesJob(
                        corpRespDto.getChangeLogMap(),
                        corpRespDto.getMdnCorpId(),
                        corpRespDto.getGroupCreatedBy(),
                        corpRespDto.getLmrInteropFlag(),
                        corpRespDto.getMcxGrpInd()
                );
            }
        } catch (KnXDMServerException e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "KnXDMServerException occurred during groupRehome", e);
            xdmResponseDTO = (KnXDMCorpRespDTO) commonMediator.getFailureResponse(xdmResponseDTO, e);
        } catch (Exception e) {
            rollback(persisterTxn);
            knLogger.error(methodName, "Exception occurred during groupRehome", e);
            xdmResponseDTO = (KnXDMCorpRespDTO) commonMediator.getFailureResponse(xdmResponseDTO, e);
        }
        knLogger.info(methodName, "EXIT - xdmResponseDTO - ", xdmResponseDTO);
        return xdmResponseDTO;
    }

